export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const colors = [
    { name: 'Magenta', hex: 0xff2fd0 },
    { name: 'Cyan', hex: 0x22e5ff },
    { name: 'Lime', hex: 0x7dff3a },
    { name: 'Amber', hex: 0xffb020 },
    { name: 'Violet', hex: 0x8a4dff },
    { name: 'Red', hex: 0xff3b3b },
  ];
  let index = 0;

  // Base plate
  const base = new THREE.Mesh(
    new THREE.CylinderGeometry(0.11, 0.12, 0.02, 40),
    new THREE.MeshStandardMaterial({ color: 0x2a2e35, roughness: 0.5, metalness: 0.4 }),
  );
  base.name = 'Base';
  base.position.set(0, 0.01, 0);
  root.add(base);

  // Ring around the button
  const ring = new THREE.Mesh(
    new THREE.TorusGeometry(0.085, 0.008, 12, 48),
    new THREE.MeshStandardMaterial({
      color: colors[0].hex, emissive: colors[0].hex, emissiveIntensity: 1.0,
    }),
  );
  ring.rotation.x = Math.PI / 2;
  ring.position.set(0, 0.022, 0);
  root.add(ring);

  // The glowing button
  const buttonMat = new THREE.MeshStandardMaterial({
    color: colors[0].hex, emissive: colors[0].hex, emissiveIntensity: 1.2, roughness: 0.3,
  });
  const button = new THREE.Mesh(
    new THREE.CylinderGeometry(0.065, 0.065, 0.04, 40),
    buttonMat,
  );
  button.name = 'GlowButton';
  button.position.set(0, 0.04, 0);
  root.add(button);
  traits(button, { onPress: () => nextColor() });

  // Glow halo (additive, unlit)
  const haloMat = new THREE.MeshBasicMaterial({
    color: colors[0].hex, transparent: true, opacity: 0.25,
    blending: THREE.AdditiveBlending, depthWrite: false,
  });
  const halo = new THREE.Mesh(new THREE.SphereGeometry(0.1, 24, 12), haloMat);
  halo.position.set(0, 0.05, 0);
  halo.scale.set(1, 0.4, 1);
  root.add(halo);

  // Info panel behind and above the button
  const info = ui(`
    <style>
      .card { width: 440px; flex-direction: column; align-items: center; gap: 8px;
              padding-top: 16px; padding-bottom: 16px; padding-left: 20px; padding-right: 20px;
              border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; text-align: center; }
      .body { color: #d7dbe2; font-size: 24px; text-align: center; }
      .name { color: #ff2fd0; font-size: 30px; font-weight: 700; text-align: center; }
    </style>
    <div class="card">
      <span class="title">Glow Button</span>
      <span class="body">Press the button to change its color.</span>
      <span class="name" id="name">Magenta</span>
    </div>`, { width: 0.3, position: [0, 0.22, -0.08] });
  root.add(info.object3D);

  let pressT = 1; // press animation progress (0..1)

  function toHex(n) {
    return '#' + n.toString(16).padStart(6, '0');
  }

  function nextColor() {
    index = (index + 1) % colors.length;
    const c = colors[index];
    buttonMat.color.setHex(c.hex);
    buttonMat.emissive.setHex(c.hex);
    ring.material.color.setHex(c.hex);
    ring.material.emissive.setHex(c.hex);
    haloMat.color.setHex(c.hex);
    info.set('name', { text: c.name, color: toHex(c.hex) });
    pressT = 0;
  }

  return {
    root,
    update(time, delta) {
      // Button press squish and recovery
      if (pressT < 1) pressT = Math.min(1, pressT + delta * 4);
      const dip = Math.sin(pressT * Math.PI) * 0.012;
      button.position.y = 0.04 - dip;
      // Gentle pulsing glow
      const pulse = 0.5 + 0.5 * Math.sin(time * 2.5);
      buttonMat.emissiveIntensity = 0.9 + pulse * 0.6 + (1 - pressT) * 1.2;
      haloMat.opacity = 0.18 + pulse * 0.12;
      ring.material.emissiveIntensity = 0.8 + pulse * 0.6;
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------- Clock (grabbable group) ----------
  const clock = new THREE.Group();
  clock.name = 'DeskClock';
  clock.position.set(0, 0, 0);
  root.add(clock);

  const caseMat = new THREE.MeshStandardMaterial({ color: 0x2b2f36, roughness: 0.5, metalness: 0.4 });
  const faceMat = new THREE.MeshStandardMaterial({ color: 0xf3efe4, roughness: 0.8 });
  const darkMat = new THREE.MeshStandardMaterial({ color: 0x15171b, roughness: 0.5 });
  const redMat = new THREE.MeshStandardMaterial({ color: 0xd9342b, roughness: 0.5 });

  const cy = 0.115; // clock center height
  const R = 0.09;

  // Base and neck
  const base = new THREE.Mesh(new THREE.BoxGeometry(0.13, 0.015, 0.08), caseMat);
  base.position.set(0, 0.0075, 0);
  clock.add(base);
  const neck = new THREE.Mesh(new THREE.BoxGeometry(0.03, 0.03, 0.03), caseMat);
  neck.position.set(0, 0.03, 0);
  clock.add(neck);

  // Case (cylinder with axis along Z)
  const body = new THREE.Mesh(new THREE.CylinderGeometry(R, R, 0.03, 40), caseMat);
  body.rotation.x = Math.PI / 2;
  body.position.set(0, cy, 0);
  body.name = 'ClockCase';
  clock.add(body);

  // Face
  const face = new THREE.Mesh(new THREE.CircleGeometry(R - 0.008, 40), faceMat);
  face.position.set(0, cy, 0.0155);
  face.name = 'ClockFace';
  clock.add(face);

  // Hour ticks
  const tickGeoBig = new THREE.BoxGeometry(0.006, 0.014, 0.002);
  const tickGeoSmall = new THREE.BoxGeometry(0.003, 0.008, 0.002);
  for (let i = 0; i < 12; i++) {
    const a = (i / 12) * Math.PI * 2;
    const big = i % 3 === 0;
    const t = new THREE.Mesh(big ? tickGeoBig : tickGeoSmall, darkMat);
    const r = R - 0.008 - (big ? 0.011 : 0.009);
    t.position.set(Math.sin(a) * r, cy + Math.cos(a) * r, 0.0168);
    t.rotation.z = -a;
    clock.add(t);
  }

  // Hands: pivot groups rotating around Z
  function makeHand(length, width, mat, z, tail) {
    const pivot = new THREE.Group();
    pivot.position.set(0, cy, z);
    const m = new THREE.Mesh(new THREE.BoxGeometry(width, length + tail, 0.003), mat);
    m.position.y = (length - tail) / 2;
    pivot.add(m);
    clock.add(pivot);
    return pivot;
  }
  const hourHand = makeHand(0.042, 0.006, darkMat, 0.0185, 0.006);
  hourHand.children[0].name = 'HourHand';
  const minuteHand = makeHand(0.064, 0.0045, darkMat, 0.0205, 0.008);
  minuteHand.children[0].name = 'MinuteHand';
  const secondHand = makeHand(0.068, 0.0018, redMat, 0.0225, 0.014);
  secondHand.children[0].name = 'SecondHand';

  const cap = new THREE.Mesh(new THREE.CylinderGeometry(0.004, 0.004, 0.006, 16), redMat);
  cap.rotation.x = Math.PI / 2;
  cap.position.set(0, cy, 0.0235);
  clock.add(cap);

  traits(clock, { grab: true });

  // ---------- Info panel ----------
  const panel = ui(`
    <style>
      .card { width: 400px; flex-direction: column; align-items: center; gap: 8px;
              padding-top: 18px; padding-bottom: 18px; padding-left: 20px; padding-right: 20px;
              border-radius: 20px; background-color: #1f2228; }
      .label { color: #aab2bf; font-size: 24px; }
      .time { color: #ffffff; font-size: 84px; font-weight: 700; }
      .ampm { color: #7fc4ff; font-size: 30px; font-weight: 700; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 18px; padding-right: 18px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btn-text { color: #ffffff; font-size: 24px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="label">Local time</span>
      <span class="time" id="time">--:--</span>
      <span class="ampm" id="ampm"> </span>
      <button class="btn" id="mode"><span class="btn-text" id="modeText">Show 24 h</span></button>
    </div>`, { width: 0.22, position: [0.23, 0.115, 0] });
  root.add(panel.object3D);

  let use24 = false;
  let lastKey = -1;
  panel.on('mode', 'click', () => {
    use24 = !use24;
    panel.set('modeText', { text: use24 ? 'Show 12 h' : 'Show 24 h' });
    lastKey = -1;
  });

  const hasDate = typeof Date !== 'undefined';
  const d = hasDate ? new Date() : null;
  const TWO_PI = Math.PI * 2;

  function pad(n) { return n < 10 ? '0' + n : '' + n; }

  return {
    root,
    update(time) {
      let h = 10, m = 10, s = 0;
      if (hasDate) {
        d.setTime(Date.now());
        h = d.getHours();
        m = d.getMinutes();
        s = d.getSeconds() + d.getMilliseconds() / 1000;
      } else {
        s = time % 60;
      }

      secondHand.rotation.z = -(s / 60) * TWO_PI;
      minuteHand.rotation.z = -((m + s / 60) / 60) * TWO_PI;
      hourHand.rotation.z = -(((h % 12) + m / 60) / 12) * TWO_PI;

      const key = h * 60 + m + (use24 ? 10000 : 0);
      if (key !== lastKey) {
        lastKey = key;
        if (use24) {
          panel.set('time', { text: pad(h) + ':' + pad(m) });
          panel.set('ampm', { text: '24-hour' });
        } else {
          const h12 = h % 12 === 0 ? 12 : h % 12;
          panel.set('time', { text: h12 + ':' + pad(m) });
          panel.set('ampm', { text: h < 12 ? 'AM' : 'PM' });
        }
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------- Clock (grabbable group) ----------
  const clock = new THREE.Group();
  clock.name = 'DeskClock';
  clock.position.set(-0.12, 0, 0);
  root.add(clock);

  const woodMat = new THREE.MeshStandardMaterial({ color: 0x3b2a20, roughness: 0.6 });
  const metalMat = new THREE.MeshStandardMaterial({ color: 0xb8bcc4, roughness: 0.3, metalness: 0.8 });
  const faceMat = new THREE.MeshStandardMaterial({ color: 0xf4f1e8, roughness: 0.7 });
  const darkMat = new THREE.MeshStandardMaterial({ color: 0x1b1d22, roughness: 0.5 });
  const redMat = new THREE.MeshStandardMaterial({ color: 0xd93a2f, roughness: 0.5 });

  const faceY = 0.12;
  const faceR = 0.08;

  const base = new THREE.Mesh(new THREE.BoxGeometry(0.14, 0.015, 0.08), woodMat);
  base.position.y = 0.0075;
  clock.add(base);

  const stem = new THREE.Mesh(new THREE.CylinderGeometry(0.008, 0.01, 0.03, 16), metalMat);
  stem.position.y = 0.03;
  clock.add(stem);

  const bezel = new THREE.Mesh(new THREE.TorusGeometry(faceR + 0.004, 0.006, 12, 48), metalMat);
  bezel.position.set(0, faceY, 0.01);
  bezel.name = 'Bezel';
  clock.add(bezel);

  const face = new THREE.Mesh(new THREE.CylinderGeometry(faceR, faceR, 0.02, 48), faceMat);
  face.rotation.x = Math.PI / 2;
  face.position.set(0, faceY, 0);
  face.name = 'ClockFace';
  clock.add(face);

  // Hour ticks
  const tickBig = new THREE.BoxGeometry(0.008, 0.016, 0.004);
  const tickSmall = new THREE.BoxGeometry(0.004, 0.009, 0.004);
  for (let i = 0; i < 12; i++) {
    const a = (i / 12) * Math.PI * 2;
    const big = i % 3 === 0;
    const t = new THREE.Mesh(big ? tickBig : tickSmall, darkMat);
    const r = faceR - (big ? 0.012 : 0.009);
    t.position.set(Math.sin(a) * r, faceY + Math.cos(a) * r, 0.011);
    t.rotation.z = -a;
    clock.add(t);
  }

  // Hands: pivot group rotates, box is offset along +Y
  function makeHand(length, width, mat, z) {
    const pivot = new THREE.Group();
    pivot.position.set(0, faceY, z);
    const m = new THREE.Mesh(new THREE.BoxGeometry(width, length, 0.003), mat);
    m.position.y = length / 2 - 0.006;
    pivot.add(m);
    clock.add(pivot);
    return pivot;
  }
  const hourHand = makeHand(0.046, 0.007, darkMat, 0.0125);
  hourHand.children[0].name = 'HourHand';
  const minuteHand = makeHand(0.068, 0.005, darkMat, 0.0155);
  minuteHand.children[0].name = 'MinuteHand';

  const cap = new THREE.Mesh(new THREE.CylinderGeometry(0.006, 0.006, 0.006, 16), redMat);
  cap.rotation.x = Math.PI / 2;
  cap.position.set(0, faceY, 0.0185);
  clock.add(cap);

  traits(clock, { grab: true });

  // ---------- Digital panel ----------
  const panel = ui(`
    <style>
      .card { width: 300px; flex-direction: column; align-items: center; gap: 8px;
              padding-top: 16px; padding-bottom: 16px; padding-left: 16px; padding-right: 16px;
              border-radius: 18px; background-color: #1f2228; }
      .time { color: #ffffff; font-size: 64px; font-weight: 700; text-align: center; }
      .sub { color: #aab2bd; font-size: 22px; text-align: center; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="sub">Current time</span>
      <span class="time" id="time">--:--</span>
      <span class="sub" id="fmt">24-hour format</span>
      <button class="btn" id="toggle"><span class="btn-text">12 / 24 h</span></button>
    </div>`, { width: 0.22, position: [0.12, 0.1, 0] });
  root.add(panel.object3D);

  let use24 = true;
  let lastShown = '';
  panel.on('toggle', 'click', () => {
    use24 = !use24;
    panel.set('fmt', { text: use24 ? '24-hour format' : '12-hour format' });
    lastShown = '';
  });

  // ---------- Time source ----------
  let dateObj = null;
  try { dateObj = new Date(); } catch (e) { dateObj = null; }

  function pad(n) { return n < 10 ? '0' + n : '' + n; }

  return {
    root,
    update(time) {
      let h, m, s;
      if (dateObj) {
        dateObj.setTime(Date.now());
        h = dateObj.getHours();
        m = dateObj.getMinutes();
        s = dateObj.getSeconds() + dateObj.getMilliseconds() / 1000;
      } else {
        const total = 10 * 3600 + 8 * 60 + time;
        h = Math.floor(total / 3600) % 24;
        m = Math.floor(total / 60) % 60;
        s = total % 60;
      }

      const minFrac = m + s / 60;
      minuteHand.rotation.z = -(minFrac / 60) * Math.PI * 2;
      hourHand.rotation.z = -(((h % 12) + minFrac / 60) / 12) * Math.PI * 2;

      let str;
      if (use24) {
        str = pad(h) + ':' + pad(m);
      } else {
        const h12 = h % 12 === 0 ? 12 : h % 12;
        str = h12 + ':' + pad(m) + (h < 12 ? ' AM' : ' PM');
      }
      if (str !== lastShown) {
        lastShown = str;
        panel.set('time', { text: str });
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---- Lamp (a single group so pressing anywhere on it toggles the light) ----
  const lamp = new THREE.Group();
  lamp.name = 'DeskLamp';
  lamp.position.set(-0.2, 0, 0);
  root.add(lamp);

  const metal = new THREE.MeshStandardMaterial({ color: 0x2b2f36, roughness: 0.4, metalness: 0.7 });
  const accent = new THREE.MeshStandardMaterial({ color: 0xd9533b, roughness: 0.45, metalness: 0.3 });

  const base = new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.08, 0.016, 32), metal);
  base.name = 'Base';
  base.position.y = 0.008;
  lamp.add(base);

  // helper: cylinder between two points
  const up = new THREE.Vector3(0, 1, 0);
  function rod(a, b, radius, mat) {
    const va = new THREE.Vector3(...a);
    const vb = new THREE.Vector3(...b);
    const dir = vb.clone().sub(va);
    const len = dir.length();
    const m = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, len, 12), mat);
    m.position.copy(va).add(vb).multiplyScalar(0.5);
    m.quaternion.setFromUnitVectors(up, dir.normalize());
    lamp.add(m);
    return m;
  }

  const P0 = [0, 0.016, 0];
  const P1 = [0.0, 0.17, 0];
  const P2 = [0.13, 0.31, 0];
  rod(P0, P1, 0.008, metal).name = 'LowerArm';
  rod(P1, P2, 0.007, metal).name = 'UpperArm';

  const joint = new THREE.Mesh(new THREE.SphereGeometry(0.014, 16, 12), accent);
  joint.position.set(...P1);
  lamp.add(joint);

  // shade: open cone, opening downward
  const shade = new THREE.Mesh(
    new THREE.ConeGeometry(0.06, 0.075, 32, 1, true),
    new THREE.MeshStandardMaterial({ color: 0xd9533b, roughness: 0.45, metalness: 0.3, side: THREE.DoubleSide }),
  );
  shade.name = 'Shade';
  shade.position.set(0.13, 0.31, 0);
  lamp.add(shade);

  const cap = new THREE.Mesh(new THREE.SphereGeometry(0.012, 16, 12), metal);
  cap.position.set(0.13, 0.352, 0);
  lamp.add(cap);

  // bulb
  const bulbMat = new THREE.MeshStandardMaterial({
    color: 0xcfc6a8, emissive: 0xffc860, emissiveIntensity: 0, roughness: 0.3,
  });
  const bulb = new THREE.Mesh(new THREE.SphereGeometry(0.02, 24, 12), bulbMat);
  bulb.name = 'Bulb';
  bulb.position.set(0.13, 0.285, 0);
  lamp.add(bulb);

  // light beam and pool of light (visual only, not pressable)
  const beamMat = new THREE.MeshBasicMaterial({
    color: 0xffd98a, transparent: true, opacity: 0, blending: THREE.AdditiveBlending,
    depthWrite: false, side: THREE.DoubleSide,
  });
  const beamH = 0.28;
  const beam = new THREE.Mesh(new THREE.ConeGeometry(0.12, beamH, 32, 1, true), beamMat);
  beam.position.set(0.13, 0.275 - beamH / 2 + 0.005, 0);
  beam.raycast = () => {};
  lamp.add(beam);

  const glowMat = new THREE.MeshBasicMaterial({
    color: 0xffd98a, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false,
  });
  const glow = new THREE.Mesh(new THREE.CircleGeometry(0.12, 32), glowMat);
  glow.rotation.x = -Math.PI / 2;
  glow.position.set(0.13, 0.003, 0);
  glow.raycast = () => {};
  lamp.add(glow);

  // small book in the lit area that brightens when the lamp is on
  const bookMat = new THREE.MeshStandardMaterial({ color: 0x2f4f8f, roughness: 0.7 });
  const book = new THREE.Mesh(new THREE.BoxGeometry(0.08, 0.016, 0.06), bookMat);
  book.position.set(0.13, 0.008, 0.0);
  book.rotation.y = 0.3;
  lamp.add(book);

  // ---- State ----
  let isOn = false;
  let level = 0; // smoothed 0..1

  // ---- Panel ----
  const panel = ui(`
    <style>
      .card { width: 440px; flex-direction: column; gap: 12px; padding-top: 18px; padding-bottom: 18px;
              padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 24px; }
      .status { color: #9aa3b0; font-size: 26px; font-weight: 700; }
      .btn { padding-top: 14px; padding-bottom: 14px; padding-left: 16px; padding-right: 16px;
             border-radius: 12px; background-color: #d9a21f; align-items: center; justify-content: center; }
      .btn-text { color: #1a1d22; font-size: 26px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Desk Lamp</span>
      <span class="body">Press the lamp, or this button, to switch it on or off.</span>
      <span class="status" id="status">Light is OFF</span>
      <button class="btn" id="toggle"><span class="btn-text" id="toggleText">Turn on</span></button>
    </div>`, { width: 0.3, position: [0.2, 0.16, 0.0], rotationY: -0.2 });
  root.add(panel.object3D);

  function toggle() {
    isOn = !isOn;
    panel.set('status', { text: isOn ? 'Light is ON' : 'Light is OFF', color: isOn ? '#ffd98a' : '#9aa3b0' });
    panel.set('toggleText', { text: isOn ? 'Turn off' : 'Turn on' });
    panel.set('toggle', { backgroundColor: isOn ? '#8a93a3' : '#d9a21f' });
  }

  panel.on('toggle', 'click', toggle);
  traits(lamp, { onPress: toggle });

  const offBook = new THREE.Color(0x1a2a4d);
  const onBook = new THREE.Color(0x4d7fe0);

  return {
    root,
    update(time, delta) {
      const target = isOn ? 1 : 0;
      level += (target - level) * Math.min(1, delta * 8);
      bulbMat.emissiveIntensity = level * 1.6;
      bulbMat.color.setHex(0xcfc6a8).lerp(new THREE.Color(0xfff2c4), level);
      beamMat.opacity = level * 0.1;
      glowMat.opacity = level * 0.35;
      bookMat.color.copy(offBook).lerp(onBook, level);
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const N = 21;                 // base pairs (about 2 turns)
  const R = 0.04;               // helix radius (m)
  const RISE = 0.0145;          // height per base pair (m)
  const STEP = (Math.PI * 2) / 10; // 10 base pairs per turn
  const totalH = (N - 1) * RISE;

  const helix = new THREE.Group();
  helix.name = 'DNA helix';
  helix.position.set(0, 0.2, 0);
  root.add(helix);

  // Faint glass capsule so the thin helix is easy to pinch
  const hit = new THREE.Mesh(
    new THREE.CylinderGeometry(R + 0.018, R + 0.018, totalH + 0.04, 20),
    new THREE.MeshStandardMaterial({
      color: 0x88aaff, transparent: true, opacity: 0.07, depthWrite: false,
    }),
  );
  hit.name = 'Grab area';
  helix.add(hit);

  // Sugar-phosphate backbones
  const backMat = new THREE.MeshStandardMaterial({ color: 0xc9cfe0, roughness: 0.4, metalness: 0.2 });
  function strandCurve(phase) {
    const pts = [];
    const samples = 120;
    for (let s = 0; s <= samples; s++) {
      const u = s / samples;
      const a = phase + u * (N - 1) * STEP;
      const y = (u - 0.5) * totalH;
      pts.push(new THREE.Vector3(Math.cos(a) * R, y, Math.sin(a) * R));
    }
    return new THREE.CatmullRomCurve3(pts);
  }
  const strandA = new THREE.Mesh(new THREE.TubeGeometry(strandCurve(0), 160, 0.0055, 8), backMat);
  strandA.name = 'Backbone 1';
  const strandB = new THREE.Mesh(new THREE.TubeGeometry(strandCurve(Math.PI), 160, 0.0055, 8), backMat);
  strandB.name = 'Backbone 2';
  helix.add(strandA, strandB);

  // Bases: A red, T yellow, G green, C blue
  const colors = { A: 0xe0443e, T: 0xf2c230, G: 0x3fbf6a, C: 0x3d7de0 };
  const comp = { A: 'T', T: 'A', G: 'C', C: 'G' };
  const seq = 'ATGCCGATTAGCGCTAAGTCG';

  const counts = { A: 0, T: 0, G: 0, C: 0 };
  for (let i = 0; i < N; i++) {
    counts[seq[i]]++;
    counts[comp[seq[i]]]++;
  }

  const halfLen = R - 0.004;
  const baseGeo = new THREE.CylinderGeometry(0.0045, 0.0045, halfLen, 8);
  const inst = {};
  const idx = { A: 0, T: 0, G: 0, C: 0 };
  for (const k of Object.keys(colors)) {
    inst[k] = new THREE.InstancedMesh(
      baseGeo,
      new THREE.MeshStandardMaterial({ color: colors[k], roughness: 0.5 }),
      counts[k],
    );
    inst[k].name = 'Base ' + k;
    helix.add(inst[k]);
  }

  const up = new THREE.Vector3(0, 1, 0);
  const dir = new THREE.Vector3();
  const pos = new THREE.Vector3();
  const quat = new THREE.Quaternion();
  const scl = new THREE.Vector3(1, 1, 1);
  const m = new THREE.Matrix4();

  for (let i = 0; i < N; i++) {
    const a = i * STEP;
    const y = (i - (N - 1) / 2) * RISE;
    const b1 = seq[i];
    const b2 = comp[b1];

    // half attached to strand 1 (outer point -> center)
    dir.set(Math.cos(a), 0, Math.sin(a)); // points from center to strand 1
    quat.setFromUnitVectors(up, dir);
    pos.set(dir.x * (R - halfLen / 2 - 0.002), y, dir.z * (R - halfLen / 2 - 0.002));
    m.compose(pos, quat, scl);
    inst[b1].setMatrixAt(idx[b1]++, m);

    // half attached to strand 2 (opposite side)
    dir.set(-Math.cos(a), 0, -Math.sin(a));
    quat.setFromUnitVectors(up, dir);
    pos.set(dir.x * (R - halfLen / 2 - 0.002), y, dir.z * (R - halfLen / 2 - 0.002));
    m.compose(pos, quat, scl);
    inst[b2].setMatrixAt(idx[b2]++, m);
  }
  for (const k of Object.keys(inst)) inst[k].instanceMatrix.needsUpdate = true;

  traits(helix, { grab: true });

  // Info panel
  const panel = ui(`
    <style>
      .card { width: 500px; flex-direction: column; gap: 12px; padding-top: 18px; padding-bottom: 18px;
              padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 24px; }
      .row { flex-direction: row; gap: 10px; }
      .chip { padding-top: 6px; padding-bottom: 6px; padding-left: 12px; padding-right: 12px; border-radius: 10px; }
      .chip-text { color: #111111; font-size: 22px; font-weight: 700; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btn-text { color: #ffffff; font-size: 24px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">DNA double helix</span>
      <div class="row">
        <div class="chip" style="background-color: #e0443e;"><span class="chip-text">A</span></div>
        <div class="chip" style="background-color: #f2c230;"><span class="chip-text">T</span></div>
        <div class="chip" style="background-color: #3fbf6a;"><span class="chip-text">G</span></div>
        <div class="chip" style="background-color: #3d7de0;"><span class="chip-text">C</span></div>
      </div>
      <span class="body" id="fact">Pinch the helix to pick it up and turn it. A pairs with T, G pairs with C.</span>
      <div class="row">
        <button class="btn" id="next"><span class="btn-text">Next fact</span></button>
        <button class="btn" id="spin"><span class="btn-text" id="spinText">Spin: on</span></button>
      </div>
    </div>`, { width: 0.32, position: [0.32, 0.2, 0], rotationY: -0.3 });
  root.add(panel.object3D);

  const facts = [
    'A = Adenine, T = Thymine, G = Guanine, C = Cytosine. These are the four bases.',
    'A pairs with T using 2 hydrogen bonds. G pairs with C using 3 hydrogen bonds.',
    'The two backbones are made of alternating sugar (deoxyribose) and phosphate groups.',
    'The two strands run in opposite directions (antiparallel).',
    'One full turn has about 10.5 base pairs and is about 3.4 nm long. The helix is about 2 nm wide.',
    'The human genome has about 3 billion base pairs.',
  ];
  let fi = -1;
  panel.on('next', 'click', () => {
    fi = (fi + 1) % facts.length;
    panel.set('fact', { text: facts[fi] });
  });

  let spinning = true;
  panel.on('spin', 'click', () => {
    spinning = !spinning;
    panel.set('spinText', { text: spinning ? 'Spin: on' : 'Spin: off' });
  });

  return {
    root,
    update(time, delta) {
      if (isGrabbed(helix)) return;
      if (spinning) helix.rotation.y += delta * 0.4;
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---- DNA parameters (scaled up model) ----
  const seq = 'GCATTAGCCGATCGTAGCTA';
  const N = seq.length;            // 20 base pairs = 2 full turns
  const bpPerTurn = 10;
  const step = (Math.PI * 2) / bpPerTurn;
  const rise = 0.015;              // m per base pair
  const R = 0.045;                 // helix radius
  const groove = 2.6;              // angular offset of strand 2 (major/minor groove)
  const comp = { A: 'T', T: 'A', G: 'C', C: 'G' };
  const baseColor = {
    A: new THREE.Color(0xe8504a),
    T: new THREE.Color(0xf2c230),
    G: new THREE.Color(0x4cc36b),
    C: new THREE.Color(0x3d8be8),
  };

  const helix = new THREE.Group();
  helix.name = 'DNA helix';
  helix.position.set(0, 0.25, 0);
  root.add(helix);

  // Faint glass capsule: makes the thin helix easy to pinch
  const hit = new THREE.Mesh(
    new THREE.CylinderGeometry(0.075, 0.075, 0.33, 24, 1),
    new THREE.MeshStandardMaterial({
      color: 0x9ad0ff, transparent: true, opacity: 0.07, depthWrite: false, roughness: 0.2,
    }),
  );
  hit.name = 'Grab volume';
  helix.add(hit);

  const yOf = (s) => (s - (N - 1) / 2) * rise;
  const p1 = (s) => new THREE.Vector3(Math.cos(s * step) * R, yOf(s), Math.sin(s * step) * R);
  const p2 = (s) => new THREE.Vector3(Math.cos(s * step + groove) * R, yOf(s), Math.sin(s * step + groove) * R);

  // ---- Backbones (sugar-phosphate) ----
  const pts1 = [];
  const pts2 = [];
  const samples = 120;
  for (let k = 0; k <= samples; k++) {
    const s = -0.4 + (k / samples) * (N - 1 + 0.8);
    pts1.push(p1(s));
    pts2.push(p2(s));
  }
  const bbMat1 = new THREE.MeshStandardMaterial({ color: 0xb8c4d6, roughness: 0.4, metalness: 0.2 });
  const bbMat2 = new THREE.MeshStandardMaterial({ color: 0xe0a46a, roughness: 0.4, metalness: 0.2 });
  const tube1 = new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts1), 240, 0.0055, 8), bbMat1);
  tube1.name = 'Backbone strand 1';
  const tube2 = new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts2), 240, 0.0055, 8), bbMat2);
  tube2.name = 'Backbone strand 2';
  helix.add(tube1, tube2);

  // ---- Sugar/phosphate beads at each base pair ----
  const beadGeo = new THREE.SphereGeometry(0.0095, 16, 12);
  const beads1 = new THREE.InstancedMesh(beadGeo, bbMat1, N);
  const beads2 = new THREE.InstancedMesh(beadGeo, bbMat2, N);
  const m = new THREE.Matrix4();
  for (let i = 0; i < N; i++) {
    m.makeTranslation(...p1(i).toArray());
    beads1.setMatrixAt(i, m);
    m.makeTranslation(...p2(i).toArray());
    beads2.setMatrixAt(i, m);
  }
  helix.add(beads1, beads2);

  // ---- Base-pair rungs: two colored halves per pair ----
  const rungGeo = new THREE.CylinderGeometry(0.0042, 0.0042, 1, 10, 1);
  const rungMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.45 });
  const rungs = new THREE.InstancedMesh(rungGeo, rungMat, N * 2);
  rungs.name = 'Base pairs';
  const up = new THREE.Vector3(0, 1, 0);
  const q = new THREE.Quaternion();
  const pos = new THREE.Vector3();
  const scl = new THREE.Vector3();
  const dir = new THREE.Vector3();
  for (let i = 0; i < N; i++) {
    const a = p1(i);
    const b = p2(i);
    const mid = a.clone().add(b).multiplyScalar(0.5);
    const base1 = seq[i];
    const base2 = comp[base1];
    const halves = [[a, base1], [b, base2]];
    for (let h = 0; h < 2; h++) {
      const [from, base] = halves[h];
      dir.copy(mid).sub(from);
      const len = dir.length();
      dir.normalize();
      q.setFromUnitVectors(up, dir);
      pos.copy(from).add(mid).multiplyScalar(0.5);
      scl.set(1, len, 1);
      m.compose(pos, q, scl);
      rungs.setMatrixAt(i * 2 + h, m);
      rungs.setColorAt(i * 2 + h, baseColor[base]);
    }
  }
  helix.add(rungs);

  traits(helix, { grab: true });

  // ---- Info panel ----
  const info = ui(`
    <style>
      .card { width: 480px; flex-direction: column; gap: 12px; padding-top: 18px; padding-bottom: 18px;
              padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 24px; }
      .row { flex-direction: row; align-items: center; gap: 12px; }
      .sw { width: 22px; height: 22px; border-radius: 6px; }
      .lg { color: #ffffff; font-size: 22px; }
      .btns { flex-direction: row; gap: 12px; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btn2 { padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px;
              border-radius: 12px; background-color: #3a4049; }
      .bt { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">DNA double helix</span>
      <span class="body" id="fact">Pinch the helix to pick it up and turn it in your hand.</span>
      <div class="row"><div class="sw" style="background-color:#e8504a"></div><span class="lg">A Adenine pairs with T</span></div>
      <div class="row"><div class="sw" style="background-color:#f2c230"></div><span class="lg">T Thymine pairs with A</span></div>
      <div class="row"><div class="sw" style="background-color:#4cc36b"></div><span class="lg">G Guanine pairs with C</span></div>
      <div class="row"><div class="sw" style="background-color:#3d8be8"></div><span class="lg">C Cytosine pairs with G</span></div>
      <div class="btns">
        <button class="btn" id="next"><span class="bt">Next fact</span></button>
        <button class="btn2" id="spin"><span class="bt" id="spinText">Spin: On</span></button>
      </div>
    </div>`, { width: 0.26, position: [0.27, 0.22, 0], rotationY: -0.2 });
  root.add(info.object3D);

  const facts = [
    'The two strands are joined by base pairs, like rungs on a twisted ladder.',
    'A pairs with T using 2 hydrogen bonds. G pairs with C using 3.',
    'The sugar-phosphate backbones run on the outside, in opposite directions.',
    'One full turn is about 10.5 base pairs, roughly 3.4 nm long.',
    'The helix is only about 2 nm wide. This model is scaled up millions of times.',
    'A human cell holds about 3 billion base pairs of DNA.',
  ];
  let fi = -1;
  info.on('next', 'click', () => {
    fi = (fi + 1) % facts.length;
    info.set('fact', { text: facts[fi] });
  });

  let spinning = true;
  info.on('spin', 'click', () => {
    spinning = !spinning;
    info.set('spinText', { text: spinning ? 'Spin: On' : 'Spin: Off' });
  });

  return {
    root,
    update(time, delta) {
      if (isGrabbed(helix)) return;
      if (spinning) helix.rotation.y += delta * 0.25;
    },
  };
}

