      const target = on ? 1 : 0;
      level += (target - level) * Math.min(1, delta * 8);
      bulbMat.emissiveIntensity = 0.05 + level * 1.8;
      shadeMat.emissiveIntensity = level * 0.35;
      beamMat.opacity = level * 0.14;
      poolMat.opacity = level * 0.18;
      poolMat2.opacity = level * 0.22;
      indicatorMat.emissiveIntensity = 0.2 + level * 1.5;
      indicatorMat.color.setHex(on ? 0x22aa55 : 0x552222);
      indicatorMat.emissive.setHex(on ? 0x33ff77 : 0xff3b30);
      switchBody.scale.y += (1 - switchBody.scale.y) * Math.min(1, delta * 10);
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // Layer data (outside -> in). Radii in meters. The crust is drawn thicker than real scale.
  const layers = [
    { id: 'crust', name: 'Crust', r0: 0.113, r1: 0.12, color: 0x6b8e4e, css: '#6b8e4e', emissive: 0x1d3a10,
      depth: 'Depth: 5-70 km (thickest under mountains)',
      body: 'Thin, solid rock skin that we live on. Oceanic crust is about 5-10 km thick, continental crust 30-70 km. Drawn extra thick here.' },
    { id: 'mantle', name: 'Mantle', r0: 0.063, r1: 0.113, color: 0xd9552b, css: '#d9552b', emissive: 0x7a1a05,
      depth: 'Depth: to about 2,900 km',
      body: 'Hot, solid rock that flows very slowly. It makes up about 84% of Earth\'s volume. Its slow movement drives plate tectonics.' },
    { id: 'outer', name: 'Outer core', r0: 0.023, r1: 0.063, color: 0xf2992e, css: '#f2992e', emissive: 0x9a4a00,
      depth: 'Depth: 2,900 - 5,150 km',
      body: 'Liquid iron and nickel, about 4,000-5,000 °C. Its churning flow creates Earth\'s magnetic field.' },
    { id: 'inner', name: 'Inner core', r0: 0, r1: 0.023, color: 0xfff1a8, css: '#fff1a8', emissive: 0xffc43d,
      depth: 'Depth: 5,150 - 6,371 km',
      body: 'A solid ball of iron and nickel, about 5,200 °C. Immense pressure keeps it solid. Radius about 1,220 km.' },
  ];

  const earth = new THREE.Group();
  earth.name = 'CutawayEarth';
  earth.position.set(-0.1, 0.16, 0);
  earth.rotation.y = 3 * Math.PI / 4; // open wedge faces the user
  root.add(earth);

  const wedge = Math.PI * 1.5; // sphere covers 270 degrees, 90 degree wedge removed
  const mats = {};

  layers.forEach((L) => {
    const mat = new THREE.MeshStandardMaterial({
      color: L.color, roughness: 0.7, emissive: L.emissive, emissiveIntensity: 0.15, side: THREE.DoubleSide,
    });
    mats[L.id] = mat;

    const shell = new THREE.Mesh(new THREE.SphereGeometry(L.r1, 32, 24, 0, wedge), mat);
    shell.name = L.name + ' shell';
    earth.add(shell);

    // Cut face: half annulus in the (rho, y) plane
    const s = new THREE.Shape();
    if (L.r0 === 0) {
      s.moveTo(0, -L.r1);
      s.absarc(0, 0, L.r1, -Math.PI / 2, Math.PI / 2, false);
      s.lineTo(0, -L.r1);
    } else {
      s.moveTo(0, -L.r1);
      s.absarc(0, 0, L.r1, -Math.PI / 2, Math.PI / 2, false);
      s.lineTo(0, L.r0);
      s.absarc(0, 0, L.r0, Math.PI / 2, -Math.PI / 2, true);
      s.lineTo(0, -L.r1);
    }
    const faceGeo = new THREE.ShapeGeometry(s, 24);
    [0, wedge].forEach((phi) => {
      const face = new THREE.Mesh(faceGeo, mat);
      face.name = L.name + ' cut face';
      face.rotation.y = Math.PI + phi;
      earth.add(face);
    });
  });

  traits(earth, { grab: true });

  // Info panel with one labelled button per layer
  const info = ui(`
    <style>
      .card { width: 500px; flex-direction: column; gap: 10px; padding-top: 18px; padding-bottom: 18px;
              padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .hint { color: #aab2bd; font-size: 22px; }
      .row { flex-direction: row; align-items: center; gap: 14px; padding-top: 9px; padding-bottom: 9px;
             padding-left: 14px; padding-right: 14px; border-radius: 12px; background-color: #333840; }
      .sw { width: 26px; height: 26px; border-radius: 13px; }
      .lbl { color: #ffffff; font-size: 26px; font-weight: 700; }
      .box { flex-direction: column; gap: 8px; padding-top: 12px; padding-bottom: 12px; padding-left: 14px;
             padding-right: 14px; border-radius: 12px; background-color: #2c3038; }
      .name { color: #ffffff; font-size: 28px; font-weight: 700; }
      .depth { color: #ffd27a; font-size: 22px; }
      .body { color: #d7dbe2; font-size: 22px; }
    </style>
    <div class="card">
      <span class="title">Layers of the Earth</span>
      <span class="hint">Press a layer. Pinch the globe to turn it.</span>
      ${layers.map((L) => `<button class="row" id="b_${L.id}"><div class="sw" style="background-color: ${L.css};"></div><span class="lbl" id="l_${L.id}">${L.name}</span></button>`).join('')}
      <div class="box">
        <span class="name" id="name">Crust</span>
        <span class="depth" id="depth">${layers[0].depth}</span>
        <span class="body" id="body">${layers[0].body}</span>
      </div>
    </div>`, { width: 0.32, position: [0.24, 0.19, 0], rotationY: -0.1 });
  root.add(info.object3D);

  let selected = 'crust';
  function select(id) {
    selected = id;
    const L = layers.find((l) => l.id === id);
    info.set('name', { text: L.name });
    info.set('depth', { text: L.depth });
    info.set('body', { text: L.body });
    layers.forEach((l) => {
      info.set('b_' + l.id, { backgroundColor: l.id === id ? '#3d6fd0' : '#333840' });
    });
  }
  layers.forEach((L) => {
    info.on('b_' + L.id, 'click', () => select(L.id));
  });
  select('crust');

  return {
    root,
    update(time) {
      layers.forEach((L) => {
        mats[L.id].emissiveIntensity = L.id === selected ? 0.6 + 0.35 * Math.sin(time * 3) : 0.15;
      });
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------- data ----------
  const cities = [
    { name: 'Madrid', cond: 'Sunny', c: 29, hi: 31, lo: 18, hum: 28, wind: 12, x: -0.26 },
    { name: 'London', cond: 'Rain', c: 14, hi: 16, lo: 10, hum: 82, wind: 19, x: 0 },
    { name: 'Oslo', cond: 'Snow', c: -2, hi: 0, lo: -6, hum: 76, wind: 9, x: 0.26 },
  ];
  let useF = false;
  let selected = 1;
  const fmt = (c) => (useF ? Math.round(c * 9 / 5 + 32) + '°F' : c + '°C');

  // ---------- shared geometry / materials ----------
  const sphereGeo = new THREE.SphereGeometry(1, 24, 12);
  const boxGeo = new THREE.BoxGeometry(1, 1, 1);
  const dropGeo = new THREE.CylinderGeometry(0.0025, 0.0025, 0.014, 8);
  const baseGeo = new THREE.CylinderGeometry(0.06, 0.065, 0.012, 32);

  const sunMat = new THREE.MeshStandardMaterial({ color: 0xffc83d, emissive: 0xff9a00, emissiveIntensity: 0.7 });
  const cloudMat = new THREE.MeshStandardMaterial({ color: 0xe8edf3, roughness: 0.9 });
  const darkCloudMat = new THREE.MeshStandardMaterial({ color: 0x9aa5b4, roughness: 0.9 });
  const dropMat = new THREE.MeshStandardMaterial({ color: 0x3f8cff, emissive: 0x1b4fb0, emissiveIntensity: 0.5 });
  const flakeMat = new THREE.MeshStandardMaterial({ color: 0xffffff, emissive: 0xaad4ff, emissiveIntensity: 0.5 });

  function makeCloud(mat) {
    const g = new THREE.Group();
    const parts = [
      [-0.022, -0.004, 0.02],
      [0.0, 0.008, 0.026],
      [0.024, -0.004, 0.02],
      [0.0, -0.008, 0.024],
    ];
    parts.forEach(([x, y, r]) => {
      const m = new THREE.Mesh(sphereGeo, mat);
      m.position.set(x, y, 0);
      m.scale.set(r, r * 0.85, r);
      g.add(m);
    });
    return g;
  }

  // ---------- icons ----------
  const icons = [];
  const bases = [];
  const rayGroups = [];
  const drops = []; // {mesh, x, phase, kind}
  const clouds = [];

  cities.forEach((city, i) => {
    const icon = new THREE.Group();
    icon.name = city.name + ' icon';
    icon.position.set(city.x, 0.26, 0);
    root.add(icon);

    if (city.cond === 'Sunny') {
      const sun = new THREE.Mesh(sphereGeo, sunMat);
      sun.name = 'Sun';
      sun.scale.setScalar(0.028);
      icon.add(sun);
      const rays = new THREE.Group();
      for (let k = 0; k < 8; k++) {
        const a = (k / 8) * Math.PI * 2;
        const ray = new THREE.Mesh(boxGeo, sunMat);
        ray.scale.set(0.01, 0.022, 0.008);
        ray.position.set(Math.cos(a) * 0.05, Math.sin(a) * 0.05, 0);
        ray.rotation.z = a - Math.PI / 2;
        rays.add(ray);
      }
      icon.add(rays);
      rayGroups.push(rays);
    } else {
      const cloud = makeCloud(city.cond === 'Rain' ? darkCloudMat : cloudMat);
      cloud.name = 'Cloud';
      cloud.position.y = 0.015;
      icon.add(cloud);
      clouds.push(cloud);
      const n = city.cond === 'Rain' ? 6 : 8;
      for (let k = 0; k < n; k++) {
        const m = city.cond === 'Rain'
          ? new THREE.Mesh(dropGeo, dropMat)
          : new THREE.Mesh(sphereGeo, flakeMat);
        if (city.cond === 'Snow') m.scale.setScalar(0.005);
        else m.rotation.z = 0.15;
        icon.add(m);
        drops.push({
          mesh: m,
          x: -0.03 + (k / (n - 1)) * 0.06,
          phase: (k * 0.37) % 1,
          snow: city.cond === 'Snow',
        });
      }
    }

    const base = new THREE.Mesh(
      baseGeo,
      new THREE.MeshStandardMaterial({ color: 0x2a2e35, emissive: 0x2f6fdb, emissiveIntensity: 0 }),
    );
    base.position.set(city.x, 0.172, 0);
    root.add(base);
    bases.push(base);
    icons.push(icon);
  });

  // ---------- city cards ----------
  const cardCss = `
    <style>
      .card { width: 340px; background-color: #1f2228; border-radius: 22px; }
      .btn { width: 340px; flex-direction: column; align-items: center; gap: 4px;
             padding-top: 14px; padding-bottom: 14px; padding-left: 10px; padding-right: 10px;
             border-radius: 22px; background-color: #23272e; }
      .name { color: #ffffff; font-size: 28px; font-weight: 700; }
      .temp { color: #ffd479; font-size: 44px; font-weight: 700; }
      .cond { color: #d7dbe2; font-size: 22px; }
    </style>`;
  const cards = cities.map((city, i) => {
    const h = ui(`${cardCss}
      <div class="card">
        <button class="btn" id="card">
          <span class="name">${city.name}</span>
          <span class="temp" id="temp">${fmt(city.c)}</span>
          <span class="cond">${city.cond}</span>
        </button>
      </div>`, { width: 0.22, position: [city.x, 0.085, 0] });
    root.add(h.object3D);
    return h;
  });

  // ---------- detail panel ----------
  const detail = ui(`
    <style>
      .panel { width: 500px; flex-direction: column; gap: 10px; padding-top: 16px; padding-bottom: 16px;
               padding-left: 22px; padding-right: 22px; border-radius: 20px; background-color: #1a1d22; }
      .row { flex-direction: row; align-items: center; justify-content: space-between; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .line { color: #d7dbe2; font-size: 22px; }
      .unit { padding-top: 8px; padding-bottom: 8px; padding-left: 16px; padding-right: 16px;
              border-radius: 12px; background-color: #2f6fdb; }
      .unit-text { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="panel">
      <div class="row">
        <span class="title" id="dTitle">London - Rain</span>
        <button class="unit" id="unit"><span class="unit-text" id="unitText">Show °F</span></button>
      </div>
      <span class="line" id="dHL">High 16°C   Low 10°C</span>
      <span class="line" id="dHW">Humidity 82%   Wind 19 km/h</span>
    </div>`, { width: 0.4, position: [0, 0.385, 0] });
  root.add(detail.object3D);

  function refresh() {
    cities.forEach((city, i) => {
      cards[i].set('temp', { text: fmt(city.c) });
      cards[i].set('card', { backgroundColor: i === selected ? '#2f6fdb' : '#23272e' });
      bases[i].material.emissiveIntensity = i === selected ? 0.9 : 0;
    });
    const s = cities[selected];
    detail.set('dTitle', { text: s.name + ' - ' + s.cond });
    detail.set('dHL', { text: 'High ' + fmt(s.hi) + '   Low ' + fmt(s.lo) });
    detail.set('dHW', { text: 'Humidity ' + s.hum + '%   Wind ' + s.wind + ' km/h' });
    detail.set('unitText', { text: useF ? 'Show °C' : 'Show °F' });
  }

  function select(i) {
    selected = i;
    refresh();
  }

  cities.forEach((_, i) => {
    cards[i].on('card', 'click', () => select(i));
    traits(icons[i], { onPress: () => select(i) });
  });
  detail.on('unit', 'click', () => {
    useF = !useF;
    refresh();
  });
  refresh();

  // ---------- animation ----------
  return {
    root,
    update(time) {
      for (let i = 0; i < rayGroups.length; i++) rayGroups[i].rotation.z = time * 0.4;
      for (let i = 0; i < clouds.length; i++) clouds[i].position.x = Math.sin(time * 0.6 + i) * 0.006;
      for (let i = 0; i < drops.length; i++) {
        const d = drops[i];
        const t = (time * (d.snow ? 0.18 : 0.5) + d.phase) % 1;
        d.mesh.position.set(
          d.x + (d.snow ? Math.sin(time * 1.5 + d.phase * 6.28) * 0.006 : 0),
          -0.01 - t * 0.055,
          0,
        );
      }
    },
  };
}

