      <div class="row">
        <button class="btn btn-on" id="tabMat"><span class="btn-text">Material</span></button>
        <button class="btn" id="tabSize"><span class="btn-text">Size</span></button>
        <button class="btn" id="tabCare"><span class="btn-text">Care</span></button>
      </div>
    </div>`, { width: 0.34, position: [0.17, 0.12, 0], rotationY: -0.2 });
  root.add(info.object3D);

  const tabs = {
    tabMat: ['MATERIAL', 'Glazed stoneware ceramic, fired at about 1200 °C. Food-safe glaze.'],
    tabSize: ['SIZE', 'Holds 350 ml. Height 9 cm, diameter 8 cm, weight about 380 g.'],
    tabCare: ['CARE', 'Dishwasher and microwave safe. Avoid sudden temperature changes.'],
  };
  const ids = Object.keys(tabs);
  ids.forEach((id) => {
    info.on(id, 'click', () => {
      info.set('tabLabel', { text: tabs[id][0] });
      info.set('detail', { text: tabs[id][1] });
      ids.forEach((other) => {
        info.set(other, { backgroundColor: other === id ? '#2f6fdb' : '#3a3f48' });
      });
    });
  });

  return {
    root,
    update(time) {
      // Steam rises and fades; it lives in the mug's local space so it follows the hand.
      for (let i = 0; i < puffs.length; i++) {
        const p = puffs[i];
        const t = (time * 0.25 + p.phase) % 1;
        p.mesh.position.set(Math.sin(time + i * 2) * 0.008, 0.045 + t * 0.06, 0);
        p.mat.opacity = 0.3 * (1 - t);
        p.mesh.scale.setScalar(0.7 + t * 0.9);
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // Sample data (illustrative, not live)
  const cities = [
    { name: 'Cairo',     cond: 'Sunny', c: 34, hi: 36, lo: 22, hum: 25, wind: 15, type: 'sun' },
    { name: 'London',    cond: 'Rain',  c: 13, hi: 15, lo: 9,  hum: 82, wind: 20, type: 'rain' },
    { name: 'Oslo',      cond: 'Snow',  c: -3, hi: -1, lo: -6, hum: 78, wind: 10, type: 'snow' },
  ];
  const DEG = '\u00b0';
  let unit = 'C';
  let selected = 0;
  const fmt = (c) => (unit === 'C' ? c + DEG + 'C' : Math.round(c * 9 / 5 + 32) + DEG + 'F');

  // Shared geometry and materials
  const sphereGeo = new THREE.SphereGeometry(1, 20, 12);
  const rayGeo = new THREE.BoxGeometry(0.02, 0.007, 0.007);
  const dropGeo = new THREE.CapsuleGeometry(0.003, 0.01, 4, 8);
  const flakeGeo = new THREE.SphereGeometry(0.005, 10, 8);
  const discGeo = new THREE.CylinderGeometry(0.07, 0.07, 0.008, 32);

  const sunMat = new THREE.MeshStandardMaterial({ color: 0xffc23d, emissive: 0xff9a00, emissiveIntensity: 0.8 });
  const rayMat = new THREE.MeshStandardMaterial({ color: 0xffd34d, emissive: 0xffa500, emissiveIntensity: 0.7 });
  const lightCloudMat = new THREE.MeshStandardMaterial({ color: 0xf2f5f8, roughness: 0.9 });
  const darkCloudMat = new THREE.MeshStandardMaterial({ color: 0x8b95a3, roughness: 0.9 });
  const dropMat = new THREE.MeshStandardMaterial({ color: 0x4aa3ff, emissive: 0x1d5fb0, emissiveIntensity: 0.4 });
  const flakeMat = new THREE.MeshStandardMaterial({ color: 0xffffff, emissive: 0xaad4ff, emissiveIntensity: 0.4 });

  function makeCloud(mat) {
    const g = new THREE.Group();
    const parts = [
      [-0.028, 0.0, 0.021], [0.0, 0.01, 0.028], [0.028, 0.0, 0.021], [0.0, -0.006, 0.022],
    ];
    for (const p of parts) {
      const m = new THREE.Mesh(sphereGeo, mat);
      m.position.set(p[0], p[1], 0);
      m.scale.setScalar(p[2]);
      g.add(m);
    }
    return g;
  }

  const cards = [];
  const panels = [];
  const raysGroups = [];
  const cores = [];
  const drops = [];
  const flakes = [];

  const xs = [-0.26, 0, 0.26];

  function cardMarkup(city, selectedFlag) {
    return `
      <style>
        .card { width: 400px; flex-direction: column; align-items: center; gap: 4px;
                padding-top: 12px; padding-bottom: 12px; padding-left: 12px; padding-right: 12px;
                border-radius: 18px; background-color: ${selectedFlag ? '#2c4268' : '#1f2228'}; }
        .name { color: #ffffff; font-size: 32px; font-weight: 700; }
        .temp { color: #ffd166; font-size: 48px; font-weight: 700; }
        .cond { color: #d0d5dc; font-size: 26px; }
      </style>
      <div class="card" id="card">
        <span class="name">${city.name}</span>
        <span class="temp" id="temp">${fmt(city.c)}</span>
        <span class="cond">${city.cond}</span>
      </div>`;
  }

  cities.forEach((city, i) => {
    const g = new THREE.Group();
    g.name = city.name + ' icon';
    g.position.set(xs[i], 0.34, 0);

    // Backdrop badge
    const discMat = new THREE.MeshStandardMaterial({ color: 0x2a2e35, roughness: 0.7, emissive: 0x2f6fdb, emissiveIntensity: 0 });
    const disc = new THREE.Mesh(discGeo, discMat);
    disc.rotation.x = Math.PI / 2;
    disc.position.z = -0.03;
    g.add(disc);

    if (city.type === 'sun') {
      const core = new THREE.Mesh(sphereGeo, sunMat);
      core.scale.setScalar(0.03);
      g.add(core);
      cores.push(core);
      const rg = new THREE.Group();
      for (let k = 0; k < 8; k++) {
        const a = (k / 8) * Math.PI * 2;
        const r = new THREE.Mesh(rayGeo, rayMat);
        r.position.set(Math.cos(a) * 0.05, Math.sin(a) * 0.05, 0);
        r.rotation.z = a;
        rg.add(r);
      }
      g.add(rg);
      raysGroups.push(rg);
    } else if (city.type === 'rain') {
      const cloud = makeCloud(darkCloudMat);
      cloud.position.y = 0.025;
      g.add(cloud);
      for (let k = 0; k < 7; k++) {
        const d = new THREE.Mesh(dropGeo, dropMat);
        d.rotation.z = 0.2;
        g.add(d);
        drops.push({ mesh: d, x: -0.03 + k * 0.01, phase: (k * 0.37) % 1 });
      }
    } else {
      const cloud = makeCloud(lightCloudMat);
      cloud.position.y = 0.025;
      g.add(cloud);
      for (let k = 0; k < 8; k++) {
        const f = new THREE.Mesh(flakeGeo, flakeMat);
        g.add(f);
        flakes.push({ mesh: f, x: -0.035 + k * 0.01, phase: (k * 0.29) % 1 });
      }
    }

    root.add(g);
    traits(g, { grab: true, onPress: () => select(i) });
    cards.push({ group: g, discMat });

    const p = ui(cardMarkup(city, i === 0), { width: 0.22, position: [xs[i], 0.19, 0] });
    root.add(p.object3D);
    panels.push(p);
  });

  // Detail panel with unit toggle
  const detail = ui(`
    <style>
      .box { width: 600px; flex-direction: row; align-items: center; gap: 20px;
             padding-top: 14px; padding-bottom: 14px; padding-left: 20px; padding-right: 20px;
             border-radius: 18px; background-color: #1a1d22; }
      .col { width: 400px; flex-direction: column; gap: 4px; }
      .head { color: #ffffff; font-size: 30px; font-weight: 700; }
      .line { color: #d7dbe2; font-size: 22px; }
      .hint { color: #8fa3bf; font-size: 20px; }
      .btn { width: 140px; padding-top: 14px; padding-bottom: 14px; padding-left: 10px; padding-right: 10px;
             border-radius: 14px; background-color: #2f6fdb; align-items: center; justify-content: center; }
      .btn-text { color: #ffffff; font-size: 24px; font-weight: 700; }
    </style>
    <div class="box">
      <div class="col">
        <span class="head" id="head"></span>
        <span class="line" id="line"></span>
        <span class="hint">Press a weather icon. Sample data.</span>
      </div>
      <button class="btn" id="unit"><span class="btn-text" id="unitText">Show ${DEG}F</span></button>
    </div>`, { width: 0.5, position: [0, 0.075, 0.08] });
  root.add(detail.object3D);

  function refreshDetail() {
    const c = cities[selected];
    detail.set('head', { text: c.name + ' - ' + c.cond });
    detail.set('line', {
      text: 'Now ' + fmt(c.c) + '. High ' + fmt(c.hi) + ', low ' + fmt(c.lo) +
            '. Humidity ' + c.hum + '%, wind ' + c.wind + ' km/h.',
    });
  }

  function select(i) {
    selected = i;
    cities.forEach((_, k) => {
      panels[k].set('card', { backgroundColor: k === i ? '#2c4268' : '#1f2228' });
      cards[k].discMat.emissiveIntensity = k === i ? 0.5 : 0;
    });
    refreshDetail();
  }

  detail.on('unit', 'click', () => {
    unit = unit === 'C' ? 'F' : 'C';
    detail.set('unitText', { text: 'Show ' + DEG + (unit === 'C' ? 'F' : 'C') });
    cities.forEach((c, k) => panels[k].set('temp', { text: fmt(c.c) }));
    refreshDetail();
  });

  select(0);

  return {
    root,
    update(time, delta) {
      for (let i = 0; i < raysGroups.length; i++) raysGroups[i].rotation.z += delta * 0.3;
      for (let i = 0; i < cores.length; i++) cores[i].scale.setScalar(0.03 * (1 + Math.sin(time * 2) * 0.04));
      for (let i = 0; i < drops.length; i++) {
        const d = drops[i];
        const u = (time * 0.15 + d.phase) % 1;
        d.mesh.position.set(d.x, -0.02 - u * 0.05, 0.005);
      }
      for (let i = 0; i < flakes.length; i++) {
        const f = flakes[i];
        const u = (time * 0.07 + f.phase) % 1;
        f.mesh.position.set(f.x + Math.sin(time * 1.5 + f.phase * 6) * 0.005, -0.02 - u * 0.05, 0.005);
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------- Plant (pot, soil, stem, leaves) ----------
  const plant = new THREE.Group();
  plant.name = 'Plant';
  root.add(plant);

  const potMat = new THREE.MeshStandardMaterial({ color: 0xb5562f, roughness: 0.8 });
  const soilMat = new THREE.MeshStandardMaterial({ color: 0x4a3222, roughness: 1 });
  const greenMat = new THREE.MeshStandardMaterial({ color: 0x3fa34d, roughness: 0.6 });
  const stemMat = new THREE.MeshStandardMaterial({ color: 0x2f7d3a, roughness: 0.7 });

  const pot = new THREE.Mesh(new THREE.CylinderGeometry(0.045, 0.035, 0.07, 24), potMat);
  pot.name = 'Pot';
  pot.position.set(0, 0.035, 0);
  plant.add(pot);

  const soil = new THREE.Mesh(new THREE.CylinderGeometry(0.043, 0.043, 0.004, 24), soilMat);
  soil.name = 'Soil';
  soil.position.set(0, 0.071, 0);
  plant.add(soil);

  const stem = new THREE.Mesh(new THREE.CylinderGeometry(0.006, 0.008, 0.2, 12), stemMat);
  stem.name = 'Stem';
  stem.position.set(0, 0.17, 0);
  plant.add(stem);

  const leafGeo = new THREE.SphereGeometry(1, 16, 10);
  const leafDefs = [
    [-0.06, 0.15, 0.3],
    [0.06, 0.14, -0.3],
    [-0.06, 0.23, 0.3],
    [0.06, 0.25, -0.3],
  ];
  leafDefs.forEach((d, i) => {
    const leaf = new THREE.Mesh(leafGeo, greenMat);
    leaf.name = 'Leaf ' + (i + 1);
    leaf.scale.set(0.06, 0.012, 0.03);
    leaf.position.set(d[0], d[1], 0);
    leaf.rotation.z = d[2];
    plant.add(leaf);
  });
  const bud = new THREE.Mesh(new THREE.SphereGeometry(0.014, 12, 8), greenMat);
  bud.name = 'Bud';
  bud.position.set(0, 0.28, 0);
  plant.add(bud);

  // ---------- Sun ----------
  const sunMat = new THREE.MeshStandardMaterial({ color: 0xffc23d, emissive: 0xff9a00, emissiveIntensity: 0.9 });
  const sun = new THREE.Mesh(new THREE.SphereGeometry(0.04, 28, 16), sunMat);
  sun.name = 'Sun';
  sun.position.set(-0.3, 0.34, 0);
  root.add(sun);

  const glow = new THREE.Mesh(
    new THREE.SphereGeometry(0.055, 20, 12),
    new THREE.MeshBasicMaterial({ color: 0xffd25a, transparent: true, opacity: 0.25, depthWrite: false }),
  );
  glow.position.copy(sun.position);
  root.add(glow);

  // ---------- Arrows ----------
  const up = new THREE.Vector3(0, 1, 0);
  function makeArrow(name, from, to, color) {
    const dir = new THREE.Vector3().subVectors(to, from);
    const L = dir.length();
    dir.normalize();
    const g = new THREE.Group();
    g.name = name;
    g.position.copy(from);
    g.quaternion.setFromUnitVectors(up, dir);
    const mat = new THREE.MeshStandardMaterial({ color, emissive: color, emissiveIntensity: 0.5, roughness: 0.5 });
    const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.005, 0.005, L - 0.04, 10), mat);
    shaft.position.y = (L - 0.04) / 2;
    g.add(shaft);
    const head = new THREE.Mesh(new THREE.ConeGeometry(0.016, 0.04, 16), mat);
    head.position.y = L - 0.02;
    g.add(head);
    const hit = new THREE.Mesh(
      new THREE.CylinderGeometry(0.02, 0.02, L, 8),
      new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false }),
    );
    hit.position.y = L / 2;
    g.add(hit);
    root.add(g);
    return { group: g, mat, from: from.clone(), to: to.clone(), color };
  }

  const LIGHT = 0xffd23f, WATER = 0x3fa9f5, CO2 = 0xb0b7c3, O2 = 0x66e0b0;
  const arrows = [
    makeArrow('Light arrow', new THREE.Vector3(-0.24, 0.29, 0), new THREE.Vector3(-0.14, 0.22, 0), LIGHT),
    makeArrow('Water arrow', new THREE.Vector3(-0.33, 0.035, 0), new THREE.Vector3(-0.055, 0.035, 0), WATER),
    makeArrow('CO2 arrow', new THREE.Vector3(0.32, 0.14, 0), new THREE.Vector3(0.13, 0.14, 0), CO2),
    makeArrow('O2 arrow', new THREE.Vector3(0.12, 0.26, 0), new THREE.Vector3(0.32, 0.26, 0), O2),
  ];

  // ---------- Flowing particles (scenery) ----------
  const partGeo = new THREE.SphereGeometry(0.009, 10, 8);
  const particles = [];
  arrows.forEach((a, ai) => {
    const m = new THREE.MeshBasicMaterial({ color: a.color });
    for (let i = 0; i < 3; i++) {
      const p = new THREE.Mesh(partGeo, m);
      root.add(p);
      particles.push({ mesh: p, arrow: a, offset: i / 3, speed: ai === 0 ? 0.35 : 0.2 });
    }
  });

  // ---------- Labels ----------
  function label(text, color, pos) {
    const h = ui(`
      <style>
        .l { width: 200px; padding-top: 8px; padding-bottom: 8px; padding-left: 8px; padding-right: 8px;
             background-color: #1a1d22; border-radius: 10px; align-items: center; justify-content: center; }
        .t { color: ${color}; font-size: 24px; font-weight: 700; text-align: center; }
      </style>
      <div class="l"><span class="t">${text}</span></div>`, { width: 0.14, position: pos });
    root.add(h.object3D);
    return h;
  }
  label('LIGHT', '#ffd23f', [-0.25, 0.17, 0]);
  label('WATER (H2O)', '#5bb8ff', [-0.25, 0.09, 0]);
  label('CO2 IN', '#d3d9e3', [0.28, 0.09, 0]);
  label('O2 OUT', '#7febbb', [0.28, 0.32, 0]);

  // ---------- Info panel ----------
  const info = ui(`
    <style>
      .card { width: 500px; flex-direction: column; gap: 8px; padding-top: 16px; padding-bottom: 16px;
              padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 22px; height: 96px; }
      .row { flex-direction: row; align-items: center; justify-content: space-between; }
      .step { color: #8f98a6; font-size: 20px; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 18px; padding-right: 18px;
             border-radius: 12px; background-color: #2f9e55; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title" id="title">Photosynthesis</span>
      <span class="body" id="body">Plants turn light, water and CO2 into sugar and oxygen. Press an arrow or the Sun!</span>
      <div class="row">
        <span class="step" id="step">Overview</span>
        <button class="btn" id="next"><span class="btn-text">Next step</span></button>
      </div>
    </div>`, { width: 0.32, position: [0, 0.42, 0] });
  root.add(info.object3D);

  const steps = [
    { title: 'Photosynthesis', body: 'Plants turn light, water and CO2 into sugar and oxygen. Press an arrow or the Sun!', tag: 'Overview' },
    { title: '1. Light', body: 'Chlorophyll in the leaves absorbs sunlight. This is the energy that powers the process.', tag: 'Step 1 of 4' },
    { title: '2. Water (H2O)', body: 'Roots take up water from the soil. It travels up the stem to the leaves.', tag: 'Step 2 of 4' },
    { title: '3. Carbon dioxide (CO2)', body: 'Leaves take in CO2 from the air through tiny pores called stomata.', tag: 'Step 3 of 4' },
    { title: '4. Oxygen (O2)', body: 'Oxygen is released as a by-product. The plant keeps the glucose sugar as food.', tag: 'Step 4 of 4' },
    { title: 'The equation', body: '6 CO2 + 6 H2O + light -> C6H12O6 (glucose) + 6 O2', tag: 'Summary' },
  ];
  let step = 0;
  function setStep(s) {
    step = s;
    const d = steps[s];
    info.set('title', { text: d.title });
    info.set('body', { text: d.body });
    info.set('step', { text: d.tag });
  }
  info.on('next', 'click', () => setStep((step + 1) % steps.length));

  traits(sun, { onPress: () => setStep(1) });
  arrows.forEach((a, i) => traits(a.group, { onPress: () => setStep(i + 1) }));
  traits(plant, { onPress: () => setStep(5) });

  // ---------- Animation ----------
  return {
    root,
    update(time) {
      const pulse = 0.5 + 0.5 * Math.sin(time * 4);
      for (let i = 0; i < arrows.length; i++) {
        const a = arrows[i];
        let intensity = 0.5;
        let thick = 1;
        if (step >= 1 && step <= 4) {
          if (step - 1 === i) {
            intensity = 0.7 + 0.5 * pulse;
            thick = 1 + 0.5 * pulse;
          } else {
            intensity = 0.08;
          }
        }
        a.mat.emissiveIntensity = intensity;
        a.group.scale.set(thick, 1, thick);
      }
      sunMat.emissiveIntensity = step === 1 ? 0.9 + 0.6 * pulse : 0.9;
      glow.scale.setScalar(1 + 0.08 * Math.sin(time * 2) + (step === 1 ? 0.1 * pulse : 0));

      for (let i = 0; i < particles.length; i++) {
        const p = particles[i];
        const t = (time * p.speed + p.offset) % 1;
        p.mesh.position.lerpVectors(p.arrow.from, p.arrow.to, t);
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // Cut-away Earth. Radii are scaled from real values (Earth radius 6371 km -> 0.1 m),
  // except the crust, which is drawn thicker so it can be seen.
  const R = 0.1;
  const CENTER_Y = 0.2;
  const layers = [
    { key: 'crust', name: 'Crust', sub: '5-70 km thick', rIn: 0.0945, rOut: 0.1, color: 0x7a5c3a, hex: '#7a5c3a',
      info: 'The thin, solid rock skin we live on. Only 5-70 km thick: thinnest under the oceans, thickest under mountains. Drawn thicker than real scale here.',
      anchor: [0.0623, 0.0743], labelY: 0.37 },
    { key: 'mantle', name: 'Mantle', sub: '~2,900 km thick', rIn: 0.0546, rOut: 0.0945, color: 0xd9531e, hex: '#d9531e',
      info: 'Hot, dense rock about 2,900 km thick, roughly 84% of Earth\'s volume. It is solid but flows very slowly, which moves the tectonic plates above.',
      anchor: [0.065, 0.0375], labelY: 0.28 },
    { key: 'outer', name: 'Outer core', sub: '~2,300 km, liquid', rIn: 0.0191, rOut: 0.0546, color: 0xffa51f, hex: '#ffa51f',
      info: 'Liquid iron and nickel, about 2,300 km thick, at roughly 4,000-5,000 °C. Its swirling flow generates Earth\'s magnetic field.',
      anchor: [0.0364, -0.0064], labelY: 0.19 },
    { key: 'inner', name: 'Inner core', sub: 'radius ~1,220 km, solid', rIn: 0, rOut: 0.0191, color: 0xfff0a0, hex: '#fff0a0',
      info: 'A solid ball of iron and nickel with a radius of about 1,220 km and roughly 5,200 °C. Enormous pressure keeps it solid despite the heat.',
      anchor: [0.007, -0.007], labelY: 0.10 },
  ];

  const globe = new THREE.Group();
  globe.name = 'CutawayEarth';
  globe.position.set(0, CENTER_Y, 0);
  root.add(globe);
  traits(globe, { grab: true });

  // The removed wedge is the front-right quadrant (x>0, z>0): phi from PI/2 to PI.
  const phiStart = Math.PI;
  const phiLength = Math.PI * 1.5;

  layers.forEach((L) => {
    L.mat = new THREE.MeshStandardMaterial({
      color: L.color, roughness: 0.7, metalness: 0.0,
      emissive: L.color, emissiveIntensity: 0.0, side: THREE.DoubleSide,
    });
    const shell = new THREE.Mesh(new THREE.SphereGeometry(L.rOut, 48, 24, phiStart, phiLength), L.mat);
    shell.name = L.name + ' shell';
    globe.add(shell);

    // Two flat cut faces (half rings / half disc) so the wedge shows each layer's cross-section.
    const g1 = L.rIn > 0
      ? new THREE.RingGeometry(L.rIn, L.rOut, 48, 1, -Math.PI / 2, Math.PI)
      : new THREE.CircleGeometry(L.rOut, 32, -Math.PI / 2, Math.PI);
    const face1 = new THREE.Mesh(g1, L.mat);
    face1.name = L.name + ' cut face A';
    globe.add(face1);
    const g2 = g1.clone();
    g2.rotateY(-Math.PI / 2);
    const face2 = new THREE.Mesh(g2, L.mat);
    face2.name = L.name + ' cut face B';
    globe.add(face2);
  });

  // Anchor dots (on the globe) and leader lines (in root space, updated each frame).
  const dotMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
  const dotGeo = new THREE.SphereGeometry(0.004, 12, 8);
  const lineMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
  const lineGeo = new THREE.BoxGeometry(0.0016, 0.0016, 1);
  const LABEL_X = 0.26;
  layers.forEach((L) => {
    L.anchorLocal = new THREE.Vector3(L.anchor[0], L.anchor[1], 0.002);
    const dot = new THREE.Mesh(dotGeo, dotMat);
    dot.position.copy(L.anchorLocal);
    globe.add(dot);
    L.line = new THREE.Mesh(lineGeo, lineMat);
    root.add(L.line);
    L.labelLocal = new THREE.Vector3(LABEL_X - 0.104, L.labelY, 0.003);
  });

  // Label panels (one per layer, each is a button).
  const labelStyle = `
    <style>
      .lbl { width: 300px; flex-direction: row; align-items: center; gap: 12px;
             padding-top: 10px; padding-bottom: 10px; padding-left: 12px; padding-right: 12px;
             border-radius: 14px; background-color: #25292f; }
      .bar { width: 12px; height: 56px; border-radius: 6px; }
      .col { flex-direction: column; gap: 2px; }
      .nm { color: #ffffff; font-size: 28px; font-weight: 700; }
      .sb { color: #c9ced6; font-size: 22px; }
    </style>`;
  layers.forEach((L) => {
    L.panel = ui(`${labelStyle}
      <button class="lbl" id="b_${L.key}">
        <div class="bar" style="background-color: ${L.hex};"></div>
        <div class="col">
          <span class="nm">${L.name}</span>
          <span class="sb">${L.sub}</span>
        </div>
      </button>`, { width: 0.2, position: [LABEL_X, L.labelY, 0] });
    root.add(L.panel.object3D);
  });

  // Info panel.
  const info = ui(`
    <style>
      .card { width: 440px; flex-direction: column; gap: 12px; padding-top: 18px; padding-bottom: 18px;
              padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 24px; }
      .note { color: #9aa1ac; font-size: 22px; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px;
             border-radius: 12px; background-color: #2f6fdb; align-items: center; justify-content: center; }
      .btn-text { color: #ffffff; font-size: 24px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title" id="iname">Layers of the Earth</span>
      <span class="body" id="ibody">Press a layer name to highlight it. Pinch the globe to move it.</span>
      <span class="note">Cut-away view. Crust exaggerated.</span>
      <button class="btn" id="reset"><span class="btn-text">Clear selection</span></button>
    </div>`, { width: 0.25, position: [-0.27, 0.2, 0], rotationY: 0.15 });
  root.add(info.object3D);

  let selected = -1;
  function select(i) {
    selected = i;
    layers.forEach((L, k) => {
      L.mat.emissiveIntensity = 0;
      L.panel.set('b_' + L.key, { backgroundColor: k === i ? '#3d4554' : '#25292f' });
    });
    if (i < 0) {
      info.set('iname', { text: 'Layers of the Earth', color: '#ffffff' });
      info.set('ibody', { text: 'Press a layer name to highlight it. Pinch the globe to move it.' });
    } else {
      info.set('iname', { text: layers[i].name, color: layers[i].hex });
      info.set('ibody', { text: layers[i].info });
    }
  }
  layers.forEach((L, i) => L.panel.on('b_' + L.key, 'click', () => select(i)));
  info.on('reset', 'click', () => select(-1));

  const a = new THREE.Vector3();
  const b = new THREE.Vector3();
  const m = new THREE.Vector3();

  return {
    root,
    update(time) {
      globe.updateWorldMatrix(true, false);
      if (selected >= 0) {
        layers[selected].mat.emissiveIntensity = 0.3 + 0.2 * Math.sin(time * 3);
      }
      for (let i = 0; i < layers.length; i++) {
        const L = layers[i];
        a.copy(L.anchorLocal);
        globe.localToWorld(a);
        b.copy(L.labelLocal);
        root.localToWorld(b);
        m.copy(a).add(b).multiplyScalar(0.5);
        root.worldToLocal(m);
        L.line.position.copy(m);
        L.line.updateWorldMatrix(true, false);
        L.line.lookAt(b);
        L.line.scale.set(1, 1, a.distanceTo(b));
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------- Plant ----------
  const potMat = new THREE.MeshStandardMaterial({ color: 0xb5651d, roughness: 0.8 });
  const pot = new THREE.Mesh(new THREE.CylinderGeometry(0.045, 0.035, 0.06, 24), potMat);
  pot.name = 'Pot';
  pot.position.set(0, 0.03, 0);
  root.add(pot);

  const soil = new THREE.Mesh(
    new THREE.CylinderGeometry(0.042, 0.042, 0.005, 24),
    new THREE.MeshStandardMaterial({ color: 0x4a2f1b, roughness: 1 }),
  );
  soil.position.set(0, 0.06, 0);
  root.add(soil);

  const stem = new THREE.Mesh(
    new THREE.CylinderGeometry(0.007, 0.01, 0.19, 12),
    new THREE.MeshStandardMaterial({ color: 0x2e7d32, roughness: 0.7 }),
  );
  stem.name = 'Stem';
  stem.position.set(0, 0.155, 0);
  root.add(stem);

  const leafMat = new THREE.MeshStandardMaterial({
    color: 0x3cb043, roughness: 0.6, emissive: 0xffc800, emissiveIntensity: 0,
  });
  const leafGeo = new THREE.SphereGeometry(1, 20, 10);
  const leafDefs = [
    [-0.045, 0.12, 0.35],
    [0.045, 0.16, -0.35],
    [-0.04, 0.21, 0.35],
    [0.045, 0.235, -0.35],
  ];
  leafDefs.forEach((d, i) => {
    const leaf = new THREE.Mesh(leafGeo, leafMat);
    leaf.name = 'Leaf' + (i + 1);
    leaf.scale.set(0.05, 0.01, 0.026);
    leaf.position.set(d[0], d[1], 0);
    leaf.rotation.z = d[2];
    root.add(leaf);
  });

  // ---------- Sun ----------
  const sunMat = new THREE.MeshStandardMaterial({ color: 0xffc23d, emissive: 0xff9a00, emissiveIntensity: 0.9 });
  const sun = new THREE.Mesh(new THREE.SphereGeometry(0.04, 32, 16), sunMat);
  sun.name = 'Sun';
  sun.position.set(-0.3, 0.37, 0);
  root.add(sun);
  const glow = new THREE.Mesh(
    new THREE.SphereGeometry(0.055, 24, 12),
    new THREE.MeshBasicMaterial({ color: 0xffd36b, transparent: true, opacity: 0.25 }),
  );
  sun.add(glow);

  // ---------- Arrows ----------
  const UP = new THREE.Vector3(0, 1, 0);
  const shaftGeo = new THREE.CylinderGeometry(0.006, 0.006, 1, 10);
  const headGeo = new THREE.ConeGeometry(0.016, 0.034, 14);
  const partGeo = new THREE.SphereGeometry(0.008, 12, 8);

  function makeArrow(key, name, fromArr, toArr, color) {
    const from = new THREE.Vector3(...fromArr);
    const to = new THREE.Vector3(...toArr);
    const dir = to.clone().sub(from);
    const len = dir.length();
    dir.normalize();
    const mat = new THREE.MeshStandardMaterial({
      color, emissive: color, emissiveIntensity: 0.15, roughness: 0.5,
    });
    const group = new THREE.Group();
    group.name = name;
    group.position.copy(from);
    group.quaternion.setFromUnitVectors(UP, dir);
    const shaftLen = len - 0.034;
    const shaft = new THREE.Mesh(shaftGeo, mat);
    shaft.scale.set(1, shaftLen, 1);
    shaft.position.y = shaftLen / 2;
    group.add(shaft);
    const head = new THREE.Mesh(headGeo, mat);
    head.position.y = len - 0.017;
    group.add(head);
    root.add(group);

    const pmat = new THREE.MeshBasicMaterial({ color });
    const particles = [];
    for (let i = 0; i < 3; i++) {
      const p = new THREE.Mesh(partGeo, pmat);
      root.add(p);
      particles.push({ mesh: p, phase: i / 3 });
    }
    return { key, group, mat, from, dir, len, particles };
  }

  const arrows = {
    light: makeArrow('light', 'LightArrow', [-0.25, 0.32, 0], [-0.1, 0.22, 0], 0xffd93d),
    water: makeArrow('water', 'WaterArrow', [-0.3, 0.04, 0], [-0.06, 0.04, 0], 0x3fa7ff),
    co2: makeArrow('co2', 'CO2Arrow', [0.3, 0.12, 0], [0.11, 0.165, 0], 0xb8b8b8),
    oxygen: makeArrow('oxygen', 'OxygenArrow', [0.11, 0.255, 0], [0.3, 0.29, 0], 0xff6b6b),
  };

  // Water drops rising inside the stem
  const dropMat = new THREE.MeshBasicMaterial({ color: 0x3fa7ff });
  const drops = [];
  for (let i = 0; i < 3; i++) {
    const d = new THREE.Mesh(partGeo, dropMat);
    d.scale.setScalar(0.7);
    root.add(d);
    drops.push({ mesh: d, phase: i / 3 });
  }

  // ---------- Labels ----------
  function label(text, color, pos) {
    const h = ui(`
      <style>
        .l { width: 210px; padding-top: 8px; padding-bottom: 8px; padding-left: 10px; padding-right: 10px;
             border-radius: 12px; background-color: #1f2228; align-items: center; justify-content: center; }
        .t { color: ${color}; font-size: 24px; font-weight: 700; text-align: center; }
      </style>
      <div class="l"><span class="t">${text}</span></div>`, { width: 0.12, position: pos });
    root.add(h.object3D);
    return h;
  }
  label('Light', '#ffd93d', [-0.28, 0.235, 0]);
  label('Water (H2O)', '#6cc0ff', [-0.28, 0.095, 0]);
  label('CO2', '#d0d0d0', [0.32, 0.175, 0]);
  label('Oxygen (O2)', '#ff8a8a', [0.32, 0.235, 0]);

  // ---------- Info panel ----------
  const info = ui(`
    <style>
      .card { width: 560px; flex-direction: column; gap: 10px; padding-top: 16px; padding-bottom: 16px;
              padding-left: 20px; padding-right: 20px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 22px; }
      .row { flex-direction: row; gap: 8px; }
      .btn { padding-top: 8px; padding-bottom: 8px; padding-left: 12px; padding-right: 12px;
             border-radius: 10px; background-color: #3a3f48; }
      .bt { color: #ffffff; font-size: 20px; font-weight: 700; }
      .eq { color: #9fe3a5; font-size: 20px; }
    </style>
    <div class="card">
      <span class="title">Photosynthesis</span>
      <span class="body" id="txt">Plants turn light, water and CO2 into sugar and oxygen. Press an arrow or a button below. Press the Sun to switch light on or off.</span>
      <div class="row">
        <button class="btn" id="b_light"><span class="bt">Light</span></button>
        <button class="btn" id="b_water"><span class="bt">Water</span></button>
        <button class="btn" id="b_co2"><span class="bt">CO2</span></button>
        <button class="btn" id="b_oxygen"><span class="bt">Oxygen</span></button>
        <button class="btn" id="b_sugar"><span class="bt">Sugar</span></button>
      </div>
      <span class="eq">6 CO2 + 6 H2O + light -> C6H12O6 + 6 O2</span>
    </div>`, { width: 0.36, position: [0, 0.4, -0.05] });
  root.add(info.object3D);

  const texts = {
    light: 'Light: chlorophyll in the leaves absorbs sunlight. This energy powers the whole process.',
    water: 'Water: roots take up water from the soil and it travels up the stem to the leaves.',
    co2: 'Carbon dioxide: CO2 from the air enters the leaf through tiny pores called stomata.',
    oxygen: 'Oxygen: O2 is a by-product. It leaves the leaf through the stomata into the air.',
    sugar: 'Sugar: the plant builds glucose (C6H12O6) from CO2 and water. It uses it for energy and growth.',
  };
  const offText = 'The light is off, so the leaves cannot make sugar or oxygen. Press the Sun to switch it on again.';
  const keys = ['light', 'water', 'co2', 'oxygen', 'sugar'];
  let selected = null;
  let lightOn = true;

  function refresh() {
    if (!lightOn) info.set('txt', { text: offText });
    else if (selected) info.set('txt', { text: texts[selected] });
    keys.forEach((k) => info.set('b_' + k, { backgroundColor: k === selected ? '#2f6fdb' : '#3a3f48' }));
  }
  function select(k) {
    selected = k;
    refresh();
  }
  keys.forEach((k) => info.on('b_' + k, 'click', () => select(k)));

  traits(sun, {
    onPress: () => {
      lightOn = !lightOn;
      refresh();
      if (lightOn && !selected) {
        info.set('txt', { text: 'Light is on. Plants turn light, water and CO2 into sugar and oxygen.' });
      }
    },
  });
  ['light', 'water', 'co2', 'oxygen'].forEach((k) => {
    traits(arrows[k].group, { onPress: () => select(k) });
  });

  // ---------- Animation ----------
  let flow = 1;
  const green = new THREE.Color(0x3cb043);
  const dull = new THREE.Color(0x8a9a58);
  const tmp = new THREE.Vector3();

  function moveParticles(a, time, speed, visible) {
    for (let i = 0; i < a.particles.length; i++) {
      const p = a.particles[i];
      p.mesh.visible = visible;
      if (!visible) continue;
      const t = (time * speed + p.phase) % 1;
      tmp.copy(a.dir).multiplyScalar(t * a.len).add(a.from);
      p.mesh.position.copy(tmp);
    }
  }

  return {
    root,
    update(time, delta) {
      flow += ((lightOn ? 1 : 0) - flow) * Math.min(1, delta * 3);

      sunMat.emissiveIntensity = lightOn ? 0.9 : 0.1;
      glow.visible = lightOn;
      arrows.light.group.visible = lightOn;
      leafMat.color.lerpColors(dull, green, flow);

      const pulse = 0.55 + 0.4 * Math.sin(time * 4);
      keys.forEach((k) => {
        if (k === 'sugar') return;
        arrows[k].mat.emissiveIntensity = selected === k ? pulse : 0.15;
      });
      leafMat.emissiveIntensity = selected === 'sugar' && lightOn ? 0.25 * pulse : 0;

      const active = flow > 0.05;
      moveParticles(arrows.light, time, 0.35, lightOn);
      moveParticles(arrows.water, time, 0.25 * flow, active);
      moveParticles(arrows.co2, time, 0.25 * flow, active);
      moveParticles(arrows.oxygen, time, 0.25 * flow, active);

      for (let i = 0; i < drops.length; i++) {
        const d = drops[i];
        d.mesh.visible = active;
        const t = (time * 0.2 * flow + d.phase) % 1;
        d.mesh.position.set(0, 0.07 + 0.13 * t, 0.012);
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------- Quiz data ----------
  const questions = [[6, 7], [8, 4], [9, 3], [7, 8], [5, 9]];
  let qi = 0;
  let score = 0;
  let answered = false;
  let finished = false;
  let correctIndex = 0;
  let options = [0, 0, 0, 0];
  const results = [0, 0, 0, 0, 0]; // 0 = pending, 1 = right, -1 = wrong

  // ---------- Dot board (visualizes a x b as an array) ----------
  const plate = new THREE.Mesh(
    new THREE.BoxGeometry(0.27, 0.27, 0.012),
    new THREE.MeshStandardMaterial({ color: 0x2a2e35, roughness: 0.7 }),
  );
  plate.name = 'DotBoard';
  plate.position.set(-0.27, 0.2, 0);
  root.add(plate);
  traits(plate, { grab: true });

  const MAX = 81;
  const cell = 0.026;
  const dots = new THREE.InstancedMesh(
    new THREE.SphereGeometry(0.0095, 16, 8),
    new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.4 }),
    MAX,
  );
  dots.name = 'Dots';
  dots.position.z = 0.012;
  plate.add(dots);

  const dummy = new THREE.Object3D();
  const tmpColor = new THREE.Color();

  function layoutDots(a, b) {
    // a rows, b columns
    let n = 0;
    for (let r = 0; r < a; r++) {
      tmpColor.setHSL((r * 0.11 + 0.55) % 1, 0.75, 0.6);
      for (let c = 0; c < b; c++) {
        dummy.position.set((c - (b - 1) / 2) * cell, ((a - 1) / 2 - r) * cell, 0);
        dummy.updateMatrix();
        dots.setMatrixAt(n, dummy.matrix);
        dots.setColorAt(n, tmpColor);
        n++;
      }
    }
    dots.count = n;
    dots.instanceMatrix.needsUpdate = true;
    if (dots.instanceColor) dots.instanceColor.needsUpdate = true;
  }

  // ---------- Progress pips ----------
  const pipGeo = new THREE.SphereGeometry(0.018, 20, 12);
  const pips = [];
  const pipMats = [];
  const popTime = [-10, -10, -10, -10, -10];
  for (let i = 0; i < 5; i++) {
    const m = new THREE.MeshStandardMaterial({ color: 0x6b7380, roughness: 0.4 });
    const p = new THREE.Mesh(pipGeo, m);
    p.name = 'Pip' + (i + 1);
    p.position.set(-0.27 + (i - 2) * 0.06, 0.37, 0);
    root.add(p);
    pips.push(p);
    pipMats.push(m);
  }

  function refreshPips() {
    for (let i = 0; i < 5; i++) {
      const r = results[i];
      const col = r === 1 ? 0x35c46a : r === -1 ? 0xe05252 : 0x6b7380;
      pipMats[i].color.setHex(col);
      pipMats[i].emissive.setHex(r === 0 ? 0x000000 : col);
      pipMats[i].emissiveIntensity = r === 0 ? 0 : 0.5;
    }
  }

  // ---------- UI panel ----------
  const panel = ui(`
    <style>
      .card { width: 500px; flex-direction: column; gap: 12px; padding-top: 20px; padding-bottom: 20px;
              padding-left: 22px; padding-right: 22px; border-radius: 20px; background-color: #1f2228; }
      .top { flex-direction: row; justify-content: space-between; align-items: center; }
      .small { color: #aab2bf; font-size: 24px; font-weight: 700; }
      .score { color: #ffd34d; font-size: 26px; font-weight: 700; }
      .q { color: #ffffff; font-size: 52px; font-weight: 700; text-align: center; }
      .hint { color: #d7dbe2; font-size: 22px; text-align: center; }
      .grid { flex-direction: column; gap: 14px; }
      .row { flex-direction: row; gap: 14px; }
      .ans { width: 215px; height: 64px; border-radius: 14px; background-color: #2f6fdb;
             align-items: center; justify-content: center; }
      .ans-t { color: #ffffff; font-size: 32px; font-weight: 700; text-align: center; }
      .fb { color: #d7dbe2; font-size: 26px; font-weight: 700; text-align: center; }
      .next { height: 56px; border-radius: 14px; background-color: #8a5cf0;
              align-items: center; justify-content: center; }
      .next-t { color: #ffffff; font-size: 26px; font-weight: 700; }
    </style>
    <div class="card">
      <div class="top">
        <span class="small" id="prog">Question 1 of 5</span>
        <span class="score" id="score">Score: 0</span>
      </div>
      <span class="q" id="q">6 x 7 = ?</span>
      <span class="hint" id="hint">Count the dots on the board.</span>
      <div class="grid" id="grid">
        <div class="row">
          <button class="ans" id="b0"><span class="ans-t" id="t0">0</span></button>
          <button class="ans" id="b1"><span class="ans-t" id="t1">0</span></button>
        </div>
        <div class="row">
          <button class="ans" id="b2"><span class="ans-t" id="t2">0</span></button>
          <button class="ans" id="b3"><span class="ans-t" id="t3">0</span></button>
        </div>
      </div>
      <span class="fb" id="fb">Pick an answer.</span>
      <button class="next" id="next"><span class="next-t" id="nextt">Next question</span></button>
    </div>`, { width: 0.4, position: [0.12, 0.22, 0] });
  root.add(panel.object3D);

  const BLUE = '#2f6fdb';
  const GREEN = '#2e9e57';
  const RED = '#c9444a';
  const GREY = '#3a4049';

  function loadQuestion() {
    const [a, b] = questions[qi];
    const raw = [a * b, a * (b + 1), a * (b - 1), (a + 1) * b];
    const shift = (qi * 3 + 1) % 4;
    options = [];
    for (let i = 0; i < 4; i++) options.push(raw[(i + shift) % 4]);
    correctIndex = options.indexOf(a * b);
    answered = false;
    dots.visible = true;
    layoutDots(a, b);
    panel.set('prog', { text: 'Question ' + (qi + 1) + ' of 5' });
    panel.set('q', { text: a + ' x ' + b + ' = ?' });
    panel.set('hint', { text: a + ' rows of ' + b + ' dots. Count them or multiply!' });
    panel.set('grid', { display: 'flex' });
    for (let i = 0; i < 4; i++) {
      panel.set('t' + i, { text: String(options[i]) });
      panel.set('b' + i, { backgroundColor: BLUE });
    }
    panel.set('fb', { text: 'Pick an answer.', color: '#d7dbe2' });
    panel.set('next', { display: 'none' });
  }

  function answer(i) {
    if (answered || finished) return;
    answered = true;
    const ok = i === correctIndex;
    const [a, b] = questions[qi];
    results[qi] = ok ? 1 : -1;
    popTime[qi] = now;
    if (ok) score++;
    refreshPips();
    panel.set('score', { text: 'Score: ' + score });
    for (let k = 0; k < 4; k++) {
      if (k === correctIndex) panel.set('b' + k, { backgroundColor: GREEN });
      else if (k === i) panel.set('b' + k, { backgroundColor: RED });
      else panel.set('b' + k, { backgroundColor: GREY });
    }
    panel.set('fb', {
      text: ok ? 'Correct! ' + a + ' x ' + b + ' = ' + (a * b)
               : 'Not quite. ' + a + ' x ' + b + ' = ' + (a * b),
      color: ok ? '#6fe39a' : '#ff8a8f',
    });
    panel.set('nextt', { text: qi === 4 ? 'See results' : 'Next question' });
    panel.set('next', { display: 'flex' });
  }

  function showResults() {
    finished = true;
    dots.visible = false;
    panel.set('prog', { text: 'Finished!' });
    panel.set('q', { text: score + ' / 5' });
    const msg = score === 5 ? 'Perfect score! Great work!'
      : score >= 3 ? 'Nice job! Try again for a perfect round.'
      : 'Keep practicing. You can do it!';
    panel.set('hint', { text: msg });
    panel.set('grid', { display: 'none' });
    panel.set('fb', { text: 'Green = right, red = wrong.', color: '#d7dbe2' });
    panel.set('nextt', { text: 'Play again' });
    panel.set('next', { display: 'flex' });
  }

  function restart() {
    qi = 0;
    score = 0;
    finished = false;
    for (let i = 0; i < 5; i++) results[i] = 0;
    refreshPips();
    panel.set('score', { text: 'Score: 0' });
    loadQuestion();
  }

  for (let i = 0; i < 4; i++) panel.on('b' + i, 'click', () => answer(i));
  panel.on('next', 'click', () => {
    if (finished) { restart(); return; }
    if (!answered) return;
    if (qi === 4) { showResults(); return; }
    qi++;
    loadQuestion();
  });

  let now = 0;
  refreshPips();
  loadQuestion();

  return {
    root,
    update(time) {
      now = time;
      for (let i = 0; i < 5; i++) {
        const t = time - popTime[i];
        const s = t >= 0 && t < 0.5 ? 1 + 0.5 * Math.sin((t / 0.5) * Math.PI) : 1;
        pips[i].scale.setScalar(s);
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
