    orb.name = 'ProgressOrb' + (i + 1);
    orb.position.set((i - 2) * 0.07, 0.06, 0.04);
    root.add(orb);
    orbs.push(orb);
    orbMats.push(mat);
  }

  // Trophy (shown when score is 4 or 5)
  const trophy = new THREE.Group();
  trophy.name = 'Trophy';
  const gold = new THREE.MeshStandardMaterial({ color: 0xffc23d, emissive: 0x6b4a00, emissiveIntensity: 0.5, metalness: 0.7, roughness: 0.3 });
  const cup = new THREE.Mesh(new THREE.CylinderGeometry(0.04, 0.022, 0.06, 24, 1, true), gold);
  cup.material.side = THREE.DoubleSide;
  cup.position.y = 0.07;
  const stem = new THREE.Mesh(new THREE.CylinderGeometry(0.008, 0.008, 0.04, 12), gold);
  stem.position.y = 0.03;
  const base = new THREE.Mesh(new THREE.CylinderGeometry(0.03, 0.035, 0.015, 24), gold);
  base.position.y = 0.008;
  trophy.add(cup, stem, base);
  trophy.position.set(0.33, 0.04, 0.05);
  trophy.visible = false;
  root.add(trophy);

  let index = 0;
  let score = 0;
  let answered = false;
  let finished = false;

  function showQuestion() {
    const item = questions[index];
    panel.set('count', { text: 'Question ' + (index + 1) + ' of 5' });
    panel.set('question', { text: item.q });
    for (let i = 0; i < 4; i++) {
      panel.set('a' + i + 't', { text: String(item.opts[i]) });
      panel.set('a' + i, { backgroundColor: BLUE });
    }
    panel.set('feedback', { text: 'Poke or pinch an answer.', color: '#d7dbe2' });
    panel.set('next', { display: 'none' });
    answered = false;
  }

  function restart() {
    index = 0;
    score = 0;
    finished = false;
    for (let i = 0; i < 5; i++) orbMats[i].color.set(0x777c85);
    trophy.visible = false;
    panel.set('score', { text: 'Score 0 / 5' });
    showQuestion();
  }

  function choose(i) {
    if (answered || finished) return;
    answered = true;
    const item = questions[index];
    if (i === item.correct) {
      score++;
      orbMats[index].color.set(0x2ecc71);
      panel.set('a' + i, { backgroundColor: GREEN });
      panel.set('feedback', { text: 'Correct! ' + item.q.replace('?', String(item.opts[item.correct])), color: '#6ee59a' });
