      orbMats[index].color.set(0xe74c3c);
      panel.set('a' + i, { backgroundColor: RED });
      panel.set('a' + item.correct, { backgroundColor: GREEN });
      panel.set('feedback', { text: 'Not quite. ' + item.q.replace('?', String(item.opts[item.correct])), color: '#ff8a7d' });
    }
    panel.set('score', { text: 'Score ' + score + ' / 5' });
    panel.set('nextt', { text: index === 4 ? 'See result' : 'Next question' });
    panel.set('next', { display: 'flex' });
  }

  for (let i = 0; i < 4; i++) {
    panel.on('a' + i, 'click', () => choose(i));
  }

  panel.on('next', 'click', () => {
    if (finished) {
      restart();
      return;
    }
    if (!answered) return;
    if (index === 4) {
      finished = true;
      let msg;
      if (score === 5) msg = 'Perfect! 5 out of 5!';
      else if (score >= 4) msg = 'Great job! ' + score + ' out of 5.';
      else if (score >= 2) msg = 'Good try: ' + score + ' out of 5.';
      else msg = 'Keep practicing: ' + score + ' out of 5.';
      panel.set('count', { text: 'Quiz finished' });
      panel.set('question', { text: score + ' / 5' });
      panel.set('feedback', { text: msg, color: '#ffd34d' });
      panel.set('nextt', { text: 'Play again' });
      for (let i = 0; i < 4; i++) panel.set('a' + i, { backgroundColor: '#3a3f48' });
      trophy.visible = score >= 4;
    } else {
      index++;
      showQuestion();
    }
  });

  showQuestion();

  return {
    root,
    update(time) {
      // Gentle pulse on the current orb; spin the trophy when earned
      for (let i = 0; i < 5; i++) {
        const s = (i === index && !finished) ? 1 + Math.sin(time * 4) * 0.08 : 1;
        orbs[i].scale.setScalar(s);
      }
      if (trophy.visible) trophy.rotation.y = time * 0.8;
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------- Atoms ----------
  const O_RADIUS = 0.035;
  const H_RADIUS = 0.025;
  const BOND_DIST = 0.09; // centers closer than this count as bonded

  const oxyMat = new THREE.MeshStandardMaterial({
    color: 0xe5484d, roughness: 0.4, emissive: 0xff3b30, emissiveIntensity: 0.1,
  });
  const hydMat = new THREE.MeshStandardMaterial({ color: 0xf2f4f8, roughness: 0.4 });

  const oxyGeo = new THREE.SphereGeometry(O_RADIUS, 32, 16);
  const hydGeo = new THREE.SphereGeometry(H_RADIUS, 24, 12);

  const startO = new THREE.Vector3(0, 0.12, 0);
  const startH = [
    new THREE.Vector3(-0.18, 0.1, 0.08),
    new THREE.Vector3(0.18, 0.1, 0.08),
    new THREE.Vector3(0.0, 0.09, 0.18),
  ];

  const oxygen = new THREE.Mesh(oxyGeo, oxyMat);
  oxygen.name = 'Oxygen';
  oxygen.position.copy(startO);
  root.add(oxygen);
  traits(oxygen, { grab: true });

  const hydrogens = [];
  for (let i = 0; i < 3; i++) {
    const h = new THREE.Mesh(hydGeo, hydMat);
    h.name = 'Hydrogen ' + (i + 1);
    h.position.copy(startH[i]);
    root.add(h);
    traits(h, { grab: true });
    hydrogens.push(h);
  }

  // ---------- Bonds (drawn live between oxygen and nearby hydrogens) ----------
  const bondGeo = new THREE.CylinderGeometry(0.008, 0.008, 1, 12);
  const bondMat = new THREE.MeshStandardMaterial({
    color: 0xc9ced6, roughness: 0.5, emissive: 0x000000,
  });
  const bonds = [];
  for (let i = 0; i < 3; i++) {
    const b = new THREE.Mesh(bondGeo, bondMat);
    b.name = 'Bond ' + (i + 1);
    b.visible = false;
    root.add(b);
    bonds.push(b);
  }

  const UP = new THREE.Vector3(0, 1, 0);
  const dir = new THREE.Vector3();
  const vA = new THREE.Vector3();
  const vB = new THREE.Vector3();

  // ---------- Info panel ----------
  const panel = ui(`
    <style>
      .card { width: 500px; flex-direction: column; gap: 12px; padding-top: 18px; padding-bottom: 18px;
              padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 24px; }
      .row { flex-direction: row; gap: 24px; }
      .red { color: #ff7a7f; font-size: 22px; font-weight: 700; }
      .white { color: #ffffff; font-size: 22px; font-weight: 700; }
      .result { color: #ffd479; font-size: 24px; font-weight: 700; }
      .btns { flex-direction: row; gap: 14px; }
      .btn { padding-top: 12px; padding-bottom: 12px; padding-left: 20px; padding-right: 20px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btn2 { padding-top: 12px; padding-bottom: 12px; padding-left: 20px; padding-right: 20px;
              border-radius: 12px; background-color: #434a55; }
      .btn-text { color: #ffffff; font-size: 24px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Build a water molecule</span>
      <span class="body">Grab the atoms and bring hydrogens next to the oxygen. Bonds appear when atoms touch.</span>
      <div class="row">
        <span class="red">Red = oxygen (O)</span>
        <span class="white">White = hydrogen (H)</span>
      </div>
      <span class="result" id="result">Press Check when you are ready.</span>
      <div class="btns">
        <button class="btn" id="check"><span class="btn-text">Check</span></button>
        <button class="btn2" id="reset"><span class="btn-text">Reset</span></button>
      </div>
    </div>`, { width: 0.34, position: [0, 0.36, -0.1] });
  root.add(panel.object3D);

  let lastTime = 0;
  let successUntil = -1;

  function setResult(text, good) {
    panel.set('result', { text, color: good ? '#6be28b' : '#ffd479' });
  }

  panel.on('check', 'click', () => {
    successUntil = -1;
    const bonded = [];
    for (let i = 0; i < hydrogens.length; i++) {
      if (hydrogens[i].position.distanceTo(oxygen.position) < BOND_DIST) bonded.push(hydrogens[i]);
    }
    const n = bonded.length;
    if (n === 0) {
      setResult('No bonds yet. Move the white hydrogen atoms right next to the red oxygen.', false);
    } else if (n === 1) {
      setResult('That is OH, a hydroxyl group. Oxygen needs two hydrogens: add one more.', false);
    } else if (n === 2) {
      vA.copy(bonded[0].position).sub(oxygen.position);
      vB.copy(bonded[1].position).sub(oxygen.position);
      const angle = THREE.MathUtils.radToDeg(vA.angleTo(vB));
      if (angle >= 85 && angle <= 130) {
        setResult('Yes, this is water, H2O! 2 H + 1 O. Your bend angle is ' + Math.round(angle) + '° (real: about 104.5°).', true);
        successUntil = lastTime + 4;
      } else {
        setResult('Right atoms, but water is bent at about 104.5°, and yours is ' + Math.round(angle) + '°. Adjust a hydrogen.', false);
      }
    } else {
      setResult('Three hydrogens on one oxygen would be H3O+ (hydronium), not water. Pull one H away.', false);
    }
  });

  panel.on('reset', 'click', () => {
    oxygen.position.copy(startO);
    for (let i = 0; i < hydrogens.length; i++) hydrogens[i].position.copy(startH[i]);
    successUntil = -1;
    setResult('Press Check when you are ready.', false);
  });

  return {
    root,
    update(time) {
      lastTime = time;

      // Draw bonds
      for (let i = 0; i < hydrogens.length; i++) {
        const h = hydrogens[i];
        const b = bonds[i];
        dir.copy(h.position).sub(oxygen.position);
        const len = dir.length();
        if (len < BOND_DIST && len > 0.0001) {
          b.visible = true;
          b.position.copy(oxygen.position).addScaledVector(dir, 0.5);
          b.scale.set(1, len, 1);
          dir.multiplyScalar(1 / len);
          b.quaternion.setFromUnitVectors(UP, dir);
        } else {
          b.visible = false;
        }
      }

      // Success glow
      if (time < successUntil) {
        oxyMat.emissiveIntensity = 0.5 + 0.4 * Math.sin(time * 6);
        bondMat.emissive.setHex(0x1f8a3a);
        bondMat.color.setHex(0x6be28b);
      } else {
        oxyMat.emissiveIntensity = 0.1;
        bondMat.emissive.setHex(0x000000);
        bondMat.color.setHex(0xc9ced6);
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------- Atoms ----------
  const R_O = 0.028;
  const R_H = 0.018;
  const geoO = new THREE.SphereGeometry(R_O, 28, 16);
  const geoH = new THREE.SphereGeometry(R_H, 24, 14);

  const defs = [
    { el: 'O', pos: [-0.28, 0.1, 0.1] },
    { el: 'O', pos: [-0.28, 0.1, -0.1] },
    { el: 'H', pos: [-0.12, 0.1, 0.15] },
    { el: 'H', pos: [-0.12, 0.1, 0.05] },
    { el: 'H', pos: [-0.12, 0.1, -0.05] },
    { el: 'H', pos: [-0.12, 0.1, -0.15] },
  ];

  const atoms = [];
  defs.forEach((d, i) => {
    const isO = d.el === 'O';
    const mat = new THREE.MeshStandardMaterial({
      color: isO ? 0xe03a3a : 0xf2f2f2,
      roughness: 0.4,
      emissive: 0x000000,
      emissiveIntensity: 0.0,
    });
    const mesh = new THREE.Mesh(isO ? geoO : geoH, mat);
    mesh.name = (isO ? 'Oxygen ' : 'Hydrogen ') + (i + 1);
    mesh.position.set(d.pos[0], d.pos[1], d.pos[2]);
    root.add(mesh);
    traits(mesh, { grab: true });
    atoms.push({ el: d.el, r: isO ? R_O : R_H, mesh, mat, home: d.pos });
  });

  // ---------- Build zone ring (decor) ----------
  const ring = new THREE.Mesh(
    new THREE.TorusGeometry(0.11, 0.003, 8, 48),
    new THREE.MeshBasicMaterial({ color: 0x5ec8ff }),
  );
  ring.rotation.x = Math.PI / 2;
  ring.position.set(0.0, 0.004, 0);
  root.add(ring);

  // ---------- Bonds ----------
  const bondGeo = new THREE.CylinderGeometry(1, 1, 1, 10);
  const bondMat = new THREE.MeshStandardMaterial({ color: 0xb9c0cc, roughness: 0.5 });
  const pairs = [];
  const bondMeshes = [];
  for (let i = 0; i < atoms.length; i++) {
    for (let j = i + 1; j < atoms.length; j++) {
      pairs.push([i, j]);
      const b = new THREE.Mesh(bondGeo, bondMat);
      b.visible = false;
      b.name = 'Bond';
      root.add(b);
      bondMeshes.push(b);
    }
  }
  const bonded = new Array(pairs.length).fill(false);
  const UP = new THREE.Vector3(0, 1, 0);
  const tmp = new THREE.Vector3();
  const BOND_GAP = 0.025;

  function computeBonds() {
    let mask = 0;
    for (let k = 0; k < pairs.length; k++) {
      const a = atoms[pairs[k][0]];
      const b = atoms[pairs[k][1]];
      const d = a.mesh.position.distanceTo(b.mesh.position);
      const isB = d < a.r + b.r + BOND_GAP;
      bonded[k] = isB;
      if (isB) mask |= (1 << k);
    }
    return mask;
  }

  // ---------- UI ----------
  const panel = ui(`
    <style>
      .card { width: 480px; flex-direction: column; gap: 12px; padding-top: 18px; padding-bottom: 18px;
              padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 22px; }
      .legend { color: #9fb4d0; font-size: 22px; }
      .result-box { padding-top: 12px; padding-bottom: 12px; padding-left: 14px; padding-right: 14px;
                    border-radius: 12px; background-color: #2a2e35; width: 436px; }
      .result { color: #d7dbe2; font-size: 24px; font-weight: 700; }
      .row { flex-direction: row; gap: 12px; }
      .check { padding-top: 12px; padding-bottom: 12px; padding-left: 18px; padding-right: 18px;
               border-radius: 12px; background-color: #2f9e5b; }
      .reset { padding-top: 12px; padding-bottom: 12px; padding-left: 18px; padding-right: 18px;
               border-radius: 12px; background-color: #4a505a; }
      .btn-text { color: #ffffff; font-size: 24px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Build a molecule</span>
      <span class="body">Pinch atoms and push them together until a bond appears. Can you build water?</span>
      <span class="legend">Red = oxygen (O), white = hydrogen (H)</span>
      <div class="result-box">
        <span class="result" id="result">Nothing built yet.</span>
      </div>
      <div class="row">
        <button class="check" id="check"><span class="btn-text">Check molecule</span></button>
        <button class="reset" id="reset"><span class="btn-text">Reset</span></button>
      </div>
    </div>`, { width: 0.32, position: [0.3, 0.2, -0.05], rotationY: -0.3 });
  root.add(panel.object3D);

  const GREEN = '#6fe39a';
  const RED = '#ff8a8a';
  const YELLOW = '#ffd36b';
  const NEUTRAL = '#d7dbe2';

  const names = {
    H2O: 'water',
    H2O2: 'hydrogen peroxide',
    H2: 'hydrogen gas',
    O2: 'oxygen gas',
    OH: 'a hydroxyl radical',
    H3O: 'a hydronium-like ion',
  };

  function formula(h, o) {
    return (h > 0 ? 'H' + (h > 1 ? h : '') : '') + (o > 0 ? 'O' + (o > 1 ? o : '') : '');
  }

  function findMolecules() {
    const parent = atoms.map((_, i) => i);
    const find = (x) => { while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; };
    for (let k = 0; k < pairs.length; k++) {
      if (bonded[k]) {
        const ra = find(pairs[k][0]);
        const rb = find(pairs[k][1]);
        if (ra !== rb) parent[ra] = rb;
      }
    }
    const groups = {};
    atoms.forEach((a, i) => {
      const r = find(i);
      if (!groups[r]) groups[r] = { o: 0, h: 0, n: 0, ids: [] };
      const g = groups[r];
      g.n++;
      g.ids.push(i);
      if (a.el === 'O') g.o++; else g.h++;
    });
    return Object.values(groups).filter((g) => g.n > 1);
  }

  let checked = false;
  let checkedMask = 0;

  function clearGlow() {
    for (const a of atoms) {
      a.mat.emissive.setHex(0x000000);
      a.mat.emissiveIntensity = 0;
    }
  }

  panel.on('check', 'click', () => {
    clearGlow();
    checkedMask = computeBonds();
    checked = true;
    const mols = findMolecules();
    if (mols.length === 0) {
      panel.set('result', { text: 'No bonds yet. Push atoms together until they connect.', color: NEUTRAL });
      return;
    }
    const waters = mols.filter((m) => m.o === 1 && m.h === 2);
    const others = mols.filter((m) => !(m.o === 1 && m.h === 2));
    for (const w of waters) {
      for (const id of w.ids) {
        atoms[id].mat.emissive.setHex(0x22cc66);
        atoms[id].mat.emissiveIntensity = 0.6;
      }
    }
    if (waters.length > 0 && others.length === 0) {
      const txt = waters.length > 1
        ? 'Yes! You built ' + waters.length + ' water molecules (H2O).'
        : 'Yes! You built water (H2O): 1 oxygen + 2 hydrogen.';
      panel.set('result', { text: txt, color: GREEN });
    } else if (waters.length > 0) {
      const o = others[0];
      const f = formula(o.h, o.o);
      panel.set('result', {
        text: 'Water (H2O) is there, but you also built ' + f + (names[f] ? ' (' + names[f] + ')' : '') + '.',
        color: YELLOW,
      });
    } else {
      const m = mols[0];
      const f = formula(m.h, m.o);
      let hint = ' Water needs 1 oxygen and 2 hydrogen.';
      if (m.o === 1 && m.h === 1) hint = ' Almost! Add one more hydrogen.';
      else if (m.o === 1 && m.h === 0) hint = ' Add hydrogen atoms.';
      panel.set('result', {
        text: 'Not water. You built ' + f + (names[f] ? ' (' + names[f] + ')' : '') + '.' + hint,
        color: RED,
      });
    }
  });

  panel.on('reset', 'click', () => {
    for (const a of atoms) {
      if (isGrabbed(a.mesh)) continue;
      a.mesh.position.set(a.home[0], a.home[1], a.home[2]);
    }
    clearGlow();
    checked = false;
    panel.set('result', { text: 'Nothing built yet.', color: NEUTRAL });
  });

  // ---------- Update ----------
  let lastMask = -1;
  return {
    root,
    update() {
      const mask = computeBonds();
      if (mask !== lastMask) {
        lastMask = mask;
        for (let k = 0; k < pairs.length; k++) {
          const bm = bondMeshes[k];
          bm.visible = bonded[k];
        }
        if (checked && mask !== checkedMask) {
          checked = false;
          clearGlow();
          panel.set('result', { text: 'Atoms changed. Press Check again.', color: NEUTRAL });
        }
      }
      for (let k = 0; k < pairs.length; k++) {
        if (!bonded[k]) continue;
        const a = atoms[pairs[k][0]].mesh.position;
        const b = atoms[pairs[k][1]].mesh.position;
        const bm = bondMeshes[k];
        tmp.copy(b).sub(a);
        const len = tmp.length();
        if (len < 1e-5) continue;
        tmp.divideScalar(len);
        bm.position.copy(a).addScaledVector(tmp, len * 0.5);
        bm.quaternion.setFromUnitVectors(UP, tmp);
        bm.scale.set(0.006, len, 0.006);
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const habits = [
    { name: 'Drink water', color: 0x4aa3ff },
    { name: 'Read 20 min', color: 0xb58cff },
    { name: 'Exercise',    color: 0xffa94a },
  ];
  const days = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
  const COLS = 7, ROWS = 3, STEP = 0.06, ROW_STEP = 0.1;

  // ---------- 3D tokens ----------
  const tokenGeo = new THREE.CylinderGeometry(0.022, 0.022, 0.012, 32);
  const offMat = new THREE.MeshStandardMaterial({ color: 0x3a3f48, roughness: 0.7 });
  const onMats = habits.map(h => new THREE.MeshStandardMaterial({
    color: h.color, emissive: h.color, emissiveIntensity: 0.45, roughness: 0.4,
  }));

  const state = [];
  const pop = [];
  const tokens = [];

  for (let h = 0; h < ROWS; h++) {
    for (let d = 0; d < COLS; d++) {
      const mesh = new THREE.Mesh(tokenGeo, offMat);
      mesh.rotation.x = Math.PI / 2;
      mesh.position.set((d - 3) * STEP, 0.3 - h * ROW_STEP, 0);
      mesh.name = `${habits[h].name} - ${days[d]}`;
      root.add(mesh);
      const idx = h * COLS + d;
      tokens.push(mesh);
      state.push(false);
      pop.push(1);
      traits(mesh, { onPress: () => toggle(idx) });
    }
  }

  // ---------- check marks (one instanced mesh) ----------
  const shape = new THREE.Shape();
  const pts = [
    [-0.0125, -0.0005], [-0.0085, 0.0035], [-0.004, -0.001],
    [0.0085, 0.0115], [0.0125, 0.0075], [-0.004, -0.0095],
  ];
  shape.moveTo(pts[0][0], pts[0][1]);
  for (let i = 1; i < pts.length; i++) shape.lineTo(pts[i][0], pts[i][1]);
  shape.closePath();
  const checkGeo = new THREE.ShapeGeometry(shape);
  const checkMat = new THREE.MeshBasicMaterial({ color: 0xffffff, side: THREE.DoubleSide });
  const checks = new THREE.InstancedMesh(checkGeo, checkMat, ROWS * COLS);
  checks.name = 'Check marks';
  checks.frustumCulled = false;
  root.add(checks);
  const dummy = new THREE.Object3D();

  // ---------- UI panels ----------
  const rowsMarkup = habits.map((h, i) => `
      <div class="row ${i % 2 ? 'alt' : ''}">
        <span class="hname h${i}">${h.name}</span>
        <span class="streak" id="streak${i}">Streak: 0 days</span>
      </div>`).join('');

  const headerCells = days.map(d => `<div class="cell"><span class="day">${d}</span></div>`).join('');

  const titlePanel = ui(`
    <style>
      .card { width: 420px; flex-direction: column; align-items: center; gap: 4px;
              padding-top: 10px; padding-bottom: 10px; padding-left: 10px; padding-right: 10px;
              border-radius: 16px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; text-align: center; }
      .hint { color: #c9ced6; font-size: 20px; text-align: center; }
    </style>
    <div class="card">
      <span class="title">My Week - Habits</span>
      <span class="hint">Tap a circle to check off a day.</span>
    </div>`, { width: 0.42, position: [0, 0.45, 0] });
  root.add(titlePanel.object3D);

  const headerPanel = ui(`
    <style>
      .bar { width: 420px; height: 36px; flex-direction: row; align-items: center;
             border-radius: 10px; background-color: #1a1d22; }
      .cell { width: 60px; height: 36px; align-items: center; justify-content: center; }
      .day { color: #e8ebf0; font-size: 22px; font-weight: 700; text-align: center; }
    </style>
    <div class="bar">${headerCells}</div>`, { width: 0.42, position: [0, 0.37, 0] });
  root.add(headerPanel.object3D);

  const labels = ui(`
    <style>
      .col { width: 190px; height: 300px; flex-direction: column; border-radius: 14px;
             background-color: #23272e; }
      .row { width: 190px; height: 100px; flex-direction: column; justify-content: center;
             gap: 4px; padding-left: 12px; padding-right: 8px; background-color: #23272e;
             border-radius: 14px; }
      .alt { background-color: #2a2e35; }
      .hname { font-size: 22px; font-weight: 700; }
      .h0 { color: #4aa3ff; }
      .h1 { color: #b58cff; }
      .h2 { color: #ffa94a; }
      .streak { color: #d7dbe2; font-size: 20px; }
    </style>
    <div class="col">${rowsMarkup}</div>`, { width: 0.19, position: [-0.305, 0.2, 0] });
  root.add(labels.object3D);

  const side = ui(`
    <style>
      .card { width: 190px; flex-direction: column; align-items: center; gap: 10px;
              padding-top: 14px; padding-bottom: 14px; padding-left: 12px; padding-right: 12px;
              border-radius: 14px; background-color: #1f2228; }
      .lbl { color: #c9ced6; font-size: 22px; text-align: center; }
      .big { color: #ffffff; font-size: 34px; font-weight: 700; text-align: center; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px;
             border-radius: 12px; background-color: #c0453d; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; text-align: center; }
    </style>
    <div class="card">
      <span class="lbl">Done</span>
      <span class="big" id="total">0 / 21</span>
      <button class="btn" id="reset"><span class="btn-text">Reset</span></button>
    </div>`, { width: 0.19, position: [0.305, 0.2, 0] });
  root.add(side.object3D);

  // ---------- logic ----------
  function longestRun(h) {
    let best = 0, cur = 0;
    for (let d = 0; d < COLS; d++) {
      if (state[h * COLS + d]) { cur++; if (cur > best) best = cur; } else cur = 0;
    }
    return best;
  }

  function refresh() {
    let total = 0;
    for (let i = 0; i < state.length; i++) if (state[i]) total++;
    for (let h = 0; h < ROWS; h++) {
      const s = longestRun(h);
      labels.set('streak' + h, {
        text: 'Streak: ' + s + (s === 1 ? ' day' : ' days'),
        color: s >= 3 ? '#6fe08a' : '#d7dbe2',
      });
    }
    side.set('total', { text: total + ' / 21' });
  }

  function applyToken(i) {
    const h = Math.floor(i / COLS);
    tokens[i].material = state[i] ? onMats[h] : offMat;
  }

  function toggle(i) {
    state[i] = !state[i];
    pop[i] = state[i] ? 1.3 : 0.85;
    applyToken(i);
    refresh();
  }

  side.on('reset', 'click', () => {
    for (let i = 0; i < state.length; i++) {
      if (state[i]) { state[i] = false; pop[i] = 0.85; applyToken(i); }
    }
    refresh();
  });

  refresh();

  return {
    root,
    update(time, delta) {
      const k = Math.min(1, delta * 10);
      for (let i = 0; i < tokens.length; i++) {
        pop[i] += (1 - pop[i]) * k;
        tokens[i].scale.setScalar(pop[i]);
        dummy.position.copy(tokens[i].position);
        dummy.position.z = 0.009;
        dummy.scale.setScalar(state[i] ? pop[i] * 1.3 : 0.0001);
        dummy.updateMatrix();
        checks.setMatrixAt(i, dummy.matrix);
      }
      checks.instanceMatrix.needsUpdate = true;
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const DAYS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
