    </style>
    <div class="row">
      ${DAYS.map((d) => `<div class="col"><span class="d">${d}</span></div>`).join('')}
    </div>`, { width: 0.42, position: [0, 0.33, 0] });
  root.add(header.object3D);

  const streakPanels = [];
  HABITS.forEach((h, r) => {
    const label = ui(`
      <style>
        .p { width: 170px; flex-direction: row; align-items: center; gap: 10px; padding-top: 10px; padding-bottom: 10px;
             padding-left: 12px; padding-right: 12px; border-radius: 12px; background-color: #1f2228; }
        .dot { width: 16px; height: 16px; border-radius: 8px; background-color: ${h.color}; }
        .t { color: #ffffff; font-size: 22px; font-weight: 700; }
      </style>
      <div class="p"><div class="dot"></div><span class="t">${h.name}</span></div>`,
      { width: 0.17, position: [-0.305, ROW_Y[r], 0] });
    root.add(label.object3D);

    const streak = ui(`
      <style>
        .p { width: 190px; align-items: center; justify-content: center; padding-top: 10px; padding-bottom: 10px;
             padding-left: 10px; padding-right: 10px; border-radius: 12px; background-color: #1f2228; }
        .t { color: #d7dbe2; font-size: 22px; font-weight: 700; }
      </style>
      <div class="p"><span class="t" id="s">Streak: 0 days</span></div>`,
      { width: 0.19, position: [0.315, ROW_Y[r], 0] });
    root.add(streak.object3D);
    streakPanels.push(streak);
  });

  const bar = ui(`
    <style>
      .bar { width: 340px; flex-direction: row; align-items: center; justify-content: space-between; gap: 14px;
             padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px;
             border-radius: 16px; background-color: #1f2228; }
      .sum { color: #ffffff; font-size: 22px; font-weight: 700; }
      .btn { padding-top: 8px; padding-bottom: 8px; padding-left: 14px; padding-right: 14px; border-radius: 12px; background-color: #3a3f47; }
      .bt { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="bar">
      <span class="sum" id="sum">Done: 0 of 21</span>
      <button class="btn" id="clear"><span class="bt">Clear week</span></button>
    </div>`, { width: 0.34, position: [0, 0.035, 0] });
  root.add(bar.object3D);

  // ---------- 3D cells ----------
  const cellGeo = new THREE.BoxGeometry(0.04, 0.04, 0.012);
  const offMat = new THREE.MeshStandardMaterial({ color: 0x3a3f47, roughness: 0.7 });
  const onMats = HABITS.map((h) => new THREE.MeshStandardMaterial({
    color: h.hex, emissive: h.hex, emissiveIntensity: 0.35, roughness: 0.5,
  }));

  const cells = [];       // index = r*7 + c
  const pulse = new Float32Array(21);
  const markScale = new Float32Array(21);
  const markTarget = new Float32Array(21);

  for (let r = 0; r < 3; r++) {
    for (let c = 0; c < 7; c++) {
      const cell = new THREE.Mesh(cellGeo, state[r][c] ? onMats[r] : offMat);
      cell.name = `${HABITS[r].name}-${DAYS[c]}`;
      cell.position.set((c - 3) * SPACING, ROW_Y[r], 0);
      root.add(cell);
      cells.push(cell);
      const i = r * 7 + c;
      markTarget[i] = state[r][c] ? 1 : 0;
      markScale[i] = markTarget[i];
    }
  }

  // Check mark (shared geometry, one instanced mesh)
  const tick = new THREE.Shape();
  tick.moveTo(-0.015, -0.002);
  tick.lineTo(-0.005, -0.012);
  tick.lineTo(0.015, 0.008);
  tick.lineTo(0.011, 0.012);
  tick.lineTo(-0.005, -0.004);
  tick.lineTo(-0.011, 0.002);
  tick.closePath();
  const tickGeo = new THREE.ExtrudeGeometry(tick, { depth: 0.004, bevelEnabled: false });
  const marks = new THREE.InstancedMesh(tickGeo, new THREE.MeshBasicMaterial({ color: 0xffffff }), 21);
  marks.name = 'CheckMarks';
  marks.frustumCulled = false;
  root.add(marks);
  const dummy = new THREE.Object3D();

  function writeMark(i, s) {
    const cell = cells[i];
    dummy.position.set(cell.position.x, cell.position.y, 0.0062);
    dummy.scale.setScalar(Math.max(s, 0.0001));
    dummy.updateMatrix();
    marks.setMatrixAt(i, dummy.matrix);
  }
  for (let i = 0; i < 21; i++) writeMark(i, markScale[i]);
  marks.instanceMatrix.needsUpdate = true;

  // ---------- Logic ----------
  function longestRun(row) {
    let best = 0;
    let cur = 0;
    for (let c = 0; c < 7; c++) {
      if (row[c]) { cur++; if (cur > best) best = cur; } else cur = 0;
    }
    return best;
  }

  function refresh() {
    let total = 0;
    for (let r = 0; r < 3; r++) {
      const s = longestRun(state[r]);
      for (let c = 0; c < 7; c++) total += state[r][c];
      streakPanels[r].set('s', {
        text: `Streak: ${s} ${s === 1 ? 'day' : 'days'}`,
        color: s >= 3 ? '#ffc23d' : '#d7dbe2',
      });
    }
    bar.set('sum', { text: `Done: ${total} of 21` });
  }

  function applyCell(r, c) {
    const i = r * 7 + c;
    cells[i].material = state[r][c] ? onMats[r] : offMat;
    markTarget[i] = state[r][c] ? 1 : 0;
    pulse[i] = 1;
  }

  for (let r = 0; r < 3; r++) {
    for (let c = 0; c < 7; c++) {
      traits(cells[r * 7 + c], {
        onPress: () => {
          state[r][c] = state[r][c] ? 0 : 1;
          applyCell(r, c);
          refresh();
        },
      });
    }
  }

  bar.on('clear', 'click', () => {
    for (let r = 0; r < 3; r++) {
      for (let c = 0; c < 7; c++) {
        if (state[r][c]) { state[r][c] = 0; applyCell(r, c); }
      }
    }
    refresh();
  });

  refresh();

  return {
    root,
    update(time, delta) {
      const k = Math.min(1, delta * 14);
      let dirty = false;
      for (let i = 0; i < 21; i++) {
        const diff = markTarget[i] - markScale[i];
        const p = pulse[i];
        if (Math.abs(diff) > 0.001 || p > 0.001) {
          markScale[i] += diff * k;
          pulse[i] = Math.max(0, p - delta * 4);
          const bump = 1 + 0.15 * pulse[i];
          cells[i].scale.setScalar(bump);
          writeMark(i, markScale[i] * bump);
          dirty = true;
        }
      }
      if (dirty) marks.instanceMatrix.needsUpdate = true;
    },
  };
}

