      <div class="row"><span class="name">Orange</span><span class="state" id="s1">on table</span><span class="price">$0.80</span></div>
      <div class="row"><span class="name">Banana</span><span class="state" id="s2">on table</span><span class="price">$0.50</span></div>
      <div class="total-row"><span class="total-l" id="cnt">Total (0)</span><span class="total-v" id="total">$0.00</span></div>
      <button class="btn" id="reset"><span class="btn-text">Put fruit back</span></button>
    </div>`, { width: 0.34, position: [0.0, 0.27, -0.14] });
  root.add(info.object3D);

  info.on('reset', 'click', () => {
    fruits.forEach((f) => {
      f.obj.position.set(f.home[0], f.rest, f.home[1]);
    });
  });

  // ---------- Logic ----------
  let lastSig = '';
  const fmt = (c) => '$' + (c / 100).toFixed(2);

  function refreshPanel() {
    let total = 0, count = 0, sig = '';
    fruits.forEach((f, i) => {
      sig += f.inBasket ? '1' : '0';
      if (f.inBasket) { total += f.price; count++; }
    });
    if (sig === lastSig) return;
    lastSig = sig;
    fruits.forEach((f, i) => {
      info.set('s' + i, {
        text: f.inBasket ? 'in basket' : 'on table',
        color: f.inBasket ? '#6fe08a' : '#8d95a3',
      });
    });
    info.set('total', { text: fmt(total) });
    info.set('cnt', { text: 'Total (' + count + ')' });
  }

  return {
    root,
    update(time, delta) {
      const dt = Math.min(delta, 0.05);

      for (let i = 0; i < fruits.length; i++) {
        const f = fruits[i];
        const o = f.obj;
        if (isGrabbed(o)) { f.inBasket = false; continue; }

        let dx = o.position.x - (BX);
        let dz = o.position.z - (BZ);
        let d = Math.sqrt(dx * dx + dz * dz);
        const inside = d < R - 0.01;

        // Nudge fruit resting against the outside of the wall
        if (!inside && d < R + 0.035 && o.position.y < H && d > 0.0001) {
          const k = (R + 0.035) / d;
          o.position.x = BX + dx * k;
          o.position.z = BZ + dz * k;
        }

        // Gentle fall onto the table or basket floor
        const floorY = (inside ? FLOOR : 0) + f.rest;
        if (o.position.y > floorY) {
          o.position.y = Math.max(floorY, o.position.y - 0.35 * dt);
        } else {
          o.position.y = floorY;
        }
      }

      // Keep resting fruits from sitting inside each other
      for (let i = 0; i < fruits.length; i++) {
        for (let j = i + 1; j < fruits.length; j++) {
          const a = fruits[i], b = fruits[j];
          if (isGrabbed(a.obj) || isGrabbed(b.obj)) continue;
          if (Math.abs(a.obj.position.y - b.obj.position.y) > 0.05) continue;
          let dx = b.obj.position.x - a.obj.position.x;
          let dz = b.obj.position.z - a.obj.position.z;
          let d = Math.sqrt(dx * dx + dz * dz);
          const minD = a.r + b.r;
          if (d < minD) {
            if (d < 0.0001) { dx = 1; dz = 0; d = 1; }
            const push = (minD - d) * 0.5;
            const nx = dx / d, nz = dz / d;
            a.obj.position.x -= nx * push;
            a.obj.position.z -= nz * push;
            b.obj.position.x += nx * push;
            b.obj.position.z += nz * push;
          }
        }
      }

      // Final state: keep basket fruit inside the walls, decide who is in the basket
      for (let i = 0; i < fruits.length; i++) {
        const f = fruits[i];
        const o = f.obj;
        if (isGrabbed(o)) continue;
        const dx = o.position.x - BX;
        const dz = o.position.z - BZ;
        const d = Math.sqrt(dx * dx + dz * dz);
        const settledInside = d < R - 0.01 && o.position.y <= FLOOR + f.rest + 0.004;
        if (settledInside) {
          const maxD = R - 0.035;
          if (d > maxD) {
            const k = maxD / d;
            o.position.x = BX + dx * k;
            o.position.z = BZ + dz * k;
          }
        }
        f.inBasket = settledInside;
      }

      refreshPanel();
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------- Basket ----------
  const BX = 0.2, BZ = 0.02;
  const RIM_H = 0.09, INNER_R = 0.1, OUTER_R = 0.11, CLAMP_R = 0.065;

  const basket = new THREE.Group();
  basket.name = 'Basket';
  basket.position.set(BX, 0, BZ);
  root.add(basket);

  const wickerMat = new THREE.MeshStandardMaterial({ color: 0xa8743a, roughness: 0.9, side: THREE.DoubleSide });
  const wall = new THREE.Mesh(new THREE.CylinderGeometry(0.11, 0.09, RIM_H, 32, 1, true), wickerMat);
  wall.position.y = RIM_H / 2;
  basket.add(wall);
  const bottom = new THREE.Mesh(new THREE.CircleGeometry(0.09, 32), wickerMat);
  bottom.rotation.x = -Math.PI / 2;
  bottom.position.y = 0.003;
  basket.add(bottom);
  const rim = new THREE.Mesh(
    new THREE.TorusGeometry(0.11, 0.007, 10, 40),
    new THREE.MeshStandardMaterial({ color: 0x7d5224, roughness: 0.8 }),
  );
  rim.rotation.x = Math.PI / 2;
  rim.position.y = RIM_H;
  basket.add(rim);
  // woven bands
  const bandMat = new THREE.MeshStandardMaterial({ color: 0x7d5224, roughness: 0.9 });
  for (let i = 0; i < 2; i++) {
    const r = 0.1 + i * 0.008;
    const band = new THREE.Mesh(new THREE.TorusGeometry(r, 0.004, 8, 40), bandMat);
    band.rotation.x = Math.PI / 2;
    band.position.y = 0.025 + i * 0.03;
    basket.add(band);
  }

  // ---------- Fruits ----------
  const fruits = [];

  function makeFruit(name, price, restY, radius, x, z, group) {
    group.name = name;
    root.add(group);
    group.position.set(x, restY, z);
    traits(group, { grab: true });
    const f = {
      name, price, restY, radius, group,
      sx: x, sz: z, vy: 0, inBasket: false, prevState: null,
    };
    fruits.push(f);
    return f;
  }

  // Apple
  const apple = new THREE.Group();
  const appleBody = new THREE.Mesh(
    new THREE.SphereGeometry(0.035, 28, 16),
    new THREE.MeshStandardMaterial({ color: 0xd62b2b, roughness: 0.45 }),
  );
  appleBody.scale.set(1, 0.92, 1);
  apple.add(appleBody);
  const stem = new THREE.Mesh(
    new THREE.CylinderGeometry(0.0025, 0.003, 0.014, 8),
    new THREE.MeshStandardMaterial({ color: 0x5a3a1a }),
  );
  stem.position.y = 0.035;
  apple.add(stem);
  const leaf = new THREE.Mesh(
    new THREE.SphereGeometry(0.009, 12, 8),
    new THREE.MeshStandardMaterial({ color: 0x3f9b3a }),
  );
  leaf.scale.set(1.6, 0.35, 0.8);
  leaf.position.set(0.01, 0.04, 0);
  apple.add(leaf);
  makeFruit('Apple', 0.8, 0.033, 0.035, -0.34, 0.05, apple);

  // Banana (lies flat)
  const banana = new THREE.Group();
  const pivot = new THREE.Group();
  pivot.rotation.x = Math.PI / 2;
  banana.add(pivot);
  const bR = 0.05;
  const bArc = Math.PI * 0.75;
  const bananaMesh = new THREE.Mesh(
    new THREE.TorusGeometry(bR, 0.015, 12, 32, bArc),
    new THREE.MeshStandardMaterial({ color: 0xf5d523, roughness: 0.55 }),
  );
  bananaMesh.rotation.z = Math.PI / 2 - bArc / 2;
  bananaMesh.position.y = -bR;
  pivot.add(bananaMesh);
  const tipMat = new THREE.MeshStandardMaterial({ color: 0x4a3418 });
  const tipGeo = new THREE.SphereGeometry(0.009, 10, 8);
  for (let s = -1; s <= 1; s += 2) {
    const a = Math.PI / 2 + s * bArc / 2;
    const tip = new THREE.Mesh(tipGeo, tipMat);
    tip.position.set(Math.cos(a) * bR, Math.sin(a) * bR - bR, 0);
    pivot.add(tip);
  }
  // invisible hit area so the thin banana is easy to pinch
  const hit = new THREE.Mesh(
    new THREE.SphereGeometry(0.035, 12, 8),
    new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false }),
  );
  banana.add(hit);
  makeFruit('Banana', 0.5, 0.016, 0.035, -0.22, 0.05, banana);

  // Orange
  const orange = new THREE.Group();
  const orangeBody = new THREE.Mesh(
    new THREE.SphereGeometry(0.036, 28, 16),
    new THREE.MeshStandardMaterial({ color: 0xf28a1a, roughness: 0.7 }),
  );
  orange.add(orangeBody);
  const nub = new THREE.Mesh(
    new THREE.SphereGeometry(0.006, 8, 6),
    new THREE.MeshStandardMaterial({ color: 0x3f7a2a }),
  );
  nub.position.y = 0.035;
  orange.add(nub);
  makeFruit('Orange', 0.7, 0.036, 0.036, -0.1, 0.05, orange);

  // ---------- Panel ----------
  const swatch = ['#d62b2b', '#f5d523', '#f28a1a'];
  const rowsMarkup = fruits.map((f, i) => `
      <div class="row">
        <div class="sw" style="background-color: ${swatch[i]};"></div>
        <span class="name">${f.name}</span>
        <span class="price">$${f.price.toFixed(2)}</span>
        <span class="status" id="s${i}">on table</span>
      </div>`).join('');

  const panel = ui(`
    <style>
      .card { width: 500px; flex-direction: column; gap: 12px; padding-top: 18px; padding-bottom: 18px;
              padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .hint { color: #b9c0cb; font-size: 22px; }
      .row { flex-direction: row; align-items: center; gap: 12px; }
      .sw { width: 22px; height: 22px; border-radius: 11px; }
      .name { color: #ffffff; font-size: 24px; width: 130px; }
      .price { color: #d7dbe2; font-size: 24px; width: 90px; }
      .status { color: #8a919c; font-size: 22px; }
      .totalrow { flex-direction: row; justify-content: space-between; align-items: center;
                  padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px;
                  border-radius: 12px; background-color: #2c3038; }
      .tlabel { color: #ffffff; font-size: 26px; font-weight: 700; }
      .total { color: #7be08a; font-size: 32px; font-weight: 700; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px;
             border-radius: 12px; background-color: #2f6fdb; align-items: center; justify-content: center; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Fruit basket</span>
      <span class="hint">Pinch a fruit and drop it into the basket.</span>
      ${rowsMarkup}
      <div class="totalrow">
        <span class="tlabel">Total</span>
        <span class="total" id="total">$0.00</span>
      </div>
      <button class="btn" id="reset"><span class="btn-text">Put fruit back</span></button>
    </div>`, { width: 0.34, position: [-0.02, 0.3, -0.15] });
  root.add(panel.object3D);

  panel.on('reset', 'click', () => {
    for (const f of fruits) {
      if (isGrabbed(f.group)) continue;
      f.group.position.set(f.sx, f.restY + 0.02, f.sz);
      f.vy = 0;
    }
  });

  let lastTotalCents = -1;

  // ---------- Simulation ----------
  const GRAVITY = 2.5;

  return {
    root,
    update(time, delta) {
      const dt = Math.min(delta, 0.05);

      for (let i = 0; i < fruits.length; i++) {
        const f = fruits[i];
        const p = f.group.position;

        if (isGrabbed(f.group)) {
          f.vy = 0;
          f.inBasket = false;
          continue;
        }

        let dx = p.x - BX, dz = p.z - BZ;
        let d = Math.sqrt(dx * dx + dz * dz);

        // Keep fruit out of the basket wall when below the rim.
        if (p.y < RIM_H && d >= INNER_R - 0.02 && d < OUTER_R + f.radius) {
          const nd = OUTER_R + f.radius + 0.005;
          const k = d > 0.0001 ? nd / d : 1;
          p.x = BX + dx * k;
          p.z = BZ + dz * k;
          dx = p.x - BX; dz = p.z - BZ;
          d = nd;
        }

        const over = d < INNER_R - 0.02;
        let floorY = f.restY;
        if (over) floorY = f.restY + 0.004;

        f.vy -= GRAVITY * dt;
        p.y += f.vy * dt;
        if (p.y <= floorY) {
          p.y = floorY;
          f.vy = 0;
        }

        // Inside the basket: stay within the floor area and spread out.
        if (over && p.y < RIM_H) {
          if (d > CLAMP_R) {
            const k = CLAMP_R / d;
            p.x = BX + dx * k;
            p.z = BZ + dz * k;
          }
          for (let j = 0; j < fruits.length; j++) {
            if (j === i) continue;
            const o = fruits[j];
            if (!o.inBasket || isGrabbed(o.group)) continue;
            const ox = p.x - o.group.position.x;
            const oz = p.z - o.group.position.z;
            const od = Math.sqrt(ox * ox + oz * oz);
            if (od < 0.07 && od > 0.0001) {
              const push = (0.07 - od) * 0.5 * Math.min(1, dt * 10);
              p.x += (ox / od) * push;
              p.z += (oz / od) * push;
            }
          }
        }

        f.inBasket = over && p.y < RIM_H + 0.01;

        // Table bounds
        if (p.x < -0.38) p.x = -0.38;
        if (p.x > 0.38) p.x = 0.38;
        if (p.z < -0.2) p.z = -0.2;
        if (p.z > 0.25) p.z = 0.25;
        if (p.y > 0.45) p.y = 0.45;
      }

      // Update panel only when something changed.
      let cents = 0;
      for (let i = 0; i < fruits.length; i++) {
        const f = fruits[i];
        if (f.inBasket) cents += Math.round(f.price * 100);
        if (f.prevState !== f.inBasket) {
          f.prevState = f.inBasket;
          panel.set('s' + i, {
            text: f.inBasket ? 'in basket' : 'on table',
            color: f.inBasket ? '#7be08a' : '#8a919c',
          });
        }
      }
      if (cents !== lastTotalCents) {
        lastTotalCents = cents;
        panel.set('total', { text: '$' + (cents / 100).toFixed(2) });
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const palette = [
    { name: 'Red', hex: 0xff3b30, css: '#ff3b30' },
    { name: 'Orange', hex: 0xff9500, css: '#ff9500' },
    { name: 'Yellow', hex: 0xffcc00, css: '#ffcc00' },
    { name: 'Green', hex: 0x34c759, css: '#34c759' },
    { name: 'Cyan', hex: 0x64d2ff, css: '#64d2ff' },
    { name: 'Blue', hex: 0x0a84ff, css: '#0a84ff' },
    { name: 'Purple', hex: 0xbf5af2, css: '#bf5af2' },
    { name: 'Pink', hex: 0xff375f, css: '#ff375f' }
  ];
  let idx = 0;
  let presses = 0;
  let dip = 0;

  // Desk pedestal
  const baseMat = new THREE.MeshStandardMaterial({ color: 0x2a2e35, roughness: 0.6, metalness: 0.3 });
  const base = new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.078, 0.04, 32), baseMat);
  base.name = 'Pedestal';
  base.position.set(0, 0.02, 0.05);
  root.add(base);

  // Glowing halo shell (same color, transparent)
  const haloMat = new THREE.MeshBasicMaterial({ color: palette[0].hex, transparent: true, opacity: 0.22 });
  const halo = new THREE.Mesh(new THREE.CylinderGeometry(0.057, 0.062, 0.039, 32), haloMat);
  halo.name = 'GlowHalo';
  halo.position.set(0, 0.0585, 0.05);
  root.add(halo);

  // Main glowing button
  const glowMat = new THREE.MeshStandardMaterial({
    color: palette[0].hex,
    emissive: palette[0].hex,
    emissiveIntensity: 1.4,
    roughness: 0.3,
    metalness: 0.1
  });
  const button = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.055, 0.035, 32), glowMat);
  button.name = 'GlowButton';
  const baseButtonY = 0.0575;
  button.position.set(0, baseButtonY, 0.05);
  root.add(button);

  // Color spill ring on desk
  const ringMat = new THREE.MeshBasicMaterial({ color: palette[0].hex, transparent: true, opacity: 0.9 });
  const ring = new THREE.Mesh(new THREE.TorusGeometry(0.088, 0.004, 12, 48), ringMat);
  ring.name = 'GlowRing';
  ring.rotation.x = -Math.PI / 2;
  ring.position.set(0, 0.004, 0.05);
  root.add(ring);

  // Top highlight disc so the press target reads clearly
  const capMat = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.35 });
  const cap = new THREE.Mesh(new THREE.CylinderGeometry(0.032, 0.032, 0.002, 32), capMat);
  cap.name = 'ButtonCap';
  cap.position.set(0, 0.076, 0.05);
  root.add(cap);

  const info = ui(`
    <style>
      .card { width: 500px; flex-direction: column; gap: 10px; padding-top: 18px; padding-bottom: 18px; padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; text-align: center; }
      .body { color: #d7dbe2; font-size: 24px; text-align: center; }
      .row { flex-direction: row; gap: 14px; align-items: center; justify-content: center; }
      .swatch { width: 64px; height: 64px; border-radius: 32px; background-color: #ff3b30; border-color: #ffffff; border-width: 3px; }
      .swatch-text { color: #ffffff; font-size: 20px; }
      .colorname { color: #ffffff; font-size: 30px; font-weight: 700; }
      .count { color: #aeb6c2; font-size: 24px; text-align: center; }
      .reset { padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px; border-radius: 12px; background-color: #3a3f47; }
      .reset-text { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Glowing Button</span>
      <span class="body">Poke or pinch the glowing button to change its color.</span>
      <div class="row">
        <div class="swatch" id="swatch"><span class="swatch-text"> </span></div>
        <span class="colorname" id="colorName">Red</span>
      </div>
      <span class="count" id="countLabel">Presses: 0</span>
      <button class="reset" id="reset"><span class="reset-text">Reset</span></button>
    </div>`, { width: 0.32, position: [0, 0.3, -0.1], rotationY: 0 });
  root.add(info.object3D);

  function applyColor() {
    const c = palette[idx];
    glowMat.color.setHex(c.hex);
    glowMat.emissive.setHex(c.hex);
    haloMat.color.setHex(c.hex);
    ringMat.color.setHex(c.hex);
    info.set('colorName', { text: c.name });
    info.set('countLabel', { text: 'Presses: ' + presses });
    info.set('swatch', { backgroundColor: c.css });
  }

  traits(button, {
    onPress: () => {
      idx = (idx + 1) % palette.length;
      presses += 1;
      dip = 1;
      applyColor();
    }
  });

  info.on('reset', 'click', () => {
    idx = 0;
    presses = 0;
    dip = 1;
    applyColor();
  });

  applyColor();

  return {
    root,
    update(time, delta) {
      if (dip > 0) {
        dip = Math.max(0, dip - delta * 4.5);
      }
      // Press dip animation
      button.position.y = baseButtonY - dip * 0.012;
      button.scale.y = 1 - dip * 0.28;
      halo.position.y = baseButtonY + 0.001 - dip * 0.012;
      cap.position.y = baseButtonY + 0.0185 - dip * 0.012;
      // Breathing glow, plus flash on press
      const pulse = Math.sin(time * 3.0) * 0.25;
      glowMat.emissiveIntensity = 1.4 + pulse + dip * 1.2;
      haloMat.opacity = 0.2 + Math.sin(time * 3.0) * 0.05 + dip * 0.25;
    }
  };
}

