  info.on('spinBtn', 'click', () => {
    spinOn = !spinOn;
    info.set('spinLabel', { text: spinOn ? 'Spin: On' : 'Spin: Off' });
  });
  info.on('nextBtn', 'click', () => {
    sel = (sel + 1) % N;
    ringMesh.position.y = ys[sel];
    info.set('pair', { text: pairInfos[sel] });
  });

  return {
    root,
    update(time, delta) {
      if (spinOn && !isGrabbed(dnaGroup)) {
        dnaGroup.rotation.y += delta * 0.6;
      }
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // Whole clock is one grabbable group (direct child of root)
  const clockGroup = new THREE.Group();
  clockGroup.position.set(-0.10, 0, 0);
