    const r = 0.047;
    tick.position.set(Math.sin(a) * r, faceCenterY + Math.cos(a) * r, faceFrontZ + 0.001);
    tick.rotation.z = -a;
    if (i % 3 === 0) tick.scale.y = 1.6;
    tick.name = 'Tick' + i;
