  const minuteGeo = new THREE.BoxGeometry(0.005, 0.045, 0.0025);
  minuteGeo.translate(0, 0.015, 0);
  const secondGeo = new THREE.BoxGeometry(0.002, 0.048, 0.0015);
  secondGeo.translate(0, 0.014, 0);

  const hourHand = new THREE.Mesh(hourGeo, darkMat);
  hourHand.position.set(0, faceCenterY, faceFrontZ + 0.003);
  hourHand.name = 'HourHand';
  clockGroup.add(hourHand);

  const minuteHand = new THREE.Mesh(minuteGeo, darkMat);
  minuteHand.position.set(0, faceCenterY, faceFrontZ + 0.0045);
  minuteHand.name = 'MinuteHand';
  clockGroup.add(minuteHand);

  const secondHand = new THREE.Mesh(secondGeo, secondMat);
  secondHand.position.set(0, faceCenterY, faceFrontZ + 0.006);
  secondHand.name = 'SecondHand';
  clockGroup.add(secondHand);

  const cap = new THREE.Mesh(new THREE.SphereGeometry(0.005, 16, 12), darkMat);
  cap.position.set(0, faceCenterY, faceFrontZ + 0.0065);
  cap.name = 'CenterCap';
  clockGroup.add(cap);

  traits(clockGroup, { grab: true });

  // Digital panel + controls
  const info = ui(`
    <style>
      .card { width: 500px; flex-direction: column; gap: 8px; padding-top: 16px; padding-bottom: 16px; padding-left: 20px; padding-right: 20px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; text-align: center; }
      .time { color: #ffd75e; font-size: 62px; font-weight: 700; text-align: center; }
      .sub { color: #d7dbe2; font-size: 24px; text-align: center; }
      .mode { color: #9aa3b2; font-size: 24px; text-align: center; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px; border-radius: 12px; background-color: #2f6fdb; }
      .btn2 { padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px; border-radius: 12px; background-color: #3a3f4a; }
      .btn-text { color: #ffffff; font-size: 24px; font-weight: 700; text-align: center; }
    </style>
    <div class="card">
      <span class="title">Desk Clock</span>
      <span class="time" id="clock">00:00</span>
      <span class="sub" id="date">---</span>
      <span class="mode" id="mode">24-hour format</span>
      <span class="sub" id="hint">Pinch the clock to move it.</span>
      <button class="btn" id="fmt"><span class="btn-text" id="fmtLabel">Switch to 12-hour</span></button>
      <button class="btn2" id="secBtn"><span class="btn-text" id="secLabel">Hide second hand</span></button>
    </div>`, { width: 0.30, position: [0.24, 0.19, 0.03], rotationY: -0.25 });
  root.add(info.object3D);

  const days = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

  const nowDate = new Date();
  let show24 = true;
  let lastKey = -9999;

  function pad(n) {
    return (n < 10 ? '0' : '') + n;
  }

  function refreshDigital() {
    const h24 = nowDate.getHours();
    const m = nowDate.getMinutes();
    let timeStr;
    if (show24) {
      timeStr = pad(h24) + ':' + pad(m);
    } else {
      let h12 = h24 % 12;
      if (h12 === 0) h12 = 12;
      const ap = h24 < 12 ? 'AM' : 'PM';
      timeStr = h12 + ':' + pad(m) + ' ' + ap;
    }
    info.set('clock', { text: timeStr });
    const dateStr = days[nowDate.getDay()] + ' ' + months[nowDate.getMonth()] + ' ' + nowDate.getDate();
    info.set('date', { text: dateStr });
    info.set('mode', { text: show24 ? '24-hour format' : '12-hour format' });
    info.set('fmtLabel', { text: show24 ? 'Switch to 12-hour' : 'Switch to 24-hour' });
    lastKey = h24 * 60 + m;
  }

  refreshDigital();

  info.on('fmt', 'click', () => {
    show24 = !show24;
    refreshDigital();
  });

  info.on('secBtn', 'click', () => {
    secondHand.visible = !secondHand.visible;
    info.set('secLabel', { text: secondHand.visible ? 'Hide second hand' : 'Show second hand' });
  });

  const TWO_PI = Math.PI * 2;

  function applyHands() {
    const sec = nowDate.getSeconds() + nowDate.getMilliseconds() / 1000;
    const min = nowDate.getMinutes() + sec / 60;
    const hr = (nowDate.getHours() % 12) + min / 60;
    secondHand.rotation.z = -(sec / 60) * TWO_PI;
    minuteHand.rotation.z = -(min / 60) * TWO_PI;
    hourHand.rotation.z = -(hr / 12) * TWO_PI;
  }

  applyHands();

  return {
    root,
    update() {
      nowDate.setTime(Date.now());
      applyHands();
      const key = nowDate.getHours() * 60 + nowDate.getMinutes();
      if (key !== lastKey) {
        refreshDigital();
      }
    }
  };
}

