    </div>`, { width: 0.32, position: [0.22, 0.21, 0.05], rotationY: -0.25 });
  root.add(info.object3D);

  let lampOn = true;
  let interacted = false;

  function applyLamp() {
    if (lampOn) {
      bulbMat.color.setHex(0xfff6d8);
      bulbMat.emissive.setHex(0xffc86e);
      bulbMat.emissiveIntensity = 1.8;
      shadeMat.emissive.setHex(0xffb45e);
      shadeMat.emissiveIntensity = 0.25;
      buttonMat.color.setHex(0x46c65a);
      buttonMat.emissive.setHex(0x1f8a2e);
      buttonMat.emissiveIntensity = 0.9;
      cone.visible = true;
      glow.visible = true;
      coneMat.opacity = 0.16;
      glowMat.opacity = 0.38;
      info.set('status', { text: 'Status: ON - warm light' });
      info.set('toggleLabel', { text: 'Switch OFF' });
