      bulbMat.color.setHex(0x9aa0a8);
      bulbMat.emissive.setHex(0x000000);
      bulbMat.emissiveIntensity = 0;
      shadeMat.emissiveIntensity = 0;
      buttonMat.color.setHex(0xc0392b);
      buttonMat.emissive.setHex(0x5a0a00);
      buttonMat.emissiveIntensity = 0.7;
      cone.visible = false;
      glow.visible = false;
      info.set('status', { text: 'Status: OFF - press lamp' });
      info.set('toggleLabel', { text: 'Switch ON' });
    }
    pressButton.scale.setScalar(1);
  }

  function toggle() {
    lampOn = !lampOn;
    interacted = true;
    applyLamp();
  }

  info.on('toggle', 'click', toggle);
  traits(lampGroup, { grab: true, onPress: toggle });
  applyLamp();

  return {
    root,
    update(time) {
      const held = isGrabbed(lampGroup);
      if (!interacted && !held) {
        const s = 1 + 0.14 * Math.sin(time * 4.0);
        pressButton.scale.setScalar(s);
      } else if (interacted && !held) {
        if (pressButton.scale.x !== 1) pressButton.scale.setScalar(1);
      }
      if (lampOn && cone.visible) {
        coneMat.opacity = 0.155 + 0.015 * Math.sin(time * 7.3) + 0.008 * Math.sin(time * 13.7);
        glowMat.opacity = 0.36 + 0.03 * Math.sin(time * 5.1);
      }
    }
  };
}

