      indicatorMat.emissiveIntensity = 1.2;
    } else {
      bulbMat.emissiveIntensity = 0.0;
      bulbMat.color.setHex(0x8a8f96);
      bulbMat.emissive.setHex(0x000000);
      indicatorMat.color.setHex(0x5a2a2a);
      indicatorMat.emissive.setHex(0x000000);
      indicatorMat.emissiveIntensity = 0.0;
    }
    glowMesh.visible = v;
    coneMesh.visible = v;
    poolMesh.visible = v;
    panel.set('state', { text: v ? 'Lamp is ON' : 'Lamp is OFF', color: v ? '#ffd27a' : '#aab0bb' });
    panel.set('toggleLabel', { text: v ? 'Switch off' : 'Switch on' });
    panel.set('toggle', { backgroundColor: v ? '#3a3f4a' : '#2f6fdb' });
    if (animate) buttonDip = 1;
  }

  panel.on('toggle', 'click', () => setOn(!isOn, true));
  traits(lampGroup, { grab: true, onPress: () => setOn(!isOn, true) });

  setOn(true, false);
  buttonDip = 0;

  return {
    root,
    update(time, delta) {
      if (buttonDip > 0) {
        buttonDip = Math.max(0, buttonDip - delta * 4);
        buttonMesh.position.y = buttonBaseY - Math.sin(buttonDip * Math.PI) * 0.007;
      }
      if (isOn && !isGrabbed(lampGroup)) {
        const f = Math.sin(time * 7.3) * 0.5 + Math.sin(time * 13.7) * 0.5;
        glowMat.opacity = 0.32 + f * 0.03;
        coneMat.opacity = 0.13 + f * 0.015;
      }
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const N = 14;
  const RADIUS = 0.055;
  const RISE = 0.022;
  const GAP = 0.012;
  const HALF_LEN = RADIUS - GAP / 2;
  const TOTAL_TWIST = Math.PI * 4;
  const STEP = TOTAL_TWIST / (N - 1);

  const seqA = ['G', 'A', 'T', 'C', 'G', 'T', 'A', 'C', 'T', 'G', 'A', 'C', 'G', 'T'];
  const comp = { A: 'T', T: 'A', G: 'C', C: 'G' };
  const seqB = seqA.map((b) => comp[b]);

  const carrier = new THREE.Group();
  carrier.position.set(0, 0.22, 0.05);
  carrier.name = 'DNA Helix';
  root.add(carrier);

  const spinner = new THREE.Group();
  carrier.add(spinner);

  const strandA = new THREE.Group();
  strandA.name = 'Strand A';
  spinner.add(strandA);
  const strandB = new THREE.Group();
  strandB.name = 'Strand B';
  spinner.add(strandB);

  const backboneMat = new THREE.MeshStandardMaterial({ color: 0x9db4d0, roughness: 0.35, metalness: 0.15 });

  const baseColors = { A: 0x2fd47e, T: 0xff5252, C: 0x40c4ff, G: 0xffc933 };
  const baseEmissive = { A: 0x0a4d2a, T: 0x4d0a0a, C: 0x0a324d, G: 0x4d3a0a };
  const baseHiEmissive = { A: 0x1aff66, T: 0xff2222, C: 0x22ccff, G: 0xffdd22 };
  const baseMats = {};
  const hiMats = {};
  for (const k of ['A', 'T', 'C', 'G']) {
    baseMats[k] = new THREE.MeshStandardMaterial({ color: baseColors[k], roughness: 0.4, metalness: 0.05, emissive: baseEmissive[k], emissiveIntensity: 0.5 });
    hiMats[k] = new THREE.MeshStandardMaterial({ color: baseColors[k], roughness: 0.3, emissive: baseHiEmissive[k], emissiveIntensity: 1.0 });
  }

  const ptsA = [];
  const ptsB = [];
  const yMid = (N - 1) / 2;
  for (let i = 0; i < N; i++) {
    const th = i * STEP;
    const y = (i - yMid) * RISE;
    ptsA.push(new THREE.Vector3(Math.cos(th) * RADIUS, y, Math.sin(th) * RADIUS));
    const th2 = th + Math.PI;
    ptsB.push(new THREE.Vector3(Math.cos(th2) * RADIUS, y, Math.sin(th2) * RADIUS));
  }

  const curveA = new THREE.CatmullRomCurve3(ptsA);
  const curveB = new THREE.CatmullRomCurve3(ptsB);
  const tubeGeoA = new THREE.TubeGeometry(curveA, 64, 0.009, 8, false);
  const tubeGeoB = new THREE.TubeGeometry(curveB, 64, 0.009, 8, false);
  const tubeA = new THREE.Mesh(tubeGeoA, backboneMat);
  tubeA.name = 'Backbone A';
  strandA.add(tubeA);
  const tubeB = new THREE.Mesh(tubeGeoB, backboneMat);
  tubeB.name = 'Backbone B';
  strandB.add(tubeB);

  const rungGeo = new THREE.CylinderGeometry(0.008, 0.008, 1, 10);
  const up = new THREE.Vector3(0, 1, 0);
  const rungA = [];
  const rungB = [];

  for (let i = 0; i < N; i++) {
    const pA = ptsA[i];
    const pB = ptsB[i];

    let dxA = -pA.x;
    let dzA = -pA.z;
    const dlA = Math.sqrt(dxA * dxA + dzA * dzA) || 1;
    dxA /= dlA; dzA /= dlA;
    const dirA = new THREE.Vector3(dxA, 0, dzA);
    const mA = new THREE.Mesh(rungGeo, baseMats[seqA[i]]);
    mA.name = 'Base ' + seqA[i] + ' ' + i;
    mA.position.set(pA.x + dxA * (HALF_LEN / 2), pA.y, pA.z + dzA * (HALF_LEN / 2));
    mA.quaternion.setFromUnitVectors(up, dirA);
    mA.scale.set(1, HALF_LEN, 1);
    strandA.add(mA);
    rungA.push(mA);

    let dxB = -pB.x;
    let dzB = -pB.z;
    const dlB = Math.sqrt(dxB * dxB + dzB * dzB) || 1;
    dxB /= dlB; dzB /= dlB;
    const dirB = new THREE.Vector3(dxB, 0, dzB);
    const mB = new THREE.Mesh(rungGeo, baseMats[seqB[i]]);
    mB.name = 'Base ' + seqB[i] + ' ' + i;
    mB.position.set(pB.x + dxB * (HALF_LEN / 2), pB.y, pB.z + dzB * (HALF_LEN / 2));
    mB.quaternion.setFromUnitVectors(up, dirB);
    mB.scale.set(1, HALF_LEN, 1);
    strandB.add(mB);
    rungB.push(mB);
  }

  const capGeo = new THREE.SphereGeometry(0.013, 16, 10);
  const fiveMat = new THREE.MeshStandardMaterial({ color: 0xff8a3d, roughness: 0.4, emissive: 0x4d2200, emissiveIntensity: 0.6 });
  const threeMat = new THREE.MeshStandardMaterial({ color: 0x2ce6c8, roughness: 0.4, emissive: 0x004d44, emissiveIntensity: 0.6 });
  const caps = [
    { p: ptsA[0], m: fiveMat, s: strandA, n: "5 prime A" },
    { p: ptsA[N - 1], m: threeMat, s: strandA, n: "3 prime A" },
    { p: ptsB[0], m: threeMat, s: strandB, n: "3 prime B" },
    { p: ptsB[N - 1], m: fiveMat, s: strandB, n: "5 prime B" },
  ];
  for (let i = 0; i < caps.length; i++) {
    const c = new THREE.Mesh(capGeo, caps[i].m);
    c.name = caps[i].n;
    c.position.copy(caps[i].p);
    caps[i].s.add(c);
  }

  const proxyGeo = new THREE.CylinderGeometry(0.085, 0.085, 0.37, 20);
  const proxyMat = new THREE.MeshBasicMaterial({ color: 0x88ccff, transparent: true, opacity: 0.07, depthWrite: false });
  const proxy = new THREE.Mesh(proxyGeo, proxyMat);
  proxy.name = 'DNA Grab Handle';
  carrier.add(proxy);

  const standGeo = new THREE.CylinderGeometry(0.095, 0.11, 0.012, 32);
  const standMat = new THREE.MeshStandardMaterial({ color: 0x2a2e35, roughness: 0.85 });
  const stand = new THREE.Mesh(standGeo, standMat);
  stand.name = 'Stand';
  stand.position.set(0, 0.006, 0.05);
  root.add(stand);

  let selected = 0;
  let spinOn = true;
  let unzipTarget = 0;
  let unzipCur = 0;
  const homePos = new THREE.Vector3(0, 0.22, 0.05);

  function bondsFor(i) {
    const a = seqA[i];
    return (a === 'G' || a === 'C') ? 3 : 2;
  }
  function pairText(i) {
    return 'Pair ' + (i + 1) + ' of ' + N + ': ' + seqA[i] + ' - ' + seqB[i] + ' | ' + bondsFor(i) + ' H-bonds';
  }
  function factText(i) {
    const b = bondsFor(i);
    if (b === 3) return 'G-C pairs have 3 hydrogen bonds. They hold tighter than A-T. Backbone is sugar + phosphate.';
    return 'A-T pairs have 2 hydrogen bonds. Strands run antiparallel: 5 prime opposite 3 prime.';
  }

  function applyHighlight() {
    for (let i = 0; i < N; i++) {
      const isSel = i === selected;
      rungA[i].material = isSel ? hiMats[seqA[i]] : baseMats[seqA[i]];
      rungB[i].material = isSel ? hiMats[seqB[i]] : baseMats[seqB[i]];
      const s = isSel ? 1.6 : 1.0;
      rungA[i].scale.x = s;
      rungA[i].scale.z = s;
      rungB[i].scale.x = s;
      rungB[i].scale.z = s;
    }
  }
  applyHighlight();

  const info = ui(`
    <style>
      .card { width: 520px; display: flex; flex-direction: column; gap: 10px; padding-top: 18px; padding-bottom: 18px; padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; text-align: left; }
      .body { color: #d7dbe2; font-size: 22px; text-align: left; }
      .pair { color: #ffd166; font-size: 23px; font-weight: 700; text-align: left; }
      .fact { color: #d7dbe2; font-size: 22px; text-align: left; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px; border-radius: 12px; background-color: #2f6fdb; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; text-align: center; }
    </style>
    <div class="card">
      <span class="title">DNA Double Helix</span>
      <span class="body">Pinch the helix to pick it up and turn it. Poke it to step through base pairs.</span>
      <span class="pair" id="pair">Pair 1 of 14</span>
      <span class="fact" id="fact">Fact</span>
      <button class="btn" id="next"><span class="btn-text">Next pair</span></button>
    </div>`, { width: 0.30, position: [-0.27, 0.27, -0.05], rotationY: 0.35 });
  root.add(info.object3D);

  const ctrl = ui(`
    <style>
      .panel { width: 400px; display: flex; flex-direction: column; gap: 10px; padding-top: 16px; padding-bottom: 16px; padding-left: 18px; padding-right: 18px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 28px; font-weight: 700; text-align: left; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px; border-radius: 12px; background-color: #333a45; }
      .btnA { padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px; border-radius: 12px; background-color: #2f6fdb; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; text-align: center; }
      .row { display: flex; flex-direction: row; gap: 8px; align-items: center; justify-content: flex-start; }
      .leg { color: #d7dbe2; font-size: 21px; text-align: left; }
      .dA { width: 18px; height: 18px; border-radius: 9px; background-color: #2fd47e; }
      .dT { width: 18px; height: 18px; border-radius: 9px; background-color: #ff5252; }
      .dC { width: 18px; height: 18px; border-radius: 9px; background-color: #40c4ff; }
      .dG { width: 18px; height: 18px; border-radius: 9px; background-color: #ffc933; }
    </style>
    <div class="panel">
      <span class="title">Controls</span>
      <button class="btnA" id="spinBtn"><span class="btn-text" id="spinTxt">Spin: ON</span></button>
      <button class="btn" id="unzipBtn"><span class="btn-text" id="unzipTxt">Unzip strands</span></button>
      <button class="btn" id="resetBtn"><span class="btn-text">Reset view</span></button>
      <div class="row"><span class="dA"></span><span class="leg">A - green</span></div>
      <div class="row"><span class="dT"></span><span class="leg">T - red</span></div>
      <div class="row"><span class="dC"></span><span class="leg">C - blue</span></div>
      <div class="row"><span class="dG"></span><span class="leg">G - yellow</span></div>
    </div>`, { width: 0.24, position: [0.27, 0.26, -0.05], rotationY: -0.35 });
  root.add(ctrl.object3D);

  function refreshInfo() {
    info.set('pair', { text: pairText(selected) });
    info.set('fact', { text: factText(selected) });
  }
  refreshInfo();

  function advance() {
    selected = (selected + 1) % N;
    applyHighlight();
    refreshInfo();
  }

  traits(carrier, { grab: true, onPress: () => { advance(); } });
  info.on('next', 'click', () => { advance(); });
  ctrl.on('spinBtn', 'click', () => {
    spinOn = !spinOn;
    ctrl.set('spinTxt', { text: spinOn ? 'Spin: ON' : 'Spin: OFF' });
  });
  ctrl.on('unzipBtn', 'click', () => {
    unzipTarget = unzipTarget > 0.5 ? 0 : 1;
    ctrl.set('unzipTxt', { text: unzipTarget > 0.5 ? 'Zip up' : 'Unzip strands' });
  });
  ctrl.on('resetBtn', 'click', () => {
    carrier.position.copy(homePos);
    carrier.rotation.set(0, 0, 0);
    spinner.rotation.set(0, 0, 0);
    unzipTarget = 0;
    unzipCur = 0;
    strandA.position.x = 0;
    strandB.position.x = 0;
    selected = 0;
    spinOn = true;
    ctrl.set('spinTxt', { text: 'Spin: ON' });
    ctrl.set('unzipTxt', { text: 'Unzip strands' });
    applyHighlight();
    refreshInfo();
  });

  return {
    root,
    update(time, delta) {
      const held = isGrabbed(carrier);
      if (spinOn && !held) {
        spinner.rotation.y += delta * 0.45;
      }
      const diff = unzipTarget - unzipCur;
      if (diff > 0.001 || diff < -0.001) {
        unzipCur += diff * Math.min(1, delta * 2.5);
        strandA.position.x = -unzipCur * 0.06;
        strandB.position.x = unzipCur * 0.06;
      }
      const s = 1.6 + 0.2 * Math.sin(time * 4.0);
      rungA[selected].scale.x = s;
      rungA[selected].scale.z = s;
      rungB[selected].scale.x = s;
      rungB[selected].scale.z = s;
    }
  };
}

