        <span class="city">${cities[i].name.toUpperCase()}</span>
        <span class="temp" id="temp">--</span>
        <span class="cond">${cities[i].cond}</span>
      </div>`, { width: 0.16, position: [xs[i], 0.105, -0.13], rotationY: 0 });
    root.add(h.object3D);
    miniHandles.push(h);
  }

  function refresh() {
    const c = cities[selected];
    main.set("headline", { text: c.name + " - " + c.cond + " - " + fmt(c.tempC) });
    const f = Math.round(c.tempC * 9 / 5 + 32);
    const tline = useC ? ("Temp " + c.tempC + "°C (" + f + "°F)") : ("Temp " + f + "°F (" + c.tempC + "°C)");
    main.set("detail", { text: tline + " ... Humidity " + c.hum + "% ... Wind " + c.wind + " km/h ... " + c.desc });
    main.set("unitLabel", { text: useC ? "Show in F" : "Show in C" });
    for (let i = 0; i < 3; i++) {
      miniHandles[i].set("temp", { text: fmt(cities[i].tempC), color: tempColors[i] });
    }
    for (let i = 0; i < 3; i++) {
      rings[i].material.emissiveIntensity = (i === selected) ? 1.2 : 0.5;
    }
  }
  refresh();

  function select(i) {
    selected = i;
    refresh();
  }

  for (let i = 0; i < 3; i++) {
    const idx = i;
    traits(groups[i], { grab: true, onPress: () => select(idx) });
  }

  main.on("unit", "click", () => { useC = !useC; refresh(); });
  main.on("next", "click", () => { selected = (selected + 1) % 3; refresh(); });

  const baseY = 0.235;
  return {
    root,
    update(time, delta) {
      if (sunRays) sunRays.rotation.z = time * 0.4;
      for (let i = 0; i < 3; i++) {
        if (!isGrabbed(groups[i])) {
          icons[i].position.y = baseY + Math.sin(time * 1.4 + i * 2.1) * 0.008;
        }
        if (i === selected) {
          const s = 1 + Math.sin(time * 3) * 0.06;
          rings[i].scale.set(s, s, 1);
        } else {
          rings[i].scale.set(1, 1, 1);
        }
      }
      for (let k = 0; k < rainDrops.length; k++) {
        const r = rainDrops[k];
        const fall = (time * 0.04 + r.off) % 0.05;
        r.mesh.position.y = -0.02 - fall;
      }
      for (let k = 0; k < snowFlakes.length; k++) {
        const s = snowFlakes[k];
        const fall = (time * 0.03 + s.off) % 0.055;
        s.mesh.position.y = -0.018 - fall;
        s.mesh.position.x = s.x0 + Math.sin(time * 2 + k * 1.7) * 0.006;
      }
    }
  };
}

