      <div class="row">
        <button class="btn" id="lightBtn"><span class="btn-text" id="lightBtnText">Light: ON</span></button>
        <button class="btn2" id="factBtn"><span class="btn-text">Next fact</span></button>
      </div>
      <span class="hint">Pinch Sun, Water drop and CO2. Press leaves and sugar.</span>
    </div>`, { width: 0.32, position: [0.30, 0.23, -0.04], rotationY: -0.32 });
  root.add(info.object3D);

  function show(t) { info.set('body', { text: t }); }

  const facts = [
    'Chlorophyll is the green pigment in leaves. It captures light energy.',
    'Water travels from roots up the stem to the leaves. Light splits water and releases oxygen.',
    'CO2 enters leaves through tiny pores called stomata. Carbon becomes sugar.',
    'Oxygen is the leftover that leaves breathe out. We breathe it in.',
    'Glucose is plant food. The plant uses it to grow. We get energy by eating plants.',
    'Photosynthesis needs all three inputs. Turn Light OFF to see what happens at night.'
  ];
  let factI = -1;

  let lightOn = true;
  info.on('factBtn', 'click', () => {
    factI = (factI + 1) % facts.length;
    show(facts[factI]);
  });
  info.on('lightBtn', 'click', () => {
    lightOn = !lightOn;
    info.set('lightBtnText', { text: lightOn ? 'Light: ON' : 'Light: OFF' });
    if (lightOn) show('Light is ON. Energy flows to the leaf and photosynthesis runs.');
    else show('Light is OFF - night time. Without light the plant cannot make sugar. Stomata close.');
  });

  // ---------- SMALL LABELS ----------
  function makeLabel(text, border, txtColor, pos, px, wM) {
    const h = ui(`
      <style>
        .pill { width: ${px}px; flex-direction: row; justify-content: center; padding-top: 8px; padding-bottom: 8px; padding-left: 10px; padding-right: 10px; border-radius: 12px; background-color: #1f2228; border-width: 2px; border-color: ${border}; }
        .txt { color: ${txtColor}; font-size: 24px; font-weight: 700; text-align: center; }
      </style>
      <div class="pill"><span class="txt">${text}</span></div>`, { width: wM, position: pos, rotationY: 0 });
    root.add(h.object3D);
    return h;
  }
  makeLabel('Light in', '#ffd23d', '#ffe082', [-0.19, 0.30, 0.02], 220, 0.12);
  makeLabel('Water in', '#2f9df0', '#bfe3ff', [-0.165, 0.115, 0.09], 230, 0.13);
  makeLabel('CO2 in', '#9aa0aa', '#e5e7eb', [0.15, 0.125, 0.07], 200, 0.115);
  makeLabel('Oxygen out', '#4ade80', '#bbf7d0', [0.155, 0.35, 0.05], 250, 0.14);

  // ---------- INTERACTIONS (only direct children of root) ----------
  traits(sun, {
    grab: true,
    onPress: () => show('Light: sunlight hits chlorophyll and powers the whole process. Pinch the Sun to hold it.')
  });
  traits(waterGroup, {
    grab: true,
    onPress: () => show('Water: roots absorb H2O from soil. It moves up the stem to leaves.')
  });
  traits(co2Group, {
    grab: true,
    onPress: () => show('Carbon dioxide: CO2 from air enters leaves through stomata. Carbon builds sugar.')
  });
  traits(lightArrow, { onPress: () => show('Light arrow: energy flows from Sun to leaf. Use the Light button to make night.') });
  traits(waterArrow, { onPress: () => show('Water arrow: blue shows H2O going into soil and up to leaves.') });
  traits(co2Arrow, { onPress: () => show('CO2 arrow: gray shows carbon dioxide from air going into the leaf.') });
  traits(o2Arrow, { onPress: () => show('Oxygen arrow: green shows fresh O2 leaving the leaf for us to breathe.') });
  traits(leafL, { onPress: () => show('Leaves are food factories. Green chlorophyll captures light.') });
  traits(leafR, { onPress: () => show('Leaves are food factories. Green chlorophyll captures light.') });
  traits(leafTop, { onPress: () => show('Inside chloroplasts, light + H2O + CO2 become glucose + O2.') });
  traits(sugar, { onPress: () => show('Glucose C6H12O6 is plant sugar. It stores sun energy as food.') });
  traits(o2Group, { onPress: () => show('Oxygen O2 is released by leaves. Animals and people need it.') });

  const tmpV = new THREE.Vector3();
  const leafLBase = leafL.rotation.z;
  const leafRBase = leafR.rotation.z;

  return {
    root,
    update(time) {
      // sun glow follows hand when grabbed
      if (!isGrabbed(sun)) {
        const p = 1.0 + Math.sin(time * 2.2) * 0.07;
        glow.scale.set(p, p, p);
      }
      glow.position.copy(sun.position);

      // gentle leaf sway (slow, pressable only)
      leafL.rotation.z = leafLBase + Math.sin(time * 1.4) * 0.06;
      leafR.rotation.z = leafRBase - Math.sin(time * 1.4 + 0.6) * 0.06;
      sugar.position.y = 0.27 + Math.sin(time * 2.0) * 0.003;

      // light on/off look
      if (lightOn) {
        sunMat.emissiveIntensity = 1.0 + Math.sin(time * 2.2) * 0.15;
        glowMat.opacity = 0.22;
        lightArrow.userData.mat.emissiveIntensity = 0.5;
        dotLight.visible = true;
      } else {
        sunMat.emissiveIntensity = 0.08;
        glowMat.opacity = 0.05;
        lightArrow.userData.mat.emissiveIntensity = 0.05;
        dotLight.visible = false;
      }

      // flowing dots along arrows (slow)
      for (let i = 0; i < flows.length; i++) {
        const f = flows[i];
        if (f.key === 'light' && !lightOn) continue;
        let t = (time * 0.35 + f.off) % 1;
        tmpV.lerpVectors(f.from, f.to, t);
        f.mesh.position.copy(tmpV);
      }
    }
  };
}

