  leafT.name = 'LeafTop';
  leafT.position.set(0, 0.235, 0.05);
  leafT.scale.set(1.1, 0.3, 0.8);
  leafT.rotation.z = 0.15;
  plantGroup.add(leafT);

  // ---------- sun (grabbable) ----------
  const sunGroup = new THREE.Group();
  sunGroup.position.set(-0.26, 0.33, -0.12);
  root.add(sunGroup);
  const sunMat = new THREE.MeshStandardMaterial({ color: 0xffc23d, emissive: 0xff8a00, emissiveIntensity: 1.0, roughness: 0.4 });
  const sun = new THREE.Mesh(new THREE.SphereGeometry(0.045, 28, 16), sunMat);
