  sunGroup.add(glow);

  // ---------- arrow builder ----------
  function makeArrow(sx, sy, sz, ex, ey, ez, color) {
    const start = new THREE.Vector3(sx, sy, sz);
    const end = new THREE.Vector3(ex, ey, ez);
    const dir = new THREE.Vector3().subVectors(end, start);
    const len = dir.length();
    dir.normalize();
    const g = new THREE.Group();
    g.position.copy(start);
    g.quaternion.setFromUnitVectors(UP, dir);
    const shaftLen = Math.max(0.02, len - 0.025);
    const shaftGeo = new THREE.CylinderGeometry(0.004, 0.004, shaftLen, 10);
    const mat = new THREE.MeshStandardMaterial({ color: color, roughness: 0.5, emissive: color, emissiveIntensity: 0.25 });
    const shaft = new THREE.Mesh(shaftGeo, mat);
    shaft.position.y = shaftLen / 2;
    g.add(shaft);
    const headGeo = new THREE.ConeGeometry(0.01, 0.025, 14);
    const head = new THREE.Mesh(headGeo, mat);
    head.position.y = shaftLen + 0.0125;
    g.add(head);
    root.add(g);
    return { group: g, start: start, end: end };
  }

  const aLight = makeArrow(-0.22, 0.30, -0.10, -0.045, 0.21, 0.02, 0xffd43b);
