  const aCO2 = makeArrow(0.22, 0.27, -0.06, 0.06, 0.20, 0.03, 0xced4da);
  aCO2.group.name = 'ArrowCO2';
  const aO2 = makeArrow(-0.03, 0.225, 0.04, -0.15, 0.305, 0.02, 0x69db7c);
  aO2.group.name = 'ArrowOxygen';

  // ---------- flow dots (scenery, not grabbable) ----------
