  const flowLight = new THREE.Mesh(flowGeo, new THREE.MeshBasicMaterial({ color: 0xffe066 }));
  const flowWater = new THREE.Mesh(flowGeo, new THREE.MeshBasicMaterial({ color: 0x74c0fc }));
  const flowCO2 = new THREE.Mesh(flowGeo, new THREE.MeshBasicMaterial({ color: 0xe9ecef }));
  const flowO2 = new THREE.Mesh(flowGeo, new THREE.MeshBasicMaterial({ color: 0x8ce99a }));
  root.add(flowLight); root.add(flowWater); root.add(flowCO2); root.add(flowO2);

