  const drop = new THREE.Mesh(new THREE.SphereGeometry(0.015, 18, 12), waterMat);
  drop.name = 'Water';
  drop.scale.set(1, 1.25, 1);
  waterGroup.add(drop);

  // CO2 : O=C=O
