  root.add(co2Group);
  const cMat = new THREE.MeshStandardMaterial({ color: 0x495057, roughness: 0.5 });
  const oMat = new THREE.MeshStandardMaterial({ color: 0xfa5252, roughness: 0.5 });
  const cAtom = new THREE.Mesh(new THREE.SphereGeometry(0.012, 16, 10), cMat);
  cAtom.name = 'CO2';
  co2Group.add(cAtom);
  const o1 = new THREE.Mesh(new THREE.SphereGeometry(0.012, 16, 10), oMat);
  o1.position.set(-0.024, 0, 0);
  co2Group.add(o1);
  const o2 = new THREE.Mesh(new THREE.SphereGeometry(0.012, 16, 10), oMat);
  o2.position.set(0.024, 0, 0);
  co2Group.add(o2);

  // O2
  const o2Group = new THREE.Group();
  o2Group.position.set(-0.15, 0.305, 0.02);
  root.add(o2Group);
  const o2Mat = new THREE.MeshStandardMaterial({ color: 0x69db7c, roughness: 0.4 });
  const oo1 = new THREE.Mesh(new THREE.SphereGeometry(0.013, 16, 10), o2Mat);
  oo1.name = 'Oxygen';
  oo1.position.set(-0.013, 0, 0);
  o2Group.add(oo1);
  const oo2 = new THREE.Mesh(new THREE.SphereGeometry(0.013, 16, 10), o2Mat);
  oo2.position.set(0.013, 0, 0);
  o2Group.add(oo2);

  // photon near sun
  const photonGroup = new THREE.Group();
  photonGroup.position.set(-0.19, 0.28, -0.06);
  root.add(photonGroup);
  const photon = new THREE.Mesh(
    new THREE.SphereGeometry(0.012, 16, 10),
    new THREE.MeshBasicMaterial({ color: 0xffec99 })
  );
  photon.name = 'Photon';
  photonGroup.add(photon);

  // ---------- UI : main panel ----------
  const info = ui(`
    <style>
      .card { width: 480px; flex-direction: column; gap: 8px; padding-top: 14px; padding-bottom: 14px; padding-left: 16px; padding-right: 16px; border-radius: 16px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; text-align: center; }
      .eq { color: #ffe066; font-size: 25px; text-align: center; }
      .detail { color: #d7dbe2; font-size: 25px; text-align: center; }
      .row { display: flex; flex-direction: row; gap: 8px; align-items: center; justify-content: center; }
      .bY { padding-top: 8px; padding-bottom: 8px; padding-left: 10px; padding-right: 10px; border-radius: 10px; background-color: #8a6d00; }
      .bB { padding-top: 8px; padding-bottom: 8px; padding-left: 10px; padding-right: 10px; border-radius: 10px; background-color: #1864ab; }
      .bG { padding-top: 8px; padding-bottom: 8px; padding-left: 10px; padding-right: 10px; border-radius: 10px; background-color: #5f6368; }
      .bT { padding-top: 8px; padding-bottom: 8px; padding-left: 10px; padding-right: 10px; border-radius: 10px; background-color: #2b8a3e; }
      .bD { padding-top: 8px; padding-bottom: 8px; padding-left: 12px; padding-right: 12px; border-radius: 10px; background-color: #343a40; }
      .bt { color: #ffffff; font-size: 25px; font-weight: 700; }
      .hint { color: #adb5bd; font-size: 25px; text-align: center; }
    </style>
    <div class="card">
      <span class="title">Photosynthesis</span>
      <span class="eq">6 CO2 + 6 H2O + light -> C6H12O6 + 6 O2</span>
      <span class="detail" id="detail">A plant makes sugar from air and water using light. Press an arrow.</span>
      <div class="row">
        <button class="bY" id="btnLight"><span class="bt">Light</span></button>
        <button class="bB" id="btnWater"><span class="bt">Water</span></button>
        <button class="bG" id="btnCO2"><span class="bt">CO2</span></button>
        <button class="bT" id="btnO2"><span class="bt">O2</span></button>
      </div>
      <div class="row">
        <button class="bD" id="flowBtn"><span class="bt" id="flowTxt">Pause flow</span></button>
      </div>
      <span class="hint">Pinch the Sun, plant and molecules to grab them.</span>
    </div>`, { width: 0.3, position: [0.22, 0.15, 0.14], rotationY: -0.35 });
  root.add(info.object3D);

  function lblPanel(text, border, pos, rot, w) {
    const h = ui(`
      <style>
        .lbl { width: 180px; flex-direction: row; gap: 6px; align-items: center; justify-content: center; padding-top: 8px; padding-bottom: 8px; padding-left: 10px; padding-right: 10px; border-radius: 10px; background-color: #1a1d22; border-color: ${border}; border-width: 3px; }
        .t { color: #ffffff; font-size: 22px; font-weight: 700; text-align: center; }
      </style>
      <div class="lbl"><span class="t">${text}</span></div>`, { width: w, position: pos, rotationY: rot });
    root.add(h.object3D);
    return h;
  }
  lblPanel('Light in', '#ffd43b', [-0.14, 0.395, -0.06], 0.15, 0.12);
  lblPanel('O2 out', '#69db7c', [-0.26, 0.235, 0.02], 0.25, 0.12);
  lblPanel('Water in H2O', '#4dabf7', [0.08, 0.035, 0.10], -0.2, 0.13);
  lblPanel('CO2 in', '#ced4da', [0.18, 0.315, -0.04], -0.25, 0.12);

  const T_LIGHT = 'Light: sunlight hits chlorophyll in leaves and supplies energy. Pinch the yellow photon.';
  const T_WATER = 'Water: H2O is taken up by roots from soil and moves to leaves. It gives H for sugar.';
  const T_CO2 = 'Carbon dioxide: CO2 enters leaves from air. Its carbon becomes sugar C6H12O6. Grab the red-grey model.';
  const T_O2 = 'Oxygen: O2 is released from leaves to air. It comes from splitting water. Grab the green pair.';
  const T_PLANT = 'Chlorophyll in leaves captures light and builds sugar. Sugar feeds the plant. O2 leaves as a by-product.';

  function show(t) { info.set('detail', { text: t }); }
  info.on('btnLight', 'click', () => show(T_LIGHT));
  info.on('btnWater', 'click', () => show(T_WATER));
  info.on('btnCO2', 'click', () => show(T_CO2));
  info.on('btnO2', 'click', () => show(T_O2));

  let flowing = true;
  info.on('flowBtn', 'click', () => {
    flowing = !flowing;
    info.set('flowTxt', { text: flowing ? 'Pause flow' : 'Play flow' });
  });

  traits(plantGroup, { grab: true, onPress: () => show(T_PLANT) });
  traits(sunGroup, { grab: true, onPress: () => show(T_LIGHT) });
  traits(waterGroup, { grab: true, onPress: () => show(T_WATER) });
  traits(co2Group, { grab: true, onPress: () => show(T_CO2) });
  traits(o2Group, { grab: true, onPress: () => show(T_O2) });
  traits(photonGroup, { grab: true, onPress: () => show(T_LIGHT) });
  traits(aLight.group, { onPress: () => show(T_LIGHT) });
  traits(aWater.group, { onPress: () => show(T_WATER) });
  traits(aCO2.group, { onPress: () => show(T_CO2) });
  traits(aO2.group, { onPress: () => show(T_O2) });

  // bases for bobbing
  const waterBaseY = waterGroup.position.y;
  const co2BaseY = co2Group.position.y;
  const o2BaseY = o2Group.position.y;
  const photonBaseY = photonGroup.position.y;
  let flowTime = 0;

  return {
    root,
    update(time, delta) {
      if (flowing) flowTime += delta;
      const s = 0.35;
      let t = (flowTime * s) % 1;
      flowLight.position.set(
        aLight.start.x + (aLight.end.x - aLight.start.x) * t,
        aLight.start.y + (aLight.end.y - aLight.start.y) * t,
        aLight.start.z + (aLight.end.z - aLight.start.z) * t
      );
      t = (flowTime * s + 0.25) % 1;
      flowWater.position.set(
        aWater.start.x + (aWater.end.x - aWater.start.x) * t,
        aWater.start.y + (aWater.end.y - aWater.start.y) * t,
        aWater.start.z + (aWater.end.z - aWater.start.z) * t
      );
      t = (flowTime * s + 0.5) % 1;
      flowCO2.position.set(
        aCO2.start.x + (aCO2.end.x - aCO2.start.x) * t,
        aCO2.start.y + (aCO2.end.y - aCO2.start.y) * t,
        aCO2.start.z + (aCO2.end.z - aCO2.start.z) * t
      );
      t = (flowTime * s + 0.75) % 1;
      flowO2.position.set(
        aO2.start.x + (aO2.end.x - aO2.start.x) * t,
        aO2.start.y + (aO2.end.y - aO2.start.y) * t,
        aO2.start.z + (aO2.end.z - aO2.start.z) * t
      );

      if (!isGrabbed(sunGroup)) {
        const p = 1 + Math.sin(time * 2.0) * 0.05;
        glow.scale.set(p, p, p);
      }
      if (!isGrabbed(plantGroup)) {
        leafL.rotation.z = 0.5 + Math.sin(time * 1.2) * 0.08;
        leafR.rotation.z = -0.5 - Math.sin(time * 1.2 + 1.0) * 0.08;
        leafT.rotation.z = 0.15 + Math.sin(time * 1.4) * 0.06;
      }
      if (!isGrabbed(waterGroup)) waterGroup.position.y = waterBaseY + Math.sin(time * 1.5) * 0.005;
      if (!isGrabbed(co2Group)) co2Group.position.y = co2BaseY + Math.sin(time * 1.5 + 2.0) * 0.005;
      if (!isGrabbed(o2Group)) o2Group.position.y = o2BaseY + Math.sin(time * 1.5 + 4.0) * 0.005;
      if (!isGrabbed(photonGroup)) photonGroup.position.y = photonBaseY + Math.sin(time * 2.2) * 0.005;
    }
  };
}

