  const steamGeo = new THREE.SphereGeometry(0.009, 12, 8);
  const steamMatA = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.22 });
  const steamMatB = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.15 });
  const steam1 = new THREE.Mesh(steamGeo, steamMatA);
  steam1.name = 'Steam 1';
  const steam2 = new THREE.Mesh(steamGeo, steamMatB);
  steam2.name = 'Steam 2';
  mug.add(steam1);
  mug.add(steam2);

  traits(mug, { grab: true });

  const card = ui(`
    <style>
      .card { width: 500px; flex-direction: column; gap: 8px; padding-top: 18px; padding-bottom: 18px; padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .price { color: #7df0a8; font-size: 30px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 23px; }
      .detail { color: #aab0bb; font-size: 21px; }
      .hint { color: #ffd98a; font-size: 21px; }
      .row { flex-direction: row; gap: 10px; margin-top: 6px; }
      .sw { padding-top: 10px; padding-bottom: 10px; padding-left: 12px; padding-right: 12px; border-radius: 12px; background-color: #343a44; }
      .sw-text { color: #ffffff; font-size: 21px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Handmade Camp Mug</span>
      <span class="price">$18.50</span>
      <span class="body">Made of glazed stoneware - kiln-fired clay with a food-safe glaze.</span>
      <span class="detail">12 oz / 350 ml - Dishwasher + microwave safe</span>
      <span class="hint" id="hint">Pinch the mug to pick it up.</span>
      <div class="row">
        <button class="sw" id="cCream"><span class="sw-text">Cream</span></button>
        <button class="sw" id="cSage"><span class="sw-text">Sage</span></button>
        <button class="sw" id="cClay"><span class="sw-text">Clay</span></button>
      </div>
    </div>`, { width: 0.32, position: [0.17, 0.21, 0.02], rotationY: -0.28 });
  root.add(card.object3D);

  card.on('cCream', 'click', () => {
    bodyMat.color.set(0xf2ead9);
    card.set('hint', { text: 'Cream glaze - classic stoneware white.' });
  });
  card.on('cSage', 'click', () => {
    bodyMat.color.set(0x9db89a);
    card.set('hint', { text: 'Sage glaze - same stoneware, green tint.' });
  });
  card.on('cClay', 'click', () => {
    bodyMat.color.set(0xc47a4a);
    card.set('hint', { text: 'Clay glaze - warm terracotta stoneware.' });
  });

  return {
    root,
    update(time) {
      // Steam rises and fades in a loop, follows mug even when held
      const t1 = (time * 0.35) % 1;
      const t2 = (time * 0.35 + 0.5) % 1;
      steam1.position.set(-0.008, 0.105 + t1 * 0.07, 0.005);
      steam2.position.set(0.01, 0.105 + t2 * 0.07, -0.004);
      const s1 = 0.7 + t1 * 1.1;
      const s2 = 0.7 + t2 * 1.1;
      steam1.scale.set(s1, s1, s1);
      steam2.scale.set(s2, s2, s2);
      steamMatA.opacity = 0.28 * (1 - t1);
      steamMatB.opacity = 0.22 * (1 - t2);
      void isGrabbed;
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
