  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(-0.10, 0.0012, 0.06);
  root.add(shadow);

  // ----- Steam (animated scenery, follows mug) -----
  const steamGeo = new THREE.SphereGeometry(0.012, 12, 8);
  const steamMeshes = [];
  const steamMats = [];
  for (let i = 0; i < 3; i++) {
    const m = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.25 });
    const s = new THREE.Mesh(steamGeo, m);
    s.name = 'Steam' + i;
    mugGroup.add(s);
    steamMeshes.push(s);
    steamMats.push(m);
  }

  // ----- Info card -----
  const info = ui(`
    <style>
      .card { width: 500px; display: flex; flex-direction: column; gap: 10px; padding-top: 18px; padding-bottom: 18px; padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #23262d; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; text-align: left; }
      .price { color: #ffd166; font-size: 32px; font-weight: 700; text-align: left; }
      .body { color: #d7dbe2; font-size: 22px; text-align: left; }
      .hint { color: #a8e6a3; font-size: 22px; text-align: left; }
      .row { display: flex; flex-direction: row; gap: 10px; align-items: center; justify-content: flex-start; }
      .label { color: #9aa0ab; font-size: 20px; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px; border-radius: 12px; background-color: #353a43; border-width: 0px; border-color: #000000; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Stoneware Coffee Mug</span>
      <span class="price">$14.99</span>
      <span class="body">Made of glazed stoneware ceramic. Matte outside, glossy inside. Holds 350 ml. Dishwasher and microwave safe.</span>
      <span class="hint" id="hint">Pinch the mug to pick it up.</span>
      <div class="row">
        <span class="label" id="colorName">Color: Cream</span>
        <button class="btn" id="bCream"><span class="btn-text">Cream</span></button>
        <button class="btn" id="bOcean"><span class="btn-text">Ocean</span></button>
        <button class="btn" id="bClay"><span class="btn-text">Clay</span></button>
      </div>
    </div>`, { width: 0.30, position: [0.20, 0.19, 0.05], rotationY: -0.28 });
  root.add(info.object3D);

  function selectColor(name, hex, btnId) {
    mugMat.color.setHex(hex);
    info.set('colorName', { text: 'Color: ' + name });
    info.set('bCream', { backgroundColor: btnId === 'bCream' ? '#2f6fdb' : '#353a43' });
    info.set('bOcean', { backgroundColor: btnId === 'bOcean' ? '#2f6fdb' : '#353a43' });
    info.set('bClay', { backgroundColor: btnId === 'bClay' ? '#2f6fdb' : '#353a43' });
  }

  info.on('bCream', 'click', () => selectColor('Cream', 0xf2ede4, 'bCream'));
  info.on('bOcean', 'click', () => selectColor('Ocean', 0x2f6fdb, 'bOcean'));
  info.on('bClay', 'click', () => selectColor('Clay', 0xc96f4a, 'bClay'));
  info.set('bCream', { backgroundColor: '#2f6fdb' });

  traits(mugGroup, {
    grab: true,
    onPress: () => {
      info.set('hint', { text: 'Nice! Lift it, turn it, set it back on the saucer.' });
    }
  });

  let wasHeld = false;

  return {
    root,
    update(time) {
      // Steam rises slowly from the coffee
      for (let i = 0; i < 3; i++) {
        const f = (time * 0.22 + i * 0.333) % 1;
        const m = steamMeshes[i];
        m.position.set(
          Math.sin(time * 1.4 + i * 2.1) * 0.008,
          0.105 + f * 0.115,
          Math.cos(time * 1.1 + i * 1.7) * 0.006
        );
        const s = 0.55 + f * 1.25;
        m.scale.set(s, s, s);
        steamMats[i].opacity = 0.30 * (1 - f);
      }

      const held = isGrabbed(mugGroup);
      if (held && !wasHeld) {
        info.set('hint', { text: 'You are holding it. Stoneware feels solid and warm.' });
      } else if (!held && wasHeld) {
        info.set('hint', { text: 'Pinch the mug to pick it up.' });
      }
      wasHeld = held;
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const earthGroup = new THREE.Group();
  earthGroup.position.set(-0.12, 0.28, -0.10);
  earthGroup.rotation.y = 2.99;
  earthGroup.name = 'EarthCutaway';
  root.add(earthGroup);
  traits(earthGroup, { grab: true });

  const layers = [
    { name: 'Crust', css: '#c69a6b', color: 0xc69a6b, r: 0.14, depth: '0-30 km', temp: '0-400 C', desc: 'Thin rocky skin. Oceanic 5-10 km, continental 30-70 km. You stand on it.' },
    { name: 'Upper Mantle', css: '#ff8c42', color: 0xff8c42, r: 0.126, depth: '30-660 km', temp: '500-1400 C', desc: 'Hot flowing rock to 660 km. Moves plates and feeds volcanoes.' },
    { name: 'Lower Mantle', css: '#e04a2f', color: 0xe04a2f, r: 0.102, depth: '660-2890 km', temp: '1400-3000 C', desc: 'Stiff hot rock 660-2890 km. Mostly bridgmanite, creeps slowly.' },
    { name: 'Outer Core', css: '#ffb300', color: 0xffb300, r: 0.06, depth: '2890-5150 km', temp: '3000-5000 C', desc: 'Liquid iron-nickel 2890-5150 km. Its flow makes the magnetic field.' },
    { name: 'Inner Core', css: '#fff176', color: 0xfff176, r: 0.03, depth: '5150-6371 km', temp: '5000-5500 C', desc: 'Solid iron-nickel ball 5150-6371 km. About as hot as the Sun surface.' }
  ];
  const mids = [0.133, 0.114, 0.081, 0.045, 0.015];
  const labelY = [0.36, 0.305, 0.25, 0.195, 0.14];

  const sphereMats = [];
  const discMats = [];
  const phiLen = Math.PI * 1.5;

  for (let i = 0; i < layers.length; i++) {
    const L = layers[i];
    const sm = new THREE.MeshStandardMaterial({
      color: L.color, roughness: 0.65, metalness: 0.05,
      side: THREE.DoubleSide, emissive: L.color, emissiveIntensity: 0.15
    });
    sphereMats.push(sm);
    const sg = new THREE.SphereGeometry(L.r, 32, 18, 0, phiLen, 0, Math.PI);
    const s = new THREE.Mesh(sg, sm);
    s.name = L.name;
    earthGroup.add(s);

    const dm = new THREE.MeshStandardMaterial({
      color: L.color, roughness: 0.85, metalness: 0.0,
      side: THREE.DoubleSide, emissive: L.color, emissiveIntensity: 0.15
    });
    discMats.push(dm);
    const cg = new THREE.CircleGeometry(L.r, 40, Math.PI / 2, Math.PI);
    const off = i * 0.0005;
    const d1 = new THREE.Mesh(cg, dm);
    d1.position.set(0, 0, -off);
    d1.name = L.name + '-cutA';
    earthGroup.add(d1);
    const d2 = new THREE.Mesh(cg, dm);
    d2.rotation.y = -Math.PI / 2;
    d2.position.set(-off, 0, 0);
    d2.name = L.name + '-cutB';
    earthGroup.add(d2);
  }

  const contMat = new THREE.MeshStandardMaterial({ color: 0x66bb6a, roughness: 0.9 });
  const contGeo = new THREE.SphereGeometry(0.024, 16, 12);
  const c1 = new THREE.Mesh(contGeo, contMat);
  c1.position.set(0.0, 0.08, 0.115); c1.scale.set(1, 0.45, 1); c1.name = 'Continent';
  earthGroup.add(c1);
  const c2 = new THREE.Mesh(contGeo, contMat);
  c2.position.set(0.09, 0.02, 0.10); c2.scale.set(1.2, 0.4, 0.9); c2.name = 'Continent';
  earthGroup.add(c2);
  const c3 = new THREE.Mesh(contGeo, contMat);
  c3.position.set(-0.07, -0.06, 0.10); c3.scale.set(0.9, 0.4, 1.1); c3.name = 'Continent';
  earthGroup.add(c3);

  const stand = new THREE.Mesh(
    new THREE.CylinderGeometry(0.09, 0.11, 0.02, 32),
    new THREE.MeshStandardMaterial({ color: 0x2f3540, roughness: 0.9 })
  );
  stand.position.set(-0.12, 0.01, -0.10);
  stand.name = 'Stand';
  root.add(stand);

  // labels (one per layer) - enlarged text for headset readability
  const labelHandles = [];
  for (let i = 0; i < layers.length; i++) {
    const L = layers[i];
    const markup =
      '<style>' +
      '.lab{width:320px;flex-direction:row;align-items:center;gap:12px;padding-top:10px;padding-bottom:10px;padding-left:14px;padding-right:14px;border-radius:14px;background-color:#22262d;}' +
      '.dot{width:18px;height:18px;border-radius:9px;background-color:' + L.css + ';}' +
      '.txt{color:#ffffff;font-size:26px;font-weight:700;}' +
      '.sub{color:#b8bec9;font-size:25px;}' +
      '</style>' +
      '<button class="lab" id="b"><span class="dot"> </span><span class="txt">' + L.name + '</span><span class="sub">' + L.depth + '</span></button>';
    const h = ui(markup, { width: 0.19, position: [0.15, labelY[i], -0.06], rotationY: 0 });
    root.add(h.object3D);
    labelHandles.push(h);
  }

  const detail = ui(
    '<style>' +
    '.card{width:500px;flex-direction:column;gap:8px;padding-top:16px;padding-bottom:16px;padding-left:20px;padding-right:20px;border-radius:18px;background-color:#1f2228;}' +
    '.title{color:#ffffff;font-size:30px;font-weight:700;text-align:center;}' +
    '.sub{color:#aeb4bf;font-size:22px;text-align:center;}' +
    '.name{color:#ffd54f;font-size:28px;font-weight:700;text-align:center;}' +
    '.meta{color:#d7dbe2;font-size:22px;text-align:center;}' +
    '.desc{color:#d7dbe2;font-size:22px;text-align:center;}' +
    '.row{flex-direction:row;gap:10px;align-items:center;justify-content:center;}' +
    '.btn{padding-top:8px;padding-bottom:8px;padding-left:16px;padding-right:16px;border-radius:12px;background-color:#2f6fdb;}' +
    '.btn-text{color:#ffffff;font-size:22px;font-weight:700;}' +
    '.hint{color:#9aa0ad;font-size:22px;text-align:center;}' +
    '</style>' +
    '<div class="card">' +
    '<span class="title">Layers of the Earth</span>' +
    '<span class="sub">Cut-away view - thickness not to scale</span>' +
    '<span class="name" id="tName">Crust</span>' +
    '<span class="meta" id="tMeta">0-30 km - 0-400 C</span>' +
    '<span class="desc" id="tDesc">Thin rocky skin.</span>' +
    '<div class="row"><button class="btn" id="prev"><span class="btn-text">Prev</span></button><button class="btn" id="next"><span class="btn-text">Next</span></button><button class="btn" id="spin"><span class="btn-text" id="spinT">Spin: Off</span></button></div>' +
    '<span class="hint">Pinch globe to move - tap a label to inspect</span>' +
    '</div>',
    { width: 0.34, position: [0.06, 0.055, 0.02], rotationY: 0 }
  );
  root.add(detail.object3D);

  let selected = 0;
  let spinOn = false;

  function select(k) {
    selected = (k + layers.length) % layers.length;
    const L = layers[selected];
    detail.set('tName', { text: L.name });
    detail.set('tMeta', { text: L.depth + ' - ' + L.temp });
    detail.set('tDesc', { text: L.desc });
    for (let j = 0; j < layers.length; j++) {
      const on = j === selected;
      labelHandles[j].set('b', { backgroundColor: on ? '#3a4556' : '#22262d' });
      sphereMats[j].emissiveIntensity = on ? 0.65 : 0.15;
      discMats[j].emissiveIntensity = on ? 0.65 : 0.15;
    }
  }

  for (let i = 0; i < layers.length; i++) {
    const idx = i;
    labelHandles[i].on('b', 'click', () => select(idx));
  }
  detail.on('prev', 'click', () => select(selected - 1));
  detail.on('next', 'click', () => select(selected + 1));
  detail.on('spin', 'click', () => {
    spinOn = !spinOn;
    detail.set('spinT', { text: spinOn ? 'Spin: On' : 'Spin: Off' });
  });
  select(0);

  const lineGeos = [];
  const linesPos = [];
  for (let i = 0; i < layers.length; i++) {
    const g = new THREE.BufferGeometry();
    const arr = new Float32Array(6);
    arr[0] = -0.12; arr[1] = 0.28; arr[2] = -0.10;
    arr[3] = 0.055; arr[4] = labelY[i]; arr[5] = -0.06;
    g.setAttribute('position', new THREE.BufferAttribute(arr, 3));
    const line = new THREE.Line(g, new THREE.LineBasicMaterial({ color: layers[i].color }));
    line.name = layers[i].name + '-leader';
    root.add(line);
    lineGeos.push(g);
    linesPos.push(arr);
  }

  const localDir = new THREE.Vector3(-0.7071, 0, -0.7071);
  const tmpDir = new THREE.Vector3();
  const tmpStart = new THREE.Vector3();

  return {
    root,
    update(time, delta) {
      if (spinOn && !isGrabbed(earthGroup)) {
        earthGroup.rotation.y += delta * 0.35;
      }
      if (selected !== 3) sphereMats[3].emissiveIntensity = 0.32 + 0.12 * Math.sin(time * 2.2);
      if (selected !== 4) sphereMats[4].emissiveIntensity = 0.38 + 0.12 * Math.sin(time * 2.2 + 1.0);
      if (selected !== 3) discMats[3].emissiveIntensity = sphereMats[3].emissiveIntensity;
      if (selected !== 4) discMats[4].emissiveIntensity = sphereMats[4].emissiveIntensity;

      for (let i = 0; i < 5; i++) {
        tmpDir.copy(localDir).applyQuaternion(earthGroup.quaternion);
        tmpStart.copy(earthGroup.position).addScaledVector(tmpDir, mids[i]);
        const p = linesPos[i];
        p[0] = tmpStart.x; p[1] = tmpStart.y; p[2] = tmpStart.z;
        p[3] = 0.055; p[4] = labelY[i]; p[5] = -0.06;
        lineGeos[i].attributes.position.needsUpdate = true;
      }
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const QUESTIONS = [
    { a: 3, b: 4, opts: [7, 12, 16, 9], correct: 1 },
    { a: 6, b: 7, opts: [36, 48, 42, 49], correct: 2 },
    { a: 4, b: 9, opts: [36, 32, 45, 27], correct: 0 },
    { a: 7, b: 8, opts: [63, 48, 56, 49], correct: 2 },
    { a: 9, b: 6, opts: [48, 54, 63, 45], correct: 1 }
  ];

  let idx = 0;
  let score = 0;
  let answered = false;
  let finished = false;
  let results = [null, null, null, null, null];

  // --- 3D: board for multiplication groups ---
  const board = new THREE.Mesh(
    new THREE.BoxGeometry(0.28, 0.012, 0.28),
    new THREE.MeshStandardMaterial({ color: 0x2a2e35, roughness: 0.9 })
  );
  board.position.set(-0.16, 0.006, -0.08);
  board.name = 'Board';
  root.add(board);

  const gridMat = new THREE.MeshStandardMaterial({ color: 0x4da3ff, roughness: 0.4 });
  const gridGeo = new THREE.BoxGeometry(0.018, 0.018, 0.018);
  const grid = new THREE.InstancedMesh(gridGeo, gridMat, 144);
  grid.position.set(-0.16, 0.026, -0.08);
  grid.name = 'GroupsGrid';
  root.add(grid);
  const dummy = new THREE.Object3D();

  function updateGrid() {
    if (finished) {
      grid.count = 0;
      grid.instanceMatrix.needsUpdate = true;
      return;
    }
    const q = QUESTIONS[idx];
    const rows = q.a;
    const cols = q.b;
    const spacing = 0.021;
    let n = 0;
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        dummy.position.set(
          (c - (cols - 1) / 2) * spacing,
          0,
          (r - (rows - 1) / 2) * spacing
        );
        dummy.rotation.set(0, 0, 0);
        dummy.updateMatrix();
        grid.setMatrixAt(n, dummy.matrix);
        n++;
      }
    }
    grid.count = n;
    grid.instanceMatrix.needsUpdate = true;
    gridMat.color.set(0x4da3ff);
  }
  updateGrid();

  // --- 3D: progress orbs ---
  const orbGeo = new THREE.SphereGeometry(0.018, 24, 12);
  const orbs = [];
  const orbMats = [];
  for (let i = 0; i < 5; i++) {
    const m = new THREE.MeshStandardMaterial({ color: 0x555c66, roughness: 0.5 });
    const s = new THREE.Mesh(orbGeo, m);
    s.position.set(-0.28 + i * 0.06, 0.025, 0.14);
    s.name = 'Q' + (i + 1);
    root.add(s);
    orbs.push(s);
    orbMats.push(m);
  }

  function updateOrbs() {
    for (let i = 0; i < 5; i++) {
      if (results[i] === true) orbMats[i].color.set(0x2ecc71);
      else if (results[i] === false) orbMats[i].color.set(0xe74c3c);
      else if (i === idx && !finished) orbMats[i].color.set(0xffffff);
      else orbMats[i].color.set(0x555c66);
    }
  }
  updateOrbs();

  // --- 3D: score stars ---
  const starGeo = new THREE.OctahedronGeometry(0.018);
  const starMatBase = new THREE.MeshStandardMaterial({ color: 0xffd166, emissive: 0xcc8a00, emissiveIntensity: 0.7, roughness: 0.3 });
  const stars = [];
  const starBaseY = [];
  for (let i = 0; i < 5; i++) {
    const st = new THREE.Mesh(starGeo, starMatBase.clone());
    st.position.set(-0.28 + i * 0.06, 0.32, -0.14);
    st.scale.setScalar(0.0001);
    st.name = 'Star' + (i + 1);
    root.add(st);
    stars.push(st);
    starBaseY.push(0.32);
  }

  function updateStars() {
    for (let i = 0; i < 5; i++) {
      if (i < score) stars[i].scale.setScalar(1);
      else stars[i].scale.setScalar(0.0001);
    }
  }

  // --- 3D: grabbable hint cube ---
  const mascot = new THREE.Mesh(
    new THREE.BoxGeometry(0.055, 0.055, 0.055),
    new THREE.MeshStandardMaterial({ color: 0xff8a2a, roughness: 0.5 })
  );
  mascot.position.set(0.06, 0.04, 0.16);
  mascot.name = 'HintCube';
  root.add(mascot);

  const crossMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
  const barGeo = new THREE.BoxGeometry(0.04, 0.008, 0.002);
  const bar1 = new THREE.Mesh(barGeo, crossMat);
  bar1.position.set(0, 0, 0.028);
  bar1.rotation.z = Math.PI / 4;
  mascot.add(bar1);
  const bar2 = new THREE.Mesh(barGeo, crossMat);
  bar2.position.set(0, 0, 0.028);
  bar2.rotation.z = -Math.PI / 4;
  mascot.add(bar2);

  // --- UI panel ---
  const quiz = ui(`
    <style>
      .card { width: 520px; flex-direction: column; gap: 10px; padding-top: 16px; padding-bottom: 16px; padding-left: 20px; padding-right: 20px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; text-align: center; }
      .sub { color: #9fb3c8; font-size: 22px; text-align: center; }
      .q { color: #ffd166; font-size: 36px; font-weight: 700; text-align: center; }
      .feed { color: #d7dbe2; font-size: 22px; text-align: center; }
      .grid { flex-direction: column; gap: 10px; align-items: center; }
      .row { flex-direction: row; gap: 10px; }
      .opt { width: 225px; padding-top: 10px; padding-bottom: 10px; padding-left: 10px; padding-right: 10px; border-radius: 12px; background-color: #2f6fdb; }
      .opttxt { color: #ffffff; font-size: 26px; font-weight: 700; text-align: center; }
      .score { color: #7bed9f; font-size: 24px; font-weight: 700; text-align: center; }
      .next { padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px; border-radius: 12px; background-color: #e67e22; }
      .nexttxt { color: #ffffff; font-size: 22px; font-weight: 700; text-align: center; }
      .hint { color: #8a94a6; font-size: 20px; text-align: center; }
    </style>
    <div class="card">
      <span class="title">Multiplication Quiz</span>
      <span class="sub" id="progress">Question 1 of 5</span>
      <span class="q" id="question">3 x 4 = ?</span>
      <span class="feed" id="feedback">Pinch an answer. Grab orange cube for hint.</span>
      <div class="grid" id="grid">
        <div class="row">
          <button class="opt" id="opt0"><span class="opttxt" id="opt0t">7</span></button>
          <button class="opt" id="opt1"><span class="opttxt" id="opt1t">12</span></button>
        </div>
        <div class="row">
          <button class="opt" id="opt2"><span class="opttxt" id="opt2t">16</span></button>
          <button class="opt" id="opt3"><span class="opttxt" id="opt3t">9</span></button>
        </div>
      </div>
      <span class="score" id="score">Score: 0</span>
      <button class="next" id="nextBtn"><span class="nexttxt" id="nextTxt">Next -></span></button>
      <span class="hint" id="hint">5 questions - blocks show the groups.</span>
    </div>
  `, { width: 0.34, position: [0.18, 0.24, 0.0], rotationY: -0.25 });
  root.add(quiz.object3D);

  function showQuestion() {
    const q = QUESTIONS[idx];
    quiz.set('progress', { text: 'Question ' + (idx + 1) + ' of 5' });
    quiz.set('question', { text: q.a + ' x ' + q.b + ' = ?' });
    for (let k = 0; k < 4; k++) {
      quiz.set('opt' + k + 't', { text: String(q.opts[k]) });
      quiz.set('opt' + k, { backgroundColor: '#2f6fdb', display: 'flex' });
    }
    quiz.set('score', { text: 'Score: ' + score });
    quiz.set('feedback', { text: idx === 0 ? 'Pinch an answer. Grab orange cube for hint.' : 'Pinch an answer.' });
    quiz.set('nextBtn', { display: 'none' });
    updateGrid();
    updateOrbs();
    updateStars();
  }

  function showResults() {
    finished = true;
    quiz.set('progress', { text: 'Quiz complete!' });
    quiz.set('question', { text: 'You scored ' + score + ' of 5!' });
    let msg = '';
    if (score === 5) msg = 'Perfect! You are a multiplication star!';
    else if (score >= 4) msg = 'Great work! Almost perfect.';
    else if (score >= 3) msg = 'Good job! Keep practicing.';
    else if (score >= 1) msg = 'Nice try! Practice makes perfect.';
    else msg = 'Keep trying! Look at the blocks and retry.';
    quiz.set('feedback', { text: msg });
    quiz.set('score', { text: 'Final score: ' + score + ' / 5' });
    for (let k = 0; k < 4; k++) quiz.set('opt' + k, { display: 'none' });
    quiz.set('nextTxt', { text: 'Play again' });
    quiz.set('nextBtn', { display: 'flex' });
    updateGrid();
    updateOrbs();
    updateStars();
  }

  function answer(choice) {
    if (finished || answered) return;
    const q = QUESTIONS[idx];
    const ans = q.a * q.b;
    const wasCorrect = q.opts[choice] === ans;
    answered = true;
    results[idx] = wasCorrect;
    if (wasCorrect) {
      score++;
      quiz.set('feedback', { text: 'Correct! ' + q.a + ' x ' + q.b + ' = ' + ans + '.' });
      gridMat.color.set(0x2ecc71);
    } else {
      quiz.set('feedback', { text: 'Not quite. ' + q.a + ' x ' + q.b + ' = ' + ans + '.' });
      gridMat.color.set(0xe74c3c);
    }
    for (let k = 0; k < 4; k++) {
      if (k === q.correct) quiz.set('opt' + k, { backgroundColor: '#2e9e4a' });
      else if (k === choice && !wasCorrect) quiz.set('opt' + k, { backgroundColor: '#c0392b' });
      else quiz.set('opt' + k, { backgroundColor: '#2f6fdb' });
    }
    quiz.set('score', { text: 'Score: ' + score });
    if (idx < 4) quiz.set('nextTxt', { text: 'Next ->' });
    else quiz.set('nextTxt', { text: 'See results' });
    quiz.set('nextBtn', { display: 'flex' });
    updateOrbs();
    updateStars();
  }

  quiz.on('opt0', 'click', () => answer(0));
  quiz.on('opt1', 'click', () => answer(1));
  quiz.on('opt2', 'click', () => answer(2));
  quiz.on('opt3', 'click', () => answer(3));

  quiz.on('nextBtn', 'click', () => {
    if (finished) {
      idx = 0;
      score = 0;
      answered = false;
      finished = false;
      results = [null, null, null, null, null];
      gridMat.color.set(0x4da3ff);
      showQuestion();
      return;
    }
    if (!answered) return;
    if (idx < 4) {
      idx++;
      answered = false;
      gridMat.color.set(0x4da3ff);
      showQuestion();
    } else {
      showResults();
    }
  });

  traits(mascot, {
    grab: true,
    onPress: () => {
      if (finished || answered) return;
      const q = QUESTIONS[idx];
      quiz.set('feedback', { text: 'Hint: ' + q.a + ' groups of ' + q.b + ' - count the blocks.' });
    }
  });

  showQuestion();

  return {
    root,
    update(time, delta) {
      for (let i = 0; i < 5; i++) {
        let s = 1;
        if (i === idx && !answered && !finished) s = 1 + 0.18 * Math.sin(time * 4);
        orbs[i].scale.setScalar(s);
        if (i < score) {
          stars[i].rotation.y += delta * (finished ? 2.0 : 0.8);
          stars[i].position.y = starBaseY[i] + Math.sin(time * 2 + i * 1.1) * 0.006;
        }
      }
      if (!isGrabbed(mascot)) {
        mascot.position.y = 0.04 + Math.sin(time * 1.6) * 0.004;
        mascot.rotation.y = Math.sin(time * 0.6) * 0.2;
      }
      if (finished && score === 5) {
        board.rotation.y = Math.sin(time * 0.8) * 0.05;
      } else {
        board.rotation.y = 0;
      }
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const QUESTIONS = [
    { a: 6, b: 7, ans: 42, opts: [36, 42, 48, 40] },
    { a: 8, b: 4, ans: 32, opts: [28, 36, 32, 24] },
    { a: 9, b: 3, ans: 27, opts: [27, 18, 24, 21] },
    { a: 7, b: 5, ans: 35, opts: [30, 40, 35, 25] },
    { a: 8, b: 6, ans: 48, opts: [54, 42, 46, 48] }
  ];

  let qIndex = 0;
  let score = 0;
  let answered = false;
  let finished = false;

  // ----- 3D: multiplication tray -----
  const trayCenter = { x: -0.24, z: 0.12 };
  const trayBase = new THREE.Mesh(
    new THREE.BoxGeometry(0.26, 0.02, 0.26),
    new THREE.MeshStandardMaterial({ color: 0x2a2e35, roughness: 0.8 })
  );
  trayBase.name = "TrayBase";
  trayBase.position.set(trayCenter.x, 0.01, trayCenter.z);
  root.add(trayBase);

  const cubeGeo = new THREE.BoxGeometry(0.02, 0.02, 0.02);
  const cubeMat = new THREE.MeshStandardMaterial({ color: 0x4da3ff, roughness: 0.4 });
  const blocks = new THREE.InstancedMesh(cubeGeo, cubeMat, 81);
  blocks.name = "ArrayBlocks";
  blocks.position.set(0, 0, 0);
  root.add(blocks);
  const dummy = new THREE.Object3D();

  function updateArray(a, b) {
    const spacing = 0.024;
    const cols = b;
    const rows = a;
    const count = a * b;
    const x0 = trayCenter.x - ((cols - 1) * spacing) / 2;
    const z0 = trayCenter.z - ((rows - 1) * spacing) / 2;
    for (let i = 0; i < count; i++) {
      const r = Math.floor(i / cols);
      const c = i % cols;
      dummy.position.set(x0 + c * spacing, 0.032, z0 + r * spacing);
      dummy.rotation.set(0, 0, 0);
      dummy.updateMatrix();
      blocks.setMatrixAt(i, dummy.matrix);
    }
    blocks.count = count;
    blocks.instanceMatrix.needsUpdate = true;
  }

  // ----- 3D: progress pillars -----
  const pillarBar = new THREE.Mesh(
    new THREE.BoxGeometry(0.24, 0.01, 0.045),
    new THREE.MeshStandardMaterial({ color: 0x2a2e35, roughness: 0.8 })
  );
  pillarBar.name = "ProgressBar";
  pillarBar.position.set(-0.24, 0.005, -0.08);
  root.add(pillarBar);

  const pillarGeo = new THREE.CylinderGeometry(0.015, 0.015, 0.022, 20);
  const pillarMats = [];
  const pillarMeshes = [];
  for (let i = 0; i < 5; i++) {
    const m = new THREE.MeshStandardMaterial({ color: 0x5a6270, roughness: 0.5 });
    pillarMats.push(m);
    const p = new THREE.Mesh(pillarGeo, m);
    p.name = "Progress" + (i + 1);
    p.position.set(-0.32 + i * 0.04, 0.021, -0.08);
    root.add(p);
    pillarMeshes.push(p);
  }

  // ----- 3D: score shelf + stars -----
  const shelf = new THREE.Mesh(
    new THREE.BoxGeometry(0.18, 0.02, 0.08),
    new THREE.MeshStandardMaterial({ color: 0x2a2e35, roughness: 0.8 })
  );
  shelf.name = "ScoreShelf";
  shelf.position.set(0.24, 0.01, 0.14);
  root.add(shelf);

  const starGeo = new THREE.OctahedronGeometry(0.018);
  const starMat = new THREE.MeshStandardMaterial({ color: 0xffd54f, emissive: 0x8a5a00, emissiveIntensity: 0.6, roughness: 0.3, metalness: 0.4 });
  const stars = [];
  for (let i = 0; i < 5; i++) {
    const s = new THREE.Mesh(starGeo, starMat);
    s.name = "ScoreStar" + (i + 1);
    s.position.set(0.176 + i * 0.032, 0.05, 0.14);
    s.visible = false;
    root.add(s);
    stars.push(s);
  }

  // ----- 3D: grabbable lucky star -----
  const lucky = new THREE.Mesh(
    new THREE.OctahedronGeometry(0.026),
    new THREE.MeshStandardMaterial({ color: 0xffd54f, emissive: 0xff8a00, emissiveIntensity: 0.7, roughness: 0.25, metalness: 0.3 })
  );
  lucky.name = "LuckyStar";
  lucky.position.set(0.0, 0.045, 0.24);
  root.add(lucky);
  traits(lucky, { grab: true });

  function refreshStars() {
    for (let i = 0; i < 5; i++) stars[i].visible = i < score;
  }

  // ----- UI panel -----
  const quizUI = ui(`
    <style>
      .card { width: 500px; flex-direction: column; gap: 8px; padding-top: 16px; padding-bottom: 16px; padding-left: 20px; padding-right: 20px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; text-align: center; }
      .row { flex-direction: row; gap: 10px; align-items: center; justify-content: space-between; }
      .progress { color: #9fb4d8; font-size: 20px; }
      .score { color: #ffd54f; font-size: 20px; font-weight: 700; }
      .question { color: #ffffff; font-size: 44px; font-weight: 700; text-align: center; }
      .hint { color: #d7dbe2; font-size: 20px; text-align: center; }
      .answersrow { flex-direction: row; gap: 10px; justify-content: center; }
      .col { flex-direction: column; gap: 10px; }
      .ansbtn { width: 220px; padding-top: 12px; padding-bottom: 12px; padding-left: 10px; padding-right: 10px; border-radius: 12px; background-color: #2f6fdb; align-items: center; justify-content: center; }
      .anstext { color: #ffffff; font-size: 28px; font-weight: 700; text-align: center; }
      .feedback { color: #d7dbe2; font-size: 22px; text-align: center; }
      .nextbtn { padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px; border-radius: 12px; background-color: #3ddc84; align-items: center; justify-content: center; }
      .nexttext { color: #0d1a12; font-size: 22px; font-weight: 700; text-align: center; }
    </style>
    <div class="card">
      <span class="title">MULTIPLICATION QUIZ</span>
      <div class="row"><span class="progress" id="progress">Question 1 of 5</span><span class="score" id="score">Score: 0</span></div>
      <span class="question" id="question">6 x 7 = ?</span>
      <span class="hint" id="hint">Count 6 rows of 7 blocks on the tray.</span>
      <div class="col" id="answers">
        <div class="answersrow"><button class="ansbtn" id="a0"><span class="anstext" id="a0t">36</span></button><button class="ansbtn" id="a1"><span class="anstext" id="a1t">42</span></button></div>
        <div class="answersrow"><button class="ansbtn" id="a2"><span class="anstext" id="a2t">48</span></button><button class="ansbtn" id="a3"><span class="anstext" id="a3t">40</span></button></div>
      </div>
      <span class="feedback" id="feedback">Pinch an answer to start!</span>
      <button class="nextbtn" id="next"><span class="nexttext" id="nextText">Next -></span></button>
    </div>`, { width: 0.34, position: [0.14, 0.34, -0.02], rotationY: -0.12 });
  root.add(quizUI.object3D);

  function showQuestion() {
    const q = QUESTIONS[qIndex];
    answered = false;
    quizUI.set("progress", { text: "Question " + (qIndex + 1) + " of 5" });
    quizUI.set("score", { text: "Score: " + score });
    quizUI.set("question", { text: q.a + " x " + q.b + " = ?" });
    quizUI.set("hint", { text: "Count " + q.a + " rows of " + q.b + " blocks on the tray." });
    quizUI.set("feedback", { text: "Pick an answer!", color: "#d7dbe2" });
    for (let k = 0; k < 4; k++) {
      quizUI.set("a" + k + "t", { text: String(q.opts[k]) });
      quizUI.set("a" + k, { backgroundColor: "#2f6fdb" });
    }
    quizUI.set("next", { display: "none" });
    updateArray(q.a, q.b);
  }

  function showResult() {
    finished = true;
    quizUI.set("progress", { text: "Quiz complete!" });
    quizUI.set("question", { text: "You scored " + score + " / 5" });
    let msg = "Keep practicing! Try again to beat your score.";
    if (score === 5) msg = "Perfect! You are a times-table champion!";
    else if (score === 4) msg = "Great job! Almost perfect!";
    else if (score === 3) msg = "Good work! Keep practicing!";
    quizUI.set("hint", { text: msg });
    quizUI.set("feedback", { text: score >= 3 ? "Hold your lucky star to celebrate!" : "Grab the lucky star and try again!", color: "#ffd54f" });
    quizUI.set("answers", { display: "none" });
    quizUI.set("nextText", { text: "Play again" });
    quizUI.set("next", { display: "flex" });
  }

  function doRestart() {
    qIndex = 0;
    score = 0;
    answered = false;
    finished = false;
    for (let i = 0; i < 5; i++) pillarMats[i].color.setHex(0x5a6270);
    refreshStars();
    quizUI.set("answers", { display: "flex" });
    quizUI.set("nextText", { text: "Next ->" });
    quizUI.set("score", { text: "Score: 0" });
    showQuestion();
  }

  function handleAnswer(k) {
    if (answered || finished) return;
    answered = true;
    const q = QUESTIONS[qIndex];
    const picked = q.opts[k];
    let correctIdx = 0;
    for (let i = 0; i < 4; i++) if (q.opts[i] === q.ans) correctIdx = i;
    const isCorrect = picked === q.ans;
    if (isCorrect) {
      score++;
      quizUI.set("score", { text: "Score: " + score });
      quizUI.set("feedback", { text: "Correct! " + q.a + " x " + q.b + " = " + q.ans, color: "#7dffb0" });
    } else {
      quizUI.set("feedback", { text: "Not quite. " + q.a + " x " + q.b + " = " + q.ans, color: "#ff8a80" });
    }
    quizUI.set("a" + correctIdx, { backgroundColor: "#2e9e5b" });
    if (!isCorrect) quizUI.set("a" + k, { backgroundColor: "#c84a4a" });
    pillarMats[qIndex].color.setHex(isCorrect ? 0x3ddc84 : 0xff5252);
    refreshStars();
    if (qIndex < 4) quizUI.set("nextText", { text: "Next ->" });
    else quizUI.set("nextText", { text: "See result" });
    quizUI.set("next", { display: "flex" });
  }

  function handleNext() {
    if (finished) {
      doRestart();
      return;
    }
    if (!answered) return;
    if (qIndex < 4) {
      qIndex++;
      showQuestion();
    } else {
      showResult();
    }
  }

  quizUI.on("a0", "click", () => handleAnswer(0));
  quizUI.on("a1", "click", () => handleAnswer(1));
  quizUI.on("a2", "click", () => handleAnswer(2));
  quizUI.on("a3", "click", () => handleAnswer(3));
  quizUI.on("next", "click", handleNext);

  showQuestion();

  return {
    root,
    update(time, delta) {
      if (!isGrabbed(lucky)) {
        lucky.position.y = 0.045 + Math.sin(time * 1.6) * 0.005;
        lucky.rotation.y += delta * 0.6;
      }
      for (let i = 0; i < 5; i++) {
        const s = stars[i];
        if (s.visible) {
          s.rotation.y += delta * 1.2;
          s.position.y = 0.05 + Math.sin(time * 2.0 + i * 0.9) * 0.006;
        }
      }
      if (finished && score >= 4) {
        lucky.rotation.y += delta * 1.0;
      }
    }
  };
}

