  const coverMat = new THREE.MeshStandardMaterial({ color: 0xe8930c, roughness: 0.6 });
  const pageMat = new THREE.MeshStandardMaterial({ color: 0xf2f0e6, roughness: 0.8 });
  const cover = new THREE.Mesh(new THREE.BoxGeometry(0.056, 0.012, 0.04), coverMat);
  cover.position.set(0, -0.012, 0);
  cover.name = 'Read book';
  const pages = new THREE.Mesh(new THREE.BoxGeometry(0.048, 0.014, 0.034), pageMat);
  pages.position.set(0, 0.001, 0);
  pages.name = 'Read pages';
  const coverTop = new THREE.Mesh(new THREE.BoxGeometry(0.056, 0.006, 0.04), coverMat);
  coverTop.position.set(0, 0.011, 0);
  coverTop.name = 'Read cover';
  g1.add(cover); g1.add(pages); g1.add(coverTop);
  root.add(g1);

  // 2: dumbbell
  const g2 = new THREE.Group();
  g2.position.set(0.22, tokenBaseY[2], -0.03);
  g2.name = 'Move token';
  const moveMat = new THREE.MeshStandardMaterial({ color: 0x2eb85c, emissive: 0x2eb85c, emissiveIntensity: 0.3, roughness: 0.5 });
  const barMat = new THREE.MeshStandardMaterial({ color: 0x9aa0ab, roughness: 0.4, metalness: 0.5 });
  const bar = new THREE.Mesh(new THREE.CylinderGeometry(0.006, 0.006, 0.07, 16), barMat);
  bar.rotation.z = Math.PI / 2;
  bar.name = 'Move bar';
  const wL = new THREE.Mesh(new THREE.SphereGeometry(0.016, 20, 12), moveMat);
  wL.position.set(-0.035, 0, 0);
  wL.name = 'Move weight';
  const wR = new THREE.Mesh(new THREE.SphereGeometry(0.016, 20, 12), moveMat);
  wR.position.set(0.035, 0, 0);
  wR.name = 'Move weight 2';
  g2.add(bar); g2.add(wL); g2.add(wR);
  root.add(g2);

  tokens.push(g0, g1, g2);

  const basePositions = [[-0.22, -0.03], [0, -0.03], [0.22, -0.03]];
  for (let i = 0; i < 3; i++) {
    const b = new THREE.Mesh(baseGeo, baseMat);
    b.position.set(basePositions[i][0], 0.004, basePositions[i][1]);
    b.name = habitNames[i] + ' base';
    root.add(b);
  }

  // ---------- 3D day cubes (pressable) ----------
  const cubeGeo = new THREE.BoxGeometry(0.032, 0.032, 0.032);
  const cubes = [];
  for (let h = 0; h < 3; h++) {
    cubes.push([]);
    for (let d = 0; d < 7; d++) {
      const m = new THREE.Mesh(cubeGeo, state[h][d] ? checkedMats[h] : uncheckedMat);
      const x = -0.12 + d * 0.04;
      const z = 0.055 + h * 0.058;
      m.position.set(x, 0.016, z);
      m.name = habitNames[h] + ' ' + dayLabels[d];
      root.add(m);
      cubes[h].push(m);
    }
  }

  // ---------- UI panel ----------
  const markup = `
    <style>
      .card { width: 560px; display: flex; flex-direction: column; gap: 10px; padding-top: 14px; padding-bottom: 14px; padding-left: 16px; padding-right: 16px; background-color: #1f2228; border-radius: 18px; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; text-align: center; }
      .sub { color: #b8bec9; font-size: 20px; text-align: center; }
      .hrow { display: flex; flex-direction: row; gap: 10px; align-items: center; justify-content: flex-start; background-color: #262a31; border-radius: 12px; padding-top: 8px; padding-bottom: 8px; padding-left: 10px; padding-right: 10px; }
      .hinfo { width: 150px; display: flex; flex-direction: column; gap: 4px; }
      .htitle { display: flex; flex-direction: row; gap: 6px; align-items: center; }
      .dot0 { width: 12px; height: 12px; background-color: #2f6fdb; border-radius: 6px; }
      .dot1 { width: 12px; height: 12px; background-color: #e8930c; border-radius: 6px; }
      .dot2 { width: 12px; height: 12px; background-color: #2eb85c; border-radius: 6px; }
      .hname { color: #ffffff; font-size: 21px; font-weight: 700; }
      .streak { color: #ffd23d; font-size: 20px; }
      .days { display: flex; flex-direction: row; gap: 6px; }
      .day { width: 44px; height: 44px; display: flex; align-items: center; justify-content: center; background-color: #33373f; border-radius: 10px; border-width: 2px; border-color: #33373f; }
      .todayB { border-color: #ffd23d; border-width: 2px; background-color: #33373f; }
      .day-text { color: #ffffff; font-size: 20px; font-weight: 700; text-align: center; }
      .footer { display: flex; flex-direction: column; gap: 8px; align-items: center; }
      .total { color: #ffffff; font-size: 22px; font-weight: 700; text-align: center; }
      .btnrow { display: flex; flex-direction: row; gap: 10px; justify-content: center; }
      .btn { padding-top: 8px; padding-bottom: 8px; padding-left: 14px; padding-right: 14px; background-color: #2f6fdb; border-radius: 10px; }
      .btn2 { padding-top: 8px; padding-bottom: 8px; padding-left: 14px; padding-right: 14px; background-color: #3a3f48; border-radius: 10px; }
      .btn-text { color: #ffffff; font-size: 20px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Habit Tracker - This Week</span>
      <span class="sub">Tap a day to check it off. Th is today. Grab a 3D token.</span>
      <div class="hrow">
        <div class="hinfo"><div class="htitle"><div class="dot0"></div><span class="hname">Drink Water</span></div><span class="streak" id="s0">Streak 0</span></div>
        <div class="days"><button class="day" id="c00"><span class="day-text" id="c00t">Mo</span></button><button class="day" id="c01"><span class="day-text" id="c01t">Tu</span></button><button class="day" id="c02"><span class="day-text" id="c02t">We</span></button><button class="todayB" id="c03"><span class="day-text" id="c03t">Th</span></button><button class="day" id="c04"><span class="day-text" id="c04t">Fr</span></button><button class="day" id="c05"><span class="day-text" id="c05t">Sa</span></button><button class="day" id="c06"><span class="day-text" id="c06t">Su</span></button></div>
      </div>
      <div class="hrow">
        <div class="hinfo"><div class="htitle"><div class="dot1"></div><span class="hname">Read 10 min</span></div><span class="streak" id="s1">Streak 0</span></div>
        <div class="days"><button class="day" id="c10"><span class="day-text" id="c10t">Mo</span></button><button class="day" id="c11"><span class="day-text" id="c11t">Tu</span></button><button class="day" id="c12"><span class="day-text" id="c12t">We</span></button><button class="todayB" id="c13"><span class="day-text" id="c13t">Th</span></button><button class="day" id="c14"><span class="day-text" id="c14t">Fr</span></button><button class="day" id="c15"><span class="day-text" id="c15t">Sa</span></button><button class="day" id="c16"><span class="day-text" id="c16t">Su</span></button></div>
      </div>
      <div class="hrow">
        <div class="hinfo"><div class="htitle"><div class="dot2"></div><span class="hname">Move Daily</span></div><span class="streak" id="s2">Streak 0</span></div>
        <div class="days"><button class="day" id="c20"><span class="day-text" id="c20t">Mo</span></button><button class="day" id="c21"><span class="day-text" id="c21t">Tu</span></button><button class="day" id="c22"><span class="day-text" id="c22t">We</span></button><button class="todayB" id="c23"><span class="day-text" id="c23t">Th</span></button><button class="day" id="c24"><span class="day-text" id="c24t">Fr</span></button><button class="day" id="c25"><span class="day-text" id="c25t">Sa</span></button><button class="day" id="c26"><span class="day-text" id="c26t">Su</span></button></div>
      </div>
      <div class="footer"><span class="total" id="total">Total 0/21</span><div class="btnrow"><button class="btn" id="todayBtn"><span class="btn-text">Check today Th</span></button><button class="btn2" id="resetBtn"><span class="btn-text">Reset week</span></button></div></div>
    </div>`;

  const info = ui(markup, { width: 0.42, position: [0, 0.32, -0.14], rotationY: 0 });
  root.add(info.object3D);

  function refresh() {
    let total = 0;
    for (let h = 0; h < 3; h++) {
      const st = streakOf(state[h]);
      const ct = countOf(state[h]);
      total += ct;
      info.set('s' + h, { text: 'Streak ' + st + 'd - ' + ct + '/7' });
      for (let d = 0; d < 7; d++) {
        const on = state[h][d];
        const bid = 'c' + h + '' + d;
        const tid = bid + 't';
        info.set(bid, { backgroundColor: on ? habitCss[h] : '#33373f' });
        info.set(tid, { text: on ? 'X' : dayLabels[d] });
        cubes[h][d].material = on ? checkedMats[h] : uncheckedMat;
      }
    }
    let msg = 'Just started';
    if (total >= 21) msg = 'Perfect week!';
    else if (total >= 15) msg = 'Almost there!';
    else if (total >= 7) msg = 'Good pace';
    info.set('total', { text: 'Total ' + total + '/21 - ' + msg });
  }

  function toggle(h, d) {
    state[h][d] = !state[h][d];
    refresh();
  }

  for (let h = 0; h < 3; h++) {
    for (let d = 0; d < 7; d++) {
      const hh = h, dd = d;
      const bid = 'c' + hh + '' + dd;
      info.on(bid, 'click', () => toggle(hh, dd));
      traits(cubes[hh][dd], { onPress: () => toggle(hh, dd) });
    }
  }

  info.on('resetBtn', 'click', () => {
    for (let h = 0; h < 3; h++) for (let d = 0; d < 7; d++) state[h][d] = false;
    refresh();
  });
  info.on('todayBtn', 'click', () => {
    for (let h = 0; h < 3; h++) state[h][TODAY] = true;
    refresh();
  });

  for (let h = 0; h < 3; h++) {
    const hh = h;
    traits(tokens[hh], {
      grab: true,
      onPress: () => toggle(hh, TODAY)
    });
  }

  refresh();

  const phases = [0, 2.1, 4.2];
  return {
    root,
    update(time) {
      for (let i = 0; i < 3; i++) {
        if (isGrabbed(tokens[i])) continue;
        tokens[i].position.y = tokenBaseY[i] + Math.sin(time * 1.4 + phases[i]) * 0.006;
        tokens[i].rotation.y = time * 0.35 + phases[i];
      }
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();
  const CENTER = new THREE.Vector3(-0.06, 0.22, -0.08);
  const phiStart = Math.PI * 0.75;
  const phiLength = Math.PI * 1.5;
  const alpha1 = -Math.PI / 4;
  const alpha2 = -Math.PI * 0.75;

  // Materials - one per layer, reused for shell + cut faces + marker + sample
  const crustMat = new THREE.MeshStandardMaterial({ color: 0x4d96d9, emissive: 0x4d96d9, emissiveIntensity: 0.18, roughness: 0.6, metalness: 0.05, side: THREE.DoubleSide });
  const mantleMat = new THREE.MeshStandardMaterial({ color: 0xe3643a, emissive: 0xe3643a, emissiveIntensity: 0.18, roughness: 0.85, metalness: 0.0, side: THREE.DoubleSide });
  const outerMat = new THREE.MeshStandardMaterial({ color: 0xffb703, emissive: 0xffb703, emissiveIntensity: 0.18, roughness: 0.4, metalness: 0.35, side: THREE.DoubleSide });
  const innerMat = new THREE.MeshStandardMaterial({ color: 0xfff6c9, emissive: 0xffb703, emissiveIntensity: 0.65, roughness: 0.3, metalness: 0.2 });
  const layerMats = [crustMat, mantleMat, outerMat, innerMat];
  const baseInt = [0.18, 0.18, 0.18, 0.65];
  const selInt = [0.6, 0.6, 0.6, 1.0];

  // Shells - 270 deg, gap faces user (+Z)
  const crustMesh = new THREE.Mesh(new THREE.SphereGeometry(0.15, 48, 24, phiStart, phiLength), crustMat);
  crustMesh.position.copy(CENTER);
  crustMesh.name = 'Crust';
  root.add(crustMesh);

  const mantleMesh = new THREE.Mesh(new THREE.SphereGeometry(0.142, 48, 24, phiStart, phiLength), mantleMat);
  mantleMesh.position.copy(CENTER);
  mantleMesh.name = 'Mantle';
  root.add(mantleMesh);

  const outerMesh = new THREE.Mesh(new THREE.SphereGeometry(0.088, 32, 16, phiStart, phiLength), outerMat);
  outerMesh.position.copy(CENTER);
  outerMesh.name = 'Outer Core';
  root.add(outerMesh);

  const innerMesh = new THREE.Mesh(new THREE.SphereGeometry(0.048, 24, 16), innerMat);
  innerMesh.position.copy(CENTER);
  innerMesh.name = 'Inner Core';
  root.add(innerMesh);

  // Cut faces - half disks sharing centre, offset toward viewer to avoid z-fight
  const geoMantleFace = new THREE.CircleGeometry(0.142, 32, -Math.PI / 2, Math.PI);
  const geoOuterFace = new THREE.CircleGeometry(0.088, 24, -Math.PI / 2, Math.PI);
  const geoInnerFace = new THREE.CircleGeometry(0.048, 20, -Math.PI / 2, Math.PI);
  const geoCrustRing = new THREE.RingGeometry(0.142, 0.15, 32, 1, -Math.PI / 2, Math.PI);

  const faceList = [];
  function addFace(geo, mat, alpha, eps, layerIdx, name) {
    const m = new THREE.Mesh(geo, mat);
    m.rotation.y = alpha;
    const nx = Math.sin(alpha);
    const nz = Math.cos(alpha);
    const s = nz >= 0 ? 1 : -1;
    m.position.set(CENTER.x + nx * s * eps, CENTER.y, CENTER.z + nz * s * eps);
    m.name = name;
    root.add(m);
    faceList.push({ mesh: m, layer: layerIdx });
    return m;
  }
  addFace(geoMantleFace, mantleMat, alpha1, 0.0, 1, 'Mantle cut A');
  addFace(geoOuterFace, outerMat, alpha1, 0.0012, 2, 'Outer cut A');
  addFace(geoInnerFace, innerMat, alpha1, 0.0024, 3, 'Inner cut A');
  addFace(geoCrustRing, crustMat, alpha1, 0.0004, 0, 'Crust cut A');
  addFace(geoMantleFace, mantleMat, alpha2, 0.0, 1, 'Mantle cut B');
  addFace(geoOuterFace, outerMat, alpha2, 0.0012, 2, 'Outer cut B');
  addFace(geoInnerFace, innerMat, alpha2, 0.0024, 3, 'Inner cut B');
  addFace(geoCrustRing, crustMat, alpha2, 0.0004, 0, 'Crust cut B');

  // Targets on cut faces for leader lines
  const tCrust = new THREE.Vector3(0.032, 0.295, 0.012);
  const tMantle = new THREE.Vector3(0.039, 0.24, 0.019);
  const tOuter = new THREE.Vector3(-0.122, 0.23, -0.018);
  const tInner = new THREE.Vector3(-0.092, 0.205, -0.048);

  const markerGeo = new THREE.SphereGeometry(0.007, 12, 8);
  const markerData = [
    { p: tCrust, m: crustMat },
    { p: tMantle, m: mantleMat },
    { p: tOuter, m: outerMat },
    { p: tInner, m: innerMat },
  ];
  for (let i = 0; i < 4; i++) {
    const mk = new THREE.Mesh(markerGeo, markerData[i].m);
    mk.position.copy(markerData[i].p);
    root.add(mk);
  }

  const crustLabelPos = [0.19, 0.335, -0.02];
  const mantleLabelPos = [0.20, 0.235, -0.02];
  const outerLabelPos = [-0.31, 0.225, -0.02];
  const innerLabelPos = [-0.30, 0.12, -0.02];

  function addLine(a, b) {
    const g = new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(a[0], a[1], a[2]), b.clone()]);
    const l = new THREE.Line(g, new THREE.LineBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.55 }));
    root.add(l);
  }
  addLine(crustLabelPos, tCrust);
  addLine(mantleLabelPos, tMantle);
  addLine(outerLabelPos, tOuter);
  addLine(innerLabelPos, tInner);

  // Grabbable sample balls in front row
  const sampleGeo = new THREE.SphereGeometry(0.02, 24, 12);
  const sampleHomes = [
    new THREE.Vector3(-0.18, 0.025, 0.15),
    new THREE.Vector3(-0.06, 0.025, 0.15),
    new THREE.Vector3(0.06, 0.025, 0.15),
    new THREE.Vector3(0.18, 0.025, 0.15),
  ];
  const sampleNames = ['Sample Crust', 'Sample Mantle', 'Sample Outer Core', 'Sample Inner Core'];
  const samples = [];
  for (let i = 0; i < 4; i++) {
    const s = new THREE.Mesh(sampleGeo, layerMats[i]);
    s.position.copy(sampleHomes[i]);
    s.name = sampleNames[i];
    root.add(s);
    samples.push(s);
  }

  // Info panel
  const info = ui(`
    <style>
      .card { width: 520px; flex-direction: column; gap: 10px; padding-top: 16px; padding-bottom: 16px; padding-left: 20px; padding-right: 20px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; text-align: center; }
      .lname { color: #ffcf6b; font-size: 26px; font-weight: 700; text-align: center; }
      .body { color: #d7dbe2; font-size: 22px; text-align: center; }
      .row { flex-direction: row; gap: 8px; align-items: center; justify-content: center; }
      .btn { padding-top: 8px; padding-bottom: 8px; padding-left: 10px; padding-right: 10px; border-radius: 10px; background-color: #2f6fdb; }
      .btn2 { padding-top: 8px; padding-bottom: 8px; padding-left: 10px; padding-right: 10px; border-radius: 10px; background-color: #3a3f47; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Layers of the Earth</span>
      <span class="lname" id="lname">Cut-away view</span>
      <span class="body" id="fact">A quarter is cut away so you can see inside. Press a layer, a sample ball, or a button. Grab sample balls to feel each layer.</span>
      <div class="row">
        <button class="btn" id="b0"><span class="btn-text">Crust</span></button>
        <button class="btn" id="b1"><span class="btn-text">Mantle</span></button>
        <button class="btn" id="b2"><span class="btn-text">Outer</span></button>
        <button class="btn" id="b3"><span class="btn-text">Inner</span></button>
      </div>
      <div class="row">
        <button class="btn2" id="reset"><span class="btn-text">Reset samples</span></button>
      </div>
    </div>`, { width: 0.30, position: [0.24, 0.155, 0.03], rotationY: -0.30 });
  root.add(info.object3D);

  function labelPanel(title, sub, border, pos, rotY) {
    return ui(`
      <style>
        .lab { width: 280px; flex-direction: column; gap: 4px; padding-top: 10px; padding-bottom: 10px; padding-left: 12px; padding-right: 12px; border-radius: 14px; background-color: #2a2e35; border-color: ${border}; border-width: 3px; align-items: center; justify-content: center; }
        .lab-name { color: #ffffff; font-size: 26px; font-weight: 700; text-align: center; }
        .lab-sub { color: #d7dbe2; font-size: 25px; text-align: center; }
      </style>
      <button class="lab" id="pick">
        <span class="lab-name">${title}</span>
        <span class="lab-sub">${sub}</span>
      </button>`, { width: 0.14, position: pos, rotationY: rotY });
  }
  const crustLabel = labelPanel('Crust', '5-70 km solid rock', '#4d96d9', crustLabelPos, -0.25);
  root.add(crustLabel.object3D);
  const mantleLabel = labelPanel('Mantle', '2900 km hot rock', '#e3643a', mantleLabelPos, -0.25);
  root.add(mantleLabel.object3D);
  const outerLabel = labelPanel('Outer Core', '2200 km liquid iron', '#ffb703', outerLabelPos, 0.25);
  root.add(outerLabel.object3D);
  const innerLabel = labelPanel('Inner Core', '1220 km solid iron', '#fff3b0', innerLabelPos, 0.25);
  root.add(innerLabel.object3D);
  const labelHandles = [crustLabel, mantleLabel, outerLabel, innerLabel];

  const layerData = [
    { name: 'Crust', fact: 'CRUST - 5 to 70 km thick solid rock. Ocean crust is thin, continents are thick. Thinnest and coolest layer. You live on it.' },
    { name: 'Mantle', fact: 'MANTLE - about 2900 km thick. Hot solid rock that creeps very slowly. Its flow moves tectonic plates. 500 to 3700 C.' },
    { name: 'Outer Core', fact: 'OUTER CORE - about 2200 km thick liquid iron and nickel. Flowing metal makes Earth magnetic field. 4000 to 5000 C.' },
    { name: 'Inner Core', fact: 'INNER CORE - 1220 km radius solid iron-nickel ball. About 5500 C, as hot as Sun surface, squeezed solid by pressure.' },
  ];

  let selected = -1;
  function select(i) {
    selected = i;
    info.set('lname', { text: layerData[i].name });
    info.set('fact', { text: layerData[i].fact });
    for (let k = 0; k < 4; k++) {
      layerMats[k].emissiveIntensity = (k === i) ? selInt[k] : baseInt[k];
      const isSel = (k === i);
      labelHandles[k].set('pick', { backgroundColor: isSel ? '#4a505c' : '#2a2e35' });
    }
    for (let s = 0; s < 4; s++) {
      if (!isGrabbed(samples[s])) {
        const sc = (s === i) ? 1.35 : 1.0;
        samples[s].scale.set(sc, sc, sc);
      }
    }
  }

  traits(crustMesh, { onPress: () => select(0) });
  traits(mantleMesh, { onPress: () => select(1) });
  traits(outerMesh, { onPress: () => select(2) });
  traits(innerMesh, { onPress: () => select(3) });
  for (let f = 0; f < faceList.length; f++) {
    const entry = faceList[f];
    traits(entry.mesh, { onPress: () => select(entry.layer) });
  }
  for (let s = 0; s < 4; s++) {
    const idx = s;
    traits(samples[s], { grab: true, onPress: () => select(idx) });
  }

  info.on('b0', 'click', () => select(0));
  info.on('b1', 'click', () => select(1));
  info.on('b2', 'click', () => select(2));
  info.on('b3', 'click', () => select(3));
  info.on('reset', 'click', () => {
    for (let s = 0; s < 4; s++) {
      if (isGrabbed(samples[s])) continue;
      samples[s].position.copy(sampleHomes[s]);
      samples[s].rotation.set(0, 0, 0);
    }
  });
  crustLabel.on('pick', 'click', () => select(0));
  mantleLabel.on('pick', 'click', () => select(1));
  outerLabel.on('pick', 'click', () => select(2));
  innerLabel.on('pick', 'click', () => select(3));

  return {
    root,
    update(time) {
      const glow = 0.12 * Math.sin(time * 2.2);
      innerMat.emissiveIntensity = (selected === 3 ? 1.0 : 0.65) + glow;
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---- color palette -------------------------------------------------------
  const COLORS = [
    { name: 'Cyan', hex: 0x22d3ee, css: '#22d3ee' },
    { name: 'Amber', hex: 0xffb020, css: '#ffb020' },
    { name: 'Magenta', hex: 0xff3ea5, css: '#ff3ea5' },
    { name: 'Lime', hex: 0x8bff3c, css: '#8bff3c' },
    { name: 'Coral', hex: 0xff5a4d, css: '#ff5a4d' },
    { name: 'Violet', hex: 0x9b6bff, css: '#9b6bff' },
    { name: 'Mint', hex: 0x34e5b0, css: '#34e5b0' },
    { name: 'Ice Blue', hex: 0x5aa8ff, css: '#5aa8ff' },
  ];

  // ---- the button ----------------------------------------------------------
  const button = new THREE.Group();
  button.position.set(0, 0, 0.07);
  root.add(button);

  // dark metal pedestal
  const pedestal = new THREE.Mesh(
    new THREE.CylinderGeometry(0.062, 0.068, 0.022, 44),
    new THREE.MeshStandardMaterial({ color: 0x23262c, roughness: 0.45, metalness: 0.7 }),
  );
  pedestal.position.y = 0.011;
  pedestal.name = 'Pedestal';
  button.add(pedestal);

  // glowing ring around the top of the pedestal
  const ringMat = new THREE.MeshStandardMaterial({
    color: 0x101216,
    emissive: COLORS[0].hex,
    emissiveIntensity: 1.2,
    roughness: 0.3,
    metalness: 0.2,
  });
  const ring = new THREE.Mesh(new THREE.TorusGeometry(0.052, 0.005, 10, 48), ringMat);
  ring.rotation.x = -Math.PI / 2;
  ring.position.y = 0.0235;
  ring.name = 'GlowRing';
  button.add(ring);

  // the dome you press
  const domeMat = new THREE.MeshStandardMaterial({
    color: COLORS[0].hex,
    emissive: COLORS[0].hex,
    emissiveIntensity: 1.4,
    roughness: 0.25,
    metalness: 0.0,
  });
  const dome = new THREE.Mesh(
    new THREE.SphereGeometry(0.043, 32, 16, 0, Math.PI * 2, 0, Math.PI / 2),
    domeMat,
  );
  dome.position.y = 0.021;
  dome.name = 'Dome';
  button.add(dome);

  // soft additive halo
  const haloMat = new THREE.MeshBasicMaterial({
    color: COLORS[0].hex,
    transparent: true,
    opacity: 0.12,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
  });
  const halo = new THREE.Mesh(new THREE.SphereGeometry(0.056, 24, 16), haloMat);
  halo.position.y = 0.026;
  halo.name = 'Halo';
  button.add(halo);

  // orbiting sparkles
  const sparkleMat = new THREE.MeshBasicMaterial({
    color: COLORS[0].hex,
    transparent: true,
    opacity: 0.9,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
  });
  const sparkleGeo = new THREE.SphereGeometry(0.0045, 8, 6);
  const sparkles = new THREE.Group();
  sparkles.position.y = 0.03;
  const sparkleMeshes = [];
  const SPARK_COUNT = 6;
  for (let i = 0; i < SPARK_COUNT; i++) {
    const s = new THREE.Mesh(sparkleGeo, sparkleMat);
    const a = (i / SPARK_COUNT) * Math.PI * 2;
    s.position.set(Math.cos(a) * 0.078, 0, Math.sin(a) * 0.078);
    sparkles.add(s);
    sparkleMeshes.push(s);
  }
  button.add(sparkles);

  // ---- info panel ----------------------------------------------------------
  const panel = ui(`
    <style>
      .card { width: 440px; flex-direction: column; gap: 10px; padding-top: 18px; padding-bottom: 18px;
              padding-left: 24px; padding-right: 24px; border-radius: 20px; background-color: #1a1d22; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .row { flex-direction: row; align-items: center; gap: 12px; }
      .swatch { width: 26px; height: 26px; border-radius: 13px; background-color: #22d3ee; }
      .color { color: #ffffff; font-size: 26px; font-weight: 700; }
      .count { color: #b9c0ca; font-size: 22px; }
      .hint { color: #8b93a1; font-size: 20px; }
    </style>
    <div class="card">
      <span class="title">Glow Button</span>
      <div class="row">
        <div class="swatch" id="swatch"></div>
        <span class="color" id="color">Cyan</span>
      </div>
      <span class="count" id="count">Presses: 0</span>
      <span class="hint">Press the glowing dome to cycle colors.</span>
    </div>`, { width: 0.28, position: [0, 0.21, -0.09], rotationY: 0 });
  root.add(panel.object3D);

  // ---- state & interaction -------------------------------------------------
  let index = 0;
  let presses = 0;
  let pressAnim = 0; // seconds remaining in the press bounce

  function applyColor() {
    const c = COLORS[index];
    domeMat.color.setHex(c.hex);
    domeMat.emissive.setHex(c.hex);
    ringMat.emissive.setHex(c.hex);
    haloMat.color.setHex(c.hex);
    sparkleMat.color.setHex(c.hex);
  }

  traits(button, {
    onPress: () => {
      index = (index + 1) % COLORS.length;
      presses += 1;
      applyColor();
      panel.set('color', { text: COLORS[index].name });
      panel.set('swatch', { backgroundColor: COLORS[index].css });
      panel.set('count', { text: 'Presses: ' + presses });
      pressAnim = 0.28;
    },
  });

  applyColor();

  // ---- animation -----------------------------------------------------------
  return {
    root,
    update(time, delta) {
      if (pressAnim > 0) pressAnim = Math.max(0, pressAnim - delta);
      const t = 1 - pressAnim / 0.28;
      const pop = pressAnim > 0 ? Math.sin(t * Math.PI) : 0;

      dome.scale.set(1 + pop * 0.06, 1 - pop * 0.22, 1 + pop * 0.06);
      dome.position.y = 0.021 - pop * 0.008;

      const pulse = 0.5 + 0.5 * Math.sin(time * 2.6);
      domeMat.emissiveIntensity = 1.1 + pulse * 0.7 + pop * 1.3;
      ringMat.emissiveIntensity = 0.8 + pulse * 0.9 + pop * 1.0;
      haloMat.opacity = 0.10 + pulse * 0.06 + pop * 0.12;
      halo.scale.setScalar(1 + pulse * 0.05 + pop * 0.12);

      sparkles.rotation.y = time * 0.4;
      for (let i = 0; i < sparkleMeshes.length; i++) {
        sparkleMeshes[i].position.y = Math.sin(time * 2.2 + i * 1.1) * 0.006;
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const dayNames = ["MO", "TU", "WE", "TH", "FR", "SA", "SU"];
  const todayIdx = 3;
  const habitNames = ["Drink Water", "Read 20 min", "Move 30 min"];
  const habitCss = ["#3aa0ff", "#ff9f2e", "#4ade80"];
  const habitCols = [0x3aa0ff, 0xff9f2e, 0x4ade80];
  const xs = [-0.22, 0, 0.22];

  const checks = [
    [true, true, true, false, false, false, false],
    [true, false, true, false, false, false, false],
    [true, true, false, false, false, false, false]
  ];

  // Base mat
  const base = new THREE.Mesh(
    new THREE.BoxGeometry(0.66, 0.012, 0.34),
    new THREE.MeshStandardMaterial({ color: 0x22262e, roughness: 0.9 })
  );
  base.position.set(0, 0.006, 0.02);
  root.add(base);

  // Pedestals
  const pedGeom = new THREE.CylinderGeometry(0.055, 0.06, 0.02, 28);
  const pedMat = new THREE.MeshStandardMaterial({ color: 0x2a2e35, roughness: 0.8 });
  for (let i = 0; i < 3; i++) {
    const p = new THREE.Mesh(pedGeom, pedMat);
    p.position.set(xs[i], 0.022, 0.10);
    root.add(p);
  }

  // Tokens (grabbable, press = check today)
  const tokens = [];
  const tokenMats = [];
  const sphereGeom = new THREE.SphereGeometry(0.026, 24, 12);
  const bookGeom = new THREE.BoxGeometry(0.046, 0.032, 0.038);
  const moveGeom = new THREE.IcosahedronGeometry(0.028, 0);
  const tokenGeoms = [sphereGeom, bookGeom, moveGeom];
  for (let i = 0; i < 3; i++) {
    const m = new THREE.MeshStandardMaterial({
      color: habitCols[i],
      emissive: habitCols[i],
      emissiveIntensity: 0.25,
      roughness: 0.35
    });
    tokenMats.push(m);
    const t = new THREE.Mesh(tokenGeoms[i], m);
    t.name = habitNames[i];
    t.position.set(xs[i], 0.062, 0.10);
    root.add(t);
    tokens.push(t);
  }

  // Week pillars: 7 segments per habit
  const baseY = 0.03;
  const stepY = 0.026;
  const segZ = -0.08;
  const segGeom = new THREE.BoxGeometry(0.05, 0.022, 0.02);
  const trackGeom = new THREE.BoxGeometry(0.058, 0.20, 0.012);
  const trackMat = new THREE.MeshStandardMaterial({ color: 0x1e2127, roughness: 0.9 });
  const uncheckedMat = new THREE.MeshStandardMaterial({ color: 0x2e333b, roughness: 0.8 });
  const checkedMats = [];
  for (let i = 0; i < 3; i++) {
    checkedMats.push(new THREE.MeshStandardMaterial({
      color: habitCols[i],
      emissive: habitCols[i],
      emissiveIntensity: 0.55,
      roughness: 0.4
    }));
  }
  const segMeshes = [[], [], []];
  for (let i = 0; i < 3; i++) {
    const track = new THREE.Mesh(trackGeom, trackMat);
    track.position.set(xs[i], baseY + 3 * stepY, -0.095);
    root.add(track);
    for (let d = 0; d < 7; d++) {
      const s = new THREE.Mesh(segGeom, uncheckedMat);
      s.position.set(xs[i], baseY + d * stepY, segZ);
      root.add(s);
      segMeshes[i].push(s);
    }
  }
  const todayY = baseY + todayIdx * stepY;
  const todayBar = new THREE.Mesh(
    new THREE.BoxGeometry(0.62, 0.005, 0.03),
    new THREE.MeshBasicMaterial({ color: 0xffd75e })
  );
  todayBar.position.set(0, todayY, segZ);
  root.add(todayBar);

  // UI panel markup
  const headerDays = dayNames.map((d) => `<span class="dhead">${d}</span>`).join("");
  let rowsHtml = "";
  for (let i = 0; i < 3; i++) {
    let btns = "";
    for (let d = 0; d < 7; d++) {
      btns += `<button class="day" id="b${i}${d}"><span class="daytext" id="t${i}${d}">${dayNames[d]}</span></button>`;
    }
    rowsHtml += `<div class="hrow"><span class="hname">${habitNames[i]}</span>${btns}<span class="streak" id="s${i}">0 days</span></div>`;
  }

  const markup = `
    <style>
      .card { width: 560px; flex-direction: column; gap: 8px; padding-top: 14px; padding-bottom: 14px; padding-left: 16px; padding-right: 16px; background-color: #1a1d22; border-radius: 18px; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; text-align: center; }
      .sub { color: #ffd75e; font-size: 20px; text-align: center; }
      .hrow { flex-direction: row; align-items: center; justify-content: center; gap: 6px; }
      .spacer { width: 120px; color: #ffffff; font-size: 18px; }
      .dhead { width: 40px; color: #8a919e; font-size: 18px; font-weight: 700; text-align: center; }
      .stitle { width: 70px; color: #8a919e; font-size: 18px; font-weight: 700; text-align: center; }
      .hname { width: 120px; color: #ffffff; font-size: 20px; font-weight: 700; }
      .day { width: 40px; height: 40px; background-color: #2e333b; border-radius: 12px; justify-content: center; align-items: center; }
      .daytext { color: #d7dbe2; font-size: 20px; font-weight: 700; text-align: center; }
      .streak { width: 70px; color: #ffffff; font-size: 19px; font-weight: 700; text-align: center; background-color: #2a2e35; border-radius: 10px; padding-top: 6px; padding-bottom: 6px; padding-left: 4px; padding-right: 4px; }
      .total { color: #d7dbe2; font-size: 22px; text-align: center; }
      .reset { background-color: #2e333b; border-radius: 12px; padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px; justify-content: center; align-items: center; }
      .resettext { color: #ffffff; font-size: 20px; font-weight: 700; text-align: center; }
      .hint { color: #8a919e; font-size: 18px; text-align: center; }
    </style>
    <div class="card">
      <span class="title">Habit Tracker - This Week</span>
      <span class="sub">TODAY THU NOV 12 - TAP A DAY TO CHECK IT OFF</span>
      <div class="hrow"><span class="spacer"></span>${headerDays}<span class="stitle">STREAK</span></div>
      ${rowsHtml}
      <span class="total" id="total">Weekly progress 0/21</span>
      <button class="reset" id="reset"><span class="resettext">Reset week</span></button>
      <span class="hint">TIP: PRESS A FLOATING SHAPE TO CHECK TODAY - GRAB TO MOVE IT</span>
    </div>`;

  const info = ui(markup, { width: 0.38, position: [0, 0.35, -0.15], rotationY: 0 });
  root.add(info.object3D);

  function calcStreak(arr) {
    if (arr[todayIdx]) {
      let s = 0;
      for (let d = todayIdx; d >= 0; d--) {
        if (arr[d]) s++;
        else break;
      }
      return s;
    } else {
      let s = 0;
      for (let d = todayIdx - 1; d >= 0; d--) {
        if (arr[d]) s++;
        else break;
      }
      return s;
    }
  }

  function refresh() {
    let grand = 0;
    for (let i = 0; i < 3; i++) {
      let total = 0;
      for (let d = 0; d < 7; d++) if (checks[i][d]) total++;
      grand += total;
      const st = calcStreak(checks[i]);
      info.set(`s${i}`, { text: `${st} day${st === 1 ? "" : "s"}` });
      for (let d = 0; d < 7; d++) {
        const btn = `b${i}${d}`;
        const lbl = `t${i}${d}`;
        if (checks[i][d]) {
          info.set(btn, { backgroundColor: habitCss[i] });
          info.set(lbl, { text: "V", color: "#ffffff" });
        } else {
          const bg = d === todayIdx ? "#3d4451" : "#2e333b";
          const col = d === todayIdx ? "#ffd75e" : "#d7dbe2";
          info.set(btn, { backgroundColor: bg });
          info.set(lbl, { text: dayNames[d], color: col });
        }
        segMeshes[i][d].material = checks[i][d] ? checkedMats[i] : uncheckedMat;
      }
      tokenMats[i].emissiveIntensity = checks[i][todayIdx] ? 0.65 : 0.25;
      const sc = checks[i][todayIdx] ? 1.12 : 1.0;
      tokens[i].scale.set(sc, sc, sc);
    }
    let msg = "Small steps count!";
    if (grand >= 15) msg = "Amazing!";
    else if (grand >= 8) msg = "Keep going!";
    info.set("total", { text: `Weekly progress ${grand}/21 - ${msg}` });
  }

  function toggle(i, d) {
    checks[i][d] = !checks[i][d];
    refresh();
  }

  for (let i = 0; i < 3; i++) {
    for (let d = 0; d < 7; d++) {
      const ii = i;
      const dd = d;
      info.on(`b${ii}${dd}`, "click", () => toggle(ii, dd));
    }
  }
  info.on("reset", "click", () => {
    for (let i = 0; i < 3; i++) for (let d = 0; d < 7; d++) checks[i][d] = false;
    refresh();
  });

  for (let i = 0; i < 3; i++) {
    const ii = i;
    traits(tokens[ii], {
      grab: true,
      onPress: () => toggle(ii, todayIdx)
    });
  }

  refresh();

  return {
    root,
    update(time) {
      for (let i = 0; i < 3; i++) {
        if (!isGrabbed(tokens[i])) {
          tokens[i].rotation.y = time * 0.5 + i * 2.1;
        }
      }
      todayBar.position.y = todayY + Math.sin(time * 3.0) * 0.002;
      const p = 1 + Math.sin(time * 3.0) * 0.015;
      todayBar.scale.set(p, 1, 1);
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------- Design ----------
  const colors = [
    { n: 'Crimson', h: 0xdc143c },
    { n: 'Tangerine', h: 0xff7a1a },
    { n: 'Gold', h: 0xffc81e },
    { n: 'Lime', h: 0x7ed321 },
    { n: 'Emerald', h: 0x14b86a },
    { n: 'Teal', h: 0x12b5b0 },
    { n: 'Azure', h: 0x1e90ff },
    { n: 'Indigo', h: 0x4b5bff },
    { n: 'Violet', h: 0x9b30ff },
    { n: 'Magenta', h: 0xff2fb4 },
  ];

  // ---------- Base (dark metal plinth) ----------
  const base = new THREE.Mesh(
    new THREE.CylinderGeometry(0.066, 0.072, 0.018, 40),
    new THREE.MeshStandardMaterial({ color: 0x24282f, roughness: 0.45, metalness: 0.7 }),
  );
  base.name = 'ButtonBase';
  base.position.set(0, 0.009, 0.03);
  root.add(base);

  // ---------- Glow ring around the button ----------
  const ringMat = new THREE.MeshBasicMaterial({
    color: colors[0].h,
    transparent: true,
    opacity: 0.8,
  });
  const ring = new THREE.Mesh(new THREE.TorusGeometry(0.063, 0.0045, 12, 56), ringMat);
  ring.name = 'GlowRing';
  ring.rotation.x = -Math.PI / 2;
  ring.position.set(0, 0.018, 0.03);
  root.add(ring);

  // ---------- The glowing cap you press ----------
  const capMat = new THREE.MeshStandardMaterial({
    color: colors[0].h,
    emissive: colors[0].h,
    emissiveIntensity: 1.0,
    roughness: 0.35,
    metalness: 0.1,
  });
  const cap = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.055, 0.022, 40), capMat);
  cap.name = 'GlowButton';
  cap.position.set(0, 0.029, 0.03);
  root.add(cap);

  // small dome on top so the cap reads as a soft button
  const dome = new THREE.Mesh(
    new THREE.SphereGeometry(0.05, 32, 16, 0, Math.PI * 2, 0, Math.PI * 0.5),
    capMat,
  );
  dome.position.set(0, 0.04, 0.03);
  dome.scale.y = 0.22;
  root.add(dome);

  // ---------- Info panel ----------
  const info = ui(`
    <style>
      .card { width: 460px; flex-direction: column; gap: 8px; padding-top: 16px; padding-bottom: 16px;
              padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1a1d22; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .name  { color: #dc143c; font-size: 34px; font-weight: 700; }
      .body  { color: #d7dbe2; font-size: 22px; }
      .hint  { color: #9aa3ae; font-size: 22px; }
    </style>
    <div class="card">
      <span class="title">Glow Button</span>
      <span class="name" id="name">Crimson</span>
      <span class="body" id="count">Presses: 0</span>
      <span class="hint">Pinch or poke the button to change its color.</span>
    </div>`, { width: 0.28, position: [0, 0.2, -0.03], rotationY: 0 });
  root.add(info.object3D);

  // ---------- State ----------
  const target = new THREE.Color(colors[0].h);
  const current = new THREE.Color(colors[0].h);
  let index = 0;
  let presses = 0;
  let pressAnim = 0;

  const hexString = (n) => '#' + n.toString(16).padStart(6, '0');

  traits(cap, {
    onPress: () => {
      index = (index + 1) % colors.length;
      const c = colors[index];
      target.setHex(c.h);
      presses++;
      info.set('name', { text: c.n, color: hexString(c.h) });
      info.set('count', { text: 'Presses: ' + presses });
      pressAnim = 1;
    },
  });
  // the dome sits on top of the cap, so it presses too
  traits(dome, {
    onPress: () => {
      index = (index + 1) % colors.length;
      const c = colors[index];
      target.setHex(c.h);
      presses++;
      info.set('name', { text: c.n, color: hexString(c.h) });
      info.set('count', { text: 'Presses: ' + presses });
      pressAnim = 1;
    },
  });

  return {
    root,
    update(time, delta) {
      // press travel: snap down, ease back up
      if (pressAnim > 0) pressAnim = Math.max(0, pressAnim - delta * 6);
      const travel = 0.009 * pressAnim;
      cap.position.y = 0.029 - travel;
      dome.position.y = 0.04 - travel;

      // smooth color blend toward the chosen color
      const k = Math.min(1, delta * 12);
      current.lerp(target, k);
      capMat.color.copy(current);
      capMat.emissive.copy(current);
      ringMat.color.copy(current);

      // gentle breathing glow
      const pulse = Math.sin(time * 3) * 0.5 + 0.5;
      capMat.emissiveIntensity = 0.8 + pulse * 0.55 + pressAnim * 0.6;
      ringMat.opacity = 0.55 + pulse * 0.35;
    },
  };
}

