  const bananaMat = new THREE.MeshStandardMaterial({ color: 0xffd93d, roughness: 0.55 });
  const bananaMesh = new THREE.Mesh(new THREE.TorusGeometry(0.032, 0.012, 12, 22, Math.PI * 0.85), bananaMat);
  bananaMesh.name = "Banana";
  bananaMesh.rotation.x = Math.PI / 2;
  bananaMesh.rotation.z = Math.PI * 0.08;
  banana.add(bananaMesh);
  const tipMat = new THREE.MeshStandardMaterial({ color: 0x6b4a1f, roughness: 1.0 });
  const tip1 = new THREE.Mesh(new THREE.SphereGeometry(0.006, 10, 8), tipMat);
  tip1.position.set(0.042, 0, 0.008);
  banana.add(tip1);
  const tip2 = new THREE.Mesh(new THREE.SphereGeometry(0.006, 10, 8), tipMat);
  tip2.position.set(-0.01, 0, -0.04);
  banana.add(tip2);

  // Orange
  const orange = new THREE.Group();
  orange.name = "Orange";
  orange.position.set(0.22, 0.032, 0.09);
  root.add(orange);
  const orangeMesh = new THREE.Mesh(
    new THREE.SphereGeometry(0.032, 26, 14),
    new THREE.MeshStandardMaterial({ color: 0xff8a1a, roughness: 0.6 })
  );
  orangeMesh.name = "Orange";
  orange.add(orangeMesh);
  const orangeDot = new THREE.Mesh(
    new THREE.CylinderGeometry(0.004, 0.005, 0.012, 8),
    new THREE.MeshStandardMaterial({ color: 0x2f7a2f, roughness: 1.0 })
  );
  orangeDot.position.y = 0.034;
  orange.add(orangeDot);

  traits(apple, { grab: true });
  traits(banana, { grab: true });
  traits(orange, { grab: true });

  const startPos = [
    [-0.22, 0.034, 0.09],
    [0, 0.016, 0.11],
    [0.22, 0.032, 0.09]
  ];

  // ----- Info panel -----
  const info = ui(`
    <style>
      .card { width: 500px; flex-direction: column; gap: 8px; padding-top: 16px; padding-bottom: 16px; padding-left: 20px; padding-right: 20px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 22px; }
      .list { color: #ffe9a8; font-size: 22px; }
      .total { color: #7dff9a; font-size: 28px; font-weight: 700; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px; border-radius: 12px; background-color: #2f6fdb; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Fruit Basket Shop</span>
      <span class="body" id="hint">Pick up fruit and drop it in the basket. Apple $1.20, Banana $0.80, Orange $1.50.</span>
      <span class="list" id="list">Basket: empty</span>
      <span class="total" id="total">Total: $0.00</span>
      <button class="btn" id="reset"><span class="btn-text">Reset fruits</span></button>
    </div>`, { width: 0.32, position: [0, 0.33, -0.18], rotationY: 0 });
  root.add(info.object3D);

  info.on("reset", "click", () => {
    apple.position.set(startPos[0][0], startPos[0][1], startPos[0][2]);
    banana.position.set(startPos[1][0], startPos[1][1], startPos[1][2]);
    orange.position.set(startPos[2][0], startPos[2][1], startPos[2][2]);
  });

  const fruits = [
    { obj: apple, name: "Apple", cents: 120, restY: 0.034, basketY: 0.038, in: false },
    { obj: banana, name: "Banana", cents: 80, restY: 0.016, basketY: 0.038, in: false },
    { obj: orange, name: "Orange", cents: 150, restY: 0.032, basketY: 0.085, in: false }
  ];

  let lastCents = -1;
  let lastKey = "";

  function centsToText(c) {
    const d = Math.floor(c / 100);
    const r = c % 100;
    const rr = r < 10 ? "0" + r : "" + r;
    return "Total: $" + d + "." + rr;
  }

  return {
    root,
    update(time, delta) {
      if (delta > 0.05) delta = 0.05;
      const k = Math.min(1, delta * 5);
      const kXZ = Math.min(1, delta * 3);

      let hovering = false;

      for (let i = 0; i < 3; i++) {
        const f = fruits[i];
        const p = f.obj.position;
        const grabbed = isGrabbed(f.obj);
        const dx = p.x - BX;
        const dz = p.z - BZ;
        const d2 = dx * dx + dz * dz;
        const overXZ = d2 < BASKET_R2;
        const low = p.y < 0.12;
        f.in = overXZ && low;

        if (grabbed) {
          if (overXZ && p.y < 0.22) hovering = true;
        } else {
          if (f.in) {
            // settle inside basket
            p.x += (BX - p.x) * kXZ * 0.6;
            p.z += (BZ - p.z) * kXZ * 0.6;
            p.y += (f.basketY - p.y) * k;
            if (p.y < 0.015) p.y = 0.015;
          } else {
            // rest on desk
            if (p.y < f.restY - 0.002 || p.y > f.restY + 0.002) {
              p.y += (f.restY - p.y) * Math.min(1, delta * 8);
            } else {
              p.y = f.restY;
            }
            if (p.y < 0.008) p.y = f.restY;
          }
        }
      }

      rimMat.emissiveIntensity = hovering ? 0.9 : 0.15;

      let total = 0;
      let key = "";
      for (let i = 0; i < 3; i++) {
        if (fruits[i].in) {
          total += fruits[i].cents;
          key += "1";
        } else {
          key += "0";
        }
      }

      if (total !== lastCents || key !== lastKey) {
        lastCents = total;
        lastKey = key;
        info.set("total", { text: centsToText(total) });
        let listText = "Basket: empty";
        if (key !== "000") {
          let names = "";
          let first = true;
          for (let i = 0; i < 3; i++) {
            if (fruits[i].in) {
              if (!first) names += " + ";
              names += fruits[i].name;
              first = false;
            }
          }
          listText = "Basket: " + names;
        }
        info.set("list", { text: listText });
      }
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---- grabbable helix -------------------------------------------------
  const helix = new THREE.Group();
  helix.name = 'DNAHelix';
  helix.position.set(-0.06, 0.22, 0);
  root.add(helix);

  const spinner = new THREE.Group(); // spins inside the grabbed group
  helix.add(spinner);

  const R = 0.045;      // helix radius
  const H = 0.30;       // helix height
  const TURNS = 1.6;    // 16 rungs / 1.6 turns = 10 base pairs per turn

  function pointAt(t, offset, out) {
    const a = t * TURNS * Math.PI * 2 + offset;
    return out.set(Math.cos(a) * R, -H / 2 + t * H, Math.sin(a) * R);
  }

  // Backbone strands (two smooth tubes)
  const SEG = 96;
  const ptsA = [];
  const ptsB = [];
  for (let i = 0; i <= SEG; i++) {
    const t = i / SEG;
    ptsA.push(pointAt(t, 0, new THREE.Vector3()));
    ptsB.push(pointAt(t, Math.PI, new THREE.Vector3()));
  }

  const backboneMatA = new THREE.MeshStandardMaterial({
    color: 0xdfe7f2, roughness: 0.35, metalness: 0.15,
  });
  const backboneMatB = new THREE.MeshStandardMaterial({
    color: 0xb9c7da, roughness: 0.35, metalness: 0.15,
  });

  const tubeA = new THREE.Mesh(
    new THREE.TubeGeometry(new THREE.CatmullRomCurve3(ptsA), 140, 0.006, 8, false),
    backboneMatA,
  );
  tubeA.name = 'BackboneA';
  spinner.add(tubeA);

  const tubeB = new THREE.Mesh(
    new THREE.TubeGeometry(new THREE.CatmullRomCurve3(ptsB), 140, 0.006, 8, false),
    backboneMatB,
  );
  tubeB.name = 'BackboneB';
  spinner.add(tubeB);

  // ---- base pairs ------------------------------------------------------
  const baseMat = {
    A: new THREE.MeshStandardMaterial({ color: 0xe4573f, roughness: 0.5, emissive: 0x2a0703, emissiveIntensity: 1 }),
    T: new THREE.MeshStandardMaterial({ color: 0x3d9be9, roughness: 0.5, emissive: 0x001220, emissiveIntensity: 1 }),
    G: new THREE.MeshStandardMaterial({ color: 0x46c07c, roughness: 0.5, emissive: 0x001c0d, emissiveIntensity: 1 }),
    C: new THREE.MeshStandardMaterial({ color: 0xf0bb3c, roughness: 0.5, emissive: 0x1f1400, emissiveIntensity: 1 }),
  };

  const rungGeo = new THREE.CylinderGeometry(0.005, 0.005, 1, 8, 1, false);
  const UP = new THREE.Vector3(0, 1, 0);

  function makeSegment(from, to, mat) {
    const dir = new THREE.Vector3().subVectors(to, from);
    const len = dir.length();
    const m = new THREE.Mesh(rungGeo, mat);
    m.position.copy(from).addScaledVector(dir, 0.5);
    m.quaternion.setFromUnitVectors(UP, dir.normalize());
    m.scale.set(1, len, 1);
    return m;
  }

  // 16 rungs over 1.6 turns -> 10 base pairs per full turn
  const pairSeq = ['AT', 'GC', 'TA', 'CG', 'AT', 'CG', 'GC', 'TA',
                   'AT', 'GC', 'TA', 'CG', 'GC', 'AT', 'CG', 'TA'];
  const NRUNG = pairSeq.length;
  const pA = new THREE.Vector3();
  const pB = new THREE.Vector3();
  const mid = new THREE.Vector3();

  for (let i = 0; i < NRUNG; i++) {
    const t = (i + 0.5) / NRUNG;
    pointAt(t, 0, pA);
    pointAt(t, Math.PI, pB);
    mid.addVectors(pA, pB).multiplyScalar(0.5);
    const pair = pairSeq[i];
    spinner.add(makeSegment(pA, mid, baseMat[pair[0]]));
    spinner.add(makeSegment(mid, pB, baseMat[pair[1]]));
  }

  // Faint halo so the thin model is easy to pinch
  const halo = new THREE.Mesh(
    new THREE.CylinderGeometry(0.06, 0.06, H + 0.012, 20, 1, true),
    new THREE.MeshBasicMaterial({
      color: 0x6fa8ff, transparent: true, opacity: 0.05,
      depthWrite: false, side: THREE.DoubleSide,
    }),
  );
  halo.name = 'GrabHalo';
  helix.add(halo);

  traits(helix, { grab: true });

  // ---- info panel ------------------------------------------------------
  const panel = ui(`
    <style>
      .card { width: 440px; flex-direction: column; gap: 12px;
              padding-top: 18px; padding-bottom: 18px; padding-left: 22px; padding-right: 22px;
              border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 23px; }
      .legend { flex-direction: row; gap: 14px; }
      .item { flex-direction: row; align-items: center; gap: 6px; }
      .dot { width: 16px; height: 16px; border-radius: 8px; }
      .dotA { background-color: #e4573f; }
      .dotT { background-color: #3d9be9; }
      .dotG { background-color: #46c07c; }
      .dotC { background-color: #f0bb3c; }
      .lt { color: #c3cad4; font-size: 20px; }
      .row { flex-direction: row; gap: 10px; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btn2 { padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px;
              border-radius: 12px; background-color: #3a4048; }
      .btn-text { color: #ffffff; font-size: 21px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">DNA Double Helix</span>
      <span class="body" id="fact">Pinch the model to pick it up and turn it around.</span>
      <div class="legend">
        <div class="item"><div class="dot dotA"></div><span class="lt">A</span></div>
        <div class="item"><div class="dot dotT"></div><span class="lt">T</span></div>
        <div class="item"><div class="dot dotG"></div><span class="lt">G</span></div>
        <div class="item"><div class="dot dotC"></div><span class="lt">C</span></div>
      </div>
      <div class="row">
        <button class="btn" id="next"><span class="btn-text">Next fact</span></button>
        <button class="btn2" id="spin"><span class="btn-text" id="spintxt">Spin: on</span></button>
      </div>
    </div>`, { width: 0.30, position: [0.24, 0.24, 0], rotationY: -0.35 });

  root.add(panel.object3D);

  const facts = [
    'DNA is a double helix: two strands twisting around one shared axis.',
    'Each rung is a base pair. A always pairs with T, and G always pairs with C.',
    'The two strands are antiparallel: they run in opposite directions.',
    'One full turn of this helix spans about 10 base pairs.',
    'Stretched out, the DNA in one human cell is about 2 meters long.',
    'The human genome holds about 3 billion base pairs.',
    'The two strands are held together by hydrogen bonds between the bases.',
  ];

  let factIndex = -1;
  panel.on('next', 'click', () => {
    factIndex = (factIndex + 1) % facts.length;
    panel.set('fact', { text: facts[factIndex] });
  });

  let spinOn = true;
  panel.on('spin', 'click', () => {
    spinOn = !spinOn;
    panel.set('spintxt', { text: spinOn ? 'Spin: on' : 'Spin: off' });
  });

  // ---- animation -------------------------------------------------------
  let angle = 0;

  return {
    root,
    update(time, delta) {
      if (!spinOn || isGrabbed(helix)) return; // never fight the user's hand
      angle += delta * 0.4;                    // rim speed ~0.018 m/s
      spinner.rotation.y = angle;
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------- the helix ----------
  const helix = new THREE.Group();
  helix.name = 'DNAHelix';
  helix.position.set(-0.14, 0.03, 0);
  root.add(helix);

  const LEVELS = 60;        // base pairs drawn
  const HEIGHT = 0.30;      // meters
  const RADIUS = 0.055;     // helix radius
  const TURNS = 2.4;        // full twists
  const BACKBONE_R = 0.008;
  const RUNG_R = 0.0024;

  const baseColor = { A: 0xff6b6b, T: 0x4d8bff, G: 0x51d88a, C: 0xffd93d };
  const complement = { A: 'T', T: 'A', G: 'C', C: 'G' };
  const pattern = 'ATGCCATTAGGCATTCG';

  // collect transforms first, then build instanced meshes
  const backbonePos = [];
  const rungData = { A: [], T: [], G: [], C: [] };

  const UP = new THREE.Vector3(0, 1, 0);
  const dir = new THREE.Vector3();
  const quat = new THREE.Quaternion();

  for (let i = 0; i < LEVELS; i++) {
    const t = i / (LEVELS - 1);
    const y = t * HEIGHT;
    const a = t * TURNS * Math.PI * 2;

    const x1 = Math.cos(a) * RADIUS;
    const z1 = Math.sin(a) * RADIUS;
    const x2 = -x1;
    const z2 = -z1;

    backbonePos.push([x1, y, z1], [x2, y, z2]);

    dir.set(Math.cos(a), 0, Math.sin(a));
    quat.setFromUnitVectors(UP, dir);

    const b1 = pattern[i % pattern.length];
    const b2 = complement[b1];
    rungData[b1].push([x1 * 0.5, y, z1 * 0.5, quat.x, quat.y, quat.z, quat.w]);
    rungData[b2].push([x2 * 0.5, y, z2 * 0.5, quat.x, quat.y, quat.z, quat.w]);
  }

  const mat4 = new THREE.Matrix4();
  const pos = new THREE.Vector3();
  const scl = new THREE.Vector3();
  const q = new THREE.Quaternion();

  // sugar-phosphate backbone (two strands of spheres)
  const bbGeo = new THREE.SphereGeometry(BACKBONE_R, 8, 6);
  const bbMat = new THREE.MeshStandardMaterial({ color: 0xb9c6da, roughness: 0.38, metalness: 0.3 });
  const backbone = new THREE.InstancedMesh(bbGeo, bbMat, backbonePos.length);
  backbone.name = 'Backbone';
  for (let i = 0; i < backbonePos.length; i++) {
    const p = backbonePos[i];
    mat4.makeTranslation(p[0], p[1], p[2]);
    backbone.setMatrixAt(i, mat4);
  }
  backbone.instanceMatrix.needsUpdate = true;
  helix.add(backbone);

  // base pairs: two half-rungs per level, colored by base
  const rungGeo = new THREE.CylinderGeometry(1, 1, 1, 8, 1, true);
  const bases = ['A', 'T', 'G', 'C'];
  for (let b = 0; b < bases.length; b++) {
    const letter = bases[b];
    const list = rungData[letter];
    const rMat = new THREE.MeshStandardMaterial({
      color: baseColor[letter],
      roughness: 0.45,
      metalness: 0.1,
      emissive: baseColor[letter],
      emissiveIntensity: 0.12,
    });
    const mesh = new THREE.InstancedMesh(rungGeo, rMat, list.length);
    mesh.name = 'Base' + letter;
    for (let i = 0; i < list.length; i++) {
      const d = list[i];
      pos.set(d[0], d[1], d[2]);
      q.set(d[3], d[4], d[5], d[6]);
      scl.set(RUNG_R, RADIUS, RUNG_R);
      mat4.compose(pos, q, scl);
      mesh.setMatrixAt(i, mat4);
    }
    mesh.instanceMatrix.needsUpdate = true;
    helix.add(mesh);
  }

  // grab the whole molecule
  traits(helix, { grab: true });

  // ---------- info panel ----------
  const info = ui(`
    <style>
      .card { width: 460px; flex-direction: column; gap: 10px;
              padding-top: 16px; padding-bottom: 16px; padding-left: 20px; padding-right: 20px;
              border-radius: 18px; background-color: #1b1f26; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .hint { color: #96a1b0; font-size: 20px; }
      .body { color: #dfe4ec; font-size: 22px; }
      .legend { flex-direction: row; gap: 16px; padding-top: 2px; padding-bottom: 2px; }
      .item { flex-direction: row; align-items: center; gap: 6px; }
      .chipA { width: 20px; height: 20px; border-radius: 5px; background-color: #ff6b6b; }
      .chipT { width: 20px; height: 20px; border-radius: 5px; background-color: #4d8bff; }
      .chipG { width: 20px; height: 20px; border-radius: 5px; background-color: #51d88a; }
      .chipC { width: 20px; height: 20px; border-radius: 5px; background-color: #ffd93d; }
      .ltxt { color: #dfe4ec; font-size: 20px; }
      .row { flex-direction: row; gap: 10px; padding-top: 4px; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btnAlt { padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px;
                border-radius: 12px; background-color: #39404a; }
      .btn-text { color: #ffffff; font-size: 21px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">DNA Double Helix</span>
      <span class="hint">Pinch the helix to lift it and turn it around.</span>
      <span class="body" id="fact">Two sugar-phosphate strands twist around each other. Every rung is a base pair.</span>
      <div class="legend">
        <div class="item"><div class="chipA"></div><span class="ltxt">A</span></div>
        <div class="item"><div class="chipT"></div><span class="ltxt">T</span></div>
        <div class="item"><div class="chipG"></div><span class="ltxt">G</span></div>
        <div class="item"><div class="chipC"></div><span class="ltxt">C</span></div>
      </div>
      <div class="row">
        <button class="btn" id="next"><span class="btn-text">Next fact</span></button>
        <button class="btnAlt" id="spin"><span class="btn-text" id="spinLabel">Spin: on</span></button>
      </div>
    </div>`, { width: 0.32, position: [0.21, 0.19, 0.02], rotationY: -0.28 });
  root.add(info.object3D);

  const facts = [
    'Two sugar-phosphate strands twist around each other. Every rung is a base pair.',
    'Base pairing: A (red) always pairs with T (blue), G (green) always pairs with C (yellow).',
    'The strands run in opposite directions - DNA is antiparallel, one 5\' to 3\', the other 3\' to 5\'.',
    'One full turn of the helix covers about 10.5 base pairs and rises 3.4 nanometres.',
    'The double helix is only about 2 nanometres wide.',
    'A human cell holds about 3 billion base pairs; stretched out, that DNA is about 2 m long.',
    'A-T pairs share two hydrogen bonds, G-C pairs share three, so GC-rich DNA is more stable.',
  ];
  let factIndex = 0;
  let spinOn = true;

  info.on('next', 'click', () => {
    factIndex = (factIndex + 1) % facts.length;
    info.set('fact', { text: facts[factIndex] });
  });
  info.on('spin', 'click', () => {
    spinOn = !spinOn;
    info.set('spinLabel', { text: spinOn ? 'Spin: on' : 'Spin: off' });
  });

  const spinSpeed = 0.35; // rad/s -> ~0.02 m/s at the backbone, slow enough to catch

  return {
    root,
    update(time, delta) {
      if (!spinOn || isGrabbed(helix)) return;
      helix.rotation.y += Math.min(delta, 0.05) * spinSpeed;
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
