  const smallTickGeom = new THREE.BoxGeometry(0.0028, 0.009, 0.002);
  const quarterTickGeom = new THREE.BoxGeometry(0.005, 0.014, 0.002);
  for (let i = 0; i < 12; i++) {
    const angle = (i * Math.PI) / 6; // clockwise from 12 o'clock
    const isQuarter = i % 3 === 0;
    const r = isQuarter ? 0.0525 : 0.0545;
    const tick = new THREE.Mesh(isQuarter ? quarterTickGeom : smallTickGeom, isQuarter ? accentMat : tickMat);
    tick.name = 'HourMarker' + i;
    tick.position.set(Math.sin(angle) * r, HUB_Y + Math.cos(angle) * r, 0.0125);
    tick.rotation.z = -angle;
    clock.add(tick);
  }

  // hands (geometry shifted so the pivot sits at the dial center)
  const hourGeom = new THREE.BoxGeometry(0.0062, 0.030, 0.0025);
  hourGeom.translate(0, 0.0125, 0);
  const minuteGeom = new THREE.BoxGeometry(0.0044, 0.049, 0.0025);
  minuteGeom.translate(0, 0.022, 0);

  const hourPivot = new THREE.Group();
  hourPivot.position.set(0, HUB_Y, 0.014);
  const hourHand = new THREE.Mesh(hourGeom, handMat);
  hourHand.name = 'HourHand';
  hourPivot.add(hourHand);
  clock.add(hourPivot);

  const minutePivot = new THREE.Group();
  minutePivot.position.set(0, HUB_Y, 0.0158);
  const minuteHand = new THREE.Mesh(minuteGeom, accentMat);
  minuteHand.name = 'MinuteHand';
  minutePivot.add(minuteHand);
  clock.add(minutePivot);

  const capGeom = new THREE.CylinderGeometry(0.005, 0.005, 0.005, 16);
  const cap = new THREE.Mesh(capGeom, handMat);
  cap.name = 'HandCap';
  cap.rotation.x = Math.PI / 2;
  cap.position.set(0, HUB_Y, 0.0175);
  clock.add(cap);

  traits(clock, { grab: true });

  // ---------------- digital readout panel ----------------
  const info = ui(`
    <style>
      .card { width: 420px; flex-direction: column; align-items: flex-start; gap: 8px;
              padding-top: 16px; padding-bottom: 16px; padding-left: 20px; padding-right: 20px;
              border-radius: 18px; background-color: #1d2128; }
      .label { color: #8f98a6; font-size: 20px; font-weight: 700; }
      .time { color: #ffffff; font-size: 50px; font-weight: 700; }
      .body { color: #cbd2dc; font-size: 22px; }
      .btn { margin-top: 6px; padding-top: 10px; padding-bottom: 10px;
             padding-left: 16px; padding-right: 16px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="label">DESK CLOCK</span>
      <span class="time" id="digital">--:--</span>
      <span class="body" id="note">The hands follow the real time. Pinch the clock to pick it up.</span>
      <button class="btn" id="fmt"><span class="btn-text">Switch 12h / 24h</span></button>
    </div>`, { width: 0.32, position: [0.19, 0.15, 0.0], rotationY: -0.26 });
  root.add(info.object3D);

  // ---------------- time keeping ----------------
  const hasDate = typeof Date !== 'undefined' && typeof Date.now === 'function';
  let tzOffsetMin = 0;
  if (hasDate) {
    tzOffsetMin = new Date().getTimezoneOffset();
  }
  const FAKE_START_MS = (10 * 60 + 9) * 60000; // fallback 10:09

  let use24 = true;
  let lastTimeText = '';

  function pad2(n) {
    return n < 10 ? '0' + n : '' + n;
  }

  info.on('fmt', 'click', () => {
    use24 = !use24;
    lastTimeText = '';
  });

  return {
    root,
    update(time) {
      // local wall-clock milliseconds (no allocation per frame)
      const localMs = hasDate ? Date.now() - tzOffsetMin * 60000 : FAKE_START_MS + time * 1000;
      let msInDay = localMs % 86400000;
      if (msInDay < 0) msInDay += 86400000;

      const totalSec = msInDay / 1000;
      const hours = Math.floor(totalSec / 3600);
      const minutes = Math.floor(totalSec / 60) % 60;
      const secondFrac = totalSec % 60;

      const minuteFrac = minutes + secondFrac / 60;
      const hourFrac = (hours % 12) + minuteFrac / 60;

      minutePivot.rotation.z = -(minuteFrac / 60) * Math.PI * 2;
      hourPivot.rotation.z = -(hourFrac / 12) * Math.PI * 2;

      const h12 = hours % 12 === 0 ? 12 : hours % 12;
      const text = use24
        ? pad2(hours) + ':' + pad2(minutes)
        : h12 + ':' + pad2(minutes) + (hours < 12 ? ' AM' : ' PM');

      if (text !== lastTimeText) {
        lastTimeText = text;
        info.set('digital', { text: text });
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const BOND_DIST = 0.065;
  const CROWD_O = 0.09;
  const CROWD_H = 0.085;

  // ----- build platform (center zone) -----
  const platformMat = new THREE.MeshStandardMaterial({ color: 0x2a2e35, roughness: 0.9 });
  const platform = new THREE.Mesh(new THREE.CylinderGeometry(0.14, 0.14, 0.02, 40), platformMat);
  platform.name = 'BuildPlatform';
  platform.position.set(0, 0.01, -0.02);
  root.add(platform);

  const ringMat = new THREE.MeshStandardMaterial({ color: 0x8a919e, emissive: 0x8a919e, emissiveIntensity: 0.35, roughness: 0.5 });
  const ring = new THREE.Mesh(new THREE.TorusGeometry(0.14, 0.005, 10, 48), ringMat);
  ring.name = 'BuildRing';
  ring.position.set(0, 0.022, -0.02);
  ring.rotation.x = -Math.PI / 2;
  root.add(ring);

  // orbiting marker to show the zone (scenery, not grabbable)
  const marker = new THREE.Mesh(
    new THREE.SphereGeometry(0.007, 12, 8),
    new THREE.MeshBasicMaterial({ color: 0x6fb3ff })
  );
  marker.name = 'ZoneMarker';
  marker.position.set(0.14, 0.03, -0.02);
  root.add(marker);

  // ----- atoms -----
  const oxyGeo = new THREE.SphereGeometry(0.032, 28, 16);
  const hydGeo = new THREE.SphereGeometry(0.022, 24, 12);
  const oxyMat = new THREE.MeshStandardMaterial({ color: 0xe23b2e, roughness: 0.35 });
  const hydMat = new THREE.MeshStandardMaterial({ color: 0xf0f4f8, roughness: 0.5 });

  const oxygens = [];
  const hydrogens = [];
  const allAtoms = [];

  function makeAtom(name, geo, mat, x, y, z) {
    const m = new THREE.Mesh(geo, mat);
    m.name = name;
    m.position.set(x, y, z);
    root.add(m);
    traits(m, { grab: true });
    m.userData.home = new THREE.Vector3(x, y, z);
    allAtoms.push(m);
    return m;
  }

  oxygens.push(makeAtom('Oxygen_1', oxyGeo, oxyMat, -0.27, 0.035, 0.02));
  oxygens.push(makeAtom('Oxygen_2', oxyGeo, oxyMat, -0.27, 0.035, -0.14));
  hydrogens.push(makeAtom('Hydrogen_1', hydGeo, hydMat, 0.27, 0.025, 0.10));
  hydrogens.push(makeAtom('Hydrogen_2', hydGeo, hydMat, 0.27, 0.025, 0.02));
  hydrogens.push(makeAtom('Hydrogen_3', hydGeo, hydMat, 0.27, 0.025, -0.06));
  hydrogens.push(makeAtom('Hydrogen_4', hydGeo, hydMat, 0.27, 0.025, -0.14));

  // ----- bond sticks (hidden until atoms touch) -----
  const bondGeo = new THREE.CylinderGeometry(0.007, 0.007, 1, 10);
  const bondMat = new THREE.MeshStandardMaterial({ color: 0x9aa0aa, roughness: 0.6 });
  const bonds = [];
  for (let oi = 0; oi < oxygens.length; oi++) {
    for (let hi = 0; hi < hydrogens.length; hi++) {
      const b = new THREE.Mesh(bondGeo, bondMat);
      b.name = 'Bond_O' + oi + '_H' + hi;
      b.visible = false;
      root.add(b);
      bonds.push({ o: oxygens[oi], h: hydrogens[hi], mesh: b });
    }
  }

  // ----- 3D check / reset blocks -----
  const checkMat = new THREE.MeshStandardMaterial({ color: 0x2ecc71, roughness: 0.5, emissive: 0x2ecc71, emissiveIntensity: 0.25 });
  const checkBox = new THREE.Mesh(new THREE.BoxGeometry(0.09, 0.03, 0.06), checkMat);
  checkBox.name = 'CheckButton';
  checkBox.position.set(0.11, 0.015, 0.20);
  root.add(checkBox);

  const resetMat = new THREE.MeshStandardMaterial({ color: 0xb0483e, roughness: 0.6 });
  const resetBox = new THREE.Mesh(new THREE.BoxGeometry(0.09, 0.03, 0.06), resetMat);
  resetBox.name = 'ResetButton';
  resetBox.position.set(-0.11, 0.015, 0.20);
  root.add(resetBox);

  // ----- info panel (single panel) -----
  const info = ui(`
    <style>
      .card { width: 500px; flex-direction: column; gap: 10px; padding-top: 18px; padding-bottom: 18px; padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; text-align: center; }
      .body { color: #d7dbe2; font-size: 22px; text-align: center; }
      .legend { color: #aeb6c2; font-size: 22px; text-align: center; }
      .status { color: #ffd166; font-size: 24px; font-weight: 700; text-align: center; }
      .detail { color: #d7dbe2; font-size: 22px; text-align: center; }
      .row { flex-direction: row; gap: 12px; justify-content: center; align-items: center; }
      .btn-check { padding-top: 10px; padding-bottom: 10px; padding-left: 18px; padding-right: 18px; border-radius: 12px; background-color: #2ecc71; }
      .btn-reset { padding-top: 10px; padding-bottom: 10px; padding-left: 18px; padding-right: 18px; border-radius: 12px; background-color: #4a4f58; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Build Water - H2O</span>
      <span class="body">Grab atoms and stick 2 H onto 1 O inside the middle ring. Green block = check, red block = reset.</span>
      <span class="legend">RED big = Oxygen, WHITE small = Hydrogen</span>
      <span class="status" id="status">Press CHECK when you think it is water.</span>
      <span class="detail" id="detail">Tip: grey sticks appear when atoms touch.</span>
      <div class="row">
        <button class="btn-check" id="check"><span class="btn-text">Check water</span></button>
        <button class="btn-reset" id="reset"><span class="btn-text">Reset</span></button>
      </div>
    </div>`, { width: 0.33, position: [0, 0.31, -0.15], rotationY: 0 });
  root.add(info.object3D);

  let succeeded = false;

  function setRing(hex, intensity) {
    ringMat.color.setHex(hex);
    ringMat.emissive.setHex(hex);
    ringMat.emissiveIntensity = intensity;
  }

  function evaluate() {
    const perO = [[], []];
    for (let i = 0; i < 2; i++) {
      for (let j = 0; j < 4; j++) {
        const d = oxygens[i].position.distanceTo(hydrogens[j].position);
        if (d < BOND_DIST) perO[i].push(j);
      }
    }
    const perH = [[], [], [], []];
    for (let i = 0; i < 2; i++) {
      for (let k = 0; k < perO[i].length; k++) {
        perH[perO[i][k]].push(i);
      }
    }
    return { perO, perH };
  }

  function doCheck() {
    const { perO, perH } = evaluate();

    // shared H between two O atoms?
    let shared = false;
    for (let j = 0; j < 4; j++) {
      if (perH[j].length > 1) shared = true;
    }
    if (shared) {
      succeeded = false;
      setRing(0xe05a4f, 0.5);
      info.set('status', { text: 'FAIL: One H is touching two O atoms.' });
      info.set('detail', { text: 'Give each O its own H atoms. Move one O away.' });
      return;
    }

    // too many H on one O?
    for (let i = 0; i < 2; i++) {
      if (perO[i].length > 2) {
        succeeded = false;
        setRing(0xe05a4f, 0.5);
        info.set('status', { text: 'FAIL: Too many H on one O.' });
        info.set('detail', { text: 'Water needs exactly 2 H on 1 O. Pull extras away.' });
        return;
      }
    }

    // check for clean O + 2H
    for (let i = 0; i < 2; i++) {
      if (perO[i].length === 2) {
        let crowded = false;
        for (let k = 0; k < 2; k++) {
          if (k === i) continue;
          if (oxygens[i].position.distanceTo(oxygens[k].position) < CROWD_O) crowded = true;
        }
        for (let j = 0; j < 4; j++) {
          const isBonded = (perO[i].indexOf(j) !== -1);
          if (!isBonded) {
            if (oxygens[i].position.distanceTo(hydrogens[j].position) < CROWD_H) crowded = true;
          }
        }
        if (!crowded) {
          succeeded = true;
          setRing(0x2ecc71, 0.7);
          info.set('status', { text: 'PASS: You built water! 1 O + 2 H.' });
          info.set('detail', { text: 'Water is H2O. Bent shape, angle about 104.5 deg.' });
          return;
        } else {
          succeeded = false;
          setRing(0xe0a44f, 0.5);
          info.set('status', { text: 'FAIL: O + 2 H found but crowded.' });
          info.set('detail', { text: 'Move extra atoms away from your water molecule.' });
          return;
        }
      }
    }

    // one bond only?
    for (let i = 0; i < 2; i++) {
      if (perO[i].length === 1) {
        succeeded = false;
        setRing(0xe0a44f, 0.4);
        info.set('status', { text: 'Almost: that O has only 1 H.' });
        info.set('detail', { text: 'Bring one more H to touch the same O.' });
        return;
      }
    }

    succeeded = false;
    setRing(0x8a919e, 0.35);
    info.set('status', { text: 'FAIL: No water yet.' });
    info.set('detail', { text: 'Drag 2 white H atoms to touch 1 red O in the ring.' });
  }

  function doReset() {
    for (let i = 0; i < allAtoms.length; i++) {
      allAtoms[i].position.copy(allAtoms[i].userData.home);
    }
    succeeded = false;
    setRing(0x8a919e, 0.35);
    info.set('status', { text: 'Press CHECK when you think it is water.' });
    info.set('detail', { text: 'Tip: grey sticks appear when atoms touch.' });
  }

  info.on('check', 'click', doCheck);
  info.on('reset', 'click', doReset);
  traits(checkBox, { onPress: doCheck });
  traits(resetBox, { onPress: doReset });

  const tmpDir = new THREE.Vector3();
  const tmpMid = new THREE.Vector3();
  const UP = new THREE.Vector3(0, 1, 0);

  return {
    root,
    update(time) {
      // live bonds
      for (let b = 0; b < bonds.length; b++) {
        const pair = bonds[b];
        tmpDir.subVectors(pair.h.position, pair.o.position);
        const len = tmpDir.length();
        if (len < BOND_DIST && len > 0.0001) {
          pair.mesh.visible = true;
          tmpMid.addVectors(pair.o.position, pair.h.position).multiplyScalar(0.5);
          pair.mesh.position.copy(tmpMid);
          pair.mesh.scale.set(1, len, 1);
          pair.mesh.quaternion.setFromUnitVectors(UP, tmpDir.normalize());
        } else {
          pair.mesh.visible = false;
        }
      }
      // orbit marker around build ring
      const a = time * 0.35;
      marker.position.set(Math.cos(a) * 0.14, 0.03, -0.02 + Math.sin(a) * 0.14);

      // success pulse on the ring
      if (succeeded) {
        ringMat.emissiveIntensity = 0.55 + Math.sin(time * 4.0) * 0.25;
      }
    }
  };
}

