      <span class="total" id="total">Total: $0.00</span>
      <button class="btn" id="empty"><span class="btn-text">Empty basket</span></button>
    </div>`, { width: 0.32, position: [0.27, 0.25, -0.02], rotationY: -0.32 });
  root.add(panel.object3D);

  function fmt(n) {
    const c = Math.round(n * 100);
    const d = Math.floor(c / 100);
    let r = c - d * 100;
    let rs = '' + r;
    if (r < 10) rs = '0' + rs;
    return '$' + d + '.' + rs;
  }

  function refreshPanel() {
    let total = 0;
    let names = '';
    let count = 0;
    for (let i = 0; i < fruits.length; i++) {
      if (fruits[i].inBasket) {
        total += fruits[i].price;
        if (count > 0) names += ' + ';
        names += fruits[i].name;
        count++;
      }
    }
    if (count === 0) {
      panel.set('basket', { text: 'Basket is empty.' });
    } else {
      panel.set('basket', { text: 'In basket: ' + names });
    }
    panel.set('total', { text: 'Total: ' + fmt(total) });
  }
  refreshPanel();

  panel.on('empty', 'click', () => {
    for (let i = 0; i < fruits.length; i++) {
      const f = fruits[i];
      if (isGrabbed(f.group)) continue;
      f.inBasket = false;
      f.wasGrabbed = false;
      f.group.position.copy(f.home);
      if (f.name === 'Banana') f.group.position.y = f.restY;
      else f.group.position.y = f.restY;
    }
    refreshPanel();
  });

  return {
    root,
    update(time, delta) {
      if (delta === undefined) delta = 0.016;
      if (delta > 0.05) delta = 0.05;
      let anyHover = false;

      for (let i = 0; i < fruits.length; i++) {
        const f = fruits[i];
        const g = f.group;
        const grabbed = isGrabbed(g);

        if (grabbed) {
          if (f.inBasket) {
            f.inBasket = false;
            refreshPanel();
          }
          f.wasGrabbed = true;
          const dx = g.position.x - basketCenterX;
          const dz = g.position.z - basketCenterZ;
          const d2 = dx * dx + dz * dz;
          if (d2 < 0.0121 && g.position.y < 0.22 && g.position.y > 0.02) {
            anyHover = true;
          }
        } else {
          if (f.wasGrabbed) {
            f.wasGrabbed = false;
            const dx = g.position.x - basketCenterX;
            const dz = g.position.z - basketCenterZ;
            const dist = Math.sqrt(dx * dx + dz * dz);
            if (dist < 0.085 && g.position.y < 0.19 && g.position.y > 0.015) {
              f.inBasket = true;
              g.position.copy(f.slot);
              refreshPanel();
            }
          }
          if (f.inBasket) {
            g.position.x = f.slot.x;
            g.position.y = f.slot.y;
            g.position.z = f.slot.z;
          } else {
            // fall to table if dropped in air
            if (g.position.y > f.restY) {
              let ny = g.position.y - delta * 0.7;
              if (ny < f.restY) ny = f.restY;
              g.position.y = ny;
            } else if (g.position.y < f.restY - 0.005) {
              g.position.y = f.restY;
            }
            // keep on desk
            if (g.position.x < -0.38) g.position.x = -0.38;
            if (g.position.x > 0.38) g.position.x = 0.38;
            if (g.position.z < -0.22) g.position.z = -0.22;
            if (g.position.z > 0.24) g.position.z = 0.24;
            if (g.position.y < 0.005) g.position.y = f.restY;
            if (g.position.y > 0.48) g.position.y = 0.48;
          }
        }
      }

      // gentle idle spin for banana when in basket, highlight rim on hover
      if (anyHover) {
        rimMat.emissiveIntensity = 1.1;
      } else {
        rimMat.emissiveIntensity = 0.25 + Math.sin(time * 2.0) * 0.08 + 0.08;
      }
      // subtle basket handle sway for life (does not move grabbables)
      basketGroup.rotation.y = Math.sin(time * 0.4) * 0.02;
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------- materials (shared) ----------
  const metalMat = new THREE.MeshStandardMaterial({ color: 0x3a3f47, roughness: 0.45, metalness: 0.55 });
  const brassMat = new THREE.MeshStandardMaterial({ color: 0xc9a227, roughness: 0.3, metalness: 0.9 });
  const faceMat = new THREE.MeshStandardMaterial({ color: 0xf2ede2, roughness: 0.95, metalness: 0.0 });
  const darkMat = new THREE.MeshStandardMaterial({ color: 0x23262b, roughness: 0.6 });
  const handMat = new THREE.MeshStandardMaterial({ color: 0x1c1f24, roughness: 0.5, metalness: 0.3 });
  const secondMat = new THREE.MeshStandardMaterial({
    color: 0xd94a3d, roughness: 0.5, emissive: 0x6a150d, emissiveIntensity: 0.5,
  });

  // ---------- the clock (one grabbable group) ----------
  const clock = new THREE.Group();
  clock.name = 'DeskClock';
  root.add(clock);

  const CY = 0.13; // height of the dial centre above the desk

  const base = new THREE.Mesh(new THREE.CylinderGeometry(0.04, 0.05, 0.05, 32), metalMat);
  base.position.set(0, 0.025, -0.012);
  base.name = 'ClockStand';
  clock.add(base);

  const body = new THREE.Mesh(new THREE.CylinderGeometry(0.085, 0.085, 0.036, 48), metalMat);
  body.rotation.x = Math.PI / 2;
  body.position.set(0, CY, -0.018);
  body.name = 'ClockBody';
  clock.add(body);

  const face = new THREE.Mesh(new THREE.CircleGeometry(0.078, 48), faceMat);
  face.position.set(0, CY, 0.0016);
  face.name = 'ClockFace';
  clock.add(face);

  const rim = new THREE.Mesh(new THREE.TorusGeometry(0.0815, 0.0055, 12, 48), brassMat);
  rim.position.set(0, CY, 0.001);
  rim.name = 'ClockRim';
  clock.add(rim);

  // twelve hour ticks
  const tickGeo = new THREE.BoxGeometry(0.0045, 0.011, 0.002);
  const ticks = new THREE.InstancedMesh(tickGeo, darkMat, 12);
  ticks.name = 'ClockTicks';
  const dummy = new THREE.Object3D();
  for (let i = 0; i < 12; i++) {
    const a = (i * Math.PI) / 6;
    dummy.position.set(Math.sin(a) * 0.067, CY + Math.cos(a) * 0.067, 0.0035);
    dummy.rotation.set(0, 0, -a);
    const big = i % 3 === 0 ? 1.6 : 0.8;
    dummy.scale.set(1, big, 1);
    dummy.updateMatrix();
    ticks.setMatrixAt(i, dummy.matrix);
  }
  ticks.instanceMatrix.needsUpdate = true;
  clock.add(ticks);

  // hands: a pivot group rotated about Z, with the blade offset upward
  function makeHand(name, length, width, thick, mat, z, back) {
    const pivot = new THREE.Group();
    pivot.position.set(0, CY, z);
    pivot.name = name;
    const blade = new THREE.Mesh(new THREE.BoxGeometry(width, length, thick), mat);
    blade.position.y = length / 2 - back;
    blade.name = name + 'Blade';
    pivot.add(blade);
    clock.add(pivot);
    return pivot;
  }
  const hourHand = makeHand('HourHand', 0.04, 0.0075, 0.003, handMat, 0.006, 0.01);
  const minuteHand = makeHand('MinuteHand', 0.06, 0.0055, 0.003, handMat, 0.0085, 0.012);
  const secondHand = makeHand('SecondHand', 0.068, 0.0022, 0.002, secondMat, 0.011, 0.015);

  const cap = new THREE.Mesh(new THREE.CylinderGeometry(0.005, 0.005, 0.005, 16), brassMat);
  cap.rotation.x = Math.PI / 2;
  cap.position.set(0, CY, 0.0135);
  cap.name = 'ClockCap';
  clock.add(cap);

  // ---------- digital readout panel ----------
  const info = ui(`
    <style>
      .card { width: 440px; flex-direction: column; gap: 8px;
              padding-top: 18px; padding-bottom: 18px; padding-left: 22px; padding-right: 22px;
              border-radius: 20px; background-color: #1a1d22; }
      .title { color: #f0d38a; font-size: 24px; font-weight: 700; }
      .time { color: #ffffff; font-size: 56px; font-weight: 700; }
      .sub { color: #9aa3af; font-size: 20px; }
      .btn { margin-top: 6px; padding-top: 10px; padding-bottom: 10px;
             padding-left: 18px; padding-right: 18px; border-radius: 12px;
             background-color: #2f6fdb; align-items: center; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">DESK CLOCK</span>
      <span class="time" id="clock">--:--</span>
      <span class="sub" id="date">--</span>
      <span class="sub">Pinch the clock to move it.</span>
      <button class="btn" id="mode"><span class="btn-text" id="modeText">Switch to 12-hour</span></button>
    </div>`, { width: 0.3, position: [0.26, 0.14, 0], rotationY: -0.3 });
  root.add(info.object3D);

  // ---------- time keeping ----------
  const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

  let mode24 = true;
  let elapsed = 0;
  let acc = 1;
  let lastClock = '';
  let lastDate = '';

  function pad2(n) { return n < 10 ? '0' + n : '' + n; }

  function refresh() {
    let h, m, s, dateStr;
    let now = null;
    try { now = new Date(); } catch (e) { now = null; }

    if (now && typeof now.getHours === 'function' && !isNaN(now.getHours())) {
      h = now.getHours();
      m = now.getMinutes();
      s = now.getSeconds();
      dateStr = DAYS[now.getDay()] + ' ' + now.getDate() + ' ' + MONTHS[now.getMonth()] + ' ' + now.getFullYear();
    } else {
      // fallback: count up from 12:00 if the clock of the device is unavailable
      const total = Math.floor(elapsed);
      s = total % 60;
      m = Math.floor(total / 60) % 60;
      h = (12 + Math.floor(total / 3600)) % 24;
      dateStr = 'running time';
    }

    hourHand.rotation.z = -(((h % 12) + m / 60 + s / 3600) * Math.PI) / 6;
    minuteHand.rotation.z = -((m + s / 60) * Math.PI) / 30;
    secondHand.rotation.z = -(s * Math.PI) / 30;

    let text;
    if (mode24) {
      text = pad2(h) + ':' + pad2(m);
    } else {
      const h12 = h % 12 === 0 ? 12 : h % 12;
      text = h12 + ':' + pad2(m) + (h < 12 ? ' AM' : ' PM');
    }
    if (text !== lastClock) { lastClock = text; info.set('clock', { text: text }); }
    if (dateStr !== lastDate) { lastDate = dateStr; info.set('date', { text: dateStr }); }
  }

  info.on('mode', 'click', () => {
    mode24 = !mode24;
    info.set('modeText', { text: mode24 ? 'Switch to 12-hour' : 'Switch to 24-hour' });
    lastClock = '';
    refresh();
  });

  traits(clock, { grab: true });

  refresh();

  return {
    root,
    update(time, delta) {
      elapsed += delta;
      acc += delta;
      if (acc >= 0.2) {
        acc = 0;
        refresh();
      }
    },
  };
}

