  });
  const pool = new THREE.Mesh(new THREE.CircleGeometry(0.15, 32), poolMat);
  pool.name = 'LightPool';
  pool.rotation.x = -Math.PI / 2;
  pool.position.set(LX, 0.001, 0.11);
  pool.visible = false;
  root.add(pool);

  // ---- info panel ----
  const info = ui(`
    <style>
      .card { width: 460px; flex-direction: column; gap: 10px; padding-top: 18px; padding-bottom: 18px;
              padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 22px; }
      .row { flex-direction: row; align-items: center; gap: 10px; }
      .lbl { color: #9aa3b0; font-size: 22px; }
      .status { color: #8b93a1; font-size: 26px; font-weight: 700; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Desk Lamp</span>
      <span class="body">Pinch the round switch on the base, or press the shade, to turn the lamp on and off.</span>
      <div class="row">
        <span class="lbl">Lamp:</span>
        <span class="status" id="status">OFF</span>
      </div>
      <button class="btn" id="toggle"><span class="btn-text" id="toggleLabel">Switch on</span></button>
    </div>`, { width: 0.30, position: [0.25, 0.20, 0.02], rotationY: -0.3 });
  root.add(info.object3D);

  // ---- switching ----
  let on = false;

  function setOn(v) {
    on = v;
    bulbMat.emissiveIntensity = on ? 2.4 : 0;
    bulbMat.color.setHex(on ? 0xfff3d0 : 0x8d8778);
    shadeMat.emissiveIntensity = on ? 0.3 : 0;
    beam.visible = on;
    pool.visible = on;
    beamMat.opacity = on ? 0.085 : 0;
    poolMat.opacity = on ? 0.26 : 0;
    knob.position.y = on ? 0.0245 : 0.026;
    info.set('status', { text: on ? 'ON' : 'OFF', color: on ? '#ffd166' : '#8b93a1' });
    info.set('toggleLabel', { text: on ? 'Switch off' : 'Switch on' });
  }

  traits(knob, { onPress: () => setOn(!on) });
  traits(shade, { onPress: () => setOn(!on) });
  info.on('toggle', 'click', () => setOn(!on));

  return {
    root,
    update(time) {
      if (!on) return;
      const pulse = 1 + Math.sin(time * 2.2) * 0.06;
      beamMat.opacity = 0.085 * pulse;
      poolMat.opacity = 0.26 * pulse;
      bulbMat.emissiveIntensity = 2.4 * (1 + Math.sin(time * 2.2) * 0.03);
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
