    color: 0xfff3da, emissive: 0xffb347, emissiveIntensity: 0, roughness: 0.35,
  });
  const switchMat = new THREE.MeshStandardMaterial({
    color: 0x5a626d, emissive: 0xffb347, emissiveIntensity: 0.04, roughness: 0.4, metalness: 0.5,
  });
  const haloMat = new THREE.MeshBasicMaterial({
    color: 0xffb96a, transparent: true, opacity: 0,
    blending: THREE.AdditiveBlending, depthWrite: false,
  });
  const beamMat = new THREE.MeshBasicMaterial({
    color: 0xffcf8f, transparent: true, opacity: 0, side: THREE.DoubleSide,
    blending: THREE.AdditiveBlending, depthWrite: false,
  });

