  // ---------- warm pool of light on the desk ----------
  function buildPool(radius, rings, segs) {
    const positions = [];
    const colors = [];
    const indices = [];
    for (let r = 0; r <= rings; r++) {
      const t = r / rings;
      const rad = radius * t;
      const f = Math.pow(1 - t, 2.0);
      for (let s = 0; s <= segs; s++) {
        const a = (s / segs) * Math.PI * 2;
        positions.push(Math.cos(a) * rad, 0, Math.sin(a) * rad);
        colors.push(f, f * 0.82, f * 0.55);
      }
    }
    const rowLen = segs + 1;
    for (let r = 0; r < rings; r++) {
      for (let s = 0; s < segs; s++) {
        const a = r * rowLen + s;
        const b = a + 1;
        const c = a + rowLen;
        const d = c + 1;
        indices.push(a, b, c, b, d, c);
      }
    }
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
    g.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
    g.setIndex(indices);
    return g;
  }

  const poolMat = new THREE.MeshBasicMaterial({
    vertexColors: true, transparent: true, opacity: 0,
    blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide,
  });
  const pool = new THREE.Mesh(buildPool(0.21, 8, 48), poolMat);
