      <button class="btn" id="toggle"><span class="btn-text">Switch it on</span></button>
    </div>`, { width: 0.30, position: [0.22, 0.20, 0.03], rotationY: -0.36 });
  root.add(panel.object3D);

  // ---------- switching logic ----------
  let isOn = false;
  let target = 0;
  let glow = 0;

  function toggle() {
    isOn = !isOn;
    target = isOn ? 1 : 0;
    panel.set('state', {
      text: isOn ? 'Light is ON' : 'Light is OFF',
      color: isOn ? '#ffd08a' : '#8b93a1',
    });
    panel.set('toggle', { text: isOn ? 'Switch it off' : 'Switch it on' });
  }

  traits(base, { onPress: toggle });
  traits(shade, { onPress: toggle });
  traits(knob, { onPress: toggle });
  panel.on('toggle', 'click', toggle);

  // ---------- animation ----------
  return {
    root,
    update(time, delta) {
      const k = Math.min(1, delta * 7);
      glow += (target - glow) * k;
      const g = glow < 0.002 ? 0 : glow;

      bulbMat.emissiveIntensity = g * 3.5;
      switchMat.emissiveIntensity = 0.04 + g * 1.8;
      haloMat.opacity = 0.22 * g;
      halo.visible = g > 0.004;
      beamMat.opacity = 0.085 * g;
      beam.visible = g > 0.004;
      poolMat.opacity = g;
      pool.visible = g > 0.004;
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // Shared geometries and materials (reuse for performance)
  const oxygenGeo = new THREE.SphereGeometry(0.035, 28, 16);
  const hydrogenGeo = new THREE.SphereGeometry(0.025, 24, 14);
  const oxygenMat = new THREE.MeshStandardMaterial({ color: 0xe23a2e, roughness: 0.35, metalness: 0.05 });
  const hydrogenMat = new THREE.MeshStandardMaterial({ color: 0xeef2f5, roughness: 0.5, metalness: 0.0 });
  const bondGeo = new THREE.CylinderGeometry(0.008, 0.008, 1, 12);
  const bondMat = new THREE.MeshStandardMaterial({ color: 0xb8bec8, roughness: 0.4 });

  // Desk mat
  const mat = new THREE.Mesh(
    new THREE.BoxGeometry(0.55, 0.01, 0.32),
    new THREE.MeshStandardMaterial({ color: 0x2a2e35, roughness: 0.9 })
  );
  mat.position.set(0, 0.005, 0.03);
  mat.name = 'WorkMat';
  root.add(mat);

  // Parking rings to show start spots
  const ringGeo = new THREE.TorusGeometry(0.042, 0.003, 8, 32);
  const ringMat = new THREE.MeshBasicMaterial({ color: 0x555c66 });
  const ringPos = [[-0.18, 0.06], [-0.06, 0.07], [0.05, 0.07]];
  for (let i = 0; i < ringPos.length; i++) {
    const r = new THREE.Mesh(ringGeo, ringMat);
    r.rotation.x = Math.PI / 2;
    r.position.set(ringPos[i][0], 0.011, ringPos[i][1]);
    root.add(r);
  }

  const atoms = [];
  const STARTS = [
    { type: 'O', x: -0.18, y: 0.055, z: 0.06 },
    { type: 'H', x: -0.06, y: 0.045, z: 0.07 },
    { type: 'H', x: 0.05, y: 0.045, z: 0.07 }
  ];

  function makeAtomMesh(type) {
    const m = new THREE.Mesh(type === 'O' ? oxygenGeo : hydrogenGeo, type === 'O' ? oxygenMat : hydrogenMat);
    m.name = type === 'O' ? 'Oxygen' : 'Hydrogen';
    return m;
  }

  for (let i = 0; i < STARTS.length; i++) {
    const s = STARTS[i];
    const mesh = makeAtomMesh(s.type);
    mesh.position.set(s.x, s.y, s.z);
    root.add(mesh);
    traits(mesh, { grab: true });
    atoms.push({ mesh: mesh, type: s.type });
  }

  let spawnCounter = 0;
  let checkPulse = 0;

  // Bond pool (reused cylinders)
  const bonds = [];
  for (let i = 0; i < 12; i++) {
    const b = new THREE.Mesh(bondGeo, bondMat);
    b.visible = false;
    b.name = 'Bond';
    root.add(b);
    bonds.push(b);
  }

  // Success halo around the oxygen of a water molecule
  const halo = new THREE.Mesh(
    new THREE.TorusGeometry(0.058, 0.007, 10, 36),
    new THREE.MeshBasicMaterial({ color: 0x4ade80 })
  );
  halo.visible = false;
  halo.name = 'WaterHalo';
  root.add(halo);

  // 3D CHECK button (poke it) + base
  const btnBase = new THREE.Mesh(
    new THREE.CylinderGeometry(0.037, 0.037, 0.01, 24),
    new THREE.MeshStandardMaterial({ color: 0x1a1d22, roughness: 0.8 })
  );
  btnBase.position.set(0.2, 0.015, 0.06);
  btnBase.name = 'CheckBase';
  root.add(btnBase);

  const checkBtn = new THREE.Mesh(
    new THREE.CylinderGeometry(0.028, 0.028, 0.02, 24),
    new THREE.MeshStandardMaterial({ color: 0x2f9d5b, roughness: 0.4, emissive: 0x1a5c34, emissiveIntensity: 0.7 })
  );
  checkBtn.position.set(0.2, 0.03, 0.06);
  checkBtn.name = 'CheckButton';
  root.add(checkBtn);

  const main = ui(`
    <style>
      .card { width: 500px; display: flex; flex-direction: column; gap: 8px; padding-top: 16px; padding-bottom: 16px; padding-left: 20px; padding-right: 20px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; text-align: center; }
      .body { color: #d7dbe2; font-size: 22px; text-align: center; }
      .legend { color: #a8e6ff; font-size: 21px; text-align: center; }
      .status { color: #a8e6ff; font-size: 22px; text-align: center; }
      .result { color: #ffe08a; font-size: 23px; font-weight: 700; text-align: center; }
      .row { display: flex; flex-direction: row; gap: 8px; align-items: center; justify-content: center; }
      .check { padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px; border-radius: 12px; background-color: #2f9d5b; }
      .small { padding-top: 8px; padding-bottom: 8px; padding-left: 10px; padding-right: 10px; border-radius: 10px; background-color: #343a44; }
      .btn-text { color: #ffffff; font-size: 23px; font-weight: 700; }
      .btn-text2 { color: #ffffff; font-size: 20px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Build Water - H2O</span>
      <span class="body">Grab red Oxygen and white Hydrogen. Bring 2 H close to 1 O until gray sticks appear.</span>
      <span class="legend">Red = Oxygen (big) ... White = Hydrogen (small)</span>
      <span class="status" id="status">O-H bonds: 0 ... Bring H near O.</span>
      <span class="result" id="result">Press CHECK to test your molecule.</span>
      <button class="check" id="check"><span class="btn-text">CHECK - Is this water?</span></button>
      <div class="row">
        <button class="small" id="addH"><span class="btn-text2">+ Hydrogen</span></button>
        <button class="small" id="addO"><span class="btn-text2">+ Oxygen</span></button>
        <button class="small" id="reset"><span class="btn-text2">Reset</span></button>
      </div>
    </div>`, { width: 0.34, position: [0.0, 0.33, -0.15], rotationY: 0 });
  root.add(main.object3D);

  const tag = ui(`
    <style>
      .tag { width: 180px; display: flex; flex-direction: column; padding-top: 8px; padding-bottom: 8px; padding-left: 10px; padding-right: 10px; border-radius: 12px; background-color: #1d5c34; }
      .tagtext { color: #ffffff; font-size: 22px; font-weight: 700; text-align: center; }
    </style>
    <div class="tag">
      <span class="tagtext">CHECK - poke green</span>
    </div>`, { width: 0.15, position: [0.2, 0.10, -0.02], rotationY: 0 });
  root.add(tag.object3D);

  const BOND_OH = 0.095;
  const BOND_HH = 0.07;
  const BOND_OO = 0.08;

  function ohDist(a, b) {
    return a.mesh.position.distanceTo(b.mesh.position);
  }

  function doCheck() {
    checkPulse = 1;
    // Gather oxygen info
    let foundSuccess = false;
    let successAngle = 0;
    let successIdx = -1;
    let bestCount = -1;
    let bestIdx = -1;
    let bestAngle = 0;
    let totalOH = 0;

    for (let oi = 0; oi < atoms.length; oi++) {
      if (atoms[oi].type !== 'O') continue;
      const hList = [];
      for (let hi = 0; hi < atoms.length; hi++) {
        if (atoms[hi].type !== 'H') continue;
        const d = ohDist(atoms[oi], atoms[hi]);
        if (d < BOND_OH) {
          hList.push(hi);
          totalOH++;
        }
      }
      if (hList.length > bestCount) {
        bestCount = hList.length;
        bestIdx = oi;
        if (hList.length === 2) {
          const ox = atoms[oi].mesh.position;
          const a = atoms[hList[0]].mesh.position;
          const b = atoms[hList[1]].mesh.position;
          const v1x = a.x - ox.x, v1y = a.y - ox.y, v1z = a.z - ox.z;
          const v2x = b.x - ox.x, v2y = b.y - ox.y, v2z = b.z - ox.z;
          const l1 = Math.sqrt(v1x * v1x + v1y * v1y + v1z * v1z) || 0.0001;
          const l2 = Math.sqrt(v2x * v2x + v2y * v2y + v2z * v2z) || 0.0001;
          let dot = (v1x * v2x + v1y * v2y + v1z * v2z) / (l1 * l2);
          if (dot > 1) dot = 1;
          if (dot < -1) dot = -1;
          bestAngle = Math.acos(dot) * 180 / Math.PI;
        }
      }
      if (hList.length === 2) {
        const ox = atoms[oi].mesh.position;
        const a = atoms[hList[0]].mesh.position;
        const b = atoms[hList[1]].mesh.position;
        const v1x = a.x - ox.x, v1y = a.y - ox.y, v1z = a.z - ox.z;
        const v2x = b.x - ox.x, v2y = b.y - ox.y, v2z = b.z - ox.z;
        const l1 = Math.sqrt(v1x * v1x + v1y * v1y + v1z * v1z) || 0.0001;
        const l2 = Math.sqrt(v2x * v2x + v2y * v2y + v2z * v2z) || 0.0001;
        let dot = (v1x * v2x + v1y * v2y + v1z * v2z) / (l1 * l2);
        if (dot > 1) dot = 1;
        if (dot < -1) dot = -1;
        const ang = Math.acos(dot) * 180 / Math.PI;
        // purity: each H touches only this O, O touches no other O
        let pure = true;
        for (let k = 0; k < 2; k++) {
          let oCount = 0;
          for (let oj = 0; oj < atoms.length; oj++) {
            if (atoms[oj].type !== 'O') continue;
            if (atoms[hList[k]].mesh.position.distanceTo(atoms[oj].mesh.position) < BOND_OH) oCount++;
          }
          if (oCount !== 1) pure = false;
        }
        for (let oj = 0; oj < atoms.length; oj++) {
          if (oj === oi) continue;
          if (atoms[oj].type !== 'O') continue;
          if (atoms[oi].mesh.position.distanceTo(atoms[oj].mesh.position) < BOND_OO) pure = false;
        }
        const hh = a.distanceTo(b);
        if (hh < 0.035) pure = false;
        if (ang >= 75 && ang <= 135 && pure) {
          foundSuccess = true;
          successAngle = ang;
          successIdx = oi;
          break;
        } else if (bestIdx === oi) {
          bestAngle = ang;
        }
      }
    }

    if (foundSuccess) {
      const extra = atoms.length > 3 ? ' Plus extra atoms are on the table.' : '';
      main.set('result', { text: 'YES - That is water! 1 O + 2 H, angle about ' + Math.round(successAngle) + ' deg. Real water is 104.5 deg.' + extra, color: '#7dff9e' });
      halo.visible = true;
      if (successIdx >= 0) halo.position.copy(atoms[successIdx].mesh.position);
    } else if (bestCount === 2) {
      main.set('result', { text: 'Almost - that O has 2 H but angle is ' + Math.round(bestAngle) + ' deg. Spread the H apart to about 104 deg and keep them on one O.', color: '#ffb86b' });
      halo.visible = false;
    } else if (bestCount === 1) {
      main.set('result', { text: 'Not yet - that oxygen has only 1 H bonded. Bring a 2nd H close to the SAME oxygen.', color: '#ffe08a' });
      halo.visible = false;
    } else if (bestCount === 0) {
      // check for H2
      let hhBond = false;
      for (let i = 0; i < atoms.length; i++) {
        for (let j = i + 1; j < atoms.length; j++) {
          if (atoms[i].type === 'H' && atoms[j].type === 'H') {
            if (atoms[i].mesh.position.distanceTo(atoms[j].mesh.position) < BOND_HH) hhBond = true;
          }
        }
      }
      if (hhBond) main.set('result', { text: 'Not water - those two H stuck together make H2. Bring both H to the oxygen instead.', color: '#ffe08a' });
      else main.set('result', { text: 'Not yet - no O-H bonds. Push H atoms against the O until gray sticks show.', color: '#ffe08a' });
      halo.visible = false;
    } else if (bestCount > 2) {
      main.set('result', { text: 'Too many - that oxygen has ' + bestCount + ' H. Water needs exactly 2. Pull extras away.', color: '#ff9a9a' });
      halo.visible = false;
    } else {
      main.set('result', { text: 'Add atoms and bring H close to O, then CHECK again.', color: '#ffe08a' });
      halo.visible = false;
    }
  }

  function spawnAtom(type) {
    if (atoms.length >= 10) {
      main.set('result', { text: 'Table is full (10 atoms). Press Reset to start over.', color: '#ff9a9a' });
      return;
    }
    const mesh = makeAtomMesh(type);
    const col = spawnCounter % 4;
    const row = Math.floor(spawnCounter / 4) % 2;
    const sx = -0.20 + col * 0.09;
    const sz = 0.15 - row * 0.06;
    mesh.position.set(sx, type === 'O' ? 0.055 : 0.045, sz);
    root.add(mesh);
    traits(mesh, { grab: true });
    atoms.push({ mesh: mesh, type: type });
    spawnCounter++;
    main.set('result', { text: 'Added ' + (type === 'O' ? 'Oxygen.' : 'Hydrogen.') + ' Grab it and press CHECK when built.', color: '#ffe08a' });
  }

  function resetAll() {
    for (let i = atoms.length - 1; i >= 3; i--) {
      root.remove(atoms[i].mesh);
      atoms.pop();
    }
    for (let i = 0; i < 3; i++) {
      atoms[i].mesh.position.set(STARTS[i].x, STARTS[i].y, STARTS[i].z);
    }
    spawnCounter = 0;
    halo.visible = false;
    main.set('result', { text: 'Press CHECK to test your molecule.', color: '#ffe08a' });
    main.set('status', { text: 'O-H bonds: 0 ... Bring H near O.' });
  }

  main.on('check', 'click', doCheck);
  main.on('addH', 'click', () => spawnAtom('H'));
  main.on('addO', 'click', () => spawnAtom('O'));
  main.on('reset', 'click', resetAll);
  traits(checkBtn, { onPress: doCheck });

  const midV = new THREE.Vector3();
  const dirV = new THREE.Vector3();
  const upV = new THREE.Vector3(0, 1, 0);
  let lastLive = -10;
  let lastStatusText = '';

  function updateBondsLive() {
    let bondIdx = 0;
    for (let i = 0; i < atoms.length; i++) {
      for (let j = i + 1; j < atoms.length; j++) {
        const pi = atoms[i].mesh.position;
        const pj = atoms[j].mesh.position;
        const d = pi.distanceTo(pj);
        let thresh = BOND_OH;
        if (atoms[i].type === 'H' && atoms[j].type === 'H') thresh = BOND_HH;
        else if (atoms[i].type === 'O' && atoms[j].type === 'O') thresh = BOND_OO;
        if (d < thresh && bondIdx < bonds.length) {
          const b = bonds[bondIdx++];
          b.visible = true;
          midV.addVectors(pi, pj).multiplyScalar(0.5);
          b.position.copy(midV);
          dirV.subVectors(pj, pi);
          const len = dirV.length() || 0.0001;
          b.scale.set(1, len, 1);
          dirV.divideScalar(len);
          b.quaternion.setFromUnitVectors(upV, dirV);
        }
      }
    }
    for (let k = bondIdx; k < bonds.length; k++) bonds[k].visible = false;
    return bondIdx;
  }

  return {
    root,
    update(time, delta) {
      // press pulse for 3D button (never moves atoms, so held objects are safe)
      if (checkPulse > 0) {
        checkPulse -= delta * 3;
        if (checkPulse < 0) checkPulse = 0;
      }
      const s = 1 + checkPulse * 0.25;
      checkBtn.scale.set(s, 1 - checkPulse * 0.3, s);

      updateBondsLive();

      // throttled live status + halo (no allocation here)
      if (time - lastLive > 0.35) {
        lastLive = time;
        let oh = 0;
        let waterOi = -1;
        let waterAng = 0;
        for (let oi = 0; oi < atoms.length; oi++) {
          if (atoms[oi].type !== 'O') continue;
          let c = 0;
          let h1 = -1;
          let h2 = -1;
          for (let hi = 0; hi < atoms.length; hi++) {
            if (atoms[hi].type !== 'H') continue;
            if (atoms[oi].mesh.position.distanceTo(atoms[hi].mesh.position) < BOND_OH) {
              oh++;
              if (c === 0) h1 = hi;
              else if (c === 1) h2 = hi;
              c++;
            }
          }
          if (c === 2 && waterOi === -1) {
            const ox = atoms[oi].mesh.position;
            const a = atoms[h1].mesh.position;
            const b = atoms[h2].mesh.position;
            const v1x = a.x - ox.x, v1y = a.y - ox.y, v1z = a.z - ox.z;
            const v2x = b.x - ox.x, v2y = b.y - ox.y, v2z = b.z - ox.z;
            const l1 = Math.sqrt(v1x * v1x + v1y * v1y + v1z * v1z) || 0.0001;
            const l2 = Math.sqrt(v2x * v2x + v2y * v2y + v2z * v2z) || 0.0001;
            let dot = (v1x * v2x + v1y * v2y + v1z * v2z) / (l1 * l2);
            if (dot > 1) dot = 1;
            if (dot < -1) dot = -1;
            const ang = Math.acos(dot) * 180 / Math.PI;
            let pure = true;
            for (let k = 0; k < 2; k++) {
              const hk = k === 0 ? h1 : h2;
              let oc = 0;
              for (let oj = 0; oj < atoms.length; oj++) {
                if (atoms[oj].type !== 'O') continue;
                if (atoms[hk].mesh.position.distanceTo(atoms[oj].mesh.position) < BOND_OH) oc++;
              }
              if (oc !== 1) pure = false;
            }
            if (ang >= 75 && ang <= 135 && pure) {
              waterOi = oi;
              waterAng = ang;
            }
          }
        }
        let txt = '';
        if (oh === 0) txt = 'O-H bonds: 0 ... Bring H near O.';
        else if (oh === 1) txt = 'O-H bonds: 1 ... One more H to the same O.';
        else if (oh === 2) txt = 'O-H bonds: 2 ... Good count. Press CHECK.';
        else txt = 'O-H bonds: ' + oh + ' ... Water needs exactly 2 on one O.';
        if (txt !== lastStatusText) {
          lastStatusText = txt;
          main.set('status', { text: txt });
        }
        // live halo follows real water shape (button still gives the verdict)
        if (waterOi >= 0) {
          // do not steal halo if user is holding that oxygen (avoid visual fight is fine, just follow)
          if (!isGrabbed(atoms[waterOi].mesh)) halo.position.copy(atoms[waterOi].mesh.position);
          else halo.position.copy(atoms[waterOi].mesh.position);
          // only auto-show halo briefly; keep hidden until CHECK says yes? show it as hint
          // keep current visibility unless CHECK set it - if live water, ensure visible
          halo.visible = true;
        } else {
          // if no live water, hide halo unless user just pressed CHECK with success and still overlapping?
          // hide to give honest feedback
          if (halo.visible) {
            // check if last result was success - we hide anyway when shape breaks
            halo.visible = false;
          }
        }
      }

      if (halo.visible) {
        halo.rotation.z += delta * 1.4;
        const p = 1 + Math.sin(time * 4) * 0.06;
        halo.scale.set(p, p, p);
      }
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------------- data ----------------
  const cities = [
    {
      name: 'Phoenix', condition: 'Sunny', temp: '31', high: 34, low: 22,
      wind: 12, humidity: 18, icon: 'sun', tempColor: '#ffcf5c',
    },
    {
      name: 'Seattle', condition: 'Rain', temp: '12', high: 14, low: 8,
      wind: 19, humidity: 88, icon: 'rain', tempColor: '#7fc4ff',
    },
    {
      name: 'Denver', condition: 'Snow', temp: '-3', high: 1, low: -9,
      wind: 24, humidity: 76, icon: 'snow', tempColor: '#cfe6ff',
    },
  ];

  const xs = [-0.26, 0, 0.26];
  const rots = [0.2, 0, -0.2];

  // ---------------- shared geometry / materials ----------------
  const sphereGeo = new THREE.SphereGeometry(1, 20, 12);
  const rayGeo = new THREE.CylinderGeometry(0.0028, 0.0028, 0.016, 6);
  const dropGeo = new THREE.CylinderGeometry(0.0012, 0.0026, 0.013, 6);
  const flakeGeo = new THREE.SphereGeometry(0.0034, 10, 8);

  const sunMat = new THREE.MeshStandardMaterial({
    color: 0xffc23d, emissive: 0xff9a12, emissiveIntensity: 0.9, roughness: 0.45,
  });
  const cloudMat = new THREE.MeshStandardMaterial({ color: 0xd9e0ea, roughness: 0.95 });
  const dropMat = new THREE.MeshStandardMaterial({
    color: 0x6fb6ff, emissive: 0x1c4f8f, emissiveIntensity: 0.5, roughness: 0.4,
  });
  const flakeMat = new THREE.MeshStandardMaterial({
    color: 0xffffff, emissive: 0x8fb6d8, emissiveIntensity: 0.35, roughness: 0.6,
  });

  // ---------------- icon builders ----------------
  function makeSun() {
    const g = new THREE.Group();
    const core = new THREE.Mesh(sphereGeo, sunMat);
    core.scale.setScalar(0.026);
    core.name = 'SunCore';
    g.add(core);
    const rays = new THREE.Group();
    for (let i = 0; i < 8; i++) {
      const a = (i / 8) * Math.PI * 2;
      const m = new THREE.Mesh(rayGeo, sunMat);
      m.position.set(Math.cos(a) * 0.037, Math.sin(a) * 0.037, 0);
      m.rotation.z = a - Math.PI / 2;
      rays.add(m);
    }
    g.add(rays);
    return {
      group: g,
      update(t) { rays.rotation.z = t * 0.35; },
    };
  }

  function makeCloud() {
    const g = new THREE.Group();
    const puffs = [
      [-0.021, -0.004, 0.000, 0.017],
      [0.000, 0.010, 0.000, 0.024],
      [0.022, -0.002, 0.002, 0.015],
      [0.002, -0.008, 0.008, 0.014],
    ];
    for (let i = 0; i < puffs.length; i++) {
      const p = puffs[i];
      const m = new THREE.Mesh(sphereGeo, cloudMat);
      m.position.set(p[0], p[1], p[2]);
      m.scale.setScalar(p[3]);
      g.add(m);
    }
    return g;
  }

  function makeRain() {
    const g = new THREE.Group();
    const cloud = makeCloud();
    cloud.position.y = 0.008;
    g.add(cloud);
    const drops = [];
    const dx = [-0.019, -0.006, 0.008, 0.021];
    for (let i = 0; i < dx.length; i++) {
      const m = new THREE.Mesh(dropGeo, dropMat);
      m.position.set(dx[i], -0.012 - (i % 2) * 0.013, 0.004);
      g.add(m);
      drops.push({ mesh: m, speed: 0.038 + i * 0.005 });
    }
    return {
      group: g,
      update(t, dt) {
        for (let i = 0; i < drops.length; i++) {
          const d = drops[i];
          d.mesh.position.y -= d.speed * dt;
          if (d.mesh.position.y < -0.042) d.mesh.position.y = -0.012;
        }
      },
    };
  }

  function makeSnow() {
    const g = new THREE.Group();
    const cloud = makeCloud();
    cloud.position.y = 0.008;
    g.add(cloud);
    const flakes = [];
    const fx = [-0.020, -0.007, 0.006, 0.019];
    for (let i = 0; i < fx.length; i++) {
      const m = new THREE.Mesh(flakeGeo, flakeMat);
      m.position.set(fx[i], -0.012 - (i % 2) * 0.013, 0.004);
      g.add(m);
      flakes.push({ mesh: m, baseX: fx[i], phase: i * 1.7, speed: 0.011 + i * 0.002 });
    }
    return {
      group: g,
      update(t, dt) {
        for (let i = 0; i < flakes.length; i++) {
          const f = flakes[i];
          f.mesh.position.y -= f.speed * dt;
          if (f.mesh.position.y < -0.042) f.mesh.position.y = -0.012;
          f.mesh.position.x = f.baseX + Math.sin(t * 1.5 + f.phase) * 0.004;
        }
      },
    };
  }

  // ---------------- detail panel ----------------
  const info = ui(`
    <style>
      .info { width: 420px; height: 140px; flex-direction: column; justify-content: center;
              gap: 4px; padding-left: 20px; padding-right: 20px; border-radius: 18px;
              background-color: #22262d; }
      .ititle { color: #ffffff; font-size: 24px; font-weight: 700; }
      .iline { color: #c6cdd8; font-size: 19px; }
      .ihint { color: #7d8796; font-size: 17px; }
    </style>
    <div class="info">
      <span class="ititle" id="info-title">Phoenix - Sunny</span>
      <span class="iline" id="info-l1">High 34 C   Low 22 C</span>
      <span class="iline" id="info-l2">Wind 12 km/h   Humidity 18%</span>
      <span class="ihint">Press a city card to see its conditions.</span>
    </div>`, { width: 0.46, position: [0, 0.085, 0] });
  root.add(info.object3D);

  // ---------------- city cards ----------------
  const cardPanels = [];
  for (let i = 0; i < cities.length; i++) {
    const c = cities[i];
    const panel = ui(`
      <style>
        .card { width: 360px; height: 150px; flex-direction: column; align-items: center;
                justify-content: center; gap: 4px; border-radius: 20px;
                padding-top: 14px; padding-bottom: 14px;
                background-color: #1c2027; }
        .city { color: #ffffff; font-size: 24px; font-weight: 700; }
        .temp { color: ${c.tempColor}; font-size: 42px; font-weight: 700; }
        .cond { color: #9aa4b2; font-size: 21px; }
      </style>
      <div class="card" id="c${i}">
        <span class="city">${c.name}</span>
        <span class="temp">${c.temp}\u00b0</span>
        <span class="cond">${c.condition}</span>
      </div>`, { width: 0.22, position: [xs[i], 0.23, 0], rotationY: rots[i] });
    root.add(panel.object3D);
    traits(panel.object3D, { onPress: () => select(i) });
    cardPanels.push(panel);
  }

  // ---------------- icons above the cards ----------------
  const iconUpdaters = [];
  for (let i = 0; i < cities.length; i++) {
    const kind = cities[i].icon;
    const built = kind === 'sun' ? makeSun() : (kind === 'rain' ? makeRain() : makeSnow());
    built.group.position.set(xs[i], 0.34, 0);
    built.group.rotation.y = rots[i];
    root.add(built.group);
    traits(built.group, { onPress: () => select(i) });
    if (built.update) iconUpdaters.push(built.update);
  }

  // ---------------- selection ----------------
  function select(i) {
    const c = cities[i];
    info.set('info-title', { text: c.name + ' - ' + c.condition });
    info.set('info-l1', { text: 'High ' + c.high + '\u00b0C   Low ' + c.low + '\u00b0C' });
    info.set('info-l2', { text: 'Wind ' + c.wind + ' km/h   Humidity ' + c.humidity + '%' });
    for (let k = 0; k < cardPanels.length; k++) {
      cardPanels[k].set('c' + k, { backgroundColor: k === i ? '#2e4059' : '#1c2027' });
    }
  }
  select(0);

  // ---------------- frame loop ----------------
  return {
    root,
    update(time, delta) {
      const dt = delta > 0.1 ? 0.1 : delta;
      for (let i = 0; i < iconUpdaters.length; i++) {
        iconUpdaters[i](time, dt);
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const cities = [
    { name: 'Lisbon', cond: 'Sunny', kind: 'sun', tempC: 24, hi: 27, lo: 16, humidity: 45, wind: 14 },
    { name: 'Seattle', cond: 'Rain', kind: 'rain', tempC: 13, hi: 15, lo: 9, humidity: 88, wind: 22 },
    { name: 'Tokyo', cond: 'Partly cloudy', kind: 'partly', tempC: 18, hi: 21, lo: 12, humidity: 63, wind: 9 },
  ];

  const XS = [-0.22, 0, 0.22];
  const CARD_Y = 0.07;
  const ICON_Y = 0.20;

  let unit = 'C';
  let selected = 0;

  // ---------- shared geometry and materials ----------
  const sphereGeo = new THREE.SphereGeometry(1, 20, 12);
  const rayGeo = new THREE.BoxGeometry(0.006, 0.016, 0.006);
  const dropGeo = new THREE.ConeGeometry(0.005, 0.014, 6);
  const plinthGeo = new THREE.BoxGeometry(0.19, 0.014, 0.07);

  const sunMat = new THREE.MeshStandardMaterial({
    color: 0xffd257, emissive: 0xff9a12, emissiveIntensity: 0.9, roughness: 0.45,
  });
  const cloudMat = new THREE.MeshStandardMaterial({ color: 0xe6ecf6, roughness: 0.95 });
  const grayCloudMat = new THREE.MeshStandardMaterial({ color: 0x98a6bb, roughness: 0.95 });
  const dropMat = new THREE.MeshStandardMaterial({
    color: 0x63b8ff, emissive: 0x1b5f9e, emissiveIntensity: 0.5, roughness: 0.3,
  });

  function sunGroup(r, rayCount, rayLen) {
    const g = new THREE.Group();
    const core = new THREE.Mesh(sphereGeo, sunMat);
    core.name = 'SunCore';
    core.scale.setScalar(r);
    g.add(core);
    for (let i = 0; i < rayCount; i++) {
      const a = (i / rayCount) * Math.PI * 2;
      const ray = new THREE.Mesh(rayGeo, sunMat);
      ray.name = 'SunRay';
      ray.scale.set(1, rayLen, 1);
      ray.position.set(Math.cos(a) * r * 1.62, Math.sin(a) * r * 1.62, 0);
      ray.rotation.z = a;
      g.add(ray);
    }
    return g;
  }

  function makeCloud(mat) {
    const g = new THREE.Group();
    const puffs = [
      [-0.021, -0.003, 0.018],
      [-0.006, 0.006, 0.024],
      [0.014, 0.002, 0.020],
      [0.024, -0.004, 0.015],
      [-0.002, -0.011, 0.017],
    ];
    for (let i = 0; i < puffs.length; i++) {
      const m = new THREE.Mesh(sphereGeo, mat);
      m.name = 'CloudPuff';
      m.position.set(puffs[i][0], puffs[i][1], 0);
      m.scale.set(puffs[i][2], puffs[i][2] * 0.9, puffs[i][2] * 0.8);
      g.add(m);
    }
    return g;
  }

  // ---------- city cards (2D panels) ----------
  const cardHandles = [];

  function cardMarkup(i) {
    const c = cities[i];
    return `
      <style>
        .card { width: 220px; flex-direction: column; align-items: center; gap: 4px;
                padding-top: 12px; padding-bottom: 12px; padding-left: 10px; padding-right: 10px;
                border-radius: 16px; background-color: #1f2228; }
        .name { color: #cfd6e0; font-size: 20px; font-weight: 700; }
        .temp { color: #ffffff; font-size: 38px; font-weight: 700; }
        .cond { color: #9fb0c4; font-size: 18px; }
      </style>
      <div class="card" id="card${i}">
        <span class="name" id="name${i}">${c.name}</span>
        <span class="temp" id="temp${i}">${c.tempC}\u00b0C</span>
        <span class="cond" id="cond${i}">${c.cond}</span>
      </div>`;
  }

  for (let i = 0; i < cities.length; i++) {
    const h = ui(cardMarkup(i), { width: 0.18, position: [XS[i], CARD_Y, 0], rotationY: 0 });
    root.add(h.object3D);
    cardHandles.push(h);
  }

  // ---------- detail panel ----------
  const info = ui(`
    <style>
      .info { width: 500px; flex-direction: row; align-items: center; gap: 14px;
              padding-top: 16px; padding-bottom: 16px; padding-left: 18px; padding-right: 18px;
              border-radius: 18px; background-color: #1a1d22; }
      .left { flex-direction: column; gap: 6px; width: 330px; }
      .ititle { color: #ffffff; font-size: 28px; font-weight: 700; }
      .ibody { color: #cdd5df; font-size: 21px; }
      .ihint { color: #7f95ad; font-size: 18px; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btntext { color: #ffffff; font-size: 20px; font-weight: 700; }
    </style>
    <div class="info">
      <div class="left">
        <span class="ititle" id="ititle">Lisbon: Sunny</span>
        <span class="ibody" id="ibody">24\u00b0C, high 27\u00b0C, low 16\u00b0C. Humidity 45%, wind 14 km/h.</span>
        <span class="ihint">Press a city card or its weather icon.</span>
      </div>
      <button class="btn" id="unitbtn"><span class="btntext" id="unittext">Use \u00b0F</span></button>
    </div>`, { width: 0.44, position: [0, 0.36, -0.03], rotationY: 0 });
  root.add(info.object3D);

  // ---------- plinths + 3D weather icons ----------
  const plinthMats = [];
  const iconGroups = [];
  const iconSpinners = [];
  const iconCurrent = [1, 1, 1];
  const iconTarget = [1, 1, 1];
  const drops = [];

  for (let i = 0; i < cities.length; i++) {
    const c = cities[i];

    const pMat = new THREE.MeshStandardMaterial({ color: 0x30353d, roughness: 0.7, metalness: 0.15 });
    plinthMats.push(pMat);
    const plinth = new THREE.Mesh(plinthGeo, pMat);
    plinth.name = 'Plinth' + c.name;
    plinth.position.set(XS[i], 0.010, 0.02);
    root.add(plinth);
    traits(plinth, { onPress: () => selectCity(i) });

    const g = new THREE.Group();
    g.name = 'Icon' + c.name;
    g.position.set(XS[i], ICON_Y, 0);
    let spinner = null;

    if (c.kind === 'sun') {
      spinner = sunGroup(0.026, 8, 1.0);
      g.add(spinner);
    } else if (c.kind === 'rain') {
      const cloud = makeCloud(grayCloudMat);
      cloud.name = 'Cloud' + c.name;
      cloud.position.y = 0.008;
      g.add(cloud);
      for (let k = 0; k < 4; k++) {
        const d = new THREE.Mesh(dropGeo, dropMat);
        d.name = 'RainDrop';
        d.rotation.x = Math.PI;
        d.position.set(-0.018 + k * 0.012, -0.030, 0);
        g.add(d);
        drops.push({ mesh: d, base: -0.030, off: k * 0.0075 });
      }
    } else {
      spinner = sunGroup(0.019, 6, 0.7);
      spinner.position.set(-0.016, 0.014, -0.006);
      g.add(spinner);
      const cloud = makeCloud(cloudMat);
      cloud.name = 'Cloud' + c.name;
      cloud.position.set(0.006, -0.008, 0.004);
      cloud.scale.setScalar(0.85);
      g.add(cloud);
    }

    root.add(g);
    traits(g, { onPress: () => selectCity(i) });
    iconGroups.push(g);
    iconSpinners.push(spinner);
  }

  // ---------- behaviour ----------
  function fmt(v) {
    return unit === 'C' ? (v + '\u00b0C') : (Math.round(v * 9 / 5 + 32) + '\u00b0F');
  }

  function updateLabels() {
    for (let i = 0; i < cities.length; i++) {
      cardHandles[i].set('temp' + i, { text: fmt(cities[i].tempC) });
    }
    const c = cities[selected];
    info.set('ititle', { text: c.name + ': ' + c.cond });
    info.set('ibody', {
      text: fmt(c.tempC) + ', high ' + fmt(c.hi) + ', low ' + fmt(c.lo) +
        '. Humidity ' + c.humidity + '%, wind ' + c.wind + ' km/h.',
    });
    info.set('unittext', { text: unit === 'C' ? 'Use \u00b0F' : 'Use \u00b0C' });
  }

  function selectCity(i) {
    selected = i;
    for (let k = 0; k < cities.length; k++) {
      const sel = k === i;
      cardHandles[k].set('card' + k, { backgroundColor: sel ? '#2b3f5c' : '#1f2228' });
      cardHandles[k].set('temp' + k, { color: sel ? '#8ecbff' : '#ffffff' });
      plinthMats[k].emissive.setHex(sel ? 0x2f6fdb : 0x000000);
      plinthMats[k].emissiveIntensity = sel ? 0.6 : 0.0;
      iconTarget[k] = sel ? 1.14 : 1.0;
    }
    updateLabels();
  }

  info.on('unitbtn', 'click', () => {
    unit = unit === 'C' ? 'F' : 'C';
    updateLabels();
  });

  selectCity(0);

  // ---------- animation ----------
  return {
    root,
    update(time, delta) {
      const k = Math.min(1, delta * 8);

      for (let i = 0; i < iconGroups.length; i++) {
        iconCurrent[i] += (iconTarget[i] - iconCurrent[i]) * k;
        iconGroups[i].scale.setScalar(iconCurrent[i]);
        iconGroups[i].position.y = ICON_Y + Math.sin(time * 0.7 + i * 1.9) * 0.0025;
        const sp = iconSpinners[i];
        if (sp) sp.rotation.z = time * 0.35;
      }

      for (let i = 0; i < drops.length; i++) {
        const d = drops[i];
        d.mesh.position.y = d.base - ((time * 0.05 + d.off) % 0.026);
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();
  const V = (x, y, z) => new THREE.Vector3(x, y, z);

  // ---------------- materials ----------------
  const leafMat = new THREE.MeshStandardMaterial({ color: 0x4aa63e, roughness: 0.72, metalness: 0.0 });
  const stemMat = new THREE.MeshStandardMaterial({ color: 0x2f7a33, roughness: 0.8 });
  const potMat  = new THREE.MeshStandardMaterial({ color: 0xb5623c, roughness: 0.85 });
  const soilMat = new THREE.MeshStandardMaterial({ color: 0x35271e, roughness: 1.0 });

  // ---------------- small plant ----------------
  const plant = new THREE.Group();
  plant.name = 'Plant';
  plant.position.set(-0.06, 0, 0);
  root.add(plant);

  const pot = new THREE.Mesh(new THREE.CylinderGeometry(0.040, 0.030, 0.062, 24), potMat);
  pot.name = 'Pot';
  pot.position.y = 0.031;
  plant.add(pot);

  const soil = new THREE.Mesh(new THREE.CylinderGeometry(0.037, 0.037, 0.014, 24), soilMat);
  soil.name = 'Soil';
  soil.position.y = 0.062;
  plant.add(soil);

  const stem = new THREE.Mesh(new THREE.CylinderGeometry(0.005, 0.007, 0.17, 10), stemMat);
  stem.name = 'Stem';
  stem.position.y = 0.150;
  plant.add(stem);

  const leafGeo = new THREE.SphereGeometry(0.030, 18, 12);
  const leafDefs = [
    [-0.032, 0.115,  0.012,  0.35,  0.30, 1.00],
    [ 0.030, 0.140, -0.008, -0.45, -0.28, 1.00],
    [-0.036, 0.180, -0.014,  1.05,  0.38, 0.95],
    [ 0.034, 0.200,  0.010, -1.15, -0.35, 0.95],
    [ 0.000, 0.228,  0.000,  0.20,  0.05, 0.85],
  ];
  const leaves = [];
  for (let i = 0; i < leafDefs.length; i++) {
    const d = leafDefs[i];
    const leaf = new THREE.Mesh(leafGeo, leafMat);
    leaf.name = 'Leaf' + (i + 1);
    leaf.position.set(d[0], d[1], d[2]);
    leaf.rotation.set(0, d[3], d[4]);
    leaf.scale.set(d[5], d[5] * 0.28, d[5] * 0.52);
    plant.add(leaf);
    leaves.push(leaf);
  }

  // ---------------- sun ----------------
  const sunPos = V(-0.28, 0.34, -0.08);
  const sun = new THREE.Mesh(
    new THREE.SphereGeometry(0.05, 32, 20),
    new THREE.MeshStandardMaterial({ color: 0xffd24a, emissive: 0xffa000, emissiveIntensity: 1.0, roughness: 0.4 }),
  );
  sun.name = 'Sun';
  sun.position.copy(sunPos);
  root.add(sun);

  const glow = new THREE.Mesh(
    new THREE.SphereGeometry(0.068, 20, 14),
    new THREE.MeshBasicMaterial({ color: 0xffcc55, transparent: true, opacity: 0.16, depthWrite: false }),
  );
  glow.name = 'SunGlow';
  glow.position.copy(sunPos);
  root.add(glow);

  const dummy = new THREE.Object3D();
  const UP = V(0, 1, 0);

  const rayGeo = new THREE.ConeGeometry(0.007, 0.028, 6);
  const rayMat = new THREE.MeshBasicMaterial({ color: 0xffbb33 });
  const rays = new THREE.InstancedMesh(rayGeo, rayMat, 10);
  rays.name = 'SunRays';
  rays.position.copy(sunPos);
  const dirv = new THREE.Vector3();
  for (let i = 0; i < 10; i++) {
    const a = (i / 10) * Math.PI * 2;
    const b = Math.sin(i * 1.7) * 0.9;
    dirv.set(Math.cos(a) * Math.cos(b), Math.sin(b), Math.sin(a) * Math.cos(b)).normalize();
    dummy.position.copy(dirv).multiplyScalar(0.072);
    dummy.quaternion.setFromUnitVectors(UP, dirv);
    dummy.scale.set(1, 1, 1);
    dummy.updateMatrix();
    rays.setMatrixAt(i, dummy.matrix);
  }
  rays.instanceMatrix.needsUpdate = true;
  root.add(rays);
  dummy.quaternion.identity();
  dummy.position.set(0, 0, 0);

  // ---------------- labeled arrows ----------------
  function makeArrow(from, to, color, name) {
    const dir = new THREE.Vector3().subVectors(to, from);
    const len = dir.length();
    const headLen = Math.min(0.032, len * 0.34);
    const shaftLen = Math.max(0.002, len - headLen);
    const mat = new THREE.MeshStandardMaterial({
      color, emissive: color, emissiveIntensity: 0.5, roughness: 0.35, metalness: 0.0,
    });
    const g = new THREE.Group();
    g.name = name;
    const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.0055, 0.0055, shaftLen, 10), mat);
    shaft.position.y = shaftLen * 0.5;
    const head = new THREE.Mesh(new THREE.ConeGeometry(0.014, headLen, 12), mat);
    head.position.y = shaftLen + headLen * 0.5;
    g.add(shaft, head);
    g.position.copy(from);
    g.quaternion.setFromUnitVectors(UP, dir.normalize());
    return g;
  }

  // light: from the sun down into the leaves
  const lightTo = V(-0.10, 0.262, -0.012);
  const lightDir = new THREE.Vector3().subVectors(lightTo, sunPos).normalize();
  const lightFrom = new THREE.Vector3().copy(sunPos).addScaledVector(lightDir, 0.062);
  const lightArrow = makeArrow(lightFrom, lightTo, 0xffd24a, 'LightArrow');
  root.add(lightArrow);

  // water: up from the soil inside the stem
  const waterFrom = V(-0.06, 0.072, 0.028);
  const waterTo   = V(-0.06, 0.195, 0.028);
  const waterArrow = makeArrow(waterFrom, waterTo, 0x5fb4ff, 'WaterArrow');
  root.add(waterArrow);

  // carbon dioxide: in from the air into a leaf
  const co2From = V(0.128, 0.200, 0.012);
  const co2To   = V(0.014, 0.200, 0.012);
  const co2Arrow = makeArrow(co2From, co2To, 0xcfd8e3, 'CO2Arrow');
  root.add(co2Arrow);

  // oxygen: out of the leaf into the air
  const o2From = V(-0.030, 0.242, 0.006);
  const o2To   = V(0.062, 0.316, 0.016);
  const o2Arrow = makeArrow(o2From, o2To, 0x66f0a0, 'OxygenArrow');
  root.add(o2Arrow);

  // ---------------- flowing particles along the arrows ----------------
  const flows = [
    { from: lightFrom, to: lightTo, color: 0xffd24a, phase: 0.00 },
    { from: waterFrom, to: waterTo, color: 0x5fb4ff, phase: 0.21 },
    { from: co2From,   to: co2To,   color: 0xcfd8e3, phase: 0.42 },
    { from: o2From,    to: o2To,    color: 0x66f0a0, phase: 0.63 },
  ];
  for (let i = 0; i < flows.length; i++) {
    const f = flows[i];
    f.delta = new THREE.Vector3().subVectors(f.to, f.from);
    const d = f.delta.clone().normalize();
    const perp = V(-d.y, d.x, 0);
    if (perp.lengthSq() < 0.0001) perp.set(1, 0, 0);
    perp.normalize().multiplyScalar(0.018);
    f.offset = perp;
  }

  const pGeo = new THREE.SphereGeometry(0.0055, 8, 6);
  const pMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
  const particles = new THREE.InstancedMesh(pGeo, pMat, flows.length * 3);
  particles.name = 'FlowParticles';
  const tmpColor = new THREE.Color();
  for (let i = 0; i < flows.length; i++) {
    tmpColor.setHex(flows[i].color);
    for (let k = 0; k < 3; k++) particles.setColorAt(i * 3 + k, tmpColor);
  }
  if (particles.instanceColor) particles.instanceColor.needsUpdate = true;
  root.add(particles);

  // ---------------- floating labels ----------------
  function makeLabel(text, color, pos) {
    return ui(`
      <style>
        .lbl { width: 220px; flex-direction: row; align-items: center; justify-content: center;
               padding-top: 12px; padding-bottom: 12px; padding-left: 8px; padding-right: 8px;
               border-radius: 14px; background-color: #1b1f25;
               border-width: 3px; border-color: ${color}; }
        .txt { color: ${color}; font-size: 26px; font-weight: 700; }
      </style>
      <div class="lbl" id="lbl"><span class="txt">${text}</span></div>`,
      { width: 0.12, position: pos });
  }

  const lightLabel = makeLabel('Light', '#ffd24a', [-0.30, 0.245, -0.04]);
  root.add(lightLabel.object3D);
  const waterLabel = makeLabel('Water', '#5fb4ff', [-0.165, 0.135, 0.02]);
  root.add(waterLabel.object3D);
  const co2Label = makeLabel('CO2', '#cfd8e3', [0.055, 0.120, 0.02]);
  root.add(co2Label.object3D);
  const o2Label = makeLabel('Oxygen', '#66f0a0', [0.060, 0.350, 0.02]);
  root.add(o2Label.object3D);

  // ---------------- info panel ----------------
  const info = ui(`
    <style>
      .card { width: 420px; flex-direction: column; gap: 12px;
              padding-top: 20px; padding-bottom: 20px; padding-left: 22px; padding-right: 22px;
              border-radius: 20px; background-color: #1a1d22; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .eq { color: #9fe870; font-size: 22px; }
      .body { color: #d7dbe2; font-size: 25px; }
    </style>
    <div class="card">
      <span class="title">Photosynthesis</span>
      <span class="eq">6 CO2 + 6 H2O + light</span>
      <span class="eq">-> C6H12O6 + 6 O2</span>
      <span class="body" id="info">Press a labeled arrow or the Sun to see what goes in and what comes out.</span>
    </div>`, { width: 0.24, position: [0.28, 0.22, -0.07], rotationY: -0.3 });
  root.add(info.object3D);

  const TEXT = {
    light: 'Sunlight is absorbed by chlorophyll in the leaves. That light energy drives the whole reaction.',
    water: 'Roots take up water (H2O) from the soil, and it travels up the stem to the leaves.',
    co2: 'Carbon dioxide (CO2) enters the leaves from the air through tiny pores called stomata.',
    o2: 'Oxygen (O2) is released as a by-product and flows out of the leaf through the stomata.',
  };
  const show = (key) => info.set('info', { text: TEXT[key] });

  // ---------------- interaction ----------------
  traits(sun, { onPress: () => show('light') });
  traits(lightArrow, { onPress: () => show('light') });
  traits(waterArrow, { onPress: () => show('water') });
  traits(co2Arrow, { onPress: () => show('co2') });
  traits(o2Arrow, { onPress: () => show('o2') });

  lightLabel.on('lbl', 'click', () => show('light'));
  waterLabel.on('lbl', 'click', () => show('water'));
  co2Label.on('lbl', 'click', () => show('co2'));
  o2Label.on('lbl', 'click', () => show('o2'));

  // ---------------- animate ----------------
  return {
    root,
    update(time) {
      glow.scale.setScalar(1 + Math.sin(time * 1.6) * 0.06);
      rays.rotation.y = time * 0.25;

      for (let i = 0; i < flows.length; i++) {
        const f = flows[i];
        for (let k = 0; k < 3; k++) {
          const t = (time * 0.30 + f.phase + k * 0.3333) % 1;
          dummy.position.copy(f.from).addScaledVector(f.delta, t).add(f.offset);
          dummy.updateMatrix();
          particles.setMatrixAt(i * 3 + k, dummy.matrix);
        }
      }
      particles.instanceMatrix.needsUpdate = true;
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
