  ];
  const ceramic = new THREE.MeshStandardMaterial({
    color: 0xe9e3d6,
    roughness: 0.34,
    metalness: 0.0,
    side: THREE.DoubleSide,
  });

  const body = new THREE.Mesh(new THREE.LatheGeometry(profile, 48), ceramic);
