  );
  coffee.name = 'Coffee';
  coffee.position.set(0, 0.074, 0);
  mug.add(coffee);

  // wisps of steam, children of the mug so they travel with it
  const steam = [];
  const steamGeo = new THREE.SphereGeometry(0.006, 12, 8);
  for (let i = 0; i < 3; i++) {
    const mat = new THREE.MeshBasicMaterial({
      color: 0xffffff,
      transparent: true,
      opacity: 0.18,
      depthWrite: false,
    });
    const mesh = new THREE.Mesh(steamGeo, mat);
    mesh.name = 'Steam' + i;
    mesh.position.set((i - 1) * 0.008, 0.1, 0);
    mug.add(mesh);
    steam.push({ mesh, mat, baseX: (i - 1) * 0.008, baseZ: (i % 2 === 0 ? -1 : 1) * 0.004, offset: i / 3 });
  }

  traits(mug, { grab: true });

  // ---------------------------------------------------------------- the card
  const info = ui(`
    <style>
      .card { width: 480px; flex-direction: column; gap: 12px;
              padding-top: 20px; padding-bottom: 20px; padding-left: 24px; padding-right: 24px;
              border-radius: 18px; background-color: #22262c; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .row { flex-direction: row; justify-content: space-between; align-items: center; }
      .label { color: #9aa4b2; font-size: 22px; }
      .value { color: #f2e9d8; font-size: 22px; font-weight: 700; }
      .detail { color: #d7dbe2; font-size: 22px; }
      .status { color: #8fbf8f; font-size: 20px; }
      .btn { padding-top: 12px; padding-bottom: 12px; padding-left: 18px; padding-right: 18px;
             border-radius: 12px; background-color: #c8763d; align-items: center; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Stoneware Mug</span>
      <div class="row">
        <span class="label">Price</span>
        <span class="value">$18.00</span>
      </div>
      <div class="row">
        <span class="label">Material</span>
        <span class="value">Glazed stoneware</span>
      </div>
      <span class="detail" id="detail">Holds 350 ml. A ceramic glaze seals the clay so it holds liquid and does not stain.</span>
      <span class="status" id="status">Status: on the desk</span>
      <button class="btn" id="next"><span class="btn-text">More details</span></button>
    </div>`, { width: 0.32, position: [0.21, 0.15, 0.0], rotationY: -0.28 });
  root.add(info.object3D);

  const details = [
    'Holds 350 ml. A ceramic glaze seals the clay so it holds liquid and does not stain.',
    'Fired at about 1200 C, which fuses the clay into a hard, non-porous stoneware.',
    'Made in Portugal. Dishwasher and microwave safe; the handle is formed by hand.',
    'Weight 340 g empty. The thick wall keeps your coffee warm for longer.',
  ];
  let detailIndex = 0;
  info.on('next', 'click', () => {
    detailIndex = (detailIndex + 1) % details.length;
    info.set('detail', { text: details[detailIndex] });
  });

  // ---------------------------------------------------------------- animation
  let wasGrabbed = false;

  return {
    root,
    update(time) {
      for (let i = 0; i < steam.length; i++) {
        const s = steam[i];
        const phase = (time * 0.22 + s.offset) % 1;
        s.mesh.position.y = 0.096 + phase * 0.105;
        s.mesh.position.x = s.baseX + Math.sin(time * 1.6 + i * 2.1) * 0.005 * phase;
        s.mesh.position.z = s.baseZ + Math.cos(time * 1.3 + i * 1.7) * 0.004 * phase;
        const sc = 0.7 + phase * 1.4;
        s.mesh.scale.set(sc, sc, sc);
        s.mat.opacity = 0.22 * Math.sin(Math.PI * phase);
      }

      const g = isGrabbed(mug);
      if (g !== wasGrabbed) {
        wasGrabbed = g;
        info.set('status', { text: g ? 'Status: in your hand - nice grip' : 'Status: on the desk' });
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------------- info panel (right side) ----------------
  const panel = ui(`
    <style>
      .card { width: 480px; flex-direction: column; gap: 12px; padding-top: 18px; padding-bottom: 18px;
              padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 22px; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 18px; padding-right: 18px;
             border-radius: 12px; background-color: #2f8f4e; align-items: center; justify-content: center; }
      .bt { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card" id="card">
      <span class="title" id="hdr">Photosynthesis</span>
      <span class="body" id="fact">Touch a labelled arrow or a leaf to explore how photosynthesis works.</span>
      <button class="btn" id="eq"><span class="bt" id="eqtext">Show equation</span></button>
    </div>`, { width: 0.30, position: [0.25, 0.16, 0.02], rotationY: -0.35 });
  root.add(panel.object3D);

  let curTitle = 'Photosynthesis';
  let curBody = 'Touch a labelled arrow or a leaf to explore how photosynthesis works.';
  let showingEq = false;

  function setFact(t, b) {
    curTitle = t;
    curBody = b;
    showingEq = false;
    panel.set('hdr', { text: t });
    panel.set('fact', { text: b });
    panel.set('eqtext', { text: 'Show equation' });
  }

  panel.on('eq', 'click', () => {
    if (showingEq) {
      setFact(curTitle, curBody);
      return;
    }
    showingEq = true;
    panel.set('hdr', { text: 'Equation' });
    panel.set('fact', { text: '6 CO2 + 6 H2O + light -> C6H12O6 + 6 O2. Sugar is stored, oxygen leaves the leaf.' });
    panel.set('eqtext', { text: 'Back' });
  });

  // ---------------- labelled chips on the arrows ----------------
  function makeChip(text, bg, pos, rotY, title, body) {
    const h = ui(`
      <style>
        .chip { width: 160px; align-items: center; justify-content: center; padding-top: 8px; padding-bottom: 8px;
                padding-left: 10px; padding-right: 10px; border-radius: 12px; background-color: ${bg}; }
        .ct { color: #1a1d22; font-size: 26px; font-weight: 700; }
      </style>
      <div class="chip" id="chip"><span class="ct">${text}</span></div>`,
      { width: 0.085, position: pos, rotationY: rotY });
    root.add(h.object3D);
    h.on('chip', 'click', () => setFact(title, body));
    return h;
  }

  makeChip('Light', '#ffd34d', [-0.29, 0.315, 0.0], 0.30, 'Light',
    'Chlorophyll, the green pigment in leaves, absorbs light. That energy drives the reaction.');
  makeChip('CO2', '#cfd6de', [-0.225, 0.245, 0.0], 0.25, 'Carbon dioxide',
    'CO2 enters the leaf through tiny pores called stomata, mostly on the underside.');
  makeChip('Water', '#4aa3ff', [-0.29, 0.085, 0.06], 0.30, 'Water',
    'Roots take up water from the soil and the stem carries it up to the leaves.');
  makeChip('O2', '#ff6b8a', [0.20, 0.375, 0.02], -0.30, 'Oxygen',
    'Oxygen is a by-product. The leaf releases it into the air through the stomata.');

  // ---------------- the Sun ----------------
  const sunMat = new THREE.MeshStandardMaterial({
    color: 0xffd34d, emissive: 0xffa726, emissiveIntensity: 1.1, roughness: 0.4,
  });
  const sun = new THREE.Mesh(new THREE.SphereGeometry(0.05, 32, 16), sunMat);
  sun.name = 'Sun';
  sun.position.set(-0.28, 0.40, -0.10);
  root.add(sun);

  const glow = new THREE.Mesh(
    new THREE.SphereGeometry(0.066, 24, 12),
    new THREE.MeshBasicMaterial({ color: 0xffc23d, transparent: true, opacity: 0.13, depthWrite: false }),
  );
  glow.position.copy(sun.position);
  root.add(glow);

  // ---------------- the plant ----------------
  const pot = new THREE.Mesh(
    new THREE.CylinderGeometry(0.05, 0.036, 0.07, 24),
    new THREE.MeshStandardMaterial({ color: 0xb5652f, roughness: 0.85 }),
  );
  pot.name = 'Pot';
  pot.position.set(-0.05, 0.035, 0);
  root.add(pot);

  const soil = new THREE.Mesh(
    new THREE.CylinderGeometry(0.047, 0.047, 0.012, 24),
    new THREE.MeshStandardMaterial({ color: 0x3a2a1e, roughness: 1 }),
  );
  soil.name = 'Soil';
  soil.position.set(-0.05, 0.068, 0);
  root.add(soil);

  const stem = new THREE.Mesh(
    new THREE.CylinderGeometry(0.008, 0.010, 0.21, 12),
    new THREE.MeshStandardMaterial({ color: 0x2f7a38, roughness: 0.7 }),
  );
  stem.name = 'Stem';
  stem.position.set(-0.05, 0.17, 0);
  root.add(stem);

  function showLeaf() {
    setFact('Leaf', "Leaves are the plant's solar panels: their cells are packed with chloroplasts.");
  }

  const leafGeo = new THREE.SphereGeometry(1, 18, 10);
  const leafMat = new THREE.MeshStandardMaterial({ color: 0x3f9a45, roughness: 0.55 });
  const leafDefs = [
    { p: [-0.105, 0.155, 0.02], rz: 0.30, ry: 0.35 },
    { p: [0.0, 0.20, -0.01], rz: -0.35, ry: -0.40 },
    { p: [-0.10, 0.245, -0.02], rz: 0.35, ry: 0.70 },
    { p: [-0.005, 0.265, 0.015], rz: -0.28, ry: -0.50 },
  ];
  for (let i = 0; i < leafDefs.length; i++) {
    const d = leafDefs[i];
    const leaf = new THREE.Mesh(leafGeo, leafMat);
    leaf.name = 'Leaf' + (i + 1);
    leaf.scale.set(0.045, 0.009, 0.028);
    leaf.position.set(d.p[0], d.p[1], d.p[2]);
    leaf.rotation.set(0, d.ry, d.rz);
    root.add(leaf);
    traits(leaf, { onPress: showLeaf });
  }

  // ---------------- arrows ----------------
  const upY = new THREE.Vector3(0, 1, 0);
  function makeArrow(from, to, color, name) {
    const dir = new THREE.Vector3().subVectors(to, from);
    const len = dir.length();
    const headL = 0.030;
    const shaftLen = Math.max(len - headL, 0.005);
    const mat = new THREE.MeshStandardMaterial({
      color, emissive: color, emissiveIntensity: 0.30, roughness: 0.45,
    });
    const g = new THREE.Group();
    g.name = name;
    const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.0055, 0.0055, shaftLen, 12), mat);
    shaft.position.y = shaftLen / 2;
    g.add(shaft);
    const head = new THREE.Mesh(new THREE.ConeGeometry(0.014, headL, 16), mat);
    head.position.y = shaftLen + headL / 2;
    g.add(head);
    g.position.copy(from);
    g.quaternion.setFromUnitVectors(upY, dir.normalize());
    root.add(g);
    return g;
  }

  const lightA = new THREE.Vector3(-0.235, 0.355, -0.045);
  const lightB = new THREE.Vector3(-0.12, 0.285, 0.0);
  makeArrow(lightA, lightB, 0xffd34d, 'LightArrow');
  makeArrow(new THREE.Vector3(-0.275, 0.205, 0.0), new THREE.Vector3(-0.14, 0.205, 0.0), 0xcfd6de, 'CO2Arrow');
  makeArrow(new THREE.Vector3(-0.275, 0.045, 0.06), new THREE.Vector3(-0.115, 0.045, 0.03), 0x4aa3ff, 'WaterArrow');
  makeArrow(new THREE.Vector3(0.03, 0.26, 0.01), new THREE.Vector3(0.16, 0.32, 0.03), 0xff6b8a, 'O2Arrow');

  // ---------------- photons travelling down the light arrow ----------------
  const dotGeo = new THREE.SphereGeometry(0.0075, 10, 8);
  const dotMat = new THREE.MeshBasicMaterial({ color: 0xfff2a8 });
  const dots = [];
  for (let i = 0; i < 3; i++) {
    const d = new THREE.Mesh(dotGeo, dotMat);
    d.name = 'Photon' + i;
    root.add(d);
    dots.push(d);
  }
  const tmp = new THREE.Vector3();

  return {
    root,
    update(time) {
      const pulse = Math.sin(time * 2.0);
      sun.scale.setScalar(1 + pulse * 0.03);
      glow.scale.setScalar(1 + pulse * 0.07);
      sunMat.emissiveIntensity = 1.05 + pulse * 0.18;

      for (let i = 0; i < dots.length; i++) {
        const t = (time * 0.28 + i / dots.length) % 1;
        tmp.lerpVectors(lightA, lightB, t);
        dots[i].position.set(tmp.x, tmp.y + 0.014, tmp.z + 0.012);
        dots[i].scale.setScalar(0.65 + 0.55 * Math.sin(t * Math.PI));
      }
    },
  };
}

