  for (let k = 0; k < 3; k++) {
    const mat = new THREE.MeshBasicMaterial({
      color: 0xffffff, transparent: true, opacity: 0.16, depthWrite: false,
    });
    const puff = new THREE.Mesh(steamGeo, mat);
    puff.name = 'Steam' + k;
    puff.userData.phase = k / 3;
    puff.position.set((k - 1) * 0.013, H + 0.008, 0);
    mug.add(puff);
    steam.push(puff);
  }

  // ---------------- info card ----------------
  const details = [
    'Capacity: 350 ml (12 oz)',
    'Dishwasher and microwave safe',
    'Fired at 1200 °C - chip resistant',
    'Made in Portugal, hand-glazed',
    'Weight: 380 g - feels solid in the hand',
