  let index = 0;

  const info = ui(`
    <style>
      .card { width: 480px; flex-direction: column; gap: 10px;
              padding-top: 18px; padding-bottom: 18px; padding-left: 22px; padding-right: 22px;
              border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .price { color: #7fd8a4; font-size: 28px; font-weight: 700; }
      .label { color: #8b93a1; font-size: 20px; }
      .body { color: #d7dbe2; font-size: 22px; }
      .hint { color: #8b93a1; font-size: 20px; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px;
             border-radius: 12px; background-color: #2f6fdb; align-items: center; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Ceramic Mug</span>
      <span class="price">$14.00</span>
      <span class="label">Material</span>
      <span class="body" id="material">Stoneware with a matte glaze</span>
      <span class="label">Detail</span>
      <span class="body" id="detail">Capacity: 350 ml (12 oz)</span>
      <button class="btn" id="next"><span class="btn-text">Next detail</span></button>
      <span class="hint">Pinch the mug to pick it up</span>
    </div>`, { width: 0.32, position: [0.22, 0.15, 0], rotationY: -0.32 });
  root.add(info.object3D);

  info.on('next', 'click', () => {
    index = (index + 1) % details.length;
    info.set('detail', { text: details[index] });
  });

  // ---------------- hand interaction ----------------
  traits(mug, {
    grab: true,
    onPress: () => {
      index = (index + 1) % details.length;
      info.set('detail', { text: details[index] });
    },
  });

  // ---------------- animation ----------------
  return {
    root,
    update(time) {
      for (let k = 0; k < steam.length; k++) {
        const p = steam[k];
        const t = (time * 0.16 + p.userData.phase) % 1;
        p.position.y = H + 0.006 + t * 0.055;
        p.scale.setScalar(0.65 + t * 1.1);
        p.material.opacity = 0.22 * (1 - t) * Math.min(1, t * 5);
      }
    },
  };
}

