      inner: 0, outer: 0.018,
      info: 'Inner core: a solid iron-nickel ball with a radius of 1,220 km, about 5,400 °C. Pressure keeps it solid.',
    },
  ];

  for (const d of defs) {
    d.mat = new THREE.MeshStandardMaterial({
