  model.add(shell);

  // the two flat cut faces (half discs of concentric bands)
  const capLeft = new THREE.Group();   // cut plane facing right-front
  capLeft.rotation.y = -Math.PI * 0.75;
  const capRight = new THREE.Group();  // cut plane facing left-front
  capRight.rotation.y = -Math.PI * 0.25;
  model.add(capLeft, capRight);

  for (let i = 0; i < defs.length; i++) {
    const d = defs[i];
    const geo = d.inner > 0.0005
      ? new THREE.RingGeometry(d.inner, d.outer, 40, 1, -Math.PI / 2, Math.PI)
      : new THREE.CircleGeometry(d.outer, 24, -Math.PI / 2, Math.PI);
    const a = new THREE.Mesh(geo, d.mat);
    const b = new THREE.Mesh(geo, d.mat);
    a.name = d.name + '_SectionA';
    b.name = d.name + '_SectionB';
    capLeft.add(a);
    capRight.add(b);
  }

  // ---------------------------------------------------------------- panel
  const panel = ui(`
    <style>
      .panel { width: 540px; flex-direction: column; gap: 9px; padding-top: 18px; padding-bottom: 18px;
               padding-left: 22px; padding-right: 22px; border-radius: 20px; background-color: #17191e; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .sub { color: #8b95a4; font-size: 20px; }
      .row { flex-direction: row; align-items: center; gap: 14px; padding-top: 9px; padding-bottom: 9px;
             padding-left: 12px; padding-right: 12px; border-radius: 12px; background-color: #24282f; }
      .chip { width: 22px; height: 22px; border-radius: 6px; }
      .c-crust { background-color: #4c7a3f; }
      .c-mantle { background-color: #c2601e; }
      .c-outer { background-color: #ff8f1f; }
      .c-inner { background-color: #ffe08a; }
      .name { color: #ffffff; font-size: 24px; font-weight: 600; width: 168px; }
      .depth { color: #a7b1bf; font-size: 20px; }
      .info { color: #d6dbe3; font-size: 22px; }
      .note { color: #828c9a; font-size: 20px; }
    </style>
    <div class="panel">
      <span class="title">Earth's layers</span>
      <span class="sub">Press a layer to highlight it on the model.</span>
      <button class="row" id="row-crust">
        <div class="chip c-crust"></div>
        <span class="name">Crust</span>
        <span class="depth">0 - 35 km</span>
      </button>
      <button class="row" id="row-mantle">
        <div class="chip c-mantle"></div>
        <span class="name">Mantle</span>
        <span class="depth">35 - 2,890 km</span>
      </button>
      <button class="row" id="row-outer">
        <div class="chip c-outer"></div>
        <span class="name">Outer core</span>
        <span class="depth">2,890 - 5,150 km</span>
      </button>
      <button class="row" id="row-inner">
        <div class="chip c-inner"></div>
        <span class="name">Inner core</span>
        <span class="depth">5,150 - 6,371 km</span>
      </button>
      <span class="info" id="info">Earth is 6,371 km from the surface to the center. Pick a layer to read about it.</span>
      <span class="note">Layer thicknesses are exaggerated so every layer is visible.</span>
    </div>`, { width: 0.36, position: [0.18, 0.185, 0.03], rotationY: -0.2 });
  root.add(panel.object3D);

  const rowIds = ['row-crust', 'row-mantle', 'row-outer', 'row-inner'];
  let selected = -1;

  function select(i) {
    selected = i;
    for (let k = 0; k < defs.length; k++) {
      panel.set(rowIds[k], { backgroundColor: k === i ? '#3d4d69' : '#24282f' });
    }
    panel.set('info', { text: defs[i].info });
  }

  for (let i = 0; i < defs.length; i++) {
    panel.on(rowIds[i], 'click', () => select(i));
  }

  // grab the model to turn it; pressing it steps through the layers
  traits(model, { grab: true, onPress: () => select((selected + 1) % defs.length) });

  // ---------------------------------------------------------------- loop
  let wasGrabbed = false;

  return {
    root,
    update(time, delta) {
      if (isGrabbed(model)) wasGrabbed = true;
      if (!wasGrabbed) model.rotation.y = Math.sin(time * 0.33) * 0.30;

      const k = Math.min(1, delta * 6);
      for (let i = 0; i < defs.length; i++) {
        const m = defs[i].mat;
        const target = defs[i].baseEmissive + (i === selected ? 0.5 : 0);
        m.emissiveIntensity += (target - m.emissiveIntensity) * k;
      }
    },
  };
}

