      .sw1 { background-color: #f59322; }
      .sw2 { background-color: #c03a24; }
      .sw3 { background-color: #8a5230; }
      .sw4 { background-color: #4f8a3d; }
      .rn { color: #e8edf5; font-size: 24px; font-weight: 600; }
      .fact { color: #cfd8e6; font-size: 22px; }
    </style>
    <div class="card">
      <span class="title">Inside the Earth</span>
      <button class="row" id="row0"><div class="sw sw0"></div><span class="rn">Inner core</span></button>
      <button class="row" id="row1"><div class="sw sw1"></div><span class="rn">Outer core</span></button>
      <button class="row" id="row2"><div class="sw sw2"></div><span class="rn">Lower mantle</span></button>
      <button class="row" id="row3"><div class="sw sw3"></div><span class="rn">Upper mantle</span></button>
      <button class="row" id="row4"><div class="sw sw4"></div><span class="rn">Crust</span></button>
      <span class="fact" id="fact">Earth's radius is 6,371 km. Press a layer to learn about it, or grab the model and turn it.</span>
    </div>`, { width: 0.28, position: [0.20, 0.145, 0], rotationY: -0.32 });

  root.add(info.object3D);

  let selected = -1;

  for (let i = 0; i < layers.length; i++) {
    ((idx) => {
      info.on('row' + idx, 'click', () => {
        selected = idx;
        info.set('fact', { text: layers[idx].fact });
