      });
    })(i);
  }

  return {
    root,
    update(time) {
      for (let i = 0; i < layers.length; i++) {
        const m = layers[i].mat;
        m.emissiveIntensity = (i === selected)
          ? 0.55 + 0.20 * Math.sin(time * 4)
          : (i === 0 ? 0.16 : 0.10);
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // --- Five progress tokens on the desk: one per question ------------------
  const tokenGeo = new THREE.BoxGeometry(0.045, 0.045, 0.045);
  const tokens = [];
  for (let i = 0; i < 5; i++) {
    const mat = new THREE.MeshStandardMaterial({
      color: 0x454c57,
      emissive: 0x000000,
      emissiveIntensity: 0.7,
      roughness: 0.45,
      metalness: 0.15,
    });
    const token = new THREE.Mesh(tokenGeo, mat);
    token.name = 'ProgressToken' + (i + 1);
    token.position.set(-0.18 + i * 0.09, 0.0225, 0.11);
    token.rotation.y = 0.5;
    root.add(token);
    tokens.push(token);
  }

  const IDLE_COLOR = 0x454c57;
  const RIGHT_COLOR = 0x2f9e5f;
  const WRONG_COLOR = 0xc0504a;

  function paintToken(i, color, glow) {
    const mat = tokens[i].material;
    mat.color.setHex(color);
    mat.emissive.setHex(glow);
  }

  // --- Quiz panel ----------------------------------------------------------
  const panel = ui(`
    <style>
      .card { width: 500px; flex-direction: column; align-items: stretch; gap: 10px;
              padding-top: 20px; padding-bottom: 20px; padding-left: 22px; padding-right: 22px;
              border-radius: 20px; background-color: #1c2026; }
      .title { color: #ffffff; font-size: 28px; font-weight: 700; text-align: center; }
      .statusbar { display: flex; flex-direction: row; justify-content: space-between; align-items: center; }
      .status { color: #9fb0c4; font-size: 21px; }
      .question { color: #ffd76a; font-size: 32px; font-weight: 700; text-align: center; }
      .row { display: flex; flex-direction: row; gap: 12px; justify-content: center; }
      .btn { width: 215px; padding-top: 14px; padding-bottom: 14px; border-radius: 14px;
             background-color: #2f6fdb; display: flex; flex-direction: row;
             align-items: center; justify-content: center; }
      .btn-text { color: #ffffff; font-size: 26px; font-weight: 700; }
      .next { width: 442px; padding-top: 13px; padding-bottom: 13px; border-radius: 14px;
              background-color: #3b8f5c; display: flex; flex-direction: row;
              align-items: center; justify-content: center; }
      .next-text { color: #ffffff; font-size: 24px; font-weight: 700; }
      .feedback { color: #c9d1db; font-size: 21px; text-align: center; }
    </style>
    <div class="card">
      <span class="title">Multiplication Quiz</span>
      <div class="statusbar">
        <span class="status" id="qcount">Question 1 of 5</span>
        <span class="status" id="score">Score 0</span>
      </div>
      <span class="question" id="question">6 x 7 = ?</span>
      <div class="row">
        <button class="btn" id="b0"><span class="btn-text" id="b0t">42</span></button>
        <button class="btn" id="b1"><span class="btn-text" id="b1t">36</span></button>
      </div>
      <div class="row">
        <button class="btn" id="b2"><span class="btn-text" id="b2t">48</span></button>
        <button class="btn" id="b3"><span class="btn-text" id="b3t">49</span></button>
      </div>
      <button class="next" id="next"><span class="next-text" id="nextText">Next question</span></button>
      <span class="feedback" id="feedback">Press the answer you think is right.</span>
    </div>`, { width: 0.44, position: [0, 0.21, 0] });
  root.add(panel.object3D);

  // --- Quiz data -----------------------------------------------------------
  const questions = [
    { a: 6, b: 7, options: [42, 36, 48, 49], correct: 0 },
    { a: 8, b: 9, options: [64, 78, 72, 81], correct: 2 },
    { a: 12, b: 4, options: [44, 46, 52, 48], correct: 3 },
    { a: 7, b: 7, options: [42, 49, 47, 56], correct: 1 },
    { a: 9, b: 6, options: [54, 45, 56, 63], correct: 0 },
  ];

  const BLUE = '#2f6fdb';
  const GREEN = '#2f9e5f';
  const RED = '#b8433f';

  let index = 0;
  let score = 0;
  let answered = false;

  function showQuestion() {
    const q = questions[index];
    panel.set('qcount', { text: 'Question ' + (index + 1) + ' of 5' });
    panel.set('score', { text: 'Score ' + score });
    panel.set('question', { text: q.a + ' x ' + q.b + ' = ?' });
    for (let i = 0; i < 4; i++) {
      panel.set('b' + i + 't', { text: String(q.options[i]) });
      panel.set('b' + i, { backgroundColor: BLUE });
    }
    panel.set('feedback', { text: 'Press the answer you think is right.', color: '#c9d1db' });
    panel.set('next', { display: 'none' });
    answered = false;
  }

  function choose(i) {
    if (answered) return;
    answered = true;

    const q = questions[index];
    const answer = q.options[q.correct];
    const last = index === questions.length - 1;
    const tail = last ? '  You scored ' + score + ' of 5.' : '';

    if (i === q.correct) {
      score++;
      panel.set('b' + i, { backgroundColor: GREEN });
      panel.set('feedback', {
        text: 'Correct! ' + q.a + ' x ' + q.b + ' = ' + answer + '.' + tail,
        color: '#7fe0a0',
      });
      paintToken(index, RIGHT_COLOR, 0x1f7a45);
    } else {
      panel.set('b' + i, { backgroundColor: RED });
      panel.set('b' + q.correct, { backgroundColor: GREEN });
      panel.set('feedback', {
        text: 'Not quite. ' + q.a + ' x ' + q.b + ' = ' + answer + '.' + tail,
        color: '#ff9b95',
      });
      paintToken(index, WRONG_COLOR, 0x5a1f1c);
    }

    panel.set('score', { text: 'Score ' + score });
    panel.set('nextText', { text: last ? 'Play again' : 'Next question' });
    panel.set('next', { display: 'flex' });
  }

  function restart() {
    index = 0;
    score = 0;
    for (let i = 0; i < tokens.length; i++) paintToken(i, IDLE_COLOR, 0x000000);
    showQuestion();
  }

  for (let i = 0; i < 4; i++) {
    panel.on('b' + i, 'click', () => choose(i));
  }

  panel.on('next', 'click', () => {
    if (!answered) return;
    if (index < questions.length - 1) {
      index++;
      showQuestion();
    } else {
      restart();
    }
  });

  showQuestion();

  return {
    root,
    update(time) {
      // The token for the current question gently turns; answered ones settle.
      for (let i = 0; i < tokens.length; i++) {
        const t = tokens[i];
        const active = !answered && i === index;
        t.position.y = 0.0225 + (active ? Math.sin(time * 2.2) * 0.006 : 0);
        t.rotation.y = active ? time * 1.1 : 0.5;
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const BTN = '#2b5fb0';
  const BTN_OK = '#2f8f4e';
  const BTN_NO = '#a83b3b';

  // Five fixed questions with plausible distractors.
  const questions = [
    { a: 7, b: 8, options: [54, 56, 48, 63], correct: 1 },
    { a: 6, b: 9, options: [54, 45, 63, 56], correct: 0 },
    { a: 12, b: 4, options: [44, 52, 48, 36], correct: 2 },
    { a: 9, b: 9, options: [72, 81, 90, 79], correct: 1 },
    { a: 8, b: 6, options: [42, 48, 54, 46], correct: 1 },
  ];

  const panel = ui(`
    <style>
      .card { width: 520px; flex-direction: column; gap: 12px; padding-top: 20px; padding-bottom: 20px;
              padding-left: 20px; padding-right: 20px; border-radius: 20px; background-color: #1f2228; }
      .row { display: flex; flex-direction: row; align-items: center; justify-content: space-between; gap: 12px; }
      .title { color: #ffffff; font-size: 28px; font-weight: 700; }
      .score { color: #8fd8a8; font-size: 24px; font-weight: 700; }
      .question { width: 480px; color: #ffffff; font-size: 46px; font-weight: 700; text-align: center; }
      .btn { display: flex; width: 232px; padding-top: 14px; padding-bottom: 14px; padding-left: 10px;
             padding-right: 10px; border-radius: 14px; background-color: #2b5fb0;
             align-items: center; justify-content: center; }
      .bt { color: #ffffff; font-size: 30px; font-weight: 700; }
      .fb { width: 310px; color: #a9b3c2; font-size: 22px; }
      .next { display: flex; width: 150px; padding-top: 12px; padding-bottom: 12px; padding-left: 8px;
              padding-right: 8px; border-radius: 14px; background-color: #3a4250;
              align-items: center; justify-content: center; }
      .nt { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <div class="row">
        <span class="title">Multiplication Quiz</span>
        <span class="score" id="score">Score 0 / 5</span>
      </div>
      <span class="question" id="q">7 x 8 = ?</span>
      <div class="row">
        <button class="btn" id="b0"><span class="bt" id="t0">54</span></button>
        <button class="btn" id="b1"><span class="bt" id="t1">56</span></button>
      </div>
      <div class="row">
        <button class="btn" id="b2"><span class="bt" id="t2">48</span></button>
        <button class="btn" id="b3"><span class="bt" id="t3">63</span></button>
      </div>
      <div class="row">
        <span class="fb" id="fb">Pick the right answer.</span>
        <button class="next" id="next"><span class="nt" id="nt">Next</span></button>
      </div>
    </div>`, { width: 0.40, position: [0, 0.17, 0] });
  root.add(panel.object3D);

  // Five progress cubes above the panel: one per question.
  const cubeGeo = new THREE.BoxGeometry(0.026, 0.026, 0.026);
  const matPending = new THREE.MeshStandardMaterial({ color: 0x3a4048, roughness: 0.6 });
  const matGood = new THREE.MeshStandardMaterial({ color: 0x2f8f4e, emissive: 0x1f6f3e, emissiveIntensity: 0.7 });
  const matBad = new THREE.MeshStandardMaterial({ color: 0xa83b3b, emissive: 0x6a1f1f, emissiveIntensity: 0.7 });
  const cubes = [];
  for (let i = 0; i < 5; i++) {
    const cube = new THREE.Mesh(cubeGeo, matPending);
    cube.name = 'Progress' + (i + 1);
    cube.position.set((i - 2) * 0.05, 0.345, 0);
    root.add(cube);
    cubes.push(cube);
  }

  let qIndex = 0;
  let score = 0;
  let answered = false;
  let finished = false;

  function loadQuestion(i) {
    const q = questions[i];
    answered = false;
    panel.set('q', { text: q.a + ' x ' + q.b + ' = ?' });
    for (let k = 0; k < 4; k++) {
      panel.set('t' + k, { text: String(q.options[k]) });
      panel.set('b' + k, { backgroundColor: BTN });
    }
    panel.set('fb', { text: 'Question ' + (i + 1) + ' of 5. Pick an answer.', color: '#a9b3c2' });
  }

  function answer(k) {
    if (answered || finished) return;
    const q = questions[qIndex];
    answered = true;
    panel.set('b' + q.correct, { backgroundColor: BTN_OK });
    if (k === q.correct) {
      score++;
      panel.set('score', { text: 'Score ' + score + ' / 5' });
      panel.set('fb', { text: 'Correct! ' + q.a + ' x ' + q.b + ' = ' + (q.a * q.b), color: '#7fe0a0' });
      cubes[qIndex].material = matGood;
    } else {
      panel.set('b' + k, { backgroundColor: BTN_NO });
      panel.set('fb', { text: 'Not quite. ' + q.a + ' x ' + q.b + ' = ' + (q.a * q.b), color: '#ff9a9a' });
      cubes[qIndex].material = matBad;
    }
  }

  function finish() {
    finished = true;
    panel.set('q', { text: 'Final score: ' + score + ' / 5' });
    for (let k = 0; k < 4; k++) {
      panel.set('b' + k, { backgroundColor: '#2a2e35' });
      panel.set('t' + k, { text: '--' });
    }
    let msg = 'Good effort. Try again to beat it.';
    if (score === 5) msg = 'Perfect score! Excellent.';
    else if (score >= 3) msg = 'Solid work. Try for 5 next time.';
    panel.set('fb', { text: msg, color: '#d7dbe2' });
    panel.set('nt', { text: 'Play again' });
  }

  function restart() {
    finished = false;
    score = 0;
    qIndex = 0;
    panel.set('score', { text: 'Score 0 / 5' });
    panel.set('nt', { text: 'Next' });
    for (let i = 0; i < cubes.length; i++) cubes[i].material = matPending;
    loadQuestion(0);
  }

  function next() {
    if (finished) { restart(); return; }
    if (!answered) {
      panel.set('fb', { text: 'Pick an answer first.', color: '#ffd166' });
      return;
    }
    if (qIndex < questions.length - 1) {
      qIndex++;
      loadQuestion(qIndex);
    } else {
      finish();
    }
  }

  for (let k = 0; k < 4; k++) {
    panel.on('b' + k, 'click', () => answer(k));
  }
  panel.on('next', 'click', next);

  loadQuestion(0);

  return {
    root,
    update(time) {
      // Gentle idle spin so the progress cubes read as live indicators.
      for (let i = 0; i < cubes.length; i++) {
        cubes[i].rotation.y = time * 0.25 + i * 0.3;
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------- data ----------
  const names = ['Drink water', 'Read 20 min', 'Stretch'];
  const accentCss = ['#74b3ff', '#ffc46b', '#b98cff'];
  const accentHex = [0x74b3ff, 0xffc46b, 0xb98cff];

  // Monday = 0 ... Sunday = 6
  let today = 0;
  try {
    today = (new Date().getDay() + 6) % 7;
  } catch (e) {
    today = 0;
  }

  const checked = [
    [false, false, false, false, false, false, false],
    [false, false, false, false, false, false, false],
    [false, false, false, false, false, false, false],
  ];
  // start with a week already partly filled so streaks are visible
  for (let d = 0; d <= today; d++) checked[0][d] = true;
  for (let d = Math.max(0, today - 2); d <= today; d++) checked[1][d] = true;

  const letters = ['M', 'T', 'W', 'T', 'F', 'S', 'S'];

  // ---------- 2D panel ----------
  let headCells = '';
  for (let d = 0; d < 7; d++) {
    headCells += `<span class="dlabel${d === today ? ' dtoday' : ''}">${letters[d]}</span>`;
  }
  const headRow = `<div class="row"><span class="hname"></span>${headCells}<span class="streak"></span></div>`;

  let rowsHtml = '';
  for (let h = 0; h < 3; h++) {
    let cells = '';
    for (let d = 0; d < 7; d++) {
      cells += `<button class="cell${d === today ? ' today' : ''}" id="c${h}_${d}"></button>`;
    }
    rowsHtml += `<div class="row"><span class="hname h${h}">${names[h]}</span>${cells}<span class="streak" id="s${h}">0</span></div>`;
  }

  const markup = `
    <style>
      .card { width: 580px; flex-direction: column; align-items: flex-start; gap: 10px;
              padding-top: 18px; padding-bottom: 18px; padding-left: 20px; padding-right: 20px;
              border-radius: 22px; background-color: #1b1e23; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .sub { color: #a8b0ba; font-size: 19px; }
      .row { flex-direction: row; align-items: center; gap: 6px; }
      .hname { width: 124px; font-size: 20px; color: #e8ecf2; }
      .dlabel { width: 42px; font-size: 20px; color: #8b939d; text-align: center; }
      .cell { width: 42px; height: 42px; border-radius: 12px; background-color: #2c3138;
              padding-top: 0px; padding-bottom: 0px; padding-left: 0px; padding-right: 0px;
              margin-top: 0px; margin-bottom: 0px; margin-left: 0px; margin-right: 0px; }
      .today { border-width: 2px; border-color: #7f8894; }
      .streak { width: 58px; font-size: 24px; font-weight: 700; text-align: center; color: #6a717b; }
      .foot { color: #8b939d; font-size: 19px; }
      .h0 { color: #74b3ff; }
      .h1 { color: #ffc46b; }
      .h2 { color: #b98cff; }
      .dtoday { color: #ffffff; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">This week</span>
      <span class="sub">Tap a day to check it off. Streak = days done in a row.</span>
      ${headRow}
      ${rowsHtml}
      <span class="foot" id="total">0 of 21 days done this week.</span>
    </div>`;

  const panel = ui(markup, { width: 0.42, position: [0, 0.21, 0], rotationY: 0 });
  root.add(panel.object3D);

  // ---------- 3D quick-check spheres (one per habit) ----------
  const sphereGeo = new THREE.SphereGeometry(0.03, 28, 16);
  const sphereMats = [];
  for (let h = 0; h < 3; h++) {
    const mat = new THREE.MeshStandardMaterial({
      color: accentHex[h],
      emissive: accentHex[h],
      emissiveIntensity: 0.08,
      roughness: 0.35,
      metalness: 0.1,
    });
    sphereMats.push(mat);
    const s = new THREE.Mesh(sphereGeo, mat);
    s.name = 'habit_' + names[h].replace(/ /g, '_');
    s.position.set((h - 1) * 0.11, 0.032, 0.14);
    root.add(s);
    traits(s, {
      onPress: () => {
        checked[h][today] = !checked[h][today];
        refresh();
      },
    });
  }

  // ---------- state -> view ----------
  function currentStreak(h) {
    let i = today;
    if (!checked[h][i]) i -= 1; // today not done yet: show the run up to yesterday
    let s = 0;
    while (i >= 0 && checked[h][i]) {
      s += 1;
      i -= 1;
    }
    return s;
  }

  function refresh() {
    let totalDone = 0;
    for (let h = 0; h < 3; h++) {
      for (let d = 0; d < 7; d++) {
        const on = checked[h][d];
        panel.set('c' + h + '_' + d, { backgroundColor: on ? '#3aa76d' : '#2c3138' });
        if (on) totalDone += 1;
      }
      const st = currentStreak(h);
      panel.set('s' + h, { text: String(st), color: st > 0 ? accentCss[h] : '#6a717b' });
    }
    panel.set('total', { text: totalDone + ' of 21 days done this week.' });
  }

  for (let h = 0; h < 3; h++) {
    for (let d = 0; d < 7; d++) {
      panel.on('c' + h + '_' + d, 'click', () => {
        checked[h][d] = !checked[h][d];
        refresh();
      });
    }
  }

  refresh();

  return {
    root,
    update(time) {
      for (let h = 0; h < 3; h++) {
        const on = checked[h][today];
        sphereMats[h].emissiveIntensity = on ? 0.55 + 0.25 * Math.sin(time * 3 + h * 1.3) : 0.08;
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------------- Build zone (the ring atoms get dropped into) ----------------
  const zoneCenter = new THREE.Vector3(0, 0, 0.06);
  const zoneRadius = 0.11;

  const discMat = new THREE.MeshBasicMaterial({
    color: 0x5aa0ff, transparent: true, opacity: 0.12, depthWrite: false,
  });
  const disc = new THREE.Mesh(new THREE.CircleGeometry(zoneRadius, 48).rotateX(-Math.PI / 2), discMat);
  disc.name = 'BuildZoneDisc';
  disc.position.set(zoneCenter.x, 0.002, zoneCenter.z);
  root.add(disc);

  const ringMat = new THREE.MeshStandardMaterial({
    color: 0x4f9ae0, emissive: 0x1a4a7a, emissiveIntensity: 0.6, roughness: 0.4, metalness: 0.1,
  });
  const ring = new THREE.Mesh(new THREE.TorusGeometry(zoneRadius, 0.0045, 8, 64).rotateX(-Math.PI / 2), ringMat);
  ring.name = 'BuildRing';
  ring.position.set(zoneCenter.x, 0.006, zoneCenter.z);
  root.add(ring);

  // ---------------- Atoms ----------------
  const geoH = new THREE.SphereGeometry(0.022, 24, 16);
  const geoO = new THREE.SphereGeometry(0.032, 24, 16);
  const matH = new THREE.MeshStandardMaterial({
    color: 0xf4f7fc, roughness: 0.32, metalness: 0.05, emissive: 0x22303f, emissiveIntensity: 0.55,
  });
  const matO = new THREE.MeshStandardMaterial({
    color: 0xe8442e, roughness: 0.4, metalness: 0.05, emissive: 0x4a0d06, emissiveIntensity: 0.7,
  });

  const layout = [
    { type: 'H', x: -0.2375 },
    { type: 'O', x: -0.1425 },
    { type: 'H', x: -0.0475 },
    { type: 'H', x: 0.0475 },
    { type: 'O', x: 0.1425 },
    { type: 'H', x: 0.2375 },
  ];

  const atoms = [];
  for (let i = 0; i < layout.length; i++) {
    const item = layout[i];
    const isH = item.type === 'H';
    const r = isH ? 0.022 : 0.032;
    const mesh = new THREE.Mesh(isH ? geoH : geoO, isH ? matH : matO);
    mesh.name = (isH ? 'Hydrogen' : 'Oxygen') + (i + 1);
    mesh.position.set(item.x, r, -0.13);
    root.add(mesh);
    traits(mesh, { grab: true });
    atoms.push({
      mesh, type: item.type, radius: r,
      slot: null, target: null, targetVec: new THREE.Vector3(), wasGrabbed: false,
    });
  }

  // Six snap slots arranged in a hexagon inside the ring
  const slots = [];
  for (let i = 0; i < 6; i++) {
    const ang = Math.PI / 2 + (i * Math.PI * 2) / 6;
    slots.push({
      x: zoneCenter.x + Math.cos(ang) * 0.072,
      z: zoneCenter.z + Math.sin(ang) * 0.072,
      owner: null,
    });
  }

  function nearestFreeSlot(atom) {
    let best = null;
    let bestD = Infinity;
    for (let i = 0; i < slots.length; i++) {
      const s = slots[i];
      if (s.owner) continue;
      const dx = atom.mesh.position.x - s.x;
      const dz = atom.mesh.position.z - s.z;
      const d = dx * dx + dz * dz;
      if (d < bestD) { bestD = d; best = s; }
    }
    return best;
  }

  // ---------------- Info / check panel ----------------
  const info = ui(`
    <style>
      .card { width: 500px; flex-direction: column; gap: 8px; padding-top: 16px; padding-bottom: 16px;
              padding-left: 20px; padding-right: 20px; border-radius: 18px; background-color: #1c2027; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 21px; }
      .count { color: #8ec5ff; font-size: 21px; font-weight: 700; }
      .result { color: #ffd479; font-size: 21px; }
      .btn { margin-top: 6px; padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px;
             border-radius: 12px; background-color: #2f6fdb; align-items: center; justify-content: center; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Build a water molecule</span>
      <span class="body">Water is H2O: 2 hydrogen (white) + 1 oxygen (red).</span>
      <span class="count" id="count">In the ring: 0 H, 0 O</span>
      <button class="btn" id="check"><span class="btn-text">Check molecule</span></button>
      <span class="result" id="result">Pinch an atom and drop it inside the ring.</span>
    </div>`, { width: 0.30, position: [0, 0.22, -0.26] });
  root.add(info.object3D);

  function countRing() {
    let h = 0;
    let o = 0;
    for (let i = 0; i < atoms.length; i++) {
      const a = atoms[i];
      if (a.slot) { if (a.type === 'H') h++; else o++; }
    }
    return [h, o];
  }

  info.on('check', 'click', () => {
    const h = countRing()[0];
    const o = countRing()[1];
    if (h === 2 && o === 1) {
      ringMat.color.set(0x53e08a);
      ringMat.emissive.set(0x0f7a3d);
      info.set('result', {
        text: 'Yes! That is water, H2O: two hydrogen atoms bonded to one oxygen atom.',
        color: '#8ef0b4',
      });
    } else if (h === 0 && o === 0) {
      info.set('result', { text: 'The ring is empty. Drop atoms inside the ring first.', color: '#ffd479' });
    } else if (h === 1 && o === 1) {
      info.set('result', { text: 'Close - HO is the hydroxyl radical. Water needs 2 hydrogen.', color: '#ffd479' });
    } else if (h === 2 && o === 2) {
      info.set('result', { text: 'That is hydrogen peroxide, H2O2 - one oxygen too many.', color: '#ffd479' });
    } else {
      info.set('result', {
        text: 'You have ' + h + ' hydrogen and ' + o + ' oxygen. Water needs 2 hydrogen and 1 oxygen.',
        color: '#ffd479',
      });
    }
  });

  let lastH = 0;
  let lastO = 0;

  return {
    root,
    update(time, delta) {
      const dt = Math.min(delta, 0.05);

      // gentle glow pulse on the ring
      ringMat.emissiveIntensity = 0.55 + Math.sin(time * 2.2) * 0.2;

      for (let i = 0; i < atoms.length; i++) {
        const a = atoms[i];
        const g = isGrabbed(a.mesh);

        if (g !== a.wasGrabbed) {
          a.wasGrabbed = g;
          if (g) {
            if (a.slot) { a.slot.owner = null; a.slot = null; }
            a.target = null;
          } else {
            const dx = a.mesh.position.x - zoneCenter.x;
            const dz = a.mesh.position.z - zoneCenter.z;
            if (dx * dx + dz * dz < 0.15 * 0.15) {
              const s = nearestFreeSlot(a);
              if (s) {
                s.owner = a;
                a.slot = s;
                a.target = s;
                a.targetVec.set(s.x, a.radius, s.z);
              }
            }
          }
        }

        if (!g && a.target) {
          a.mesh.position.lerp(a.targetVec, Math.min(1, dt * 9));
        }
      }

      const c = countRing();
      if (c[0] !== lastH || c[1] !== lastO) {
        lastH = c[0];
        lastO = c[1];
        info.set('count', { text: 'In the ring: ' + lastH + ' H, ' + lastO + ' O' });
        ringMat.color.set(0x4f9ae0);
        ringMat.emissive.set(0x1a4a7a);
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------------- this week ----------------
  const now = new Date();
  const TODAY = (now.getDay() + 6) % 7; // 0 = Monday ... 6 = Sunday
  const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  const mon = new Date(now.getFullYear(), now.getMonth(), now.getDate() - TODAY);
  const sun = new Date(now.getFullYear(), now.getMonth(), now.getDate() - TODAY + 6);
  const range = MONTHS[mon.getMonth()] + ' ' + mon.getDate() + ' - ' +
    (sun.getMonth() === mon.getMonth() ? '' : MONTHS[sun.getMonth()] + ' ') + sun.getDate();

  const DAY_LABELS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

  // ---------------- habits ----------------
  const habits = [
    { name: 'Drink water', days: [false, false, false, false, false, false, false] },
    { name: 'Walk 20 min', days: [false, false, false, false, false, false, false] },
    { name: 'Read 10 min', days: [false, false, false, false, false, false, false] },
  ];

  // Seed the days that already happened so streaks are visible right away.
  for (let c = 0; c < TODAY; c++) {
    habits[0].days[c] = true;               // perfect so far
    habits[1].days[c] = c >= TODAY - 2;     // last two days
    habits[2].days[c] = c % 2 === 0;        // every other day
  }

  // ---------------- markup ----------------
  let headHtml = '<span class="hname">Habit</span>';
  for (let c = 0; c < 7; c++) {
    headHtml += '<span class="' + (c === TODAY ? 'hl-today' : 'hl') + '">' + DAY_LABELS[c] + '</span>';
  }
  headHtml += '<span class="hstreak">Streak</span>';

  let rowsHtml = '';
  for (let r = 0; r < habits.length; r++) {
    let cells = '';
    for (let c = 0; c < 7; c++) {
      cells += '<button class="day" id="b' + r + c + '"></button>';
    }
    rowsHtml += '<div class="hrow">' +
      '<span class="name">' + habits[r].name + '</span>' +
      cells +
      '<span class="streak" id="s' + r + '">0d</span>' +
      '</div>';
  }

  const info = ui(`
    <style>
      .panel { width: 600px; flex-direction: column; gap: 10px;
               padding-top: 20px; padding-bottom: 20px; padding-left: 20px; padding-right: 20px;
               border-radius: 22px; background-color: #191c21; }
      .trow { flex-direction: row; justify-content: space-between; align-items: center; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .summary { color: #3ecf8e; font-size: 20px; font-weight: 700; }
      .sub { color: #9aa3b0; font-size: 20px; }
      .hrow { flex-direction: row; gap: 5px; align-items: center; }
      .hname { width: 150px; color: #8b93a1; font-size: 20px; }
      .hl { width: 42px; color: #8b93a1; font-size: 20px; text-align: center; }
      .hl-today { width: 42px; color: #ffc23d; font-size: 20px; font-weight: 700; text-align: center; }
      .hstreak { width: 70px; color: #8b93a1; font-size: 20px; text-align: center; }
      .name { width: 150px; color: #e8ecf2; font-size: 22px; }
      .day { width: 42px; height: 42px; border-radius: 12px; background-color: #2a2e35; }
      .streak { width: 70px; color: #5b626d; font-size: 22px; font-weight: 700; text-align: center; }
    </style>
    <div class="panel">
      <div class="trow">
        <span class="title">This week</span>
        <span class="summary" id="summary">Today 0/3</span>
      </div>
      <span class="sub">${range} - tap a day to check it off</span>
      <div class="hrow">${headHtml}</div>
      ${rowsHtml}
    </div>`, { width: 0.46, position: [0, 0.20, -0.02] });
  root.add(info.object3D);

  // ---------------- reward star ----------------
  const starShape = new THREE.Shape();
  const spikes = 5, outerR = 0.030, innerR = 0.013;
  for (let i = 0; i < spikes * 2; i++) {
    const rad = (i % 2 === 0) ? outerR : innerR;
    const a = Math.PI / 2 + (i * Math.PI) / spikes;
    const x = Math.cos(a) * rad;
    const y = Math.sin(a) * rad;
    if (i === 0) starShape.moveTo(x, y); else starShape.lineTo(x, y);
  }
  starShape.closePath();

  const starGeo = new THREE.ExtrudeGeometry(starShape, { depth: 0.010, bevelEnabled: false, curveSegments: 1 });
  starGeo.center();

  const star = new THREE.Mesh(starGeo, new THREE.MeshStandardMaterial({
    color: 0xffc23d, emissive: 0xff9a00, emissiveIntensity: 0.6, metalness: 0.5, roughness: 0.3,
  }));
  star.name = 'RewardStar';
  star.position.set(0.31, 0.115, 0.0);
  star.visible = false;
  root.add(star);

  const pedestal = new THREE.Mesh(
    new THREE.CylinderGeometry(0.028, 0.036, 0.022, 24),
    new THREE.MeshStandardMaterial({ color: 0x3a4048, roughness: 0.75, metalness: 0.2 }),
  );
  pedestal.name = 'Pedestal';
  pedestal.position.set(0.31, 0.011, 0.0);
  root.add(pedestal);

  // ---------------- logic ----------------
  let starOn = false;

  function streakOf(days) {
    let i = TODAY;
    if (!days[i]) i = TODAY - 1; // today not done yet: the streak is still alive
    let n = 0;
    while (i >= 0 && days[i]) { n++; i--; }
    return n;
  }

  function refresh() {
    let total = 0, todayDone = 0;
    for (let r = 0; r < habits.length; r++) {
      const days = habits[r].days;
      for (let c = 0; c < 7; c++) {
        const on = days[c];
        if (on) { total++; if (c === TODAY) todayDone++; }
        let bg = '#2a2e35';
        if (on) bg = '#3ecf8e';
        else if (c === TODAY) bg = '#3a424c';
        info.set('b' + r + c, { backgroundColor: bg });
      }
      const s = streakOf(days);
      info.set('s' + r, { text: s + 'd', color: s > 0 ? '#ffc23d' : '#5b626d' });
    }
    info.set('summary', { text: 'Today ' + todayDone + '/3 - week ' + total + '/21' });
    starOn = todayDone === 3;
  }

  for (let r = 0; r < habits.length; r++) {
    for (let c = 0; c < 7; c++) {
      info.on('b' + r + c, 'click', () => {
        habits[r].days[c] = !habits[r].days[c];
        refresh();
      });
    }
  }

  refresh();

  let starShown = 0;
  return {
    root,
    update(time, delta) {
      const step = Math.min(1, delta * 5);
      starShown += ((starOn ? 1 : 0) - starShown) * step;
      const s = Math.max(0.001, starShown);
      star.scale.set(s, s, s);
      star.visible = starShown > 0.03;
      star.rotation.y = time * 0.9;
      star.position.y = 0.115 + Math.sin(time * 1.6) * 0.006;
      star.material.emissiveIntensity = 0.5 + 0.3 * (0.5 + 0.5 * Math.sin(time * 2.4));
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------- geometry constants ----------
  const O_R = 0.030;          // oxygen radius
  const H_R = 0.020;          // hydrogen radius
  const BOND = 0.070;         // O-H distance once bonded
  const SNAP_DIST = 0.115;    // drop a hydrogen this close to oxygen and it bonds
  const HALF = THREE.MathUtils.degToRad(52.25); // half of the real 104.5 degree bond angle
  const SLOT_DIRS = [
    new THREE.Vector3(Math.cos(Math.PI / 2 - HALF), 0, Math.sin(Math.PI / 2 - HALF)),
    new THREE.Vector3(Math.cos(Math.PI / 2 + HALF), 0, Math.sin(Math.PI / 2 + HALF)),
  ];

  // ---------- atoms ----------
  const oMat = new THREE.MeshStandardMaterial({ color: 0xd8452f, roughness: 0.34, metalness: 0.05 });
  const oxygen = new THREE.Mesh(new THREE.SphereGeometry(O_R, 32, 20), oMat);
  oxygen.name = 'Oxygen';
  oxygen.position.set(-0.13, O_R, -0.01);
  root.add(oxygen);

  const hMat = new THREE.MeshStandardMaterial({ color: 0xeef1f5, roughness: 0.28, metalness: 0.06 });
  const hGeo = new THREE.SphereGeometry(H_R, 24, 16);

  const h1 = new THREE.Mesh(hGeo, hMat);
  h1.name = 'Hydrogen1';
  h1.position.set(-0.33, H_R, 0.10);

  const h2 = new THREE.Mesh(hGeo, hMat);
  h2.name = 'Hydrogen2';
  h2.position.set(0.00, H_R, 0.13);

  root.add(h1, h2);

  const Hs = [h1, h2];
  h1.userData.slot = -1;
  h2.userData.slot = -1;
  const slotOwner = [-1, -1];

  const O_START = oxygen.position.clone();
  const H_START = [h1.position.clone(), h2.position.clone()];

  traits(oxygen, { grab: true });
  traits(h1, { grab: true });
  traits(h2, { grab: true });

  // ---------- bond sticks ----------
  const stickGeo = new THREE.CylinderGeometry(0.0055, 0.0055, 1, 10, 1);
  const stickMat = new THREE.MeshStandardMaterial({ color: 0xc3cbd6, roughness: 0.5, metalness: 0.1 });
  const sticks = [new THREE.Mesh(stickGeo, stickMat), new THREE.Mesh(stickGeo, stickMat)];
  sticks[0].name = 'Bond1';
  sticks[1].name = 'Bond2';
  sticks[0].visible = false;
  sticks[1].visible = false;
  root.add(sticks[0], sticks[1]);

  // ---------- empty bond-slot markers (where hydrogens click in) ----------
  const ringGeo = new THREE.RingGeometry(0.019, 0.028, 28);
  const rings = SLOT_DIRS.map((d) => {
    const m = new THREE.Mesh(
      ringGeo,
      new THREE.MeshBasicMaterial({
        color: 0x5ac8fa, transparent: true, opacity: 0.3, side: THREE.DoubleSide, depthWrite: false,
      }),
    );
    m.name = 'BondSlot';
    m.rotation.x = -Math.PI / 2;
    m.position.set(oxygen.position.x + d.x * BOND, 0.002, oxygen.position.z + d.z * BOND);
    root.add(m);
    return m;
  });

  // ---------- panel ----------
  const panel = ui(`
    <style>
      .card { width: 500px; flex-direction: column; gap: 10px; padding-top: 18px; padding-bottom: 18px;
              padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 22px; }
      .row { flex-direction: row; gap: 12px; }
      .btn { padding-top: 12px; padding-bottom: 12px; padding-left: 20px; padding-right: 20px;
             border-radius: 12px; background-color: #2f8fdb; }
      .btn2 { background-color: #3a3f47; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Build a water molecule</span>
      <span class="body" id="status">Bonded hydrogens: 0 of 2</span>
      <span class="body" id="msg">Pinch a white hydrogen atom and drop it on a blue ring next to the red oxygen.</span>
      <div class="row">
        <button class="btn" id="check"><span class="btn-text">Check</span></button>
        <button class="btn btn2" id="reset"><span class="btn-text">Reset</span></button>
      </div>
    </div>`, { width: 0.30, position: [0.235, 0.185, 0.02], rotationY: -0.32 });
  root.add(panel.object3D);

  // ---------- state ----------
  let complete = false;

  function countBonded() {
    return (h1.userData.slot >= 0 ? 1 : 0) + (h2.userData.slot >= 0 ? 1 : 0);
  }

  function refresh() {
    const n = countBonded();
    panel.set('status', { text: 'Bonded hydrogens: ' + n + ' of 2' });
    const wasComplete = complete;
    complete = n === 2;
    if (complete && !wasComplete) {
      panel.set('msg', { text: 'Water! Two hydrogens on one oxygen. Press Check to confirm.' });
    } else if (!complete && wasComplete) {
      panel.set('msg', { text: 'A bond broke. Drop a hydrogen near the oxygen again.' });
    }
    oMat.emissive.setHex(complete ? 0xff4422 : 0x000000);
  }

  // ---------- snapping ----------
  const tmpTarget = new THREE.Vector3();
  const tmpDir = new THREE.Vector3();
  const UP = new THREE.Vector3(0, 1, 0);

  function trySnap(h) {
    const idx = h === h1 ? 0 : 1;
    if (h.position.distanceTo(oxygen.position) > SNAP_DIST) return;
    let best = -1;
    let bestD = Infinity;
    for (let s = 0; s < 2; s++) {
      if (slotOwner[s] !== -1) continue;
      tmpTarget.copy(oxygen.position).addScaledVector(SLOT_DIRS[s], BOND);
      const d = tmpTarget.distanceToSquared(h.position);
      if (d < bestD) { bestD = d; best = s; }
    }
    if (best < 0) return;
    h.userData.slot = best;
    slotOwner[best] = idx;
    refresh();
  }

  function updateStick(i) {
    const h = Hs[i];
    const s = sticks[i];
    if (h.userData.slot < 0) { s.visible = false; return; }
    tmpDir.subVectors(h.position, oxygen.position);
    const len = tmpDir.length();
    if (len < 1e-5) { s.visible = false; return; }
    tmpDir.divideScalar(len);
    s.visible = true;
    s.position.copy(oxygen.position).addScaledVector(tmpDir, len * 0.5);
    s.quaternion.setFromUnitVectors(UP, tmpDir);
    s.scale.set(1, len, 1);
  }

  // ---------- buttons ----------
  panel.on('check', 'click', () => {
    const n = countBonded();
    if (n === 0) {
      panel.set('msg', { text: 'Nothing is bonded yet. Pinch a white hydrogen atom and drop it on one of the blue rings around the red oxygen.' });
    } else if (n === 1) {
      panel.set('msg', { text: 'One O-H bond so far. Hydrogen is not finished: oxygen needs two hydrogens, so add the second one.' });
    } else {
      panel.set('msg', { text: 'Correct! That is water: H2O. The two O-H bonds sit 104.5 degrees apart, so the molecule is bent.' });
    }
  });

  panel.on('reset', 'click', () => {
    h1.userData.slot = -1;
    h2.userData.slot = -1;
    slotOwner[0] = -1;
    slotOwner[1] = -1;
    h1.position.copy(H_START[0]);
    h2.position.copy(H_START[1]);
    oxygen.position.copy(O_START);
    sticks[0].visible = false;
    sticks[1].visible = false;
    complete = false;
    refresh();
    panel.set('msg', { text: 'Pinch a white hydrogen atom and drop it on a blue ring next to the red oxygen.' });
  });

  // ---------- per-frame ----------
  const prevGrabbed = [false, false];

  return {
    root,
    update(time, delta) {
      const dt = Math.min(Math.max(delta, 0), 0.05);

      if (!isGrabbed(oxygen) && oxygen.position.y > O_R) {
        oxygen.position.y += (O_R - oxygen.position.y) * Math.min(1, dt * 8);
      }

      for (let i = 0; i < 2; i++) {
        const h = Hs[i];
        const g = isGrabbed(h);

        if (g !== prevGrabbed[i]) {
          if (g) {
            if (h.userData.slot >= 0) {
              slotOwner[h.userData.slot] = -1;
              h.userData.slot = -1;
              refresh();
            }
          } else {
            trySnap(h);
          }
          prevGrabbed[i] = g;
        }

        if (h.userData.slot >= 0 && !g) {
          tmpTarget.copy(oxygen.position).addScaledVector(SLOT_DIRS[h.userData.slot], BOND);
          h.position.lerp(tmpTarget, Math.min(1, dt * 20));
        } else if (!g && h.position.y > H_R) {
          h.position.y += (H_R - h.position.y) * Math.min(1, dt * 8);
        }

        updateStick(i);
      }

      const anyHand = isGrabbed(oxygen) || isGrabbed(h1) || isGrabbed(h2);
      for (let s = 0; s < 2; s++) {
        const ring = rings[s];
        const free = slotOwner[s] === -1;
        ring.visible = free;
        ring.position.set(
          oxygen.position.x + SLOT_DIRS[s].x * BOND,
          0.002,
          oxygen.position.z + SLOT_DIRS[s].z * BOND,
        );
        const target = free ? (anyHand ? 0.75 : 0.3) : 0;
        ring.material.opacity += (target - ring.material.opacity) * Math.min(1, dt * 10);
      }

      if (complete) {
        oMat.emissiveIntensity = 0.35 + 0.22 * Math.sin(time * 3);
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const BX = -0.13; // basket centre x
  const BZ = -0.02; // basket centre z

  // ---------------- basket ----------------
  const wickerMat = new THREE.MeshStandardMaterial({ color: 0xb4803f, roughness: 0.85, side: THREE.DoubleSide });
  const darkWickerMat = new THREE.MeshStandardMaterial({ color: 0x7a5326, roughness: 0.9 });

  const basketBody = new THREE.Mesh(new THREE.CylinderGeometry(0.085, 0.06, 0.09, 28, 1, true), wickerMat);
  basketBody.name = 'Basket';
  basketBody.position.set(BX, 0.045, BZ);
  root.add(basketBody);

  const basketFloor = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.06, 0.01, 28), darkWickerMat);
  basketFloor.name = 'BasketFloor';
  basketFloor.position.set(BX, 0.005, BZ);
  root.add(basketFloor);

  const basketRim = new THREE.Mesh(new THREE.TorusGeometry(0.085, 0.007, 10, 36), wickerMat);
  basketRim.rotation.x = Math.PI / 2;
  basketRim.position.set(BX, 0.09, BZ);
  root.add(basketRim);

  for (let i = 0; i < 3; i++) {
    const y = 0.018 + i * 0.026;
    const r = 0.06 + 0.025 * (y / 0.09);
    const band = new THREE.Mesh(new THREE.TorusGeometry(r, 0.0035, 8, 32), darkWickerMat);
    band.rotation.x = Math.PI / 2;
    band.position.set(BX, y, BZ);
    root.add(band);
  }

  // ---------------- fruit geometry & materials ----------------
  const appleGeo = new THREE.SphereGeometry(0.030, 28, 18);
  const orangeGeo = new THREE.SphereGeometry(0.027, 28, 18);
  const bananaGeo = new THREE.TorusGeometry(0.036, 0.010, 12, 36, Math.PI * 0.9);
  bananaGeo.rotateZ(-Math.PI * 0.45);
  bananaGeo.translate(-0.025, 0, 0);
  const stemGeo = new THREE.CylinderGeometry(0.0028, 0.0034, 0.015, 8);
  const leafGeo = new THREE.SphereGeometry(0.010, 10, 8);

  const stemMat = new THREE.MeshStandardMaterial({ color: 0x5b3a1a, roughness: 0.9 });
  const leafMat = new THREE.MeshStandardMaterial({ color: 0x3fa34d, roughness: 0.7 });
  const appleMat = new THREE.MeshStandardMaterial({ color: 0xd42b2b, roughness: 0.35 });
  const orangeMat = new THREE.MeshStandardMaterial({ color: 0xf59a1e, roughness: 0.65 });
  const bananaMat = new THREE.MeshStandardMaterial({ color: 0xf2d43a, roughness: 0.55 });

  // Apple
  const apple = new THREE.Mesh(appleGeo, appleMat);
  const aStem = new THREE.Mesh(stemGeo, stemMat);
  aStem.position.set(0.002, 0.028, 0);
  aStem.rotation.z = 0.22;
  apple.add(aStem);
  const aLeaf = new THREE.Mesh(leafGeo, leafMat);
  aLeaf.scale.set(1.5, 0.35, 0.9);
  aLeaf.position.set(0.014, 0.031, 0);
  aLeaf.rotation.z = -0.5;
  apple.add(aLeaf);

  // Banana
  const banana = new THREE.Mesh(bananaGeo, bananaMat);
  banana.rotation.set(-Math.PI / 2 + 0.55, 0, 0.4);

  // Orange
  const orange = new THREE.Mesh(orangeGeo, orangeMat);
  const oStem = new THREE.Mesh(stemGeo, leafMat);
  oStem.scale.set(0.9, 0.55, 0.9);
  oStem.position.set(0, 0.026, 0);
  orange.add(oStem);

  // ---------------- info panel ----------------
  const info = ui(`
    <style>
      .card { width: 480px; flex-direction: column; gap: 8px; padding-top: 16px; padding-bottom: 16px;
              padding-left: 20px; padding-right: 20px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .row { flex-direction: row; justify-content: space-between; }
      .name { color: #d7dbe2; font-size: 22px; }
      .price { color: #9aa3af; font-size: 22px; }
      .total { color: #7ee787; font-size: 26px; font-weight: 700; }
      .hint { color: #9aa3af; font-size: 20px; }
      .btn { padding-top: 8px; padding-bottom: 8px; padding-left: 16px; padding-right: 16px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Fruit Basket</span>
      <div class="row"><span class="name" id="n0">Apple</span><span class="price" id="p0">$0.60</span></div>
      <div class="row"><span class="name" id="n1">Banana</span><span class="price" id="p1">$0.30</span></div>
      <div class="row"><span class="name" id="n2">Orange</span><span class="price" id="p2">$0.75</span></div>
      <span class="total" id="total">Total: $0.00</span>
      <span class="hint" id="hint">Pinch a fruit and drop it in the basket.</span>
      <button class="btn" id="reset"><span class="btn-text">Empty basket</span></button>
    </div>`, { width: 0.30, position: [0.02, 0.235, -0.17], rotationY: 0 });
  root.add(info.object3D);

  // ---------------- fruits on the desk ----------------
  const defs = [
    { mesh: apple,  name: 'Apple',  price: 0.60, restY: 0.030, home: [0.05, 0.030, 0.055] },
    { mesh: banana, name: 'Banana', price: 0.30, restY: 0.028, home: [0.15, 0.028, 0.005] },
    { mesh: orange, name: 'Orange', price: 0.75, restY: 0.027, home: [0.23, 0.027, 0.060] },
  ];

  const fruits = [];
  for (let i = 0; i < defs.length; i++) {
    const d = defs[i];
    d.mesh.name = d.name;
    d.mesh.position.set(d.home[0], d.home[1], d.home[2]);
    root.add(d.mesh);
    traits(d.mesh, { grab: true });
    fruits.push({
      mesh: d.mesh,
      name: d.name,
      price: d.price,
      restY: d.restY,
      home: d.mesh.position.clone(),
      slot: -1,
      wasGrabbed: false,
      id: i,
    });
  }

  // resting places inside the basket (triangle) - y is the top of the basket floor
  const SLOT = [
    { x: BX,         z: BZ + 0.031, y: 0.009 },
    { x: BX - 0.027, z: BZ - 0.016, y: 0.009 },
    { x: BX + 0.027, z: BZ - 0.016, y: 0.009 },
  ];

  function refreshPanel() {
    let total = 0;
    let count = 0;
    for (let i = 0; i < fruits.length; i++) {
      const f = fruits[i];
      const inBasket = f.slot >= 0;
      if (inBasket) { total += f.price; count++; }
      info.set('n' + i, { color: inBasket ? '#7ee787' : '#d7dbe2' });
      info.set('p' + i, { color: inBasket ? '#7ee787' : '#9aa3af' });
    }
    info.set('total', { text: 'Total: $' + total.toFixed(2) });
    if (count === 3) {
      info.set('hint', { text: 'Basket full: 3 fruits.' });
    } else {
      info.set('hint', { text: 'Pinch a fruit and drop it in the basket.' });
    }
  }

  function freeSlot() {
    for (let i = 0; i < SLOT.length; i++) {
      let taken = false;
      for (let j = 0; j < fruits.length; j++) {
        if (fruits[j].slot === i) { taken = true; break; }
      }
      if (!taken) return i;
    }
    return -1;
  }

  function settle(f) {
    const p = f.mesh.position;
    const dx = p.x - BX;
    const dz = p.z - BZ;
    const dist = Math.sqrt(dx * dx + dz * dz);

    if (dist < 0.09) {
      const idx = freeSlot();
      if (idx >= 0) {
        f.slot = idx;
        p.set(SLOT[idx].x, SLOT[idx].y + f.restY, SLOT[idx].z);
      }
    } else {
      f.slot = -1;
      // keep it from intersecting the basket wall
      if (dist > 0.0001 && dist < 0.125) {
        const s = 0.125 / dist;
        p.x = BX + dx * s;
        p.z = BZ + dz * s;
      }
      p.y = f.restY;
      if (p.x < -0.30) p.x = -0.30;
      if (p.x > 0.32) p.x = 0.32;
      if (p.z < -0.13) p.z = -0.13;
      if (p.z > 0.15) p.z = 0.15;
    }
    refreshPanel();
  }

  info.on('reset', 'click', () => {
    for (let i = 0; i < fruits.length; i++) {
      const f = fruits[i];
      f.slot = -1;
      f.mesh.position.copy(f.home);
    }
    refreshPanel();
  });

  refreshPanel();

  return {
    root,
    update(time, delta) {
      for (let i = 0; i < fruits.length; i++) {
        const f = fruits[i];
        const g = isGrabbed(f.mesh);
        if (g && !f.wasGrabbed && f.slot >= 0) {
          f.slot = -1; // lifted back out of the basket
          refreshPanel();
        }
        if (!g && f.wasGrabbed) {
          settle(f);
        }
        f.wasGrabbed = g;
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const palette = [
