  baseRing.position.y = 0.015;
  base.add(baseRing);

  const buttonMaterial = new THREE.MeshStandardMaterial({
    color: palette[0].hex,
    emissive: palette[0].hex,
    emissiveIntensity: 1.4,
    metalness: 0.15,
    roughness: 0.28,
