    color: palette[0].hex,
    transparent: true,
    opacity: 0.8,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
  });

  const halo = new THREE.Mesh(
    new THREE.TorusGeometry(0.069, 0.004, 8, 40),
    haloMaterial,
  );
  halo.rotation.x = Math.PI / 2;
  halo.position.y = 0.02;
  button.add(halo);

  const outerHaloMaterial = haloMaterial.clone();
  outerHaloMaterial.opacity = 0.22;

  const outerHalo = new THREE.Mesh(
    new THREE.TorusGeometry(0.078, 0.009, 8, 40),
    outerHaloMaterial,
  );
  outerHalo.rotation.x = Math.PI / 2;
  outerHalo.position.y = 0.004;
  button.add(outerHalo);

  const panel = ui(`
    <style>
      .card {
        width: 460px;
        flex-direction: column;
        gap: 12px;
        padding-top: 20px;
        padding-bottom: 20px;
        padding-left: 24px;
        padding-right: 24px;
        border-radius: 18px;
        border-width: 2px;
        border-color: #3b424e;
        background-color: #1a1d22;
      }
      .title {
        color: #ffffff;
        font-size: 32px;
        font-weight: 700;
      }
      .body {
        color: #d7dbe2;
        font-size: 23px;
      }
      .status {
        flex-direction: row;
        align-items: center;
        gap: 12px;
        margin-top: 4px;
      }
      .swatch {
        width: 30px;
        height: 30px;
        border-radius: 15px;
        background-color: #24d9ff;
      }
      .color-name {
        color: #24d9ff;
        font-size: 28px;
        font-weight: 700;
      }
      .count {
        color: #aab3c0;
        font-size: 21px;
      }
    </style>
    <div class="card">
      <span class="title">Color pulse</span>
      <span class="body">Poke or pinch the glowing button. Every press switches to a new color.</span>
      <div class="status">
        <div class="swatch" id="swatch"></div>
        <span class="color-name" id="colorName">Cyan</span>
      </div>
      <span class="count" id="count">Presses: 0</span>
    </div>`, {
    width: 0.3,
    position: [0.24, 0.18, -0.025],
    rotationY: -0.3,
  });
  root.add(panel.object3D);

  let colorIndex = 0;
  let presses = 0;
  let flash = 0;

  traits(button, {
    onPress: () => {
      colorIndex = (colorIndex + 1) % palette.length;
      presses += 1;
      flash = 1;

      const next = palette[colorIndex];
      buttonMaterial.color.setHex(next.hex);
      buttonMaterial.emissive.setHex(next.hex);
      haloMaterial.color.setHex(next.hex);
      outerHaloMaterial.color.setHex(next.hex);

      panel.set('colorName', { text: next.name, color: next.css });
      panel.set('swatch', { backgroundColor: next.css });
      panel.set('count', { text: `Presses: ${presses}` });
    },
  });

  return {
    root,
    update(time, delta) {
      if (isGrabbed(button)) return;

      flash = Math.max(0, flash - delta * 3.5);
      const pulse = Math.sin(time * 2.6) * 0.5 + 0.5;
      const scale = 1 + pulse * 0.018 + flash * 0.09;

      button.scale.set(scale, 1 - flash * 0.16, scale);
      buttonMaterial.emissiveIntensity = 1.15 + pulse * 0.35 + flash * 2.4;
      haloMaterial.opacity = 0.55 + pulse * 0.25 + flash * 0.2;
      outerHaloMaterial.opacity = 0.14 + pulse * 0.12 + flash * 0.25;
      outerHalo.rotation.z = time * 0.35;
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
