  // ---------- shared geometry ----------
  const sphereGeo = new THREE.SphereGeometry(1, 20, 14);
  const smallGeo = new THREE.SphereGeometry(1, 10, 8);
  const stemGeo = new THREE.CylinderGeometry(0.0025, 0.0035, 0.016, 6);
  const bananaArcGeo = new THREE.TorusGeometry(0.05, 0.014, 8, 20, Math.PI * 0.8);

