  const leafMat = new THREE.MeshStandardMaterial({ color: 0x3f8f3a, roughness: 0.85 });
  const tipMat = new THREE.MeshStandardMaterial({ color: 0x6b4a1f, roughness: 0.9 });
  const wickerMat = new THREE.MeshStandardMaterial({ color: 0xb9854c, roughness: 0.85, side: THREE.DoubleSide });

  // ---------- fruit factories ----------
  function makeApple() {
    const g = new THREE.Group();
    const body = new THREE.Mesh(sphereGeo, appleMat);
    body.scale.set(0.035, 0.032, 0.035);
    body.name = 'AppleBody';
    g.add(body);
    const stem = new THREE.Mesh(stemGeo, stemMat);
    stem.position.set(0.001, 0.036, 0);
    stem.rotation.z = 0.28;
    g.add(stem);
    const leaf = new THREE.Mesh(smallGeo, leafMat);
    leaf.scale.set(0.014, 0.0025, 0.008);
    leaf.position.set(0.015, 0.036, 0);
    leaf.rotation.z = -0.45;
    g.add(leaf);
    return g;
  }

  function makeOrange() {
    const g = new THREE.Group();
    const body = new THREE.Mesh(sphereGeo, orangeMat);
    body.scale.setScalar(0.032);
    body.name = 'OrangeBody';
    g.add(body);
    const nub = new THREE.Mesh(smallGeo, stemMat);
    nub.scale.setScalar(0.005);
    nub.position.set(0, 0.029, 0);
    g.add(nub);
    return g;
  }

  function makeBanana() {
    const g = new THREE.Group();
    const shape = new THREE.Group();
    shape.rotation.x = Math.PI / 2;
    shape.rotation.z = Math.PI * 0.1;
    shape.position.z = -0.03;
    const arc = new THREE.Mesh(bananaArcGeo, bananaMat);
    arc.name = 'BananaBody';
    shape.add(arc);
    const t1 = new THREE.Mesh(smallGeo, tipMat);
    t1.scale.setScalar(0.0132);
    t1.position.set(0.05, 0, 0);
    shape.add(t1);
    const t2 = new THREE.Mesh(smallGeo, tipMat);
    t2.scale.setScalar(0.0132);
    t2.position.set(0.05 * Math.cos(Math.PI * 0.8), 0.05 * Math.sin(Math.PI * 0.8), 0);
    shape.add(t2);
    g.add(shape);
    return g;
  }

  // ---------- basket ----------
  const basketPos = new THREE.Vector3(0, 0, -0.10);
  const basket = new THREE.Group();
  basket.name = 'Basket';
  basket.position.copy(basketPos);
  root.add(basket);

  const wall = new THREE.Mesh(new THREE.CylinderGeometry(0.095, 0.075, 0.085, 28, 1, true), wickerMat);
  wall.position.y = 0.0425;
  wall.name = 'BasketWall';
  basket.add(wall);

  const base = new THREE.Mesh(new THREE.CylinderGeometry(0.075, 0.075, 0.01, 28), wickerMat);
  base.position.y = 0.005;
  base.name = 'BasketBase';
  basket.add(base);

  const rimMat = new THREE.MeshStandardMaterial({
    color: 0xc9975c, roughness: 0.7, emissive: 0x66ff99, emissiveIntensity: 0,
  });
  const rim = new THREE.Mesh(new THREE.TorusGeometry(0.095, 0.0075, 10, 32), rimMat);
  rim.rotation.x = Math.PI / 2;
  rim.position.y = 0.085;
  rim.name = 'BasketRim';
  basket.add(rim);

  // ---------- fruits ----------
  const FRUIT_INFO = {
    apple:  { name: 'Apple',  price: 0.60, make: makeApple,  y: 0.032 },
    orange: { name: 'Orange', price: 0.45, make: makeOrange, y: 0.032 },
    banana: { name: 'Banana', price: 0.30, make: makeBanana, y: 0.0155 },
  };

  const layout = [
    ['apple', -0.21, 0.16],
    ['orange', 0.00, 0.17],
    ['banana', 0.20, 0.15],
    ['apple', -0.21, 0.05],
    ['orange', 0.00, 0.06],
    ['banana', 0.20, 0.04],
  ];

  const fruits = [];
  for (let i = 0; i < layout.length; i++) {
    const kind = layout[i][0];
    const x = layout[i][1];
    const z = layout[i][2];
    const info = FRUIT_INFO[kind];
    const g = info.make();
    g.name = info.name;
    g.position.set(x, info.y, z);
    root.add(g);
    traits(g, { grab: true });
    fruits.push({
      kind: kind,
      group: g,
      collected: false,
      slot: new THREE.Vector3(),
      start: new THREE.Vector3(x, info.y, z),
    });
  }

  // ---------- info panel ----------
  const panel = ui(`
    <style>
      .card { width: 520px; flex-direction: column; gap: 10px; padding-top: 20px; padding-bottom: 20px;
              padding-left: 24px; padding-right: 24px; border-radius: 20px; background-color: #1c1f25; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .hint { color: #98a1ae; font-size: 21px; }
      .totalrow { display: flex; flex-direction: row; justify-content: space-between;
                  align-items: center; margin-top: 4px; }
      .lab { color: #c7ced9; font-size: 26px; }
      .amt { color: #7fe08c; font-size: 34px; font-weight: 700; }
      .row { display: flex; flex-direction: row; justify-content: space-between; }
      .rname { color: #d7dbe2; font-size: 23px; }
      .rprice { color: #d7dbe2; font-size: 23px; }
      .hidden { display: none; }
      .btn { margin-top: 6px; padding-top: 10px; padding-bottom: 10px; padding-left: 16px;
             padding-right: 16px; border-radius: 14px; background-color: #2f6fdb; align-items: center; }
      .btntext { color: #ffffff; font-size: 23px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Fruit Basket</span>
      <span class="hint" id="hint">Pinch a fruit and drop it into the basket.</span>
      <div class="totalrow">
        <span class="lab">Total</span>
        <span class="amt" id="total">$0.00</span>
      </div>
      <div class="row hidden" id="rowApple">
        <span class="rname" id="nameApple">Apple</span>
        <span class="rprice" id="priceApple">$0.00</span>
      </div>
      <div class="row hidden" id="rowOrange">
        <span class="rname" id="nameOrange">Orange</span>
        <span class="rprice" id="priceOrange">$0.00</span>
      </div>
      <div class="row hidden" id="rowBanana">
        <span class="rname" id="nameBanana">Banana</span>
        <span class="rprice" id="priceBanana">$0.00</span>
      </div>
      <button class="btn" id="clear"><span class="btntext">Empty basket</span></button>
    </div>`, { width: 0.34, position: [0, 0.26, -0.27] });
  root.add(panel.object3D);

  // ---------- state ----------
  const KINDS = ['apple', 'orange', 'banana'];
  const counts = { apple: 0, orange: 0, banana: 0 };
  let basketCount = 0;
  let pulse = 0;

  function refreshPanel() {
    let total = 0;
    let n = 0;
    for (let i = 0; i < KINDS.length; i++) {
      const k = KINDS[i];
      const c = counts[k];
      const info = FRUIT_INFO[k];
      const cap = k.charAt(0).toUpperCase() + k.slice(1);
      n += c;
      const sub = c * info.price;
      total += sub;
      if (c > 0) {
        panel.set('row' + cap, { display: 'flex' });
        panel.set('name' + cap, { text: info.name + ' x' + c });
        panel.set('price' + cap, { text: '$' + sub.toFixed(2) });
      } else {
        panel.set('row' + cap, { display: 'none' });
      }
    }
    panel.set('total', { text: '$' + total.toFixed(2) });
    if (n === 0) {
      panel.set('hint', { text: 'Pinch a fruit and drop it into the basket.' });
    } else {
      panel.set('hint', { text: n + (n === 1 ? ' item' : ' items') + ' in the basket.' });
    }
  }

  // ---------- drop zone ----------
  const CAP_R2 = 0.085 * 0.085;

  function inBasket(p) {
    const dx = p.x - basketPos.x;
    const dz = p.z - basketPos.z;
    return dx * dx + dz * dz < CAP_R2 && p.y > 0.004 && p.y < 0.30;
  }

  function collect(f) {
    f.collected = true;
    const i = basketCount++;
    const layer = Math.min(Math.floor(i / 3), 2);
    const ring = i % 3;
    const ang = ring * 2.0944 + layer * 0.7;
    const r = layer === 0 ? 0.045 : 0.032;
    f.slot.set(
      basketPos.x + Math.cos(ang) * r,
      0.045 + layer * 0.055,
      basketPos.z + Math.sin(ang) * r,
    );
    f.group.position.copy(f.slot);
    counts[f.kind]++;
    pulse = 1;
    refreshPanel();
  }

  function resetBasket() {
    basketCount = 0;
    counts.apple = 0;
    counts.orange = 0;
    counts.banana = 0;
    for (let i = 0; i < fruits.length; i++) {
      const f = fruits[i];
      f.collected = false;
      if (!isGrabbed(f.group)) f.group.position.copy(f.start);
    }
    pulse = 0.7;
    refreshPanel();
  }

  panel.on('clear', 'click', resetBasket);
  refreshPanel();

  return {
    root,
    update(time, delta) {
      const d = delta > 0.05 ? 0.05 : delta;
      let hover = false;
      for (let i = 0; i < fruits.length; i++) {
        const f = fruits[i];
        const p = f.group.position;
        if (isGrabbed(f.group)) {
          if (!f.collected && inBasket(p)) hover = true;
          continue;
        }
        if (!f.collected) {
          if (inBasket(p)) collect(f);
        } else if (p.distanceToSquared(f.slot) > 1e-8) {
          p.copy(f.slot);
        }
      }
      pulse = Math.max(0, pulse - d * 2.2);
      rimMat.emissiveIntensity = (hover ? 0.55 : 0) + pulse * 1.1;
    },
  };
}

export default function build({ THREE, traits, ui }) {
  const root = new THREE.Group();

  const palette = [
