  root.add(housing);

  const buttonMaterial = new THREE.MeshStandardMaterial({
    color: palette[0].hex,
    emissive: palette[0].hex,
    emissiveIntensity: 1.1,
    roughness: 0.25,
    metalness: 0.12,
  });

  const button = new THREE.Mesh(
    new THREE.SphereGeometry(0.063, 32, 16, 0, Math.PI * 2, 0, Math.PI / 2),
    buttonMaterial,
  );
  button.name = 'Glowing color button';
  button.rotation.x = Math.PI / 2;
  button.position.set(-0.15, 0.135, 0.033);
  root.add(button);

  const trimMaterial = new THREE.MeshStandardMaterial({
    color: palette[0].hex,
    emissive: palette[0].hex,
    emissiveIntensity: 0.9,
    roughness: 0.3,
  });

  const trim = new THREE.Mesh(new THREE.TorusGeometry(0.073, 0.005, 12, 48), trimMaterial);
  trim.position.set(-0.15, 0.135, 0.035);
  root.add(trim);

  const pulseMaterial = new THREE.MeshBasicMaterial({
    color: palette[0].hex,
    transparent: true,
    opacity: 0,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
  });

  const pulseRing = new THREE.Mesh(new THREE.TorusGeometry(0.076, 0.0025, 8, 48), pulseMaterial);
  pulseRing.position.set(-0.15, 0.135, 0.038);
  pulseRing.visible = false;
  root.add(pulseRing);

  const info = ui(`
    <style>
      .card { width: 420px; flex-direction: column; gap: 12px; padding-top: 20px; padding-bottom: 20px;
              padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1f232a;
              border-color: #3a424e; border-width: 2px; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 22px; }
      .status { color: #22D3EE; font-size: 25px; font-weight: 700; }
      .count { color: #aeb6c2; font-size: 22px; }
    </style>
    <div class="card">
      <span class="title">Glowing color button</span>
      <span class="body">Poke or pinch the glowing button. Every press switches to a different color.</span>
      <span class="status" id="color">Current color: Cyan</span>
      <span class="count" id="presses">Presses: 0</span>
    </div>`, { width: 0.3, position: [0.18, 0.17, -0.01], rotationY: -0.18 });
  root.add(info.object3D);

  traits(button, {
    onPress: () => {
      colorIndex = (colorIndex + 1) % palette.length;
      pressCount += 1;
      pressAmount = 1;
      pulseAmount = 1;

      const selected = palette[colorIndex];
      buttonMaterial.color.setHex(selected.hex);
      buttonMaterial.emissive.setHex(selected.hex);
      trimMaterial.color.setHex(selected.hex);
      trimMaterial.emissive.setHex(selected.hex);
      pulseMaterial.color.setHex(selected.hex);

      info.set('color', {
        text: 'Current color: ' + selected.name,
        color: selected.css,
      });
      info.set('presses', { text: 'Presses: ' + pressCount });
    },
  });

  return {
    root,
    update(time, delta) {
      pressAmount = Math.max(0, pressAmount - delta * 4);
      pulseAmount = Math.max(0, pulseAmount - delta * 1.8);

      button.position.z = 0.033 - pressAmount * 0.008;
      buttonMaterial.emissiveIntensity =
        1.05 + Math.sin(time * 2.5) * 0.18 + pressAmount * 1.3;
      trimMaterial.emissiveIntensity = 0.8 + Math.sin(time * 2.5) * 0.15;

      pulseRing.visible = pulseAmount > 0.01;
      if (pulseRing.visible) {
        const ringScale = 1 + (1 - pulseAmount) * 0.65;
        pulseRing.scale.setScalar(ringScale);
        pulseMaterial.opacity = pulseAmount * 0.7;
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const clock = new THREE.Group();
  clock.name = 'Desk clock';
  clock.position.set(-0.135, 0.17, 0);
  root.add(clock);

  const body = new THREE.Mesh(
    new THREE.CylinderGeometry(0.112, 0.112, 0.046, 48, 1),
    new THREE.MeshStandardMaterial({ color: 0x343a43, roughness: 0.35, metalness: 0.65 }),
  );
  body.name = 'Clock housing';
  body.rotation.x = Math.PI / 2;
  clock.add(body);

  const face = new THREE.Mesh(
    new THREE.CylinderGeometry(0.099, 0.099, 0.004, 48, 1),
    new THREE.MeshStandardMaterial({ color: 0xf2f0e9, roughness: 0.8 }),
  );
  face.name = 'Clock face';
  face.rotation.x = Math.PI / 2;
  face.position.z = 0.025;
  clock.add(face);

  const rim = new THREE.Mesh(
    new THREE.TorusGeometry(0.105, 0.006, 8, 48),
    new THREE.MeshStandardMaterial({ color: 0x707983, roughness: 0.28, metalness: 0.8 }),
  );
  rim.position.z = 0.029;
  clock.add(rim);

  const markers = new THREE.InstancedMesh(
    new THREE.BoxGeometry(1, 1, 1),
    new THREE.MeshStandardMaterial({ color: 0x30343a, roughness: 0.7 }),
    60,
  );
  markers.name = 'Minute markers';
  const markerDummy = new THREE.Object3D();
  for (let i = 0; i < 60; i++) {
    const major = i % 5 === 0;
    const angle = (i / 60) * Math.PI * 2;
    const length = major ? 0.015 : 0.0075;
    const radius = 0.091 - length / 2;
    markerDummy.position.set(Math.sin(angle) * radius, Math.cos(angle) * radius, 0.031);
    markerDummy.rotation.set(0, 0, -angle);
    markerDummy.scale.set(major ? 0.0035 : 0.0018, length, major ? 0.0025 : 0.0018);
    markerDummy.updateMatrix();
    markers.setMatrixAt(i, markerDummy.matrix);
  }
  markers.instanceMatrix.needsUpdate = true;
  clock.add(markers);

  const handMaterial = new THREE.MeshStandardMaterial({ color: 0x20242a, roughness: 0.55 });
  const hourGeometry = new THREE.BoxGeometry(0.006, 0.052, 0.004);
  hourGeometry.translate(0, 0.026, 0);
  const hourHand = new THREE.Mesh(hourGeometry, handMaterial);
  hourHand.name = 'Hour hand';
  hourHand.position.z = 0.038;

  const minuteGeometry = new THREE.BoxGeometry(0.004, 0.075, 0.003);
  minuteGeometry.translate(0, 0.0375, 0);
  const minuteHand = new THREE.Mesh(minuteGeometry, handMaterial);
  minuteHand.name = 'Minute hand';
  minuteHand.position.z = 0.042;

  const hourPivot = new THREE.Group();
  const minutePivot = new THREE.Group();
  hourPivot.add(hourHand);
  minutePivot.add(minuteHand);
  clock.add(hourPivot, minutePivot);

  const centerPin = new THREE.Mesh(
    new THREE.SphereGeometry(0.006, 20, 12),
    new THREE.MeshStandardMaterial({ color: 0xe59a35, roughness: 0.35, metalness: 0.4 }),
  );
  centerPin.position.z = 0.045;
  clock.add(centerPin);

  const standMaterial = new THREE.MeshStandardMaterial({ color: 0x343a43, roughness: 0.4, metalness: 0.6 });
  const stem = new THREE.Mesh(new THREE.BoxGeometry(0.028, 0.052, 0.03), standMaterial);
  stem.position.set(0, -0.135, -0.005);
  clock.add(stem);

  const base = new THREE.Mesh(new THREE.BoxGeometry(0.17, 0.02, 0.085), standMaterial);
  base.name = 'Clock base';
  base.position.set(0, -0.16, 0);
  clock.add(base);

  const panel = ui(`
    <style>
      .card { display: flex; width: 440px; flex-direction: column; align-items: flex-start; gap: 12px;
              padding-top: 20px; padding-bottom: 20px; padding-left: 24px; padding-right: 24px;
              border-radius: 18px; background-color: #1f232a; border-color: #414852; border-width: 2px; }
      .title { color: #d7dbe2; font-size: 28px; font-weight: 700; }
      .time { color: #ffffff; font-size: 48px; font-weight: 700; }
      .period { color: #f0b45a; font-size: 24px; font-weight: 700; }
      .hint { color: #c5cbd4; font-size: 22px; }
      .btn { padding-top: 11px; padding-bottom: 11px; padding-left: 18px; padding-right: 18px;
             border-radius: 12px; background-color: #356bb0; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Desk clock</span>
      <span class="time" id="time">00:00</span>
      <span class="period" id="period">Local time - 24 hour</span>
      <button class="btn" id="mode"><span class="btn-text" id="mode-label">Use 12 hour</span></button>
      <span class="hint">Pinch the clock to move it. Tap the clock or press the button to switch format.</span>
    </div>`, { width: 0.29, position: [0.205, 0.17, 0.015], rotationY: -0.18 });
  root.add(panel.object3D);

  const date = new Date();
  let use24Hour = true;
  let shownHour = -1;
  let shownMinute = -1;

  function pad(value) {
    return value < 10 ? '0' + value : String(value);
  }

  function refreshTime(force) {
    const hours = date.getHours();
    const minutes = date.getMinutes();
    if (!force && hours === shownHour && minutes === shownMinute) return;

    shownHour = hours;
    shownMinute = minutes;

    minutePivot.rotation.z = -(minutes / 60) * Math.PI * 2;
    hourPivot.rotation.z = -(((hours % 12) + minutes / 60) / 12) * Math.PI * 2;

    const displayHour = use24Hour ? hours : (hours % 12 || 12);
    panel.set('time', { text: pad(displayHour) + ':' + pad(minutes) });
    panel.set('period', {
      text: use24Hour ? 'Local time - 24 hour' : (hours < 12 ? 'AM - local time' : 'PM - local time'),
    });
  }

  function toggleMode() {
    use24Hour = !use24Hour;
    panel.set('mode-label', { text: use24Hour ? 'Use 12 hour' : 'Use 24 hour' });
    refreshTime(true);
  }

  panel.on('mode', 'click', toggleMode);
  traits(clock, { grab: true, onPress: toggleMode });

  date.setTime(Date.now());
  refreshTime(true);

  return {
    root,
    update() {
      date.setTime(Date.now());
      refreshTime(false);
    },
  };
}

