      <div class="row">
        <button class="tag" id="pickouter" style="background-color:#f2d348"><span class="tagtext">3</span></button>
        <div class="details"><span class="layername">Outer core</span><span class="fact">Liquid iron and nickel, roughly 2,200 km thick. Its motion drives Earth's magnetic field.</span></div>
      </div>
      <div class="row">
        <button class="tag" id="pickinner" style="background-color:#ed7265"><span class="tagtext">4</span></button>
        <div class="details"><span class="layername">Inner core</span><span class="fact">Solid iron-nickel sphere with a radius of about 1,220 km and temperatures near 5,000-6,000 C.</span></div>
      </div>
      <button class="btn" id="rebuild"><span class="btntext" id="rebuildtext">Assemble Earth</span></button>
      <span class="note">A 90-degree wedge is removed. Crust thickness is exaggerated so it can be seen.</span>
    </div>`, { width: 0.34, position: [0.17, 0.245, -0.015], rotationY: -0.2 });
  root.add(info.object3D);

  const model = new THREE.Group();
  model.position.set(-0.205, 0.17, 0.025);
  root.add(model);

  const layerData = [
    {
      key: 'crust', name: 'Crust', inner: 0.135, outer: 0.16, color: 0x63a76f,
      highlight: 0x34653d, position: [-0.205, 0.17, 0.025], offset: [-0.038, 0.052, 0.005]
    },
    {
      key: 'mantle', name: 'Mantle', inner: 0.083, outer: 0.135, color: 0xe58b38,
      highlight: 0x74320d, position: [-0.205, 0.17, 0.025], offset: [0, -0.018, 0.022]
    },
    {
      key: 'outer', name: 'Outer core', inner: 0.031, outer: 0.083, color: 0xf1ca3e,
      highlight: 0x806000, position: [-0.205, 0.17, 0.025], offset: [0.012, 0.012, 0.04]
    },
    {
      key: 'inner', name: 'Inner core', inner: 0, outer: 0.031, color: 0xed7062,
      highlight: 0x7d201b, position: [-0.205, 0.17, 0.025], offset: [0.02, 0.024, 0.065]
    }
  ];

  function cutFace(innerRadius, outerRadius, theta, material, name) {
    const segments = 8;
    const positions = [];
    const indices = [];
    for (let j = 0; j <= segments; j++) {
      const polar = j * Math.PI / segments;
      const y = Math.cos(polar);
      const s = Math.sin(polar);
      positions.push(
        outerRadius * s * Math.cos(theta), outerRadius * y, outerRadius * s * Math.sin(theta),
        innerRadius * s * Math.cos(theta), innerRadius * y, innerRadius * s * Math.sin(theta)
      );
    }
    for (let j = 0; j < segments; j++) {
      const a = j * 2;
      const b = a + 1;
      const c = a + 2;
      const d = a + 3;
      indices.push(a, c, d, a, d, b);
    }
    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
    geometry.setIndex(indices);
    geometry.computeVertexNormals();
    const mesh = new THREE.Mesh(geometry, material);
    mesh.name = name;
    return mesh;
  }

  const pickMeshes = [];
  const layers = [];
  const baseColors = [0x63a76f, 0xe58b38, 0xf1ca3e, 0xed7062];

  function makeCutLayer(data, index, parent) {
    const group = new THREE.Group();
    group.name = data.name;
    const material = new THREE.MeshStandardMaterial({
      color: data.color,
      roughness: index === 2 ? 0.32 : 0.66,
      metalness: index >= 2 ? 0.25 : 0.03,
      emissive: 0x000000,
      emissiveIntensity: 0,
      side: THREE.DoubleSide
    });
    const outer = new THREE.Mesh(
      new THREE.SphereGeometry(data.outer, 36, 20, -Math.PI / 2, Math.PI * 1.5, 0, Math.PI),
      material
    );
    outer.name = data.name;
    group.add(outer);
    const picks = [outer];

    if (data.inner > 0) {
      const inner = new THREE.Mesh(
        new THREE.SphereGeometry(data.inner, 32, 18, -Math.PI / 2, Math.PI * 1.5, 0, Math.PI),
        material
      );
      group.add(inner);
      picks.push(inner);
    }

    const faceA = cutFace(data.inner, data.outer, -Math.PI / 2, material);
    const faceB = cutFace(data.inner, data.outer, Math.PI, material);
    group.add(faceA, faceB);
    picks.push(faceA, faceB);

    parent.add(group);
    const record = { group, material, data, picks, assembled: true, home: new THREE.Vector3().fromArray(data.position) };
    layers.push(record);
    for (let i = 0; i < picks.length; i++) {
      pickMeshes.push({ mesh: picks[i], index });
    }
    return record;
  }

  for (let i = 0; i < layerData.length; i++) {
    makeCutLayer(layerData[i], i, model);
  }

  // Interactive, directly attached duplicates are used only while exploring the separated layers.
  const looseLayers = [];
  for (let i = 0; i < layerData.length; i++) {
    const group = new THREE.Group();
    group.name = layerData[i].name + ' selection';
    group.position.fromArray(layerData[i].position);
    group.visible = false;
    root.add(group);
    const material = new THREE.MeshStandardMaterial({
      color: baseColors[i], roughness: 0.6, metalness: i >= 2 ? 0.22 : 0,
      emissive: 0x000000, emissiveIntensity: 0, side: THREE.DoubleSide
    });
    const radius = Math.max(0.017, layerData[i].outer * 0.55);
    const marker = new THREE.Mesh(new THREE.SphereGeometry(radius, 20, 12), material);
    marker.name = layerData[i].name;
    group.add(marker);
    const record = { group, material, index: i, start: new THREE.Vector3(), target: new THREE.Vector3() };
    looseLayers.push(record);
    traits(group, {
      onPress: () => selectLayer(i)
    });
  }

  const glow = new THREE.PointLight(0xffc66d, 0.12, 0.8);
  glow.position.set(-0.205, 0.17, 0.11);
  root.add(glow);

  let selected = -1;
  let separated = false;
  function selectLayer(index) {
    selected = index;
    for (let i = 0; i < layers.length; i++) {
      layers[i].material.emissive.setHex(i === index ? layerData[i].highlight : 0x000000);
      layers[i].material.emissiveIntensity = i === index ? 0.55 : 0;
      looseLayers[i].material.emissive.setHex(i === index ? layerData[i].highlight : 0x000000);
      looseLayers[i].material.emissiveIntensity = i === index ? 0.55 : 0;
    }
  }

  for (let i = 0; i < pickMeshes.length; i++) {
    // These nested meshes are not registered with traits; their labelled partners are direct children.
    pickMeshes[i].mesh.userData.layerIndex = pickMeshes[i].index;
  }

  const pickerLayers = [];
  for (let i = 0; i < layerData.length; i++) {
    const material = new THREE.MeshStandardMaterial({
      color: baseColors[i], roughness: 0.6, metalness: i >= 2 ? 0.22 : 0,
      emissive: 0x000000, emissiveIntensity: 0
    });
    const picker = new THREE.Mesh(new THREE.SphereGeometry(0.013, 16, 10), material);
    picker.name = layerData[i].name + ' button';
    const positions = [
      [-0.33, 0.29, 0.035],
      [-0.285, 0.245, 0.055],
      [-0.22, 0.205, 0.075],
      [-0.19, 0.17, 0.065]
    ];
    picker.position.fromArray(positions[i]);
    root.add(picker);
    pickerLayers.push({ mesh: picker, material });
    traits(picker, { onPress: () => selectLayer(i) });
  }

  info.on('pickcrust', 'click', () => selectLayer(0));
  info.on('pickmantle', 'click', () => selectLayer(1));
  info.on('pickouter', 'click', () => selectLayer(2));
  info.on('pickinner', 'click', () => selectLayer(3));
  info.on('rebuild', 'click', () => {
    separated = !separated;
    info.set('rebuildtext', { text: separated ? 'Reassemble layers' : 'Assemble Earth' });
    for (let i = 0; i < layers.length; i++) {
      layers[i].group.visible = !separated;
      looseLayers[i].group.visible = separated;
      looseLayers[i].start.copy(looseLayers[i].group.position);
      looseLayers[i].target.fromArray(layerData[i].position);
      if (separated) {
        looseLayers[i].target.x += layerData[i].offset[0];
        looseLayers[i].target.y += layerData[i].offset[1];
        looseLayers[i].target.z += layerData[i].offset[2];
      }
    }
    for (let i = 0; i < pickerLayers.length; i++) {
      pickerLayers[i].mesh.visible = !separated;
    }
  });

  function update(time, delta) {
    if (!separated) {
      model.rotation.y = Math.sin(time * 0.28) * 0.055;
    }
    for (let i = 0; i < looseLayers.length; i++) {
      const item = looseLayers[i];
      if (!item.group.visible || isGrabbed(item.group)) continue;
      const blend = Math.min(1, delta * 5);
      item.group.position.lerp(item.target, blend);
      item.group.rotation.y += delta * (0.16 + i * 0.03);
    }
    for (let i = 0; i < layers.length; i++) {
      const active = selected === i;
      layers[i].material.emissiveIntensity = active ? 0.42 + Math.sin(time * 3) * 0.12 : 0;
      looseLayers[i].material.emissiveIntensity = active ? 0.42 + Math.sin(time * 3) * 0.12 : 0;
      pickerLayers[i].material.emissive.setHex(active ? layerData[i].highlight : 0x000000);
      pickerLayers[i].material.emissiveIntensity = active ? 0.5 : 0;
    }
  }

  return { root, update };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // A transparent hit volume makes the entire helix easy to pinch.
  const helix = new THREE.Mesh(
    new THREE.CylinderGeometry(0.072, 0.072, 0.326, 16, 1, false),
    new THREE.MeshBasicMaterial({
      transparent: true,
      opacity: 0,
      depthWrite: false,
      side: THREE.DoubleSide,
    }),
  );
  helix.name = 'DNA double helix';
  helix.position.set(-0.085, 0.205, 0);
  root.add(helix);

  const radius = 0.058;
  const halfHeight = 0.147;
  const pairCount = 22;
  const angleStep = (Math.PI * 2) / 10.5;
  const baseColors = {
    A: 0x48c774,
    T: 0xe85d75,
    C: 0x4fa3ff,
    G: 0xf2c14e,
  };
  const complement = { A: 'T', T: 'A', C: 'G', G: 'C' };
  const sequence = [
    'A', 'C', 'G', 'T', 'A', 'G', 'C', 'T', 'G', 'A', 'T',
    'C', 'A', 'G', 'T', 'C', 'G', 'A', 'C', 'T', 'A', 'G',
  ];

  const pairs = sequence.map((base1, i) => ({
    base1,
    base2: complement[base1],
    type: base1 === 'A' || base1 === 'T' ? 'AT' : 'GC',
    bonds: base1 === 'A' || base1 === 'T' ? 2 : 3,
    theta: i * angleStep,
    y: -halfHeight + (i * halfHeight * 2) / (pairCount - 1),
  }));

  // Smooth sugar-phosphate backbones: two full turns of B-DNA.
  const strandColors = [0x63d8ff, 0xb394ff];
  for (let strand = 0; strand < 2; strand++) {
    const points = [];
    const samples = 160;
    for (let s = 0; s <= samples; s++) {
      const t = s / samples;
      const theta = t * Math.PI * 4 + strand * Math.PI;
      points.push(new THREE.Vector3(
        Math.cos(theta) * radius,
        -halfHeight + t * halfHeight * 2,
        Math.sin(theta) * radius,
      ));
    }
    const curve = new THREE.CatmullRomCurve3(points);
    const backbone = new THREE.Mesh(
      new THREE.TubeGeometry(curve, 160, 0.0052, 8, false),
      new THREE.MeshStandardMaterial({
        color: strandColors[strand],
        emissive: strandColors[strand],
        emissiveIntensity: 0.12,
        roughness: 0.34,
        metalness: 0.12,
      }),
    );
    backbone.name = strand === 0 ? 'Backbone A' : 'Backbone B';
    helix.add(backbone);
  }

  const nodeGeometry = new THREE.SphereGeometry(0.0072, 12, 8);
  const nodeMaterial = new THREE.MeshStandardMaterial({
    color: 0xffffff,
    roughness: 0.32,
    metalness: 0.1,
  });
  const nodes = new THREE.InstancedMesh(nodeGeometry, nodeMaterial, pairCount * 2);
  nodes.name = 'Sugar phosphate nodes';
  helix.add(nodes);

  const unitCylinder = new THREE.CylinderGeometry(1, 1, 1, 8, 1, false);
  const bases = new THREE.InstancedMesh(
    unitCylinder,
    new THREE.MeshStandardMaterial({
      color: 0xffffff,
      roughness: 0.38,
      metalness: 0.04,
    }),
    pairCount * 2,
  );
  bases.name = 'Color coded base pairs';
  helix.add(bases);

  const bondCount = pairs.reduce((sum, pair) => sum + pair.bonds, 0);
  const bondGeometry = new THREE.CylinderGeometry(1, 1, 1, 6, 1, false);
  const bonds = new THREE.InstancedMesh(
    bondGeometry,
    new THREE.MeshStandardMaterial({
      color: 0xffffff,
      roughness: 0.25,
      metalness: 0.05,
    }),
    bondCount,
  );
  bonds.name = 'Hydrogen bonds';
  helix.add(bonds);

  const up = new THREE.Vector3(0, 1, 0);
  const direction = new THREE.Vector3();
  const midpoint = new THREE.Vector3();
  const quaternion = new THREE.Quaternion();
  const scale = new THREE.Vector3();
  const matrix = new THREE.Matrix4();
  const dummy = new THREE.Object3D();
  const color = new THREE.Color();

  function setCylinder(mesh, index, a, b, thickness) {
    direction.subVectors(b, a);
    const length = direction.length();
    midpoint.copy(a).add(b).multiplyScalar(0.5);
    quaternion.setFromUnitVectors(up, direction.normalize());
    scale.set(thickness, length, thickness);
    matrix.compose(midpoint, quaternion, scale);
    mesh.setMatrixAt(index, matrix);
  }

  let nodeIndex = 0;
  let baseIndex = 0;
  let bondIndex = 0;
  const gapRadius = 0.009;

  pairs.forEach((pair) => {
    const c = Math.cos(pair.theta);
    const s = Math.sin(pair.theta);
    const p1 = new THREE.Vector3(c * radius, pair.y, s * radius);
    const p2 = new THREE.Vector3(-c * radius, pair.y, -s * radius);
    const inner1 = new THREE.Vector3(c * gapRadius, pair.y, s * gapRadius);
    const inner2 = new THREE.Vector3(-c * gapRadius, pair.y, -s * gapRadius);

    [p1, p2].forEach((position, strand) => {
      dummy.position.copy(position);
      dummy.quaternion.identity();
      dummy.scale.set(1, 1, 1);
      dummy.updateMatrix();
      nodes.setMatrixAt(nodeIndex, dummy.matrix);
      nodes.setColorAt(nodeIndex, color.setHex(strandColors[strand]));
      nodeIndex++;
    });

    setCylinder(bases, baseIndex++, p1, inner1, 0.0055);
    setCylinder(bases, baseIndex++, p2, inner2, 0.0055);

    for (let j = 0; j < pair.bonds; j++) {
      const yOffset = (j - (pair.bonds - 1) / 2) * 0.005;
      const a = inner1.clone();
      const b = inner2.clone();
      a.y += yOffset;
      b.y += yOffset;
      setCylinder(bonds, bondIndex++, a, b, 0.00125);
    }
  });

  nodes.instanceMatrix.needsUpdate = true;
  nodes.instanceColor.needsUpdate = true;
  bases.instanceMatrix.needsUpdate = true;
  bonds.instanceMatrix.needsUpdate = true;
  nodes.computeBoundingSphere();
  bases.computeBoundingSphere();
  bonds.computeBoundingSphere();

  const panel = ui(`
    <style>
      .card { display: flex; width: 500px; flex-direction: column; gap: 12px;
              padding-top: 18px; padding-bottom: 18px; padding-left: 22px; padding-right: 22px;
              border-radius: 18px; border-width: 1px; border-color: #454d59;
              background-color: #1f232a; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .body { color: #e1e6ed; font-size: 22px; }
      .legend { color: #bfc9d6; font-size: 22px; }
      .detail { color: #d7dbe2; font-size: 22px; }
      .row { display: flex; flex-direction: row; gap: 9px; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 15px; padding-right: 15px;
             border-radius: 11px; background-color: #303742; }
      .primary { padding-top: 10px; padding-bottom: 10px; padding-left: 15px; padding-right: 15px;
                 border-radius: 11px; background-color: #2f6fdb; }
      .btn-text { color: #ffffff; font-size: 21px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">DNA double helix</span>
      <span class="body">Pinch the DNA to pick it up. Turn your wrist to inspect it from any angle.</span>
      <span class="legend">A = green, T = red, C = blue, G = gold</span>
      <div class="row">
        <button class="btn" id="at"><span class="btn-text">A-T pairs</span></button>
        <button class="btn" id="gc"><span class="btn-text">G-C pairs</span></button>
        <button class="btn" id="all"><span class="btn-text">Show all</span></button>
      </div>
      <span class="detail" id="detail">A pairs with T, and G pairs with C. The pale connectors are hydrogen bonds.</span>
      <div class="row">
        <button class="primary" id="fact"><span class="btn-text">Next fact</span></button>
        <button class="btn" id="reset"><span class="btn-text">Reset pose</span></button>
      </div>
    </div>`, {
    width: 0.32,
    position: [0.255, 0.205, 0.01],
    rotationY: -0.28,
  });
  root.add(panel.object3D);

  function highlight(kind) {
    let bi = 0;
    let hi = 0;
    const dim = 0x30353d;

    pairs.forEach((pair) => {
      const active = kind === 'all' || kind === pair.type;
      bases.setColorAt(bi++, color.setHex(active ? baseColors[pair.base1] : dim));
      bases.setColorAt(bi++, color.setHex(active ? baseColors[pair.base2] : dim));
      for (let j = 0; j < pair.bonds; j++) {
        bonds.setColorAt(hi++, color.setHex(active ? 0xe5f2ff : 0x20252c));
      }
    });

    bases.instanceColor.needsUpdate = true;
    bonds.instanceColor.needsUpdate = true;
    panel.set('at', { backgroundColor: kind === 'AT' ? '#28583e' : '#303742' });
    panel.set('gc', { backgroundColor: kind === 'GC' ? '#304f78' : '#303742' });
    panel.set('all', { backgroundColor: kind === 'all' ? '#2f6fdb' : '#303742' });
  }

  highlight('all');

  panel.on('at', 'click', () => {
    highlight('AT');
    panel.set('detail', {
      text: 'Adenine pairs with thymine using 2 hydrogen bonds. The bright rungs are A-T pairs.',
    });
  });

  panel.on('gc', 'click', () => {
    highlight('GC');
    panel.set('detail', {
      text: 'Guanine pairs with cytosine using 3 hydrogen bonds. The bright rungs are G-C pairs.',
    });
  });

  panel.on('all', 'click', () => {
    highlight('all');
    panel.set('detail', {
      text: 'A pairs with T, and G pairs with C. The pale connectors are hydrogen bonds.',
    });
  });

  const facts = [
    'The sugar-phosphate backbones are outside; the nitrogenous bases point inward.',
    'The strands are antiparallel: one runs 5\' to 3\', while the other runs 3\' to 5\'.',
    'B-DNA makes one full turn about every 10.5 base pairs. This model shows 2 turns.',
    'The bases are adenine, thymine, cytosine and guanine.',
    'Complementary base pairing lets each strand serve as a template during DNA replication.',
  ];
  let factIndex = -1;
  panel.on('fact', 'click', () => {
    factIndex = (factIndex + 1) % facts.length;
    panel.set('detail', { text: facts[factIndex] });
  });

  const homePosition = helix.position.clone();
  const homeQuaternion = helix.quaternion.clone();
  panel.on('reset', 'click', () => {
    helix.position.copy(homePosition);
    helix.quaternion.copy(homeQuaternion);
    helix.scale.set(1, 1, 1);
    panel.set('detail', { text: 'View reset. Pinch the DNA and turn your wrist to explore it.' });
  });

  traits(helix, { grab: true });

  return { root };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

