  const homeQuaternion = dna.quaternion.clone();

  const sequence = 'ATGCCGTAAGCTTAGCGATCCG';
  const complement = { A: 'T', T: 'A', G: 'C', C: 'G' };
  const pairCount = sequence.length;
  const height = 0.35;
  const radius = 0.058;
  const angleStep = Math.PI * 2 / 10.5;

  const strandAPoints = [];
  const strandBPoints = [];

  for (let i = 0; i < pairCount; i++) {
    const angle = i * angleStep;
    const y = i * height / (pairCount - 1);
    const c = Math.cos(angle) * radius;
    const s = Math.sin(angle) * radius;

    // Negative Z rotation with increasing Y makes a right-handed helix.
