    G: new THREE.InstancedMesh(baseGeometry, baseMaterials.G, pairCount),
    C: new THREE.InstancedMesh(baseGeometry, baseMaterials.C, pairCount),
  };
  baseMeshes.A.name = 'Adenine bases';
  baseMeshes.T.name = 'Thymine bases';
  baseMeshes.G.name = 'Guanine bases';
  baseMeshes.C.name = 'Cytosine bases';

  const pairs = [];
  let totalBonds = 0;
  for (let i = 0; i < pairCount; i++) {
    const first = sequence[i];
    const second = complement[first];
    const bondCount = first === 'A' || first === 'T' ? 2 : 3;
    pairs.push({ first, second, bondCount });
    totalBonds += bondCount;
  }

  const hydrogenBonds = new THREE.InstancedMesh(bondGeometry, bondMaterial, totalBonds);
  hydrogenBonds.name = 'Hydrogen bonds between base pairs';

  const dummy = new THREE.Object3D();
  const up = new THREE.Vector3(0, 1, 0);
  const direction = new THREE.Vector3();

  function setPoint(mesh, index, point, scale) {
    dummy.position.copy(point);
    dummy.quaternion.identity();
    dummy.scale.setScalar(scale);
    dummy.updateMatrix();
    mesh.setMatrixAt(index, dummy.matrix);
  }

  function setSegment(mesh, index, start, end) {
    direction.subVectors(end, start);
    const length = direction.length();
    dummy.position.copy(start).add(end).multiplyScalar(0.5);
    dummy.quaternion.setFromUnitVectors(up, direction.normalize());
    dummy.scale.set(1, length, 1);
    dummy.updateMatrix();
    mesh.setMatrixAt(index, dummy.matrix);
  }

  for (let i = 0; i < pairCount; i++) {
    const endScale = i === 0 || i === pairCount - 1 ? 1.2 : 1;
    setPoint(beadsA, i, strandAPoints[i], endScale);
    setPoint(beadsB, i, strandBPoints[i], endScale);
  }

  let phosphateIndex = 0;
  for (let i = 0; i < pairCount - 1; i++) {
    setSegment(linksA, i, strandAPoints[i], strandAPoints[i + 1]);
    setSegment(linksB, i, strandBPoints[i], strandBPoints[i + 1]);

    const phosphateA = strandAPoints[i].clone().lerp(strandAPoints[i + 1], 0.5);
    const phosphateB = strandBPoints[i].clone().lerp(strandBPoints[i + 1], 0.5);
    setPoint(phosphates, phosphateIndex++, phosphateA, 1);
    setPoint(phosphates, phosphateIndex++, phosphateB, 1);
  }

  const baseIndices = { A: 0, T: 0, G: 0, C: 0 };
  let bondIndex = 0;
  const centralGap = 0.01;

  for (let i = 0; i < pairCount; i++) {
    const pair = pairs[i];
    const pointA = strandAPoints[i];
    const pointB = strandBPoints[i];
    const axis = pointB.clone().sub(pointA).normalize();
    const center = pointA.clone().add(pointB).multiplyScalar(0.5);

    const startA = pointA.clone().addScaledVector(axis, 0.004);
    const endA = center.clone().addScaledVector(axis, -centralGap * 0.5);
    const startB = pointB.clone().addScaledVector(axis, -0.004);
    const endB = center.clone().addScaledVector(axis, centralGap * 0.5);

    setSegment(baseMeshes[pair.first], baseIndices[pair.first]++, startA, endA);
    setSegment(baseMeshes[pair.second], baseIndices[pair.second]++, startB, endB);

    const angle = i * angleStep;
    const tangent = new THREE.Vector3(-Math.sin(angle), 0, -Math.cos(angle));

    for (let b = 0; b < pair.bondCount; b++) {
      const offset = (b - (pair.bondCount - 1) * 0.5) * 0.004;
      const bondStart = endA.clone().addScaledVector(tangent, offset);
      const bondEnd = endB.clone().addScaledVector(tangent, offset);
      setSegment(hydrogenBonds, bondIndex++, bondStart, bondEnd);
    }
  }

  const instancedMeshes = [
    beadsA, beadsB, linksA, linksB, phosphates,
    baseMeshes.A, baseMeshes.T, baseMeshes.G, baseMeshes.C,
    hydrogenBonds,
  ];

  for (const key of Object.keys(baseMeshes)) {
    baseMeshes[key].count = baseIndices[key];
  }

  for (const mesh of instancedMeshes) {
    mesh.instanceMatrix.needsUpdate = true;
    mesh.computeBoundingSphere();
    dna.add(mesh);
  }

  traits(dna, { grab: true });

  const restingStatus = {
    text: 'Pinch and hold the helix. Move your hand to lift it, then turn your wrist to inspect both sides.',
  };
  const holdingStatus = {
    text: 'You are holding DNA. Rotate your wrist to examine the backbone and base-pair rungs.',
  };

  const info = ui(`
    <style>
      .card { width: 500px; display: flex; flex-direction: column; gap: 12px;
              padding-top: 20px; padding-bottom: 20px; padding-left: 22px; padding-right: 22px;
              border-radius: 18px; border-width: 1px; border-color: #3c4855;
              background-color: #1b2027; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .status { color: #d9e1e9; font-size: 22px; }
      .key { display: flex; flex-direction: row; align-items: center; gap: 9px; }
      .pill { width: 38px; height: 34px; text-align: center; font-size: 21px;
              font-weight: 700; border-radius: 8px; padding-top: 5px; }
      .a { color: #07180f; background-color: #4dcc88; }
      .t { color: #260a09; background-color: #ef706c; }
      .g { color: #251b05; background-color: #f2c14e; }
      .c { color: #ffffff; background-color: #608ff0; }
      .join { color: #b9c3ce; font-size: 20px; }
      .bond { color: #e7edf3; font-size: 21px; font-weight: 700; }
      .fact { color: #bfcbd6; font-size: 22px; }
      .buttons { display: flex; flex-direction: row; gap: 10px; }
      .btn { display: flex; align-items: center; justify-content: center;
             padding-top: 11px; padding-bottom: 11px; padding-left: 12px; padding-right: 12px;
             border-radius: 12px; border-width: 1px; }
      .next { width: 220px; background-color: #316fa8; border-color: #5b96c8; }
      .reset { width: 190px; background-color: #2b333d; border-color: #526171; }
      .btn-text { color: #ffffff; font-size: 21px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">DNA double helix</span>
      <span class="status" id="status">Pinch and hold the helix. Move your hand to lift it, then turn your wrist to inspect both sides.</span>
      <div class="key">
        <span class="pill a">A</span>
        <span class="join">pairs with</span>
        <span class="pill t">T</span>
        <span class="bond">2 H bonds</span>
      </div>
      <div class="key">
        <span class="pill g">G</span>
        <span class="join">pairs with</span>
        <span class="pill c">C</span>
        <span class="bond">3 H bonds</span>
      </div>
      <span class="fact" id="fact">A is adenine, T is thymine, G is guanine and C is cytosine. They form the colored base-pair rungs.</span>
      <div class="buttons">
        <button class="btn next" id="next"><span class="btn-text">Next fact</span></button>
        <button class="btn reset" id="reset"><span class="btn-text">Reset position</span></button>
      </div>
    </div>`, {
    width: 0.32,
    position: [0.19, 0.25, 0],
    rotationY: -0.28,
  });
  root.add(info.object3D);

  const facts = [
    'A is adenine, T is thymine, G is guanine and C is cytosine. They form the colored base-pair rungs.',
    'A-T base pairs have 2 hydrogen bonds. G-C pairs have 3, shown by the small pale links.',
    "The strands are antiparallel: one runs 5' to 3', the other 3' to 5'.",
    'This is right-handed B-DNA. The model averages 10.5 base pairs per turn, like B-DNA in cells.',
    'The sequence on one strand is ATGCCGTAAGCTTAGCGATCCG. Its order carries genetic information.',
  ];
  let factIndex = 0;

  info.on('next', 'click', () => {
    factIndex = (factIndex + 1) % facts.length;
    info.set('fact', { text: facts[factIndex] });
  });

  info.on('reset', 'click', () => {
    if (!isGrabbed(dna)) {
      dna.position.copy(homePosition);
      dna.quaternion.copy(homeQuaternion);
      info.set('status', restingStatus);
    }
  });

  let wasGrabbed = false;

  return {
    root,
    update(time) {
      const grabbed = isGrabbed(dna);
      if (grabbed !== wasGrabbed) {
        wasGrabbed = grabbed;
        info.set('status', grabbed ? holdingStatus : restingStatus);
        strandAMaterial.emissiveIntensity = grabbed ? 0.5 : 0.18;
        strandBMaterial.emissiveIntensity = grabbed ? 0.5 : 0.18;
      }
      bondMaterial.emissiveIntensity = 0.3 + Math.sin(time * 2) * 0.08;
    },
  };
}

