    new THREE.Vector3(-0.025, 0.004, -0.115),
    new THREE.Vector3(0.02, 0.004, -0.135),
  ]);
  const cord = new THREE.Mesh(
    new THREE.TubeGeometry(cordCurve, 24, 0.0025, 8, false),
    darkMetal,
  );
  cord.name = 'Power cord';
