  const beamMaterial = new THREE.MeshBasicMaterial({
    color: 0xffd78a,
    transparent: true,
    opacity: 0.07,
    depthWrite: false,
    side: THREE.DoubleSide,
    blending: THREE.AdditiveBlending,
  });
  const beam = new THREE.Mesh(
    new THREE.ConeGeometry(0.09, 0.21, 48, 1, true),
    beamMaterial,
  );
  beam.name = 'Visible light beam';
  beam.position.y = -0.125;
  head.add(beam);

  const poolOpacities = [0.035, 0.055, 0.075];
  const poolRadii = [0.12, 0.09, 0.06];
  const pools = [];
  for (let i = 0; i < 3; i++) {
    const material = new THREE.MeshBasicMaterial({
      color: 0xffd98f,
      transparent: true,
      opacity: poolOpacities[i],
      depthWrite: false,
      blending: THREE.AdditiveBlending,
    });
    const pool = new THREE.Mesh(new THREE.CircleGeometry(poolRadii[i], 48), material);
    pool.name = 'Desk light pool';
    pool.rotation.x = -Math.PI / 2;
    pool.position.set(-0.06, 0.0015 + i * 0.0005, 0.056);
    root.add(pool);
    pools.push(pool);
  }

  const panel = ui(`
    <style>
      .card { width: 440px; display: flex; flex-direction: column; gap: 12px;
