      .status { color: #ffd166; font-size: 28px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 23px; }
      .button { padding-top: 11px; padding-bottom: 11px; padding-left: 16px; padding-right: 16px;
                border-radius: 12px; background-color: #356f6b; }
      .button-text { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Desk lamp</span>
      <span class="status" id="status">Light: ON</span>
      <span class="body" id="hint">Press any part of the lamp to switch it off.</span>
      <button class="button" id="power"><span class="button-text" id="powerText">Switch off</span></button>
    </div>`, {
    width: 0.28,
    position: [0.22, 0.18, -0.02],
    rotationY: -0.28,
  });
  root.add(panel.object3D);

  let on = true;
  let level = 1;

  function togglePower() {
    on = !on;
    panel.set('status', {
      text: on ? 'Light: ON' : 'Light: OFF',
      color: on ? '#ffd166' : '#aeb5bf',
    });
    panel.set('hint', {
      text: on
        ? 'Press any part of the lamp to switch it off.'
        : 'Press any part of the lamp to switch it on.',
    });
    panel.set('powerText', { text: on ? 'Switch off' : 'Switch on' });
  }

  traits(lamp, { onPress: togglePower });
  panel.on('power', 'click', togglePower);

  return {
    root,
    update(time, delta) {
      const target = on ? 1 : 0;
      level += (target - level) * Math.min(1, delta * 10);
      if (Math.abs(target - level) < 0.001) level = target;

      bulbMaterial.emissiveIntensity = 0.02 + level * 2.38;
      innerMaterial.emissiveIntensity = 0.01 + level * 0.81;
      switchMaterial.emissiveIntensity = level * 0.7;
      switchMaterial.color.setRGB(
        0.16 + level * 0.68,
        0.17 + level * 0.38,
        0.16 + level * 0.04,
      );

      beam.visible = level > 0.002;
      beamMaterial.opacity = level * 0.07;
      for (let i = 0; i < pools.length; i++) {
        pools[i].visible = level > 0.002;
        pools[i].material.opacity = level * poolOpacities[i];
      }
    },
  };
}

