    const displayHour = use12Hour ? (hour24 % 12 || 12) : pad2(hour24);

    panel.set('time', { text: displayHour + ':' + pad2(minute) });
    panel.set('period', { text: use12Hour ? (hour24 < 12 ? 'AM' : 'PM') : '24 HOUR' });
    panel.set('format-label', { text: use12Hour ? 'Use 24 hour' : 'Use 12 hour' });

    paintedMinutes = currentMinutes;
    paintedMode = use12Hour;
  }

  function toggleFormat() {
    use12Hour = !use12Hour;
    paintReadout();
  }

  function setClockTime(dayMs) {
    const wrapped = ((dayMs % DAY_MS) + DAY_MS) % DAY_MS;
    const hourAngle = ((wrapped / 43200000) % 1) * TAU;
    const minuteAngle = ((wrapped % 3600000) / 3600000) * TAU;

    hourHand.rotation.z = -hourAngle;
    minuteHand.rotation.z = -minuteAngle;

    currentMinutes = Math.floor(wrapped / 60000);
    paintReadout();
  }

  traits(clock, { onPress: toggleFormat });
  panel.on('format', 'click', toggleFormat);

  setClockTime(initialDayMs);

  return {
    root,
    update(time) {
      if (originTime === null) originTime = time;
      const elapsedMs = Math.max(0, time - originTime) * 1000;
      setClockTime(initialDayMs + elapsedMs);
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // A small potted plant: soil and roots below, stem and leaves above.
  const pot = new THREE.Group();
  pot.position.set(-0.06, 0, 0);
  root.add(pot);

  const potMat = new THREE.MeshStandardMaterial({ color: 0xb9683f, roughness: 0.85 });
  const soilMat = new THREE.MeshStandardMaterial({ color: 0x38251b, roughness: 1 });
  const stemMat = new THREE.MeshStandardMaterial({ color: 0x3d9b4f, roughness: 0.65 });
  const leafMat = new THREE.MeshStandardMaterial({ color: 0x55b95b, roughness: 0.6 });
  const leafLightMat = new THREE.MeshStandardMaterial({ color: 0x79cf63, roughness: 0.6 });

  const potBody = new THREE.Mesh(new THREE.CylinderGeometry(0.044, 0.034, 0.06, 24), potMat);
  potBody.position.y = 0.034;
  pot.add(potBody);

  const potRim = new THREE.Mesh(new THREE.CylinderGeometry(0.048, 0.048, 0.014, 24), potMat);
  potRim.position.y = 0.065;
  pot.add(potRim);

  const soil = new THREE.Mesh(new THREE.CylinderGeometry(0.043, 0.043, 0.005, 24), soilMat);
  soil.position.y = 0.072;
  soil.name = 'Soil';
  pot.add(soil);

  const stem = new THREE.Mesh(new THREE.CylinderGeometry(0.005, 0.007, 0.145, 12), stemMat);
  stem.position.set(0, 0.143, 0);
  stem.name = 'Stem';
  pot.add(stem);

  const leafGeometry = new THREE.SphereGeometry(1, 24, 12);
  const leaves = [];

  function addLeaf(name, x, y, z, sx, sy, sz, rz, material) {
    const leaf = new THREE.Mesh(leafGeometry, material);
    leaf.name = name;
    leaf.position.set(x, y, z);
    leaf.scale.set(sx, sy, sz);
    leaf.rotation.z = rz;
    leaf.rotation.y = rz * 0.25;
    pot.add(leaf);
    leaves.push(leaf);
    return leaf;
  }

  addLeaf('Left lower leaf', -0.039, 0.145, 0.006, 0.043, 0.014, 0.021, 0.48, leafMat);
  addLeaf('Right lower leaf', 0.039, 0.172, -0.004, 0.045, 0.015, 0.022, -0.45, leafLightMat);
  addLeaf('Left upper leaf', -0.032, 0.201, -0.008, 0.036, 0.012, 0.018, 0.63, leafLightMat);
  addLeaf('Top leaf', 0.008, 0.23, 0, 0.033, 0.012, 0.018, 1.15, leafMat);

  // Subtle vein across the largest leaf.
  const vein = new THREE.Mesh(
    new THREE.CylinderGeometry(0.0012, 0.0012, 0.068, 8),
    new THREE.MeshStandardMaterial({ color: 0xb5df72, roughness: 0.7 })
  );
  vein.position.set(0.039, 0.172, 0.017);
  vein.rotation.z = Math.PI / 2 - 0.45;
  pot.add(vein);

  // Sun, with reusable tapered rays.
  const sun = new THREE.Group();
  sun.name = 'Sun';
  sun.position.set(-0.27, 0.34, -0.02);
  root.add(sun);

  const sunMat = new THREE.MeshStandardMaterial({
    color: 0xffcf45,
    emissive: 0xff9d18,
    emissiveIntensity: 0.65,
    roughness: 0.7
  });
  const sunSphere = new THREE.Mesh(new THREE.SphereGeometry(0.038, 24, 16), sunMat);
  sun.add(sunSphere);

  const rayMat = new THREE.MeshStandardMaterial({
    color: 0xffb829,
    emissive: 0xff8e12,
    emissiveIntensity: 0.5,
    roughness: 0.7
  });
  const rayGeo = new THREE.CylinderGeometry(0.0025, 0.004, 0.022, 8);
  for (let i = 0; i < 10; i++) {
    const a = (i / 10) * Math.PI * 2;
    const ray = new THREE.Mesh(rayGeo, rayMat);
    ray.position.set(Math.cos(a) * 0.052, Math.sin(a) * 0.052, 0);
    ray.rotation.z = a - Math.PI / 2;
    sun.add(ray);
  }

  // Arrow construction: shared cylinder and cone geometries keep the scene light.
  const shaftGeometries = new Map();
  function shaftGeometry(length) {
    const key = length.toFixed(3);
    if (!shaftGeometries.has(key)) {
      shaftGeometries.set(key, new THREE.CylinderGeometry(0.004, 0.004, length, 10));
    }
    return shaftGeometries.get(key);
  }
  const headGeometry = new THREE.ConeGeometry(0.012, 0.029, 14);

  function makeArrow(name, color, from, to) {
    const group = new THREE.Group();
    group.name = name;
    root.add(group);

    const start = new THREE.Vector3(from[0], from[1], from[2]);
    const end = new THREE.Vector3(to[0], to[1], to[2]);
    const direction = end.clone().sub(start);
    const length = direction.length();
    direction.normalize();

    const material = new THREE.MeshStandardMaterial({
      color,
      emissive: color,
      emissiveIntensity: 0.12,
      roughness: 0.55
    });

    const headLength = 0.029;
    const shaftLength = Math.max(0.015, length - headLength);
    const shaft = new THREE.Mesh(shaftGeometry(shaftLength), material);
    shaft.position.copy(start).addScaledVector(direction, shaftLength * 0.5);
    shaft.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), direction);
    group.add(shaft);

    const head = new THREE.Mesh(headGeometry, material);
    head.position.copy(end).addScaledVector(direction, -headLength * 0.5);
    head.quaternion.copy(shaft.quaternion);
    group.add(head);

    return { group, material };
  }

  const lightArrow = makeArrow(
    'Light energy arrow', 0xffc62f,
    [-0.232, 0.305, 0.005], [-0.105, 0.216, 0.005]
  );
  const waterArrow = makeArrow(
    'Water arrow', 0x40a9ef,
    [-0.06, 0.012, 0.045], [-0.06, 0.132, 0.045]
  );
  const carbonArrow = makeArrow(
    'Carbon dioxide arrow', 0xb6bdc8,
    [0.065, 0.28, 0.005], [-0.006, 0.205, 0.005]
  );
  const oxygenArrow = makeArrow(
    'Oxygen arrow', 0x6fe3d2,
    [-0.022, 0.23, 0.018], [0.075, 0.337, 0.018]
  );

  function label(markup, width, position, rotationY) {
    const handle = ui(markup, { width, position, rotationY });
    root.add(handle.object3D);
    return handle;
  }

  function arrowLabel(id, text, color, position) {
    return label(`
      <style>
        .tag { width: 150px; padding-top: 8px; padding-bottom: 8px; padding-left: 8px;
               padding-right: 8px; border-radius: 12px; background-color: #20242a;
               border-width: 2px; border-color: ${color}; justify-content: center; }
        .txt { color: ${color}; font-size: 27px; font-weight: 700; text-align: center; }
      </style>
      <div class="tag"><span class="txt">${text}</span></div>
    `, 0.112, position, 0);
  }

  arrowLabel('light', 'LIGHT', '#ffd45c', [-0.215, 0.405, 0.045]);
  arrowLabel('water', 'WATER', '#74c8ff', [-0.165, 0.087, 0.075]);
  arrowLabel('co2', 'CO2 IN', '#e0e5ec', [0.07, 0.252, 0.07]);
  arrowLabel('oxygen', 'OXYGEN OUT', '#8bf3e2', [0.092, 0.376, 0.055]);

  const info = ui(`
    <style>
      .card { width: 470px; flex-direction: column; gap: 11px; padding-top: 17px;
              padding-bottom: 17px; padding-left: 20px; padding-right: 20px;
              border-radius: 18px; background-color: #1c2026; border-width: 2px;
              border-color: #46505b; }
      .title { color: #ffffff; font-size: 31px; font-weight: 700; }
      .body { color: #e1e6eb; font-size: 23px; }
      .equation { color: #aeea95; font-size: 23px; font-weight: 700; }
      .hint { color: #b9c3ce; font-size: 21px; }
    </style>
    <div class="card">
      <span class="title" id="heading">Photosynthesis</span>
      <span class="body" id="fact">Plants use light energy to make sugar. Press an arrow to follow an input or output.</span>
      <span class="equation">light + water + CO2 -> sugar + oxygen</span>
      <span class="hint">Pinch the plant to lift it. Press the Sun for the energy source.</span>
    </div>
  `, { width: 0.285, position: [0.235, 0.112, 0.07], rotationY: -0.18 });
  root.add(info.object3D);

  function explain(title, text) {
    info.set('heading', { text: title });
    info.set('fact', { text });
  }

  const explanations = [
    [lightArrow, 'Light', 'Chlorophyll in chloroplasts absorbs light energy. This energy powers the reactions that build sugar.'],
    [waterArrow, 'Water', 'Roots absorb water from the soil. The stem carries it to the leaves, where water supplies hydrogen and electrons.'],
    [carbonArrow, 'Carbon dioxide', 'CO2 enters leaves through tiny pores called stomata. Its carbon atoms become part of glucose.'],
    [oxygenArrow, 'Oxygen', 'Oxygen is released when water molecules are split. Much of it exits the leaf through stomata.']
  ];
  explanations.forEach(([arrow, title, text]) => {
    traits(arrow.group, { onPress: () => explain(title, text) });
  });

  traits(pot, { grab: true });
  traits(sun, {
    onPress: () => explain('The Sun', 'Sunlight supplies the energy, but it is not food. The plant stores some of that energy in chemical bonds in glucose.')
  });

  const basePotX = pot.position.x;
  const basePotZ = pot.position.z;

  return {
    root,
    update(time) {
      sun.rotation.z = Math.sin(time * 0.3) * 0.05;
      sunMat.emissiveIntensity = 0.58 + Math.sin(time * 1.3) * 0.1;

      // Gentle motion only in the plant's leaves; a grabbed plant stays completely still.
      if (!isGrabbed(pot)) {
        pot.position.x = basePotX;
        pot.position.z = basePotZ;
        for (let i = 0; i < leaves.length; i++) {
          leaves[i].rotation.y = Math.sin(time * 0.75 + i * 1.2) * 0.07;
        }
      }

      const pulse = 0.12 + (Math.sin(time * 2) + 1) * 0.07;
      lightArrow.material.emissiveIntensity = pulse;
      waterArrow.material.emissiveIntensity = pulse;
      carbonArrow.material.emissiveIntensity = pulse * 0.7;
      oxygenArrow.material.emissiveIntensity = pulse;
    }
  };
}

export default function build({ THREE, traits, ui }) {
  const root = new THREE.Group();

  const metal = new THREE.MeshStandardMaterial({
