  const indicatorMaterial = new THREE.MeshStandardMaterial({
    color: 0x25332e,
    emissive: 0x48ff91,
    emissiveIntensity: 0.03,
    metalness: 0.25,
    roughness: 0.45,
  });
  const powerButton = new THREE.Mesh(
    new THREE.CylinderGeometry(0.011, 0.011, 0.006, 24),
    indicatorMaterial,
  );
  powerButton.name = 'Power button';
  powerButton.position.set(baseX + 0.025, 0.0395, 0.033);
  lamp.add(powerButton);
  const buttonRestY = powerButton.position.y;

  const up = new THREE.Vector3(0, 1, 0);
  function addRod(name, from, to, radius, material) {
    const a = new THREE.Vector3(from[0], from[1], from[2]);
    const b = new THREE.Vector3(to[0], to[1], to[2]);
    const direction = new THREE.Vector3().subVectors(b, a);
    const mesh = new THREE.Mesh(
      new THREE.CylinderGeometry(radius, radius, direction.length(), 16),
      material,
    );
    mesh.name = name;
    mesh.position.copy(a).add(b).multiplyScalar(0.5);
    mesh.quaternion.setFromUnitVectors(up, direction.normalize());
    lamp.add(mesh);
    return mesh;
  }

  addRod('Lamp stem', [baseX, 0.036, 0], [baseX, 0.165, 0], 0.011, darkMetal);

  const lowerJoint = new THREE.Mesh(new THREE.SphereGeometry(0.018, 24, 12), accent);
  lowerJoint.position.set(baseX, 0.165, 0);
  lamp.add(lowerJoint);

  const elbow = [baseX + 0.055, 0.246, 0];
  const headPivot = [headX, 0.275, 0];
  addRod('Lower lamp arm', [baseX, 0.165, 0], elbow, 0.009, metal);
  addRod('Upper lamp arm', elbow, headPivot, 0.009, metal);

  const elbowJoint = new THREE.Mesh(new THREE.SphereGeometry(0.015, 24, 12), accent);
  elbowJoint.position.set(elbow[0], elbow[1], elbow[2]);
  lamp.add(elbowJoint);

  const head = new THREE.Group();
