  const innerShade = new THREE.Mesh(shadeGeometry, innerMaterial);
  innerShade.position.y = -0.038;
  innerShade.scale.setScalar(0.97);
  head.add(innerShade);

  const topCap = new THREE.Mesh(
    new THREE.CylinderGeometry(0.03, 0.03, 0.008, 32),
    darkMetal,
  );
  topCap.position.y = -0.001;
  head.add(topCap);

  const rim = new THREE.Mesh(new THREE.TorusGeometry(0.064, 0.003, 8, 32), accent);
  rim.rotation.x = Math.PI / 2;
  rim.position.y = -0.075;
  head.add(rim);

  const bulbMaterial = new THREE.MeshStandardMaterial({
    color: 0x696a63,
    emissive: 0xffb347,
    emissiveIntensity: 0.02,
    roughness: 0.28,
  });
  const bulb = new THREE.Mesh(new THREE.SphereGeometry(0.0195, 24, 16), bulbMaterial);
  bulb.name = 'Light bulb';
  bulb.position.y = -0.078;
  head.add(bulb);

  const cordCurve = new THREE.CatmullRomCurve3([
    new THREE.Vector3(baseX - 0.035, 0.008, -0.03),
    new THREE.Vector3(baseX - 0.065, 0.006, -0.09),
    new THREE.Vector3(baseX - 0.04, 0.006, -0.15),
    new THREE.Vector3(baseX + 0.025, 0.006, -0.19),
  ]);
  const cord = new THREE.Mesh(
    new THREE.TubeGeometry(cordCurve, 24, 0.0035, 8, false),
    cordMaterial,
  );
  cord.name = 'Lamp cord';
  lamp.add(cord);

  // Light is represented with emissive surfaces and translucent geometry.
  const lightEffects = new THREE.Group();
  lightEffects.position.copy(head.position);
  lightEffects.rotation.copy(head.rotation);
  root.add(lightEffects);

  const beamMaterial = new THREE.MeshBasicMaterial({
    color: 0xffd58a,
    transparent: true,
    opacity: 0,
    side: THREE.DoubleSide,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    toneMapped: false,
  });
  const beam = new THREE.Mesh(
    new THREE.ConeGeometry(0.088, 0.18, 32, 1, true),
    beamMaterial,
  );
  beam.name = 'Light beam';
  beam.position.y = -0.187;
  lightEffects.add(beam);

  const poolMaterial = new THREE.MeshBasicMaterial({
    color: 0xffc66d,
    transparent: true,
    opacity: 0,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    toneMapped: false,
  });
  const lightPool = new THREE.Mesh(new THREE.CircleGeometry(0.086, 48), poolMaterial);
  lightPool.name = 'Lit desktop area';
  lightPool.rotation.x = -Math.PI / 2;
  lightPool.position.set(headX, 0.002, 0.06);
  root.add(lightPool);

  const outerPoolMaterial = poolMaterial.clone();
  const outerPool = new THREE.Mesh(new THREE.CircleGeometry(0.106, 48), outerPoolMaterial);
  outerPool.rotation.x = -Math.PI / 2;
  outerPool.position.set(headX, 0.001, 0.06);
  root.add(outerPool);

  const info = ui(`
    <style>
      .card { width: 430px; flex-direction: column; gap: 12px; padding-top: 20px; padding-bottom: 20px;
              padding-left: 24px; padding-right: 24px; border-radius: 18px; background-color: #1f2429;
              border-color: #466068; border-width: 1px; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .status { color: #aab4bd; font-size: 28px; font-weight: 700; }
      .body { color: #d7dfe5; font-size: 22px; }
    </style>
    <div class="card">
      <span class="title">Desk lamp</span>
      <span class="status" id="status">OFF</span>
      <span class="body">Press any part of the lamp to switch it on or off.</span>
    </div>`, {
    width: 0.27,
    position: [0.235, 0.17, -0.04],
    rotationY: -0.28,
  });
  root.add(info.object3D);

  let lampOn = false;
  let level = 0;
  let target = 0;
  let pressAnimation = 0;

  const bulbOffColor = new THREE.Color(0x696a63);
  const bulbOnColor = new THREE.Color(0xfff1c9);
  const indicatorOffColor = new THREE.Color(0x25332e);
  const indicatorOnColor = new THREE.Color(0xb8ffd0);

  traits(lamp, {
    onPress: () => {
      lampOn = !lampOn;
      target = lampOn ? 1 : 0;
      pressAnimation = 1;
      info.set('status', {
        text: lampOn ? 'ON' : 'OFF',
        color: lampOn ? '#ffd27a' : '#aab4bd',
      });
    },
  });

  return {
    root,
    update(time, delta) {
      level += (target - level) * Math.min(1, delta * 10);

      bulbMaterial.color.copy(bulbOffColor).lerp(bulbOnColor, level);
      bulbMaterial.emissiveIntensity = 0.02 + level * 2.4;
      innerMaterial.emissiveIntensity = level * 0.55;
      beamMaterial.opacity = level * 0.11;
      poolMaterial.opacity = level * 0.26;
      outerPoolMaterial.opacity = level * 0.08;

      indicatorMaterial.color.copy(indicatorOffColor).lerp(indicatorOnColor, level);
      indicatorMaterial.emissiveIntensity = 0.03 + level * 1.2;

      let depression = 0;
      if (pressAnimation > 0) {
        depression = Math.sin((1 - pressAnimation) * Math.PI) * 0.003;
        pressAnimation = Math.max(0, pressAnimation - delta * 5);
      }
      powerButton.position.y = buttonRestY - depression;
    },
  };
}

