export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const glaze = new THREE.MeshStandardMaterial({
    color: 0x78a7a1,
    roughness: 0.24,
    metalness: 0.02,
    side: THREE.DoubleSide,
  });

  const saucerGlaze = new THREE.MeshStandardMaterial({
    color: 0x638e89,
    roughness: 0.3,
    metalness: 0.01,
    side: THREE.DoubleSide,
  });

  const mug = new THREE.Group();
  mug.name = 'Glazed stoneware coffee mug';
  mug.position.set(-0.11, 0.004, 0.025);
  root.add(mug);

  // A continuous ceramic shell with a real hollow interior and solid base.
  const profile = [
    new THREE.Vector2(0, 0),
    new THREE.Vector2(0.033, 0),
    new THREE.Vector2(0.041, 0.003),
    new THREE.Vector2(0.045, 0.012),
    new THREE.Vector2(0.047, 0.085),
    new THREE.Vector2(0.0475, 0.09),
    new THREE.Vector2(0.045, 0.094),
    new THREE.Vector2(0.042, 0.094),
    new THREE.Vector2(0.041, 0.089),
    new THREE.Vector2(0.041, 0.02),
    new THREE.Vector2(0.035, 0.011),
    new THREE.Vector2(0, 0.011),
  ];

  const body = new THREE.Mesh(new THREE.LatheGeometry(profile, 48), glaze);
  body.name = 'Mug body';
  mug.add(body);

  const handle = new THREE.Mesh(new THREE.TorusGeometry(0.026, 0.0055, 12, 48), glaze);
  handle.name = 'Rounded mug handle';
  handle.position.set(0.045, 0.053, 0);
  mug.add(handle);

  const coffee = new THREE.Mesh(
    new THREE.CylinderGeometry(0.0405, 0.0405, 0.002, 48),
    new THREE.MeshStandardMaterial({ color: 0x28150d, roughness: 0.2, metalness: 0.02 })
  );
  coffee.name = 'Coffee surface';
  coffee.position.y = 0.077;
  mug.add(coffee);

  const coffeeEdge = new THREE.Mesh(
    new THREE.TorusGeometry(0.0385, 0.0011, 6, 48),
    new THREE.MeshStandardMaterial({ color: 0x8b542c, roughness: 0.42 })
  );
  coffeeEdge.rotation.x = Math.PI / 2;
  coffeeEdge.position.y = 0.0782;
  mug.add(coffeeEdge);

  const saucerProfile = [
    new THREE.Vector2(0, 0),
    new THREE.Vector2(0.045, 0),
    new THREE.Vector2(0.064, 0.002),
    new THREE.Vector2(0.07, 0.005),
    new THREE.Vector2(0.068, 0.007),
    new THREE.Vector2(0.052, 0.004),
    new THREE.Vector2(0.039, 0.003),
    new THREE.Vector2(0, 0.003),
  ];
  const saucer = new THREE.Mesh(new THREE.LatheGeometry(saucerProfile, 48), saucerGlaze);
  saucer.name = 'Matching saucer';
  saucer.position.set(-0.11, 0.0005, 0.025);
  root.add(saucer);

  const steam = [];
  for (let i = 0; i < 3; i += 1) {
    const x = (i - 1) * 0.016;
    const curve = new THREE.CatmullRomCurve3([
      new THREE.Vector3(x, 0.082, 0),
      new THREE.Vector3(x + 0.005, 0.105, 0.001),
      new THREE.Vector3(x - 0.004, 0.13, -0.001),
      new THREE.Vector3(x + 0.003, 0.158, 0),
    ]);
    const material = new THREE.MeshBasicMaterial({
      color: 0xf4f1e9,
      transparent: true,
      opacity: 0.13,
      depthWrite: false,
    });
    const wisp = new THREE.Mesh(new THREE.TubeGeometry(curve, 16, 0.0008, 5, false), material);
    wisp.name = 'Steam wisp ' + (i + 1);
    mug.add(wisp);
    steam.push(wisp);
  }

  const info = ui(`
    <style>
      .card {
        width: 460px;
        display: flex;
        flex-direction: column;
        gap: 12px;
        padding-top: 22px;
        padding-bottom: 22px;
        padding-left: 26px;
        padding-right: 26px;
        border-radius: 20px;
        border-width: 1px;
        border-color: #3a424c;
        background-color: #1f2329;
      }
      .kicker { color: #96d4cd; font-size: 21px; font-weight: 700; }
      .title { color: #ffffff; font-size: 33px; font-weight: 700; }
      .price { color: #ffd58a; font-size: 42px; font-weight: 700; }
      .label { color: #aeb8c4; font-size: 22px; font-weight: 700; }
      .value { color: #f2f5f7; font-size: 27px; font-weight: 700; }
      .details {
        color: #d9dfe6;
        font-size: 24px;
        padding-top: 12px;
        padding-bottom: 12px;
        padding-left: 14px;
        padding-right: 14px;
        border-radius: 12px;
        background-color: #292f37;
      }
      .hint { color: #b9c4cf; font-size: 21px; }
      .button {
        display: flex;
        align-items: center;
        justify-content: center;
        margin-top: 2px;
        padding-top: 11px;
        padding-bottom: 11px;
        padding-left: 16px;
        padding-right: 16px;
        border-radius: 12px;
        background-color: #376f70;
      }
      .buttonText { color: #ffffff; font-size: 23px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="kicker">EVERYDAY COLLECTION</span>
      <span class="title">Ceramic Coffee Mug</span>
      <span class="price">$18.00</span>
      <span class="label">Material</span>
      <span class="value">Glazed stoneware</span>
      <span class="details" id="details">350 ml capacity with a comfortable rounded handle.</span>
      <button class="button" id="care">
        <span class="buttonText" id="careLabel">Show care details</span>
      </button>
      <span class="hint" id="hint">Pinch and lift the mug to pick it up.</span>
    </div>
  `, { width: 0.31, position: [0.16, 0.17, 0], rotationY: -0.16 });
  root.add(info.object3D);

  let showingCare = false;
  info.on('care', 'click', () => {
    showingCare = !showingCare;
    info.set('details', {
      text: showingCare
        ? 'Dishwasher and microwave safe. The glossy glaze is food-safe.'
        : '350 ml capacity with a comfortable rounded handle.',
    });
    info.set('careLabel', {
      text: showingCare ? 'Show mug details' : 'Show care details',
    });
  });

  traits(mug, { grab: true });

  const restingHint = { text: 'Pinch and lift the mug to pick it up.' };
  const holdingHint = { text: 'Release your pinch to set the mug down.' };
  let wasGrabbed = false;

  return {
    root,
    update(time) {
      const grabbed = isGrabbed(mug);
      if (grabbed !== wasGrabbed) {
        wasGrabbed = grabbed;
        info.set('hint', grabbed ? holdingHint : restingHint);
      }

      if (grabbed) return;

      for (let i = 0; i < steam.length; i += 1) {
        const wisp = steam[i];
        wisp.position.x = Math.sin(time * 0.7 + i * 1.8) * 0.002;
        wisp.position.z = Math.cos(time * 0.6 + i * 1.4) * 0.002;
        wisp.material.opacity = 0.12 + 0.045 * (Math.sin(time * 1.1 + i * 2) + 1);
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();
  root.name = 'Weather dashboard';

  const cities = [
