  let selected = cities[0];

  const panel = ui(`
    <style>
      .dash { width: 560px; flex-direction: column; gap: 12px; padding-top: 16px;
              padding-bottom: 16px; padding-left: 16px; padding-right: 16px;
              background-color: #1a1d22; border-color: #3a424d; border-width: 2px;
              border-radius: 22px; }
      .header { flex-direction: row; align-items: center; justify-content: space-between; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .unit { background-color: #315f9e; border-radius: 12px; padding-top: 8px;
              padding-bottom: 8px; padding-left: 14px; padding-right: 14px; }
      .unitText { color: #ffffff; font-size: 20px; font-weight: 700; }
      .subtitle { color: #b6c0cc; font-size: 20px; }
      .cities { flex-direction: row; justify-content: center; gap: 12px; }
      .city { width: 156px; height: 126px; flex-direction: column; align-items: center;
              justify-content: center; gap: 4px; padding-top: 10px; padding-bottom: 10px;
              padding-left: 8px; padding-right: 8px; background-color: #242931;
              border-color: #3a4450; border-width: 2px; border-radius: 16px; }
      .name { color: #e5eaf0; font-size: 22px; font-weight: 700; }
      .temp { color: #ffffff; font-size: 36px; font-weight: 700; }
      .condition { color: #aebed0; font-size: 20px; text-align: center; }
      .detail { color: #d7e0e9; font-size: 21px; text-align: center; }
    </style>
    <div class="dash">
      <div class="header">
        <span class="title">Weather dashboard</span>
        <button class="unit" id="units"><span class="unitText" id="unitText">Show F</span></button>
      </div>
      <span class="subtitle">Demo conditions - tap a city or its icon</span>
      <div class="cities">
        <button class="city" id="london">
          <span class="name">London</span>
          <span class="temp" id="londonTemp">16 C</span>
          <span class="condition">Light rain</span>
        </button>
        <button class="city" id="newyork">
          <span class="name">New York</span>
          <span class="temp" id="newyorkTemp">22 C</span>
          <span class="condition">Sunny</span>
        </button>
        <button class="city" id="tokyo">
          <span class="name">Tokyo</span>
          <span class="temp" id="tokyoTemp">26 C</span>
          <span class="condition">Partly cloudy</span>
        </button>
      </div>
      <span class="detail" id="detail">London: high 18 C, low 11 C. Humidity 78%, wind 14 km/h.</span>
    </div>`, { width: 0.48, position: [0, 0.15, 0] });
  root.add(panel.object3D);

  function formatTemp(celsius) {
    const value = unit === 'C' ? celsius : celsius * 9 / 5 + 32;
    return Math.round(value) + ' ' + unit;
  }

  function detailText(city) {
    return city.name + ': high ' + formatTemp(city.high) + ', low ' + formatTemp(city.low) +
      '. Humidity ' + city.humidity + '%, wind ' + city.wind + ' km/h.';
  }

  function selectCity(city) {
    selected = city;
    for (let i = 0; i < cities.length; i++) {
      panel.set(cities[i].id, {
        backgroundColor: cities[i] === city ? '#2d4b62' : '#242931',
      });
    }
    panel.set('detail', { text: detailText(city) });
  }

  function updateReadouts() {
    for (let i = 0; i < cities.length; i++) {
      panel.set(cities[i].id + 'Temp', { text: formatTemp(cities[i].temp) });
    }
    panel.set('unitText', { text: unit === 'C' ? 'Show F' : 'Show C' });
    panel.set('detail', { text: detailText(selected) });
  }

  for (let i = 0; i < cities.length; i++) {
    const city = cities[i];
    panel.on(city.id, 'click', () => selectCity(city));
  }
  panel.on('units', 'click', () => {
    unit = unit === 'C' ? 'F' : 'C';
    updateReadouts();
  });

  const cloudMaterial = new THREE.MeshStandardMaterial({
    color: 0xdce5ec,
    roughness: 0.82,
    metalness: 0.02,
  });
  const rainMaterial = new THREE.MeshStandardMaterial({
    color: 0x58a6ff,
    emissive: 0x123d68,
    emissiveIntensity: 0.35,
    roughness: 0.35,
  });
  const sunMaterial = new THREE.MeshStandardMaterial({
    color: 0xffc43d,
    emissive: 0xff8a00,
    emissiveIntensity: 0.7,
    roughness: 0.45,
  });

  const puffGeometry = new THREE.SphereGeometry(0.02, 24, 12);
  const cloudBaseGeometry = new THREE.BoxGeometry(0.064, 0.018, 0.026);
  const dropGeometry = new THREE.SphereGeometry(0.008, 16, 8);
  const rayGeometry = new THREE.BoxGeometry(0.006, 0.02, 0.006);

  function addCloud(parent, x, y, z, scale) {
    const cloud = new THREE.Group();

    const left = new THREE.Mesh(puffGeometry, cloudMaterial);
    left.position.set(-0.022, 0.002, 0);
    left.scale.set(0.85, 0.78, 0.75);
    cloud.add(left);

    const center = new THREE.Mesh(puffGeometry, cloudMaterial);
    center.position.set(0, 0.012, 0);
    center.scale.set(1.15, 1.12, 0.9);
    cloud.add(center);

    const right = new THREE.Mesh(puffGeometry, cloudMaterial);
    right.position.set(0.022, 0.002, 0);
    right.scale.set(0.85, 0.78, 0.75);
    cloud.add(right);

    const base = new THREE.Mesh(cloudBaseGeometry, cloudMaterial);
    base.position.set(0, -0.008, 0);
    cloud.add(base);

    cloud.position.set(x, y, z);
    cloud.scale.setScalar(scale);
    parent.add(cloud);
    return cloud;
  }

  function addRays(parent, count, radius, scale) {
    const rays = new THREE.Group();
    for (let i = 0; i < count; i++) {
      const angle = i * Math.PI * 2 / count;
      const ray = new THREE.Mesh(rayGeometry, sunMaterial);
      ray.position.set(Math.cos(angle) * radius, Math.sin(angle) * radius, 0);
      ray.rotation.z = angle - Math.PI / 2;
      ray.scale.setScalar(scale);
      rays.add(ray);
    }
    parent.add(rays);
    return rays;
  }

  const londonIcon = new THREE.Group();
  londonIcon.name = 'London';
  londonIcon.position.set(-0.15, 0.39, 0.02);
  root.add(londonIcon);
  addCloud(londonIcon, 0, 0.012, 0, 1);

  const rainDrops = [];
  for (let i = 0; i < 3; i++) {
    const drop = new THREE.Mesh(dropGeometry, rainMaterial);
    drop.name = 'Rain drop';
    drop.position.set((i - 1) * 0.022, -0.034 - i * 0.006, 0.008);
    drop.scale.set(0.48, 1.35, 0.48);
    drop.userData.phase = i / 3;
    londonIcon.add(drop);
    rainDrops.push(drop);
  }

  const newYorkIcon = new THREE.Group();
  newYorkIcon.name = 'New York';
  newYorkIcon.position.set(0, 0.39, 0.02);
  root.add(newYorkIcon);

  const mainSun = new THREE.Mesh(
    new THREE.SphereGeometry(0.029, 32, 16),
    sunMaterial,
  );
  mainSun.name = 'New York sun';
  newYorkIcon.add(mainSun);
  const newYorkRays = addRays(newYorkIcon, 8, 0.048, 1);

  const tokyoIcon = new THREE.Group();
  tokyoIcon.name = 'Tokyo';
  tokyoIcon.position.set(0.15, 0.39, 0.02);
  root.add(tokyoIcon);

  const smallSunGroup = new THREE.Group();
  smallSunGroup.position.set(0.024, 0.014, -0.008);
  tokyoIcon.add(smallSunGroup);

  const smallSun = new THREE.Mesh(
    new THREE.SphereGeometry(0.018, 24, 12),
    sunMaterial,
  );
  smallSun.name = 'Tokyo sun';
  smallSunGroup.add(smallSun);
  const tokyoRays = addRays(smallSunGroup, 6, 0.029, 0.65);
  addCloud(tokyoIcon, -0.01, -0.012, 0.014, 0.9);

  traits(londonIcon, { onPress: () => selectCity(cityById.london) });
  traits(newYorkIcon, { onPress: () => selectCity(cityById.newyork) });
  traits(tokyoIcon, { onPress: () => selectCity(cityById.tokyo) });

  const iconList = [
    { id: 'london', group: londonIcon, baseY: 0.39 },
    { id: 'newyork', group: newYorkIcon, baseY: 0.39 },
    { id: 'tokyo', group: tokyoIcon, baseY: 0.39 },
  ];

  selectCity(selected);
  updateReadouts();

  return {
    root,
    update(time) {
      for (let i = 0; i < iconList.length; i++) {
        const item = iconList[i];
        const active = selected.id === item.id;
        const pulse = active ? Math.sin(time * 2.4) * 0.012 : 0;
        item.group.scale.setScalar((active ? 1.08 : 1) + pulse);
        item.group.position.y = item.baseY + Math.sin(time * 1.1 + i * 1.7) * 0.002;
      }

      newYorkRays.rotation.z = time * 0.16;
      tokyoRays.rotation.z = -time * 0.12;

      for (let i = 0; i < rainDrops.length; i++) {
        const drop = rainDrops[i];
        const cycle = (time * 0.55 + drop.userData.phase) % 1;
        drop.position.y = -0.034 - cycle * 0.019;
      }
    },
  };
}

