  });
  const rainMaterial = new THREE.MeshStandardMaterial({
    color: 0x48a9e6, emissive: 0x176a9a, emissiveIntensity: 0.25, roughness: 0.35,
  });
  const snowMaterial = new THREE.MeshStandardMaterial({
    color: 0xeaf8ff, emissive: 0x83c7e8, emissiveIntensity: 0.25, roughness: 0.5,
  });

  const cloudPuffs = [
    [-0.037, 0.005, 0, 0.034, 0.025, 0.026],
    [-0.012, 0.025, 0, 0.034, 0.034, 0.029],
    [0.023, 0.016, 0, 0.038, 0.030, 0.028],
    [0.043, -0.002, 0, 0.027, 0.022, 0.023],
    [0.002, -0.010, 0, 0.052, 0.020, 0.026],
  ];

  function addCloud(icon, material) {
    for (let i = 0; i < cloudPuffs.length; i++) {
      const p = cloudPuffs[i];
      const puff = new THREE.Mesh(sphereGeometry, material);
      puff.position.set(p[0], p[1], p[2]);
      puff.scale.set(p[3], p[4], p[5]);
      icon.add(puff);
    }
  }

  function addRain(icon, city) {
    const positions = [-0.038, 0, 0.038];
    for (let i = 0; i < positions.length; i++) {
      const drop = new THREE.Mesh(sphereGeometry, rainMaterial);
      drop.name = 'Raindrop';
      drop.scale.set(0.0045, 0.009, 0.0045);
      drop.position.set(positions[i], -0.03, 0.018);
      icon.add(drop);
      city.raindrops.push({ mesh: drop, phase: i * 0.31 });
    }
  }

  const snowArmGeometry = new THREE.CylinderGeometry(0.0016, 0.0016, 0.026, 6);

  function addSnow(icon, city) {
    const positions = [-0.038, 0, 0.038];
    for (let i = 0; i < positions.length; i++) {
      const flake = new THREE.Group();
      flake.name = 'Snowflake';
      flake.position.set(positions[i], -0.03, 0.018);

      for (let armIndex = 0; armIndex < 3; armIndex++) {
        const arm = new THREE.Mesh(snowArmGeometry, snowMaterial);
        arm.rotation.z = armIndex * Math.PI / 3;
        flake.add(arm);
      }

      icon.add(flake);
      city.snowflakes.push({ group: flake, phase: i * 0.33 });
    }
  }

  function addSun(icon, city) {
    const sunMaterial = new THREE.MeshStandardMaterial({
      color: 0xffc63d,
      emissive: 0xff8a00,
      emissiveIntensity: 0.65,
      roughness: 0.42,
    });
    const rayMaterial = new THREE.MeshStandardMaterial({
      color: 0xffdc72,
      emissive: 0xff9d16,
      emissiveIntensity: 0.45,
      roughness: 0.5,
    });

    const sun = new THREE.Mesh(new THREE.SphereGeometry(0.034, 24, 16), sunMaterial);
    sun.name = 'Sun';
    icon.add(sun);

    const rayRing = new THREE.Group();
    rayRing.name = 'Sun rays';
    const rayGeometry = new THREE.CylinderGeometry(0.002, 0.002, 0.020, 8);

    for (let i = 0; i < 8; i++) {
      const angle = i * Math.PI / 4;
      const ray = new THREE.Mesh(rayGeometry, rayMaterial);
      ray.position.set(Math.cos(angle) * 0.052, Math.sin(angle) * 0.052, -0.004);
      ray.rotation.z = angle - Math.PI / 2;
      rayRing.add(ray);
    }

    icon.add(rayRing);
    city.rayRing = rayRing;
  }

  for (let i = 0; i < cities.length; i++) {
    const city = cities[i];
    const icon = new THREE.Group();
    icon.name = city.name + ' weather icon';
    icon.position.set(city.x, 0.326, 0);
    root.add(icon);
    city.icon = icon;

    if (city.kind === 'rain') {
      addCloud(icon, seattleCloudMaterial);
      addRain(icon, city);
    } else if (city.kind === 'snow') {
      addCloud(icon, denverCloudMaterial);
      addSnow(icon, city);
    } else {
      addSun(icon, city);
    }

    traits(icon, {
      grab: true,
      onPress: () => {
        city.detailsVisible = !city.detailsVisible;
        syncDetails(city);
      },
    });
  }

  return {
    root,
    update(time) {
      for (let i = 0; i < cities.length; i++) {
        const city = cities[i];
        if (isGrabbed(city.icon)) continue;

        if (city.kind === 'rain') {
          for (let j = 0; j < city.raindrops.length; j++) {
            const drop = city.raindrops[j];
            const progress = (time * 0.22 + drop.phase) % 1;
            drop.mesh.position.y = -0.026 - progress * 0.040;
          }
        } else if (city.kind === 'snow') {
          for (let j = 0; j < city.snowflakes.length; j++) {
            const flake = city.snowflakes[j];
            const progress = (time * 0.16 + flake.phase) % 1;
            flake.group.position.y = -0.025 - progress * 0.040;
            flake.group.rotation.z = time * 0.35 + flake.phase * Math.PI * 2;
          }
        } else {
          city.rayRing.rotation.z = time * 0.18;
        }
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
