    { text: '6 x 7 = ?', choices: [36, 42, 48, 56], correct: 1, answer: 42 },
    { text: '8 x 9 = ?', choices: [64, 69, 72, 81], correct: 2, answer: 72 },
    { text: '12 x 4 = ?', choices: [44, 46, 48, 52], correct: 2, answer: 48 },
    { text: '7 x 5 = ?', choices: [30, 35, 42, 45], correct: 1, answer: 35 },
    { text: '11 x 6 = ?', choices: [56, 61, 66, 72], correct: 2, answer: 66 },
  ];

  const panel = ui(`
    <style>
      .card { width: 540px; flex-direction: column; gap: 10px;
              padding-top: 18px; padding-bottom: 18px; padding-left: 22px; padding-right: 22px;
              border-radius: 18px; background-color: #1d2127;
