      .title { color: #ffffff; font-size: 32px; font-weight: 700; text-align: center; }
      .top-row { flex-direction: row; justify-content: space-between; align-items: center; }
      .meta { color: #b9c5d4; font-size: 22px; }
      .score { color: #ffd166; font-size: 24px; font-weight: 700; }
      .question { color: #ffffff; font-size: 36px; font-weight: 700; text-align: center; }
      .hint { color: #c9d1dc; font-size: 22px; text-align: center; }
      .answers { flex-direction: column; gap: 10px; }
      .answer-row { flex-direction: row; gap: 12px; justify-content: center; }
      .answer { width: 230px; align-items: center; justify-content: center;
                padding-top: 10px; padding-bottom: 10px; padding-left: 12px; padding-right: 12px;
                border-radius: 12px; background-color: #35404d;
                border-color: #607086; border-width: 2px; }
      .answer-text { color: #ffffff; font-size: 28px; font-weight: 700; }
      .feedback { color: #c9d1dc; font-size: 23px; text-align: center; }
      .action { align-items: center; justify-content: center;
                padding-top: 10px; padding-bottom: 10px; padding-left: 18px; padding-right: 18px;
                border-radius: 12px; background-color: #2f6fdb; }
      .action-text { color: #ffffff; font-size: 24px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Multiplication Quiz</span>
      <div class="top-row">
        <span class="meta" id="progress">Question 1 of 5</span>
        <span class="score" id="score">Score: 0</span>
      </div>
      <span class="question" id="question">6 x 7 = ?</span>
      <span class="hint">Poke or pinch one answer.</span>
      <div class="answers" id="answers">
        <div class="answer-row">
          <button class="answer" id="a0"><span class="answer-text" id="a0text">36</span></button>
          <button class="answer" id="a1"><span class="answer-text" id="a1text">42</span></button>
        </div>
        <div class="answer-row">
          <button class="answer" id="a2"><span class="answer-text" id="a2text">48</span></button>
          <button class="answer" id="a3"><span class="answer-text" id="a3text">56</span></button>
        </div>
      </div>
      <span class="feedback" id="feedback">Choose the correct product.</span>
      <button class="action" id="action"><span class="action-text" id="actiontext">Next question</span></button>
    </div>`, { width: 0.42, position: [0, 0.19, 0] });
  root.add(panel.object3D);

  const neutralMaterial = new THREE.MeshStandardMaterial({
    color: 0x566170, roughness: 0.55, metalness: 0.15,
  });
  const currentMaterial = new THREE.MeshStandardMaterial({
    color: 0xffd166, emissive: 0x7a4d00, emissiveIntensity: 0.35,
    roughness: 0.4, metalness: 0.2,
  });
  const correctMaterial = new THREE.MeshStandardMaterial({
    color: 0x43d17c, emissive: 0x0b4d27, emissiveIntensity: 0.35,
    roughness: 0.4,
  });
  const wrongMaterial = new THREE.MeshStandardMaterial({
    color: 0xef6670, emissive: 0x591018, emissiveIntensity: 0.25,
    roughness: 0.45,
  });
  const markerGeometry = new THREE.OctahedronGeometry(0.013, 0);
  const markers = [];
  const results = [0, 0, 0, 0, 0];

  for (let i = 0; i < 5; i++) {
    const marker = new THREE.Mesh(markerGeometry, neutralMaterial);
    marker.name = 'Question ' + (i + 1) + ' result marker';
    marker.position.set(-0.08 + i * 0.04, 0.42, 0);
    marker.rotation.z = Math.PI * 0.25;
    root.add(marker);
    markers.push(marker);
  }

  let questionIndex = 0;
  let score = 0;
  let phase = 'answering';

  function refreshMarkers() {
    for (let i = 0; i < markers.length; i++) {
      if (results[i] === 1) {
        markers[i].material = correctMaterial;
      } else if (results[i] === 2) {
        markers[i].material = wrongMaterial;
      } else if (i === questionIndex && phase !== 'results') {
        markers[i].material = currentMaterial;
      } else {
        markers[i].material = neutralMaterial;
      }
    }
  }

  function showQuestion() {
    const item = questions[questionIndex];
    panel.set('progress', { text: 'Question ' + (questionIndex + 1) + ' of 5' });
    panel.set('question', { text: item.text });
    panel.set('feedback', {
      text: 'Choose the correct product.',
      color: '#c9d1dc',
    });
    panel.set('answers', { display: 'flex' });
    panel.set('action', { display: 'none' });

    for (let i = 0; i < 4; i++) {
      panel.set('a' + i + 'text', { text: String(item.choices[i]) });
      panel.set('a' + i, { backgroundColor: '#35404d' });
    }
    refreshMarkers();
  }

  function chooseAnswer(choiceIndex) {
    if (phase !== 'answering') return;

    const item = questions[questionIndex];
    const isCorrect = choiceIndex === item.correct;
    phase = 'feedback';

    if (isCorrect) {
      score++;
      results[questionIndex] = 1;
      panel.set('feedback', {
        text: 'Correct! ' + item.text.replace('?', String(item.answer)),
        color: '#75e6a2',
      });
      panel.set('a' + choiceIndex, { backgroundColor: '#26734d' });
    } else {
      results[questionIndex] = 2;
      panel.set('feedback', {
        text: 'Not quite. ' + item.text.replace('?', String(item.answer)),
        color: '#ff9aa2',
      });
      panel.set('a' + choiceIndex, { backgroundColor: '#9f3d45' });
      panel.set('a' + item.correct, { backgroundColor: '#26734d' });
    }

    panel.set('score', { text: 'Score: ' + score });
    panel.set('actiontext', {
      text: questionIndex === questions.length - 1 ? 'See results' : 'Next question',
    });
    panel.set('action', { display: 'flex' });
    refreshMarkers();
  }

  function showResults() {
    phase = 'results';
    panel.set('progress', { text: 'Finished: 5 of 5' });
    panel.set('question', { text: 'Quiz complete!' });
    panel.set('answers', { display: 'none' });

    let message;
    if (score === 5) {
      message = 'Perfect score! You got 5 out of 5.';
    } else if (score >= 3) {
      message = 'Well done! You scored ' + score + ' out of 5.';
    } else {
      message = 'You scored ' + score + ' out of 5. Try again!';
    }

    panel.set('feedback', { text: message, color: '#ffd166' });
    panel.set('actiontext', { text: 'Play again' });
    panel.set('action', { display: 'flex' });
    refreshMarkers();
  }

  function resetQuiz() {
    questionIndex = 0;
    score = 0;
    phase = 'answering';
    for (let i = 0; i < results.length; i++) results[i] = 0;
    panel.set('score', { text: 'Score: 0' });
    showQuestion();
  }

  for (let i = 0; i < 4; i++) {
    panel.on('a' + i, 'click', () => chooseAnswer(i));
  }

  panel.on('action', 'click', () => {
    if (phase === 'results') {
      resetQuiz();
    } else if (phase === 'feedback') {
      if (questionIndex === questions.length - 1) {
        showResults();
      } else {
        questionIndex++;
        phase = 'answering';
        showQuestion();
      }
    }
  });

  panel.set('action', { display: 'none' });
  refreshMarkers();

  return {
    root,
    update(time) {
      for (let i = 0; i < markers.length; i++) {
        const marker = markers[i];
        marker.rotation.y = time * 0.65 + i * 0.4;
        const active = i === questionIndex && phase === 'answering';
        const scale = active ? 1.12 + Math.sin(time * 3) * 0.1 : 1;
        marker.scale.setScalar(scale);
      }
    },
  };
}

export default function build({ THREE, ui }) {
  const root = new THREE.Group();

  const dayNames = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
  const habits = [
    { name: 'Morning walk', checked: Array(7).fill(false) },
    { name: 'Read 20 minutes', checked: Array(7).fill(false) },
    { name: 'Drink 8 glasses', checked: Array(7).fill(false) },
  ];

  const habitCards = habits.map((habit, h) => {
    const buttons = dayNames.map((day, d) => `
      <button class="day" id="h${h}d${d}">
        <span class="day-name">${day}</span>
        <span class="day-state" id="s${h}d${d}">Open</span>
      </button>`).join('');

    return `
      <div class="habit">
        <div class="habit-head">
          <span class="habit-name">${habit.name}</span>
          <span class="streak" id="streak${h}">Streak: 0 days</span>
        </div>
        <div class="days">${buttons}</div>
      </div>`;
  }).join('');

  const panel = ui(`
    <style>
      .panel {
        width: 560px;
        flex-direction: column;
        gap: 8px;
        padding-top: 12px;
        padding-bottom: 12px;
        padding-left: 12px;
        padding-right: 12px;
        border-radius: 18px;
        border-width: 2px;
        border-color: #3b424d;
        background-color: #1a1d22;
      }
      .title {
        color: #ffffff;
        font-size: 30px;
        font-weight: 700;
        text-align: center;
      }
      .subtitle {
        color: #d7dbe2;
        font-size: 22px;
        text-align: center;
      }
      .habit {
        flex-direction: column;
        gap: 6px;
        padding-top: 10px;
        padding-bottom: 10px;
        padding-left: 10px;
        padding-right: 10px;
        border-radius: 14px;
        background-color: #252a31;
      }
      .habit-head {
        flex-direction: row;
        align-items: center;
        justify-content: space-between;
      }
      .habit-name {
        color: #ffffff;
        font-size: 26px;
        font-weight: 700;
      }
      .streak {
        color: #8fe0b2;
        font-size: 22px;
        font-weight: 700;
      }
      .days {
        flex-direction: row;
        gap: 8px;
      }
      .day {
        width: 60px;
        height: 60px;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        gap: 2px;
        border-radius: 10px;
        border-width: 2px;
        border-color: #505a67;
        background-color: #363d47;
      }
      .day-name {
        color: #ffffff;
        font-size: 20px;
        font-weight: 700;
      }
      .day-state {
        color: #b8c0cb;
        font-size: 16px;
      }
      .note {
        color: #aeb6c2;
        font-size: 18px;
        text-align: center;
      }
    </style>
    <div class="panel">
      <span class="title">This week</span>
      <span class="subtitle">Tap a day to check it off. Tap again to undo.</span>
      ${habitCards}
      <span class="note">Streak counts back from your latest checked day.</span>
    </div>
  `, {
    width: 0.50,
    position: [0, 0.25, 0],
  });
  root.add(panel.object3D);

  function currentStreak(checked) {
    let latest = -1;
    for (let d = 0; d < 7; d++) {
      if (checked[d]) latest = d;
    }
    if (latest === -1) return 0;

    let streak = 0;
    for (let d = latest; d >= 0 && checked[d]; d--) {
      streak++;
    }
    return streak;
  }

  function renderHabit(h) {
    const habit = habits[h];

    for (let d = 0; d < 7; d++) {
      const isDone = habit.checked[d];
      panel.set(`h${h}d${d}`, {
        backgroundColor: isDone ? '#287a50' : '#363d47',
      });
      panel.set(`s${h}d${d}`, {
        text: isDone ? 'Done' : 'Open',
        color: isDone ? '#effff5' : '#b8c0cb',
      });
    }

    const streak = currentStreak(habit.checked);
    panel.set(`streak${h}`, {
      text: `Streak: ${streak} ${streak === 1 ? 'day' : 'days'}`,
    });
  }

  habits.forEach((habit, h) => {
    for (let d = 0; d < 7; d++) {
      panel.on(`h${h}d${d}`, 'click', () => {
        habit.checked[d] = !habit.checked[d];
        renderHabit(h);
      });
    }
    renderHabit(h);
  });

  return { root };
}

