    0.0027,
    rootMaterial,
    'Fine root',
  );
  addSegment(
    root,
    new THREE.Vector3(-0.07, 0.046, 0.059),
    new THREE.Vector3(-0.052, 0.027, 0.059),
    0.0027,
    rootMaterial,
    'Fine root',
  );

  addSegment(
    root,
    new THREE.Vector3(-0.07, 0.095, 0),
    new THREE.Vector3(-0.07, 0.315, 0),
    0.007,
    stemMaterial,
    'Stem',
  );

  const leaves = [];

  function addLeaf(x, y, z, sx, sy, sz, angle, index) {
    addSegment(
      root,
      new THREE.Vector3(-0.07, y - 0.018, 0),
      new THREE.Vector3(x, y, z),
      0.0035,
      stemMaterial,
      'Leaf stalk',
    );

    const leaf = new THREE.Mesh(unitSphere, leafMaterials[index % 2]);
    leaf.position.set(x, y, z);
    leaf.scale.set(sx, sy, sz);
    leaf.rotation.set(0.18, index % 2 ? -0.12 : 0.12, angle);
    leaf.name = 'Leaf ' + (index + 1);
    leaf.userData.baseAngle = angle;
    leaf.userData.phase = index * 0.9;
    root.add(leaf);
    traits(leaf, { onPress: () => show('leaf') });
    leaves.push(leaf);
  }

  addLeaf(-0.12, 0.16, 0, 0.05, 0.015, 0.024, -0.35, 0);
  addLeaf(-0.018, 0.18, 0.002, 0.052, 0.015, 0.025, 0.3, 1);
  addLeaf(-0.13, 0.216, 0, 0.055, 0.016, 0.026, 0.25, 2);
  addLeaf(-0.008, 0.253, 0.004, 0.055, 0.016, 0.026, -0.2, 3);
  addLeaf(-0.13, 0.285, 0.001, 0.048, 0.014, 0.023, -0.28, 4);
  addLeaf(-0.07, 0.32, 0, 0.047, 0.014, 0.022, Math.PI / 2, 5);

  // Sun and its rays.
  const sun = new THREE.Group();
  sun.position.set(-0.292, 0.392, 0);
  sun.name = 'Sun';
  root.add(sun);

  const sunMaterial = new THREE.MeshStandardMaterial({
    color: 0xffd251,
    emissive: 0xff9d16,
    emissiveIntensity: 0.9,
    roughness: 0.5,
  });
  const sunSphere = new THREE.Mesh(unitSphere, sunMaterial);
  sunSphere.scale.setScalar(0.045);
  sunSphere.name = 'Sun surface';
  sun.add(sunSphere);

  const rays = new THREE.Group();
  rays.name = 'Sun rays';
  sun.add(rays);
  const rayMaterial = new THREE.MeshStandardMaterial({
    color: 0xffc33c,
    emissive: 0xff9b16,
    emissiveIntensity: 0.5,
  });
  for (let i = 0; i < 8; i++) {
    const angle = (i * Math.PI) / 4;
    const ray = new THREE.Mesh(unitBox, rayMaterial);
    ray.position.set(Math.cos(angle) * 0.067, Math.sin(angle) * 0.067, 0);
    ray.scale.set(0.009, 0.028, 0.009);
    ray.rotation.z = angle - Math.PI / 2;
    rays.add(ray);
  }
  traits(sun, { onPress: () => show('sun') });

  // A water drop marks the starting point of water uptake.
  const waterDrop = new THREE.Group();
  waterDrop.position.set(-0.335, 0.06, 0.06);
  waterDrop.name = 'Water drop';
  const waterMaterial = new THREE.MeshStandardMaterial({
    color: 0x43b6ff,
    emissive: 0x126bab,
    emissiveIntensity: 0.35,
    roughness: 0.3,
  });
  const dropBody = new THREE.Mesh(unitSphere, waterMaterial);
  dropBody.scale.set(0.016, 0.017, 0.016);
  waterDrop.add(dropBody);
  const dropTip = new THREE.Mesh(unitCone, waterMaterial);
  dropTip.position.y = 0.018;
  dropTip.scale.set(0.01, 0.02, 0.01);
  waterDrop.add(dropTip);
  root.add(waterDrop);
  traits(waterDrop, { onPress: () => show('water') });

  // Labeled arrows remain fixed while bright pulses show direction of flow.
  function addArrow(key, name, startArray, endArray, color, phase) {
    const start = new THREE.Vector3().fromArray(startArray);
    const end = new THREE.Vector3().fromArray(endArray);
    const direction = new THREE.Vector3().subVectors(end, start);
    const length = direction.length();

    const group = new THREE.Group();
    group.position.copy(start);
    group.quaternion.setFromUnitVectors(up, direction.normalize());
    group.name = name;
    root.add(group);

    const material = new THREE.MeshStandardMaterial({
      color,
      emissive: color,
      emissiveIntensity: 0.28,
      roughness: 0.42,
    });
    const headLength = Math.min(0.04, length * 0.25);
    const shaftLength = length - headLength;

    const shaft = new THREE.Mesh(unitCylinder, material);
    shaft.position.y = shaftLength * 0.5;
    shaft.scale.set(0.0085, shaftLength, 0.0085);
    shaft.name = name + ' shaft';
    group.add(shaft);

    const head = new THREE.Mesh(unitCone, material);
    head.position.y = shaftLength + headLength * 0.5;
    head.scale.set(0.021, headLength, 0.021);
    head.name = name + ' head';
    group.add(head);

    const pulseMaterial = new THREE.MeshBasicMaterial({ color });
    const pulses = [];
    for (let i = 0; i < 2; i++) {
      const pulse = new THREE.Mesh(unitSphere, pulseMaterial);
      pulse.scale.setScalar(0.0105);
      pulse.position.y = 0.012 + i * length * 0.35;
      pulse.userData.offset = i * 0.5;
      group.add(pulse);
      pulses.push(pulse);
    }

    arrows.push({ key, group, material, pulses, length, phase });
    traits(group, { onPress: () => show(key) });
  }

  addArrow(
    'light',
    'Light energy arrow',
    [-0.249, 0.346, 0.022],
    [-0.13, 0.285, 0.022],
    0xffd54a,
    0.1,
  );
  addArrow(
    'water',
    'Water arrow',
    [-0.309, 0.06, 0.06],
    [-0.114, 0.06, 0.06],
    0x43b6ff,
    0.3,
  );
  addArrow(
    'co2',
    'Carbon dioxide arrow',
    [0.205, 0.257, 0.025],
    [0.012, 0.257, 0.025],
    0xb8c5d1,
    0.55,
  );
  addArrow(
    'oxygen',
    'Oxygen arrow',
    [-0.058, 0.337, 0.022],
    [0.15, 0.385, 0.022],
    0x66e4cd,
    0.75,
  );

  // Blue pulses continue upward through the stem, representing xylem transport.
  const stemWaterPulses = [];
  const stemPulseMaterial = new THREE.MeshBasicMaterial({ color: 0x69c8ff });
  for (let i = 0; i < 3; i++) {
    const pulse = new THREE.Mesh(unitSphere, stemPulseMaterial);
    pulse.scale.set(0.006, 0.008, 0.006);
    pulse.position.set(-0.07, 0.11 + i * 0.055, 0.01);
    pulse.name = 'Water moving through xylem';
    root.add(pulse);
    stemWaterPulses.push(pulse);
  }

  function addLabel(text, rootPixels, widthMeters, position, accent, name) {
    const label = ui(
      `
      <style>
        .tag { width: ${rootPixels}px; display: flex; align-items: center; justify-content: center;
               padding-top: 8px; padding-bottom: 8px; padding-left: 10px; padding-right: 10px;
               background-color: #20262c; border-color: ${accent}; border-width: 2px; border-radius: 12px; }
        .label-text { color: ${accent}; font-size: 26px; font-weight: 700; text-align: center; }
      </style>
      <div class="tag"><span class="label-text">${text}</span></div>`,
      { width: widthMeters, position },
    );
    label.object3D.name = name;
    root.add(label.object3D);
    return label;
  }

  addLabel(
    'Light energy',
    220,
    0.13,
    [-0.295, 0.267, 0.035],
    '#ffdf71',
    'Light label',
  );
  addLabel(
    'Water (H2O)',
    240,
    0.13,
    [-0.245, 0.14, 0.035],
    '#79ccff',
    'Water label',
  );
  addLabel(
    'Carbon dioxide (CO2)',
    320,
    0.17,
    [0.18, 0.307, 0.035],
    '#d7e0e8',
    'Carbon dioxide label',
  );
  addLabel(
    'Oxygen (O2)',
    240,
    0.13,
    [0.195, 0.433, 0.035],
    '#8af1dd',
    'Oxygen label',
  );

  return {
    root,
    update(time, delta) {
      if (flowing) {
        flowTime += Math.min(delta, 0.05);
      }

      for (let i = 0; i < arrows.length; i++) {
        const arrow = arrows[i];
        const travel = Math.max(0.02, arrow.length - 0.04);

        for (let j = 0; j < arrow.pulses.length; j++) {
          const pulse = arrow.pulses[j];
          const phase =
            (flowTime * 0.32 + pulse.userData.offset + arrow.phase) % 1;
          pulse.position.y = 0.012 + phase * travel;
        }

        arrow.material.emissiveIntensity =
          selectedKey === arrow.key
            ? 0.85 + Math.sin(flowTime * 4) * 0.12
            : 0.28;
      }

      for (let i = 0; i < stemWaterPulses.length; i++) {
        const phase = (flowTime * 0.25 + i / 3) % 1;
        stemWaterPulses[i].position.y = 0.095 + phase * 0.19;
      }

      for (let i = 0; i < leaves.length; i++) {
        const leaf = leaves[i];
        leaf.rotation.z =
          leaf.userData.baseAngle +
          Math.sin(flowTime * 0.7 + leaf.userData.phase) * 0.018;
      }

      rays.rotation.z = flowTime * 0.08;
      sunMaterial.emissiveIntensity =
        0.9 + (flowing ? Math.sin(flowTime * 2) * 0.12 : 0);
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const days = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
  const habits = ['Water 2 L', 'Move 20 min', 'Read 15 min'];
  const checked = habits.map(() => Array(7).fill(false));

  let markup = `
    <style>
      .card { width: 600px; display: flex; flex-direction: column; gap: 12px;
              padding-top: 20px; padding-bottom: 20px; padding-left: 24px; padding-right: 24px;
              border-radius: 22px; background-color: #1c2026; border-color: #424a55; border-width: 2px; }
      .top { display: flex; flex-direction: row; align-items: center; justify-content: space-between; gap: 12px; }
      .titleblock { width: 366px; display: flex; flex-direction: column; gap: 5px; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .subtitle { color: #c3cbd5; font-size: 22px; }
      .totalbox { width: 154px; height: 54px; display: flex; align-items: center; justify-content: center;
                  border-radius: 14px; background-color: #29313a; }
      .total { color: #8ee2b0; font-size: 22px; font-weight: 700; text-align: center; }
      .weekhead { display: flex; flex-direction: row; align-items: center; gap: 8px; }
      .spacer { width: 134px; }
      .dayname { width: 50px; color: #aeb8c5; font-size: 20px; font-weight: 700; text-align: center; }
      .habitrow { display: flex; flex-direction: row; align-items: center; gap: 8px; }
      .habitmeta { width: 134px; height: 58px; display: flex; flex-direction: column;
                   justify-content: center; gap: 3px; }
      .habitname { color: #ffffff; font-size: 22px; font-weight: 700; }
      .streak { color: #8ee2b0; font-size: 22px; }
      .day { width: 50px; height: 58px; display: flex; flex-direction: column; align-items: center;
             justify-content: center; padding-top: 0px; padding-bottom: 0px; padding-left: 0px; padding-right: 0px;
             border-radius: 12px; background-color: #30363f; border-color: #505a67; border-width: 2px; }
      .daytext { color: #b9c2cd; font-size: 20px; font-weight: 700; text-align: center; }
      .footer { display: flex; flex-direction: row; align-items: center; justify-content: space-between; gap: 12px; }
      .hint { width: 390px; color: #aeb8c5; font-size: 20px; }
      .clear { width: 132px; height: 48px; display: flex; align-items: center; justify-content: center;
               padding-top: 0px; padding-bottom: 0px; padding-left: 0px; padding-right: 0px;
               border-radius: 12px; background-color: #39414c; border-color: #596575; border-width: 2px; }
      .cleartext { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <div class="top">
        <div class="titleblock">
          <span class="title">This week</span>
          <span class="subtitle">Tap a day to check it off. Tap again to undo.</span>
        </div>
        <div class="totalbox"><span class="total" id="total">0 / 21 done</span></div>
      </div>
      <div class="weekhead">
        <div class="spacer"></div>`;

  days.forEach((day, d) => {
    markup += `<span class="dayname" id="day${d}">${day}</span>`;
  });

  markup += `</div>`;

  habits.forEach((habit, h) => {
    markup += `
      <div class="habitrow">
        <div class="habitmeta">
          <span class="habitname">${habit}</span>
          <span class="streak" id="streak${h}">Streak: 0</span>
        </div>`;
    for (let d = 0; d < 7; d++) {
      markup += `
        <button class="day" id="h${h}d${d}">
          <span class="daytext" id="h${h}d${d}text">Open</span>
        </button>`;
    }
    markup += `</div>`;
  });

  markup += `
      <div class="footer">
        <span class="hint">Today is green. Streaks run back from the latest checked day.</span>
        <button class="clear" id="clear"><span class="cleartext">Clear week</span></button>
      </div>
    </div>`;

  const tracker = ui(markup, {
    width: 0.5,
    position: [0, 0.245, 0],
  });
  root.add(tracker.object3D);

  const today = (new Date().getDay() + 6) % 7;
  tracker.set(`day${today}`, { color: '#8ee2b0' });

  function streakFor(h) {
    let latest = 6;
    while (latest >= 0 && !checked[h][latest]) latest--;
    if (latest < 0) return 0;

    let streak = 0;
    for (let d = latest; d >= 0 && checked[h][d]; d--) streak++;
    return streak;
  }

  function refreshHabit(h) {
    tracker.set(`streak${h}`, { text: `Streak: ${streakFor(h)}` });

    let total = 0;
    for (let row = 0; row < habits.length; row++) {
      for (let d = 0; d < 7; d++) {
        if (checked[row][d]) total++;
      }
    }
    tracker.set('total', { text: `${total} / 21 done` });
  }

  function refreshDay(h, d) {
    const isDone = checked[h][d];
    tracker.set(`h${h}d${d}`, {
      backgroundColor: isDone ? '#23744f' : '#30363f',
      borderColor: isDone ? '#78dca4' : '#505a67',
    });
    tracker.set(`h${h}d${d}text`, {
      text: isDone ? 'Done' : 'Open',
      color: isDone ? '#ffffff' : '#b9c2cd',
    });
  }

  habits.forEach((habit, h) => {
    days.forEach((day, d) => {
      tracker.on(`h${h}d${d}`, 'click', () => {
        checked[h][d] = !checked[h][d];
        refreshDay(h, d);
        refreshHabit(h);
      });
    });
  });

  tracker.on('clear', 'click', () => {
    habits.forEach((habit, h) => {
      for (let d = 0; d < 7; d++) {
        checked[h][d] = false;
        refreshDay(h, d);
      }
      refreshHabit(h);
    });
  });

  return { root };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();
  root.name = 'Multiplication Quiz';

  const questions = [
    { a: 6, b: 7, options: [42, 36, 48, 40], correct: 0 },
    { a: 8, b: 8, options: [56, 64, 72, 62], correct: 1 },
    { a: 12, b: 4, options: [44, 52, 48, 36], correct: 2 },
    { a: 11, b: 7, options: [70, 87, 66, 77], correct: 3 },
    { a: 9, b: 5, options: [54, 45, 40, 49], correct: 1 },
  ];

  let current = 0;
  let score = 0;
  let answered = false;
  let finished = false;
  let modelOn = false;
  const results = [null, null, null, null, null];

  const panel = ui(`
    <style>
      .card { width: 540px; flex-direction: column; gap: 10px;
              padding-top: 20px; padding-bottom: 20px; padding-left: 22px; padding-right: 22px;
              border-radius: 20px; background-color: #1b2028;
              border-width: 2px; border-color: #3c485a; }
      .top { flex-direction: row; justify-content: space-between; align-items: center; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .score { color: #ffd166; font-size: 24px; font-weight: 700; }
      .meta { color: #b9c5d6; font-size: 22px; }
      .prompt { color: #ffffff; font-size: 38px; font-weight: 700; text-align: center;
                padding-top: 4px; padding-bottom: 4px; }
      .answers { flex-direction: column; gap: 10px; }
      .row { flex-direction: row; gap: 12px; }
      .answer { width: 242px; height: 54px; align-items: center; justify-content: center;
                border-radius: 12px; background-color: #303b4b;
                border-width: 2px; border-color: #52617a; }
      .answer-text { color: #ffffff; font-size: 26px; font-weight: 700; }
      .feedback { width: 496px; height: 52px; color: #d5dce6; font-size: 22px; text-align: center; }
      .controls { flex-direction: row; justify-content: center; gap: 12px; }
      .control { width: 238px; height: 52px; align-items: center; justify-content: center;
                 border-radius: 12px; background-color: #37517a; }
      .next { background-color: #2f6fdb; }
      .control-text { color: #ffffff; font-size: 22px; font-weight: 700; }
      .model-info { width: 496px; height: 52px; color: #aeb9ca; font-size: 22px; text-align: center; }
      .hidden { display: none; }
    </style>
    <div class="card">
      <div class="top">
        <span class="title" id="title">Multiplication Quiz</span>
        <span class="score" id="score">Score: 0</span>
      </div>
      <span class="meta" id="progress">Question 1 of 5</span>
      <span class="prompt" id="question">6 x 7 = ?</span>
      <div class="answers" id="answers">
        <div class="row">
          <button class="answer" id="a0"><span class="answer-text" id="a0text">42</span></button>
          <button class="answer" id="a1"><span class="answer-text" id="a1text">36</span></button>
        </div>
        <div class="row">
          <button class="answer" id="a2"><span class="answer-text" id="a2text">48</span></button>
          <button class="answer" id="a3"><span class="answer-text" id="a3text">40</span></button>
        </div>
      </div>
      <span class="feedback" id="feedback">Choose the correct product.</span>
      <div class="controls">
        <button class="control" id="modelBtn"><span class="control-text" id="modelText">Show groups</span></button>
        <button class="control next hidden" id="next"><span class="control-text" id="nextText">Next question</span></button>
      </div>
      <span class="model-info" id="modelInfo">Press Show groups for an equal-groups hint below.</span>
    </div>`, { width: 0.42, position: [0, 0.26, -0.055] });
  root.add(panel.object3D);

  const tray = new THREE.Mesh(
    new THREE.BoxGeometry(0.26, 0.012, 0.26),
    new THREE.MeshStandardMaterial({ color: 0x202832, roughness: 0.75, metalness: 0.1 }),
  );
  tray.name = 'Equal groups tray';
  tray.position.set(0, 0.006, 0.145);
  root.add(tray);

  const dummy = new THREE.Object3D();
  const color = new THREE.Color();
  const rowColors = [0x4f8edc, 0x47bfa0, 0xf0b24a, 0xd96aa0, 0x8b7de8, 0xe87852];

  const model = new THREE.InstancedMesh(
    new THREE.BoxGeometry(0.011, 0.011, 0.011),
    new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.5 }),
    144,
  );
  model.name = 'Equal groups model';
  model.frustumCulled = false;
  model.visible = false;
  root.add(model);

  const markers = new THREE.InstancedMesh(
    new THREE.SphereGeometry(0.01, 12, 8),
    new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.45 }),
    5,
  );
  markers.name = 'Question progress markers';
  markers.frustumCulled = false;
  for (let i = 0; i < 5; i++) {
    dummy.position.set((i - 2) * 0.038, 0.022, 0.028);
    dummy.updateMatrix();
    markers.setMatrixAt(i, dummy.matrix);
  }
  markers.instanceMatrix.needsUpdate = true;
  root.add(markers);

  function updateMarkers() {
    for (let i = 0; i < 5; i++) {
      let markerColor = 0x4a5565;
      if (results[i] === true) markerColor = 0x39d98a;
      if (results[i] === false) markerColor = 0xff6b6b;
      if (results[i] === null && i === current && !finished) markerColor = 0xffd166;
      markers.setColorAt(i, color.setHex(markerColor));
    }
    if (markers.instanceColor) markers.instanceColor.needsUpdate = true;
  }

  function updateModel(q) {
    const rows = q.a;
    const columns = q.b;
    const spacing = 0.015;
    let index = 0;

    for (let row = 0; row < rows; row++) {
      for (let column = 0; column < columns; column++) {
        dummy.position.set(
          (column - (columns - 1) / 2) * spacing,
          0.0185,
          0.145 + (row - (rows - 1) / 2) * spacing,
        );
        dummy.updateMatrix();
        model.setMatrixAt(index, dummy.matrix);
        model.setColorAt(index, color.setHex(rowColors[row % rowColors.length]));
        index++;
      }
    }

    model.count = index;
    model.instanceMatrix.needsUpdate = true;
    if (model.instanceColor) model.instanceColor.needsUpdate = true;
  }

  function modelInfoText() {
    const q = questions[current];
    if (!modelOn) return 'Press Show groups for an equal-groups hint below.';
    if (answered) return `${q.a} rows of ${q.b} cubes makes ${q.a * q.b}.`;
    return `${q.a} rows of ${q.b} cubes. Count them to find the product.`;
  }

  function renderQuestion() {
    const q = questions[current];
    answered = false;
    modelOn = false;
    model.visible = false;
    updateModel(q);

    panel.set('title', { text: 'Multiplication Quiz' });
    panel.set('score', { text: `Score: ${score}` });
    panel.set('progress', { text: `Question ${current + 1} of 5` });
    panel.set('question', { text: `${q.a} x ${q.b} = ?` });
    panel.set('feedback', { text: 'Choose the correct product.', color: '#d5dce6' });
    panel.set('answers', { display: 'flex' });
    panel.set('modelBtn', { display: 'flex' });
    panel.set('modelText', { text: 'Show groups' });
    panel.set('modelInfo', { text: modelInfoText() });
    panel.set('next', { display: 'none' });

    for (let i = 0; i < 4; i++) {
      panel.set(`a${i}text`, { text: `${q.options[i]}` });
      panel.set(`a${i}`, { backgroundColor: '#303b4b' });
    }

    updateMarkers();
  }

  function chooseAnswer(choice) {
    if (answered || finished) return;

    answered = true;
    const q = questions[current];
    const isCorrect = choice === q.correct;
    results[current] = isCorrect;

    if (isCorrect) {
      score++;
      panel.set('score', { text: `Score: ${score}` });
      panel.set('feedback', {
        text: `Correct! ${q.a} x ${q.b} = ${q.a * q.b}.`,
        color: '#73e2a7',
      });
    } else {
      panel.set(`a${choice}`, { backgroundColor: '#873744' });
      panel.set('feedback', {
        text: `Not quite. ${q.a} x ${q.b} = ${q.a * q.b}.`,
        color: '#ff9aa5',
      });
    }

    panel.set(`a${q.correct}`, { backgroundColor: '#176b4d' });
    panel.set('nextText', { text: current === questions.length - 1 ? 'See results' : 'Next question' });
    panel.set('next', { display: 'flex' });
    panel.set('modelInfo', { text: modelInfoText() });
    updateMarkers();
  }

  function showResults() {
    finished = true;
    modelOn = false;
    model.visible = false;

    panel.set('title', { text: 'Quiz complete' });
    panel.set('progress', { text: `${score * 20}% correct` });
    panel.set('question', { text: `Final score: ${score} / 5` });
    panel.set('answers', { display: 'none' });
    panel.set('modelBtn', { display: 'none' });
    panel.set('nextText', { text: 'Restart quiz' });
    panel.set('next', { display: 'flex' });
    panel.set('modelInfo', { text: 'Restart to try the same five questions again.' });

    let message = `You scored ${score} out of 5. Use equal groups and try again.`;
    if (score >= 3) message = `You scored ${score} out of 5. Good work - try again to improve.`;
    if (score === 5) message = 'Perfect score: 5 out of 5. Excellent work!';
    panel.set('feedback', { text: message, color: '#ffd166' });
    updateMarkers();
  }

  function resetQuiz() {
    current = 0;
    score = 0;
    finished = false;
    for (let i = 0; i < results.length; i++) results[i] = null;
    renderQuestion();
  }

  for (let i = 0; i < 4; i++) {
    panel.on(`a${i}`, 'click', () => chooseAnswer(i));
  }

  panel.on('modelBtn', 'click', () => {
    if (finished) return;
    modelOn = !modelOn;
    model.visible = modelOn;
    panel.set('modelText', { text: modelOn ? 'Hide groups' : 'Show groups' });
    panel.set('modelInfo', { text: modelInfoText() });
  });

  panel.on('next', 'click', () => {
    if (finished) {
      resetQuiz();
      return;
    }
    if (!answered) return;
    if (current === questions.length - 1) {
      showResults();
    } else {
      current++;
      renderQuestion();
    }
  });

  renderQuestion();
  return { root };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const BUILD_X = -0.085;
  const BUILD_Z = -0.045;
  const BUILD_RADIUS = 0.148;

  // Atom supply tray.
  const tray = new THREE.Mesh(
    new THREE.BoxGeometry(0.66, 0.012, 0.105),
    new THREE.MeshStandardMaterial({ color: 0x252c34, roughness: 0.78 }),
  );
  tray.name = 'Atom supply tray';
  tray.position.set(-0.02, 0.006, 0.174);
  root.add(tray);

  // The raised rings show the 3D region in which the molecule is checked.
  const zonePadMaterial = new THREE.MeshStandardMaterial({
    color: 0x17313b,
    emissive: 0x092532,
    emissiveIntensity: 0.35,
    roughness: 0.72,
    transparent: true,
    opacity: 0.82,
  });
  const zonePad = new THREE.Mesh(
    new THREE.CylinderGeometry(BUILD_RADIUS, BUILD_RADIUS, 0.012, 48),
    zonePadMaterial,
  );
  zonePad.name = 'Build zone';
  zonePad.position.set(BUILD_X, 0.006, BUILD_Z);
  root.add(zonePad);

  const ringGeometry = new THREE.TorusGeometry(BUILD_RADIUS, 0.0035, 8, 64);
  const bottomRingMaterial = new THREE.MeshBasicMaterial({
    color: 0x54c7ec,
    transparent: true,
    opacity: 0.8,
    depthWrite: false,
  });
  const upperRingMaterial = new THREE.MeshBasicMaterial({
    color: 0x54c7ec,
    transparent: true,
    opacity: 0.22,
    depthWrite: false,
  });

  const bottomRing = new THREE.Mesh(ringGeometry, bottomRingMaterial);
  bottomRing.name = 'Build zone lower ring';
  bottomRing.rotation.x = Math.PI / 2;
  bottomRing.position.set(BUILD_X, 0.018, BUILD_Z);
  root.add(bottomRing);

  const upperRing = new THREE.Mesh(ringGeometry, upperRingMaterial);
  upperRing.name = 'Build zone upper ring';
  upperRing.rotation.x = Math.PI / 2;
  upperRing.position.set(BUILD_X, 0.262, BUILD_Z);
  root.add(upperRing);

  const postGeometry = new THREE.CylinderGeometry(0.0014, 0.0014, 0.24, 6);
  const postOffsets = [
    [BUILD_RADIUS, 0],
    [-BUILD_RADIUS, 0],
    [0, BUILD_RADIUS],
    [0, -BUILD_RADIUS],
  ];
  for (const offset of postOffsets) {
    const post = new THREE.Mesh(postGeometry, upperRingMaterial);
    post.name = 'Build zone guide';
    post.position.set(BUILD_X + offset[0], 0.142, BUILD_Z + offset[1]);
    root.add(post);
  }

  const hydrogenGeometry = new THREE.SphereGeometry(0.028, 24, 12);
  const oxygenGeometry = new THREE.SphereGeometry(0.036, 32, 16);
  const hydrogenMaterial = new THREE.MeshStandardMaterial({
    color: 0xf2f5f7,
    emissive: 0x344050,
    emissiveIntensity: 0.15,
    roughness: 0.28,
  });
  const oxygenMaterial = new THREE.MeshStandardMaterial({
    color: 0xe84c42,
    emissive: 0x3b0905,
    emissiveIntensity: 0.25,
    roughness: 0.32,
  });

  const atomSpecs = [
    { name: 'Hydrogen 1', type: 'H', position: [-0.28, 0.041, 0.174] },
    { name: 'Hydrogen 2', type: 'H', position: [-0.165, 0.041, 0.174] },
    { name: 'Hydrogen 3', type: 'H', position: [-0.05, 0.041, 0.174] },
    { name: 'Oxygen 1', type: 'O', position: [0.09, 0.049, 0.174] },
    { name: 'Oxygen 2', type: 'O', position: [0.235, 0.049, 0.174] },
  ];

  const atoms = [];
  const homePositions = [];

  for (const spec of atomSpecs) {
    const isHydrogen = spec.type === 'H';
    const atom = new THREE.Mesh(
      isHydrogen ? hydrogenGeometry : oxygenGeometry,
      isHydrogen ? hydrogenMaterial : oxygenMaterial,
    );
    atom.name = spec.name;
    atom.userData.element = spec.type;
    atom.position.fromArray(spec.position);
    root.add(atom);
    traits(atom, { grab: true });
    atoms.push(atom);
    homePositions.push(atom.position.clone());
  }

  // Reused bond meshes connect nearby atoms in model space.
  const bondGeometry = new THREE.CylinderGeometry(0.005, 0.005, 1, 8);
  const ohBondMaterial = new THREE.MeshStandardMaterial({
    color: 0xdbe7ed,
    roughness: 0.38,
    metalness: 0.12,
  });
  const hhBondMaterial = new THREE.MeshStandardMaterial({
    color: 0x91adbd,
    roughness: 0.42,
  });
  const ooBondMaterial = new THREE.MeshStandardMaterial({
    color: 0xc88480,
    roughness: 0.42,
  });

  const OH_MIN = 0.055;
  const OH_MAX = 0.11;
  const HH_MAX = 0.06;
  const bonds = [];

  for (let i = 0; i < atoms.length; i++) {
    for (let j = i + 1; j < atoms.length; j++) {
      const typeA = atoms[i].userData.element;
      const typeB = atoms[j].userData.element;
      const isOH = typeA !== typeB;
      const isHH = typeA === 'H' && typeB === 'H';
      const mesh = new THREE.Mesh(
        bondGeometry,
        isOH ? ohBondMaterial : (isHH ? hhBondMaterial : ooBondMaterial),
      );
      mesh.name = `Bond ${atoms[i].name} - ${atoms[j].name}`;
      mesh.visible = false;
      root.add(mesh);
      bonds.push({
        a: atoms[i],
        b: atoms[j],
        mesh,
        min: isOH ? OH_MIN : (isHH ? 0.034 : 0.045),
        max: isOH ? OH_MAX : (isHH ? HH_MAX : 0.1),
      });
    }
  }

  const bondDelta = new THREE.Vector3();
  const bondDirection = new THREE.Vector3();
  const bondMidpoint = new THREE.Vector3();
  const cylinderAxis = new THREE.Vector3(0, 1, 0);

  const panel = ui(`
    <style>
      .card { width: 500px; flex-direction: column; gap: 10px; padding-top: 18px;
              padding-bottom: 18px; padding-left: 22px; padding-right: 22px;
              border-radius: 18px; border-width: 1px; border-color: #3c4852;
              background-color: #1c2229; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 22px; }
      .goal { color: #a9ddf0; font-size: 22px; }
      .legend-row { flex-direction: row; gap: 24px; align-items: center; }
      .hydrogen-label { color: #f2f5f7; font-size: 22px; font-weight: 700; }
      .oxygen-label { color: #ff8a84; font-size: 22px; font-weight: 700; }
      .button-row { flex-direction: row; gap: 12px; align-items: center; }
      .check-button { padding-top: 10px; padding-bottom: 10px; padding-left: 16px;
                      padding-right: 16px; border-radius: 12px; background-color: #167a91; }
      .reset-button { padding-top: 10px; padding-bottom: 10px; padding-left: 16px;
                      padding-right: 16px; border-radius: 12px; background-color: #363e48; }
      .button-text { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Molecule lab</span>
      <span class="body">Pinch and drag atoms into the blue build zone. Close atoms form bonds.</span>
      <div class="legend-row">
        <span class="hydrogen-label">H = white (3)</span>
        <span class="oxygen-label">O = red (2)</span>
      </div>
      <span class="goal">Water: 2 H + 1 O, two O-H bonds, bent near 104.5°.</span>
      <span class="body" id="status">Move atoms, then press Check molecule.</span>
      <div class="button-row">
        <button class="check-button" id="check"><span class="button-text">Check molecule</span></button>
        <button class="reset-button" id="reset"><span class="button-text">Reset</span></button>
      </div>
    </div>`, {
    width: 0.34,
    position: [0.27, 0.32, -0.035],
    rotationY: -0.28,
  });
  root.add(panel.object3D);

  let builtWater = false;

  function setZoneSuccess(success) {
    const color = success ? 0x7dffad : 0x54c7ec;
    bottomRingMaterial.color.setHex(color);
    upperRingMaterial.color.setHex(color);
    zonePadMaterial.emissive.setHex(success ? 0x164d31 : 0x092532);
  }

  function isInBuildZone(atom) {
    const dx = atom.position.x - BUILD_X;
    const dz = atom.position.z - BUILD_Z;
    return (
      atom.position.y >= 0.02 &&
      atom.position.y <= 0.275 &&
      dx * dx + dz * dz <= BUILD_RADIUS * BUILD_RADIUS
    );
  }

  function showStatus(text, color) {
    panel.set('status', { text, color });
  }

  function checkMolecule() {
    builtWater = false;
    setZoneSuccess(false);

    const inside = atoms.filter(isInBuildZone);
    const hydrogens = inside.filter((atom) => atom.userData.element === 'H');
    const oxygens = inside.filter((atom) => atom.userData.element === 'O');

    if (inside.length === 0) {
      showStatus('The build zone is empty. Bring in 2 H and 1 O.', '#ffd28a');
      return;
    }

    if (hydrogens.length !== 2 || oxygens.length !== 1) {
      if (inside.length > 3 && hydrogens.length >= 2 && oxygens.length >= 1) {
        showStatus(
          'Too many atoms are in the zone. Water is exactly 2 H and 1 O; move extras back to the tray.',
          '#ffd28a',
        );
      } else {
        showStatus(
          `Water needs 2 H and 1 O. Build zone: ${hydrogens.length} H and ${oxygens.length} O.`,
          '#ffd28a',
        );
      }
      return;
    }

    const oxygen = oxygens[0];
    const toH1 = new THREE.Vector3().subVectors(hydrogens[0].position, oxygen.position);
    const toH2 = new THREE.Vector3().subVectors(hydrogens[1].position, oxygen.position);
    const distance1 = toH1.length();
    const distance2 = toH2.length();

    if (distance1 < OH_MIN || distance2 < OH_MIN) {
      showStatus(
        'Some atoms are stacked together. Separate them so each H sits against O, not inside it.',
        '#ffd28a',
      );
      return;
    }

    const connected1 = distance1 <= OH_MAX;
    const connected2 = distance2 <= OH_MAX;

    if (!connected1 || !connected2) {
      const bondCount = (connected1 ? 1 : 0) + (connected2 ? 1 : 0);
      if (bondCount === 0) {
        showStatus(
          'Correct atoms, but no O-H bonds yet. Place each white H against the red O.',
          '#ffd28a',
        );
      } else {
        showStatus(
          'One O-H bond is connected. Bring the second H to the same O.',
          '#ffd28a',
        );
      }
      return;
    }

    const hydrogenDistance = hydrogens[0].position.distanceTo(hydrogens[1].position);
    if (hydrogenDistance < HH_MAX) {
      showStatus(
        'The H atoms are also bonded together. Separate them so only two O-H bonds remain.',
        '#ffd28a',
      );
      return;
    }

    const cosine = THREE.MathUtils.clamp(
      toH1.dot(toH2) / (distance1 * distance2),
      -1,
      1,
    );
    const angle = Math.acos(cosine) * 180 / Math.PI;

    if (angle < 80 || angle > 130) {
      const shapeHint = angle > 150
        ? 'It is too straight; water is bent.'
        : 'Move the H atoms to adjust the angle.';
      showStatus(
        `The H-O-H angle is ${Math.round(angle)}°. ${shapeHint} Aim near 104.5°.`,
        '#ffd28a',
      );
      return;
    }

    builtWater = true;
    setZoneSuccess(true);
    showStatus(
      `Yes - you built water, H2O! Two O-H bonds, bent at ${Math.round(angle)}°. Water is polar.`,
      '#9df2b6',
    );
  }

  panel.on('check', 'click', checkMolecule);
  panel.on('reset', 'click', () => {
    builtWater = false;
    setZoneSuccess(false);
    for (let i = 0; i < atoms.length; i++) {
      atoms[i].position.copy(homePositions[i]);
      atoms[i].rotation.set(0, 0, 0);
    }
    showStatus('Atoms returned to the tray. Build 2 H + 1 O, then check.', '#d7dbe2');
  });

  return {
    root,
    update(time) {
      const pulse = builtWater
        ? 1 + Math.sin(time * 4) * 0.035
        : 1 + Math.sin(time * 2) * 0.012;
      bottomRing.scale.setScalar(pulse);

      for (const bond of bonds) {
        bondDelta.subVectors(bond.b.position, bond.a.position);
        const distance = bondDelta.length();

        if (distance < bond.min || distance > bond.max) {
          bond.mesh.visible = false;
          continue;
        }

        bond.mesh.visible = true;
        bondMidpoint.addVectors(bond.a.position, bond.b.position).multiplyScalar(0.5);
        bond.mesh.position.copy(bondMidpoint);
        bondDirection.copy(bondDelta).multiplyScalar(1 / distance);
        bond.mesh.quaternion.setFromUnitVectors(cylinderAxis, bondDirection);
        bond.mesh.scale.set(1, distance, 1);
      }

      if (builtWater) {
        for (const atom of atoms) {
          if (isGrabbed(atom)) {
            builtWater = false;
            setZoneSuccess(false);
            showStatus('Molecule changed. Press Check molecule when ready.', '#d7dbe2');
            break;
          }
        }
      }
    },
  };
}

