      </div>
      <span class="total" id="total">Total: $0.00</span>
      <span class="status" id="status">Basket: empty</span>
      <button class="btn" id="empty"><span class="btn-text">Empty basket</span></button>
    </div>`, {
    width: 0.38,
    position: [-0.16, 0.27, -0.15],
    rotationY: 0.12,
  });
  root.add(info.object3D);

  function updateReceipt() {
    let cents = 0;
    const names = [];
    for (let i = 0; i < fruits.length; i++) {
      if (fruits[i].inBasket) {
        cents += fruits[i].cents;
        names.push(fruits[i].name);
      }
    }
    info.set('total', { text: 'Total: $' + (cents / 100).toFixed(2) });
    info.set('status', { text: names.length ? 'Basket: ' + names.join(', ') : 'Basket: empty' });
  }

  function handleDrop(fruit) {
    const p = fruit.object.position;
    const overOpening =
      Math.abs(p.x - basketCenter.x) <= 0.125 &&
      Math.abs(p.z - basketCenter.z) <= 0.1 &&
      p.y > 0.015 &&
      p.y < 0.34;

    if (overOpening) {
      fruit.inBasket = true;
      p.copy(fruit.slot);
    } else {
      fruit.inBasket = false;
      const x = Math.max(-0.3, Math.min(0.34, p.x));
      const z = Math.max(-0.1, Math.min(0.18, p.z));
      p.set(x, fruit.restY, z);
    }
    updateReceipt();
  }

  info.on('empty', 'click', () => {
    for (let i = 0; i < fruits.length; i++) {
      const fruit = fruits[i];
      const held = isGrabbed(fruit.object);
      fruit.inBasket = false;
      fruit.wasGrabbed = held;
      if (!held) fruit.object.position.copy(fruit.home);
    }
    updateReceipt();
  });

  return {
    root,
    update(time) {
      let anyGrabbed = false;

      for (let i = 0; i < fruits.length; i++) {
        const fruit = fruits[i];
        const grabbed = isGrabbed(fruit.object);

        if (grabbed) {
          anyGrabbed = true;
          fruit.wasGrabbed = true;
        } else if (fruit.wasGrabbed) {
          fruit.wasGrabbed = false;
          handleDrop(fruit);
        }
      }

      glowMaterial.opacity = anyGrabbed ? 0.24 + Math.sin(time * 5) * 0.07 : 0.03;
      rimMaterial.emissiveIntensity = anyGrabbed ? 0.3 : 0.02;
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const O_RADIUS = 0.04;
  const H_RADIUS = 0.025;
  const TARGET_DISTANCE = 0.088;
  const MIN_BOND_DISTANCE = 0.048;
  const MAX_BOND_DISTANCE = 0.115;

  // A compact assembly area on the desk.
  const base = new THREE.Mesh(
    new THREE.CylinderGeometry(0.19, 0.19, 0.018, 40),
    new THREE.MeshStandardMaterial({ color: 0x252b33, roughness: 0.82, metalness: 0.08 }),
  );
  base.name = 'Assembly area';
  base.position.set(-0.135, 0.009, 0);
  root.add(base);

  const baseRing = new THREE.Mesh(
    new THREE.TorusGeometry(0.164, 0.0015, 6, 48),
    new THREE.MeshBasicMaterial({ color: 0x536575 }),
  );
  baseRing.position.set(-0.135, 0.019, 0);
  baseRing.rotation.x = Math.PI / 2;
  root.add(baseRing);

  const oxygenMaterial = new THREE.MeshStandardMaterial({
    color: 0xd94841,
    roughness: 0.4,
    metalness: 0.04,
    emissive: 0xff5b4d,
    emissiveIntensity: 0,
  });
  const h1Material = new THREE.MeshStandardMaterial({
    color: 0xf2f4f7,
    roughness: 0.36,
    emissive: 0xa9e5ff,
    emissiveIntensity: 0,
  });
  const h2Material = h1Material.clone();

  const oxygen = new THREE.Group();
  oxygen.name = 'Oxygen atom';
  const oxygenSphere = new THREE.Mesh(
    new THREE.SphereGeometry(O_RADIUS, 32, 16),
    oxygenMaterial,
  );
  oxygenSphere.name = 'Oxygen';
  oxygen.add(oxygenSphere);

  // A geometric O label on the front of the red sphere.
  const oLabel = new THREE.Mesh(
    new THREE.TorusGeometry(0.012, 0.0025, 8, 28),
    new THREE.MeshBasicMaterial({ color: 0xffffff }),
  );
  oLabel.position.z = O_RADIUS + 0.0005;
  oxygen.add(oLabel);
  oxygen.position.set(-0.135, 0.15, 0);
  root.add(oxygen);

  const hVerticalGeometry = new THREE.BoxGeometry(0.004, 0.021, 0.002);
  const hCrossGeometry = new THREE.BoxGeometry(0.017, 0.004, 0.002);
  const hLabelMaterial = new THREE.MeshBasicMaterial({ color: 0x263747 });
  const hydrogenGeometry = new THREE.SphereGeometry(H_RADIUS, 24, 16);

  function makeHydrogen(name, material) {
    const atom = new THREE.Group();
    atom.name = name;

    const sphere = new THREE.Mesh(hydrogenGeometry, material);
    sphere.name = name;
    atom.add(sphere);

    // Three small bars form an H without requiring a font or texture.
    const left = new THREE.Mesh(hVerticalGeometry, hLabelMaterial);
    left.position.set(-0.007, 0, H_RADIUS + 0.0007);
    atom.add(left);

    const right = new THREE.Mesh(hVerticalGeometry, hLabelMaterial);
    right.position.set(0.007, 0, H_RADIUS + 0.0007);
    atom.add(right);

    const cross = new THREE.Mesh(hCrossGeometry, hLabelMaterial);
    cross.position.set(0, 0, H_RADIUS + 0.0007);
    atom.add(cross);

    root.add(atom);
    return atom;
  }

  const hydrogen1 = makeHydrogen('Hydrogen 1', h1Material);
  const hydrogen2 = makeHydrogen('Hydrogen 2', h2Material);
  hydrogen1.position.set(-0.285, 0.047, 0.065);
  hydrogen2.position.set(-0.005, 0.047, 0.065);

  const oxygenStart = oxygen.position.clone();
  const hydrogen1Start = hydrogen1.position.clone();
  const hydrogen2Start = hydrogen2.position.clone();

  traits(oxygen, { grab: true });
  traits(hydrogen1, { grab: true });
  traits(hydrogen2, { grab: true });

  // Faint targets show the correct O-H spacing and 104.5 degree H-O-H angle.
  // This guide is separate from the oxygen grab group so it cannot steal a pinch.
  const guide = new THREE.Group();
  guide.name = 'Water assembly guide';
  root.add(guide);

  const guideMaterial = new THREE.MeshBasicMaterial({
    color: 0x75c9dd,
    transparent: true,
    opacity: 0.22,
    depthWrite: false,
  });
  const guideRingGeometry = new THREE.TorusGeometry(H_RADIUS * 1.12, 0.002, 6, 28);
  const guideRodGeometry = new THREE.CylinderGeometry(0.0017, 0.0017, 1, 8);
  const up = new THREE.Vector3(0, 1, 0);
  const halfAngle = THREE.MathUtils.degToRad(104.5 / 2);
  const targetX = Math.sin(halfAngle) * TARGET_DISTANCE;
  const targetY = -Math.cos(halfAngle) * TARGET_DISTANCE;
  const guideTargets = [
    new THREE.Vector3(-targetX, targetY, 0),
    new THREE.Vector3(targetX, targetY, 0),
  ];

  for (const target of guideTargets) {
    const ring = new THREE.Mesh(guideRingGeometry, guideMaterial);
    ring.position.copy(target);
    guide.add(ring);

    const rod = new THREE.Mesh(guideRodGeometry, guideMaterial);
    rod.position.copy(target).multiplyScalar(0.5);
    rod.scale.y = TARGET_DISTANCE;
    const direction = target.clone().normalize();
    rod.quaternion.setFromUnitVectors(up, direction);
    guide.add(rod);
  }

  const bondMaterial = new THREE.MeshStandardMaterial({
    color: 0xb8c4ce,
    roughness: 0.35,
    emissive: 0x65d9ff,
    emissiveIntensity: 0.04,
  });
  const bondGeometry = new THREE.CylinderGeometry(0.0055, 0.0055, 1, 12);
  const bond1 = new THREE.Mesh(bondGeometry, bondMaterial);
  const bond2 = new THREE.Mesh(bondGeometry, bondMaterial);
  bond1.name = 'O-H bond 1';
  bond2.name = 'O-H bond 2';
  root.add(bond1, bond2);

  const panel = ui(`
    <style>
      .card { width: 470px; display: flex; flex-direction: column; gap: 12px;
              padding-top: 20px; padding-bottom: 20px; padding-left: 22px; padding-right: 22px;
              border-radius: 18px; border-width: 1px; border-color: #414853;
              background-color: #1f232a; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 23px; }
      .result { color: #d7dbe2; font-size: 24px; font-weight: 700; }
      .row { display: flex; flex-direction: row; gap: 12px; }
      .check { width: 260px; padding-top: 12px; padding-bottom: 12px;
               padding-left: 12px; padding-right: 12px; border-radius: 12px;
               background-color: #2f6fdb; }
      .reset { width: 130px; padding-top: 12px; padding-bottom: 12px;
               padding-left: 10px; padding-right: 10px; border-radius: 12px;
               background-color: #353b45; }
      .buttonText { color: #ffffff; font-size: 24px; font-weight: 700; }
      .hint { color: #aeb9c5; font-size: 21px; }
    </style>
    <div class="card">
      <span class="title">Build a water molecule</span>
      <span class="body">Grab the red O and two white H atoms. Move each H into a faint blue ring near O, then press Check.</span>
      <span class="result" id="result">Goal: H2O = 2 hydrogen atoms + 1 oxygen atom.</span>
      <div class="row">
        <button class="check" id="check"><span class="buttonText">Check molecule</span></button>
        <button class="reset" id="reset"><span class="buttonText">Reset</span></button>
      </div>
      <span class="hint">Water is bent: the H-O-H angle is about 104.5°.</span>
    </div>`, {
    width: 0.3,
    position: [0.22, 0.205, 0.02],
    rotationY: -0.28,
  });
  root.add(panel.object3D);

  let builtWater = false;
  const vector1 = new THREE.Vector3();
  const vector2 = new THREE.Vector3();
  const bondDirection = new THREE.Vector3();

  function setResult(text, color) {
    panel.set('result', { text, color });
  }

  panel.on('check', 'click', () => {
    builtWater = false;
    bondMaterial.color.setHex(0xb8c4ce);

    vector1.copy(hydrogen1.position).sub(oxygen.position);
    vector2.copy(hydrogen2.position).sub(oxygen.position);
    const distance1 = vector1.length();
    const distance2 = vector2.length();

    if (distance1 < MIN_BOND_DISTANCE || distance2 < MIN_BOND_DISTANCE) {
      setResult('Not yet: atoms are overlapping. Leave a short bond between each H and O.', '#ffd58a');
      return;
    }

    const bondCount =
      (distance1 <= MAX_BOND_DISTANCE ? 1 : 0) +
      (distance2 <= MAX_BOND_DISTANCE ? 1 : 0);

    if (bondCount === 0) {
      setResult('No O-H bonds yet. Move both white H atoms close to the red O.', '#ffb0a6');
      return;
    }
    if (bondCount === 1) {
      setResult('One O-H bond is formed. Bring the other H atom close to O.', '#ffd58a');
      return;
    }

    vector1.normalize();
    vector2.normalize();
    const angle = THREE.MathUtils.radToDeg(
      Math.acos(THREE.MathUtils.clamp(vector1.dot(vector2), -1, 1)),
    );

    if (angle < 80) {
      setResult('Both bonds formed, but the H atoms are too close together. Spread them into a wide V.', '#ffd58a');
      return;
    }
    if (angle > 130) {
      if (angle > 155) {
        setResult('The bonds make almost a straight line. Put both H atoms on the same side of O.', '#ffd58a');
      } else {
        setResult('Too open. Bring the H ends toward each other to approach 104.5°.', '#ffd58a');
      }
      return;
    }

    builtWater = true;
    bondMaterial.color.setHex(0x8fd8e8);
    setResult(
      'Yes - you built water! H2O has 2 O-H bonds and a bent 104.5° shape. Your angle: ' +
        Math.round(angle) + '°.',
      '#9ff0b2',
    );
  });

  panel.on('reset', 'click', () => {
    builtWater = false;
    oxygen.position.copy(oxygenStart);
    hydrogen1.position.copy(hydrogen1Start);
    hydrogen2.position.copy(hydrogen2Start);
    oxygen.rotation.set(0, 0, 0);
    hydrogen1.rotation.set(0, 0, 0);
    hydrogen2.rotation.set(0, 0, 0);
    bondMaterial.color.setHex(0xb8c4ce);
    setResult('Reset. Place both H atoms in the blue rings around O, then check.', '#d7dbe2');
  });

  function updateBond(mesh, from, to) {
    bondDirection.subVectors(to, from);
    const distance = bondDirection.length();
    mesh.visible = distance > 0.001 && distance <= MAX_BOND_DISTANCE;
    if (!mesh.visible) return;

    mesh.position.copy(from).add(to).multiplyScalar(0.5);
    mesh.scale.y = distance;
    bondDirection.normalize();
    mesh.quaternion.setFromUnitVectors(up, bondDirection);
  }

  return {
    root,
    update(time) {
      guide.position.copy(oxygen.position);
      guide.quaternion.copy(oxygen.quaternion);
      guideMaterial.opacity = builtWater
        ? 0.07
        : 0.22 + (isGrabbed(oxygen) ? 0 : Math.sin(time * 2.2) * 0.04);

      updateBond(bond1, oxygen.position, hydrogen1.position);
      updateBond(bond2, oxygen.position, hydrogen2.position);

      const glow = builtWater ? 0.28 + Math.sin(time * 4) * 0.1 : 0;
      oxygenMaterial.emissiveIntensity = isGrabbed(oxygen) ? 0 : glow;
      h1Material.emissiveIntensity = isGrabbed(hydrogen1) ? 0 : glow;
      h2Material.emissiveIntensity = isGrabbed(hydrogen2) ? 0 : glow;
      bondMaterial.emissiveIntensity = builtWater ? 0.7 : 0.04;
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();
  root.name = 'Fruit Basket Shop';

  const basketX = 0.22;
  const basketZ = 0.015;
  const basketRadius = 0.115;
  const states = [];

