    const ring = new THREE.Mesh(ringGeometry, wicker);
    ring.rotation.x = Math.PI / 2;
    ring.position.y = height;
    basket.add(ring);
  });

  const ribGeometry = new THREE.CylinderGeometry(0.004, 0.004, 0.099, 8);
  for (let i = 0; i < 12; i++) {
    const angle = (i / 12) * Math.PI * 2;
    const rib = new THREE.Mesh(ribGeometry, wicker);
    rib.position.set(
      Math.cos(angle) * 0.103,
      0.077,
      Math.sin(angle) * 0.103,
    );
    basket.add(rib);
  }

  const apple = new THREE.Group();
  apple.name = 'Apple - $1.25';
  apple.position.set(-0.265, 0.048, 0.09);
  root.add(apple);

  const appleBody = new THREE.Mesh(
    new THREE.SphereGeometry(0.041, 24, 16),
    new THREE.MeshStandardMaterial({
      color: 0xd9403a,
      roughness: 0.48,
    }),
  );
  appleBody.scale.set(1, 0.94, 1);
  apple.add(appleBody);

  const appleStem = new THREE.Mesh(
    new THREE.CylinderGeometry(0.0035, 0.0045, 0.024, 8),
    stemMaterial,
  );
  appleStem.position.set(0, 0.045, 0);
  appleStem.rotation.z = -0.18;
  apple.add(appleStem);

  const appleLeaf = new THREE.Mesh(
    new THREE.SphereGeometry(0.012, 12, 8),
    leafMaterial,
  );
  appleLeaf.scale.set(1.5, 0.25, 0.7);
  appleLeaf.position.set(0.015, 0.049, 0);
  appleLeaf.rotation.z = 0.45;
  apple.add(appleLeaf);

  const orange = new THREE.Group();
  orange.name = 'Orange - $0.95';
  orange.position.set(-0.16, 0.043, 0.105);
  root.add(orange);

  const orangeBody = new THREE.Mesh(
    new THREE.SphereGeometry(0.039, 24, 16),
    new THREE.MeshStandardMaterial({
      color: 0xf18b22,
      roughness: 0.72,
    }),
  );
  orange.add(orangeBody);

  const orangeStem = new THREE.Mesh(
    new THREE.CylinderGeometry(0.005, 0.006, 0.008, 10),
    stemMaterial,
  );
  orangeStem.position.y = 0.039;
  orange.add(orangeStem);

  const orangeLeaf = new THREE.Mesh(
    new THREE.SphereGeometry(0.011, 12, 8),
    leafMaterial,
  );
  orangeLeaf.scale.set(1.45, 0.25, 0.75);
  orangeLeaf.position.set(0.011, 0.043, 0);
  orangeLeaf.rotation.z = 0.35;
  orange.add(orangeLeaf);

