  banana.position.set(-0.058, 0.067, 0.09);
  banana.rotation.z = -0.25;
  root.add(banana);

  const bananaCurve = new THREE.CatmullRomCurve3([
    new THREE.Vector3(-0.048, -0.025, 0),
    new THREE.Vector3(-0.028, -0.006, 0),
    new THREE.Vector3(0, 0.006, 0),
    new THREE.Vector3(0.028, -0.006, 0),
    new THREE.Vector3(0.048, -0.025, 0),
  ]);
  const bananaBody = new THREE.Mesh(
    new THREE.TubeGeometry(bananaCurve, 20, 0.013, 8, false),
    new THREE.MeshStandardMaterial({
      color: 0xf5cf3d,
      roughness: 0.65,
    }),
  );
  banana.add(bananaBody);

  const bananaTipGeometry = new THREE.SphereGeometry(0.011, 12, 8);
  const leftTip = new THREE.Mesh(bananaTipGeometry, stemMaterial);
  leftTip.scale.set(0.65, 0.65, 0.65);
  leftTip.position.set(-0.048, -0.025, 0);
  banana.add(leftTip);

  const rightTip = new THREE.Mesh(bananaTipGeometry, stemMaterial);
  rightTip.scale.set(0.65, 0.65, 0.65);
  rightTip.position.set(0.048, -0.025, 0);
  banana.add(rightTip);

  const panel = ui(`
    <style>
      .card {
        width: 500px;
        flex-direction: column;
        gap: 12px;
        padding-top: 18px;
        padding-bottom: 18px;
        padding-left: 22px;
        padding-right: 22px;
        border-radius: 18px;
        background-color: #1f2329;
        border-width: 2px;
        border-color: #46505b;
      }
      .title {
        color: #ffffff;
        font-size: 32px;
        font-weight: 700;
      }
      .instruction {
        color: #d7dde5;
        font-size: 22px;
      }
      .prices {
        color: #f4d58a;
        font-size: 22px;
      }
      .total {
        color: #9df0b1;
        font-size: 32px;
        font-weight: 700;
      }
      .status {
        color: #c8d0da;
        font-size: 22px;
      }
      .row {
        flex-direction: row;
        gap: 12px;
      }
      .button {
        padding-top: 10px;
        padding-bottom: 10px;
        padding-left: 16px;
        padding-right: 16px;
        border-radius: 12px;
        background-color: #356ca8;
      }
      .button-text {
        color: #ffffff;
        font-size: 21px;
        font-weight: 700;
      }
    </style>
    <div class="card">
      <span class="title">Fruit Basket</span>
      <span class="instruction">Pinch a fruit, then release it over the basket. Pick it up again to remove it.</span>
      <span class="prices">Apple $1.25 | Orange $0.95 | Banana $0.60</span>
      <span class="total" id="total">Basket total: $0.00</span>
      <span class="status" id="status">Basket is empty.</span>
      <div class="row">
        <button class="button" id="empty"><span class="button-text">Empty basket</span></button>
      </div>
    </div>
  `, {
    width: 0.34,
    position: [0.035, 0.36, -0.085],
    rotationY: 0,
  });
  root.add(panel.object3D);

  function makeState(object, label, price, slot, home, homeRotationZ) {
    const state = {
      object,
      label,
      price,
      slot: new THREE.Vector3(
        basketX + slot[0],
        slot[1],
        basketZ + slot[2],
      ),
      home: new THREE.Vector3(home[0], home[1], home[2]),
      homeRotationZ,
      inBasket: false,
      beingHeld: false,
      bobPhase: states.length * 1.7,
    };
    states.push(state);
    return state;
  }

  makeState(apple, 'Apple', 1.25, [-0.046, 0.068, -0.022], [-0.265, 0.048, 0.09], 0);
  makeState(orange, 'Orange', 0.95, [0.043, 0.064, -0.018], [-0.16, 0.043, 0.105], 0);
  makeState(banana, 'Banana', 0.60, [0, 0.157, 0.032], [-0.058, 0.067, 0.09], -0.25);

  function refreshTotal(message) {
    let cents = 0;
    let count = 0;
    for (const state of states) {
      if (state.inBasket) {
        cents += Math.round(state.price * 100);
        count++;
      }
    }

    panel.set('total', {
      text: 'Basket total: $' + (cents / 100).toFixed(2),
    });

    if (message) {
      panel.set('status', { text: message });
    } else if (count === 0) {
      panel.set('status', { text: 'Basket is empty.' });
    } else {
      panel.set('status', {
        text: count + (count === 1 ? ' fruit' : ' fruits') + ' in the basket.',
      });
    }
  }

  for (const state of states) {
    traits(state.object, { grab: true });
  }

