        }
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const layerData = [
    {
      name: 'Crust',
      outer: 0.145,
      inner: 0.139,
      exterior: 0x3f684f,
      color: 0x86a85e,
      css: '#86a85e',
      background: '#26362b',
      selectedBackground: '#425d3d',
      pointRadius: 0.142,
      pointAngle: 65,
      labelY: 0.38,
      fact: 'Crust - Thin, solid rock. Oceanic crust is 5-10 km thick; continental crust is usually 30-70 km. Shown thicker than scale.',
    },
    {
      name: 'Mantle',
      outer: 0.139,
      inner: 0.0793,
      exterior: 0x9f3e2a,
      color: 0xd35a35,
      css: '#d35a35',
      background: '#3b2724',
      selectedBackground: '#713a2b',
      pointRadius: 0.109,
      pointAngle: 30,
      labelY: 0.305,
      fact: "Mantle - Solid silicate rock that flows very slowly. It reaches about 2,900 km deep and makes up most of Earth's volume.",
    },
    {
      name: 'Outer core',
      outer: 0.0793,
      inner: 0.0278,
      exterior: 0xd47b24,
      color: 0xf0a43c,
      css: '#f0a43c',
      background: '#3d301f',
      selectedBackground: '#785021',
      pointRadius: 0.0535,
      pointAngle: -8,
      labelY: 0.23,
      fact: "Outer core - Liquid iron and nickel, about 2,900-5,150 km deep. Moving metal here helps generate Earth's magnetic field.",
    },
    {
      name: 'Inner core',
      outer: 0.0278,
      inner: 0,
      exterior: 0xf5c85a,
      color: 0xffdc78,
      css: '#ffdc78',
      background: '#3c3623',
      selectedBackground: '#756127',
      pointRadius: 0.02,
      pointAngle: -55,
      labelY: 0.155,
      fact: 'Inner core - A solid, mostly iron-nickel sphere, radius about 1,220 km. The center is nearly 6,000 degrees C.',
    },
  ];

  const model = new THREE.Group();
  model.name = 'Cutaway Earth';
  model.position.set(-0.145, 0.275, 0);
  root.add(model);

  function makeCutFace(innerRadius, outerRadius) {
    const shape = new THREE.Shape();
    shape.moveTo(0, -outerRadius);
    shape.absarc(0, 0, outerRadius, -Math.PI / 2, Math.PI / 2, false);

    if (innerRadius > 0) {
      shape.lineTo(0, innerRadius);
      shape.absarc(0, 0, innerRadius, Math.PI / 2, -Math.PI / 2, true);
    }

    shape.closePath();
    return new THREE.ShapeGeometry(shape, 32);
  }

  for (let i = 0; i < layerData.length; i++) {
    const layer = layerData[i];

    const surfaceMaterial = new THREE.MeshStandardMaterial({
      color: layer.exterior,
      roughness: 0.72,
      metalness: i >= 2 ? 0.18 : 0.03,
      side: THREE.FrontSide,
    });

    const surface = new THREE.Mesh(
      new THREE.SphereGeometry(
        layer.outer,
        48,
        24,
        Math.PI,
        Math.PI * 1.5,
        0,
        Math.PI
      ),
      surfaceMaterial
    );
    surface.name = layer.name + ' curved surface';
    model.add(surface);

    const capMaterial = new THREE.MeshStandardMaterial({
      color: layer.color,
      emissive: layer.color,
      emissiveIntensity: i === 3 ? 0.16 : 0.06,
      roughness: 0.58,
      metalness: i >= 2 ? 0.2 : 0.02,
      side: THREE.DoubleSide,
    });
    layer.capMaterial = capMaterial;

    const capGeometry = makeCutFace(layer.inner, layer.outer);

    const frontCut = new THREE.Mesh(capGeometry, capMaterial);
    frontCut.name = layer.name + ' front cut face';
    model.add(frontCut);

    const sideCut = new THREE.Mesh(capGeometry, capMaterial);
    sideCut.name = layer.name + ' side cut face';
    sideCut.rotation.y = -Math.PI / 2;
    model.add(sideCut);
  }

  traits(model, { grab: true });

  const info = ui(`
    <style>
      .info-card {
        width: 520px;
        display: flex;
        flex-direction: column;
        padding-top: 10px;
        padding-bottom: 10px;
        padding-left: 14px;
        padding-right: 14px;
        border-radius: 14px;
        border-width: 2px;
        border-color: #46505d;
        background-color: #20242b;
      }
      .info-text {
        color: #eef2f6;
        font-size: 22px;
        text-align: center;
      }
    </style>
    <div class="info-card" id="infoCard">
      <span class="info-text" id="fact">EARTH LAYERS - Press a colored label for facts. Pinch-drag the cutaway globe to move it.</span>
    </div>`, {
    width: 0.48,
    position: [0, 0.05, 0.12],
  });
  root.add(info.object3D);

  const leaderGeometry = new THREE.CylinderGeometry(0.0009, 0.0009, 1, 6);
  const beadGeometry = new THREE.SphereGeometry(0.0045, 16, 8);
  const leaders = [];
  let selectedIndex = -1;

  function selectLayer(index) {
    selectedIndex = index;

    for (let i = 0; i < layerData.length; i++) {
      const layer = layerData[i];
      const selected = i === index;

      layer.labelHandle.set('layerButton', {
        backgroundColor: selected ? layer.selectedBackground : layer.background,
      });
      layer.capMaterial.emissiveIntensity = selected ? 0.34 : (i === 3 ? 0.16 : 0.06);
      layer.leaderMaterial.color.setHex(selected ? 0xffffff : layer.color);
      layer.beadMaterial.emissiveIntensity = selected ? 0.75 : 0.22;
    }

    info.set('fact', { text: layerData[index].fact });
    info.set('infoCard', { backgroundColor: layerData[index].background });
  }

  for (let i = 0; i < layerData.length; i++) {
    const layer = layerData[i];

    const labelHandle = ui(`
      <style>
        .layer-button {
          width: 190px;
          display: flex;
          align-items: center;
          justify-content: center;
          padding-top: 8px;
          padding-bottom: 8px;
          padding-left: 10px;
          padding-right: 10px;
          border-radius: 12px;
          border-width: 2px;
          border-color: ${layer.css};
          background-color: ${layer.background};
        }
        .layer-text {
          color: #ffffff;
          font-size: 24px;
          font-weight: 700;
          text-align: center;
        }
      </style>
      <button class="layer-button" id="layerButton">
        <span class="layer-text">${layer.name}</span>
      </button>`, {
      width: 0.19,
      position: [0.205, layer.labelY, 0.06],
      rotationY: -0.18,
    });
    root.add(labelHandle.object3D);
    labelHandle.on('layerButton', 'click', () => selectLayer(i));
    layer.labelHandle = labelHandle;

    const angle = layer.pointAngle * Math.PI / 180;
    const startLocal = new THREE.Vector3(
      Math.cos(angle) * layer.pointRadius,
      Math.sin(angle) * layer.pointRadius,
      0.002
    );

    const leaderMaterial = new THREE.MeshBasicMaterial({ color: layer.color });
    const leader = new THREE.Mesh(leaderGeometry, leaderMaterial);
    leader.name = layer.name + ' label leader';
    root.add(leader);

    const beadMaterial = new THREE.MeshStandardMaterial({
      color: layer.color,
      emissive: layer.color,
      emissiveIntensity: 0.22,
      roughness: 0.45,
    });
    const bead = new THREE.Mesh(beadGeometry, beadMaterial);
    bead.name = layer.name + ' label marker';
    root.add(bead);

    layer.leaderMaterial = leaderMaterial;
    layer.beadMaterial = beadMaterial;

    leaders.push({
      startLocal,
      start: new THREE.Vector3(),
      end: new THREE.Vector3(0.111, layer.labelY, 0.043),
      delta: new THREE.Vector3(),
      leader,
      bead,
    });
  }

  const up = new THREE.Vector3(0, 1, 0);

  return {
    root,
    update(time) {
      model.updateMatrix();

      for (let i = 0; i < leaders.length; i++) {
        const item = leaders[i];

        item.start.copy(item.startLocal).applyMatrix4(model.matrix);
        item.bead.position.copy(item.start);

        item.delta.subVectors(item.end, item.start);
        const length = item.delta.length();

        item.leader.position.copy(item.start).addScaledVector(item.delta, 0.5);
        item.leader.quaternion.setFromUnitVectors(up, item.delta.multiplyScalar(1 / length));
        item.leader.scale.set(1, length, 1);

        const pulse = selectedIndex === i ? 1 + Math.sin(time * 4) * 0.12 : 1;
        item.bead.scale.setScalar(pulse);
      }
    },
  };
}
